object SlidersHighFreqState {
    private val values = java.util.concurrent.ConcurrentHashMap<String, Float>()
    fun get(key: String, defaultValue: Float): Float {
        return values[key] ?: defaultValue
    }
    fun put(key: String, value: Float) {
        values[key] = value
        com.aistudio.zenithstudio.rpxwtq.EffectStackManager.notifySliderInteraction()
    }
    fun set(key: String, value: Float) {
        values[key] = value
        com.aistudio.zenithstudio.rpxwtq.EffectStackManager.notifySliderInteraction()
    }
}

object ComposePaintCache {
    private val paintThreadLocal = object : ThreadLocal<Paint>() {
        override fun initialValue() = Paint()
    }
    fun getCleanPaint(): Paint {
        val paint = paintThreadLocal.get()!!
        paint.color = androidx.compose.ui.graphics.Color.Black
        paint.alpha = 1.0f
        paint.blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
        paint.style = androidx.compose.ui.graphics.PaintingStyle.Fill
        paint.colorFilter = null
        paint.strokeWidth = 0f
        paint.asFrameworkPaint().apply {
            maskFilter = null
            shader = null
            colorFilter = null
            pathEffect = null
            clearShadowLayer()
        }
        return paint
    }
}

object AdrenoAdjustmentCache {
    fun getOrCreatePaint(
        brightness: Float = 0f,
        contrast: Float = 0f,
        saturation: Float = 0f,
        tintColor: androidx.compose.ui.graphics.Color = androidx.compose.ui.graphics.Color.Transparent,
        tintIntensity: Float = 0f
    ): Paint {
        val paint = ComposePaintCache.getCleanPaint()
        val cm = android.graphics.ColorMatrix()
        if (brightness != 0f) cm.postConcat(android.graphics.ColorMatrix(floatArrayOf(
            1f, 0f, 0f, 0f, brightness * 255f,
            0f, 1f, 0f, 0f, brightness * 255f,
            0f, 0f, 1f, 0f, brightness * 255f,
            0f, 0f, 0f, 1f, 0f
        )))
        paint.colorFilter = androidx.compose.ui.graphics.ColorFilter.colorMatrix(androidx.compose.ui.graphics.ColorMatrix(cm.array))
        return paint
    }
}

@Composable
fun ProjectThumbnail(
    projectId: String,
    modifier: Modifier = Modifier
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val thumbFile = java.io.File(context.filesDir, "thumb_${projectId}.png")
    
    Box(
        modifier = modifier
            .background(Color(0xFF22222B), RoundedCornerShape(8.dp))
            .border(1.dp, HighslateOutline, RoundedCornerShape(8.dp)),
        contentAlignment = Alignment.Center
    ) {
        if (thumbFile.exists()) {
            coil.compose.AsyncImage(
                model = thumbFile,
                contentDescription = null,
                modifier = Modifier.fillMaxSize().clip(RoundedCornerShape(8.dp)),
                contentScale = androidx.compose.ui.layout.ContentScale.Fit
            )
        } else {
            Icon(
                imageVector = Icons.Default.Palette,
                contentDescription = null,
                tint = IndustrialAmber,
                modifier = Modifier.size(24.dp)
            )
        }
    }
}

