fun decodeSampledBitmapFromFile(path: String, maxDim: Int = 4096): android.graphics.Bitmap? {
    try {
        android.util.Log.d("StudioImageLoader", "decodeSampledBitmapFromFile path=$path maxDim=$maxDim")
        val options = android.graphics.BitmapFactory.Options().apply {
            inJustDecodeBounds = true
        }
        android.graphics.BitmapFactory.decodeFile(path, options)
        val width = options.outWidth
        val height = options.outHeight
        if (width <= 0 || height <= 0) {
            android.util.Log.e("StudioImageLoader", "Failed to decode bounds for path=$path (outWidth=$width, outHeight=$height)")
            return null
        }

        var inSampleSize = 1
        while ((width / inSampleSize) > maxDim || (height / inSampleSize) > maxDim) {
            inSampleSize *= 2
        }

        val decodeOptions = android.graphics.BitmapFactory.Options().apply {
            this.inSampleSize = inSampleSize
                                            val isOpaque = options.outMimeType == "image/jpeg" || options.outMimeType == "image/heic"
                                            inPreferredConfig = if (isOpaque) android.graphics.Bitmap.Config.RGB_565 else android.graphics.Bitmap.Config.ARGB_8888
            inPremultiplied = true
            inScaled = false
            inMutable = true
        }
        val decoded = android.graphics.BitmapFactory.decodeFile(path, decodeOptions)
        android.util.Log.d("StudioImageLoader", "path=$path decoded bitmap: $decoded, width: ${decoded?.width}, height: ${decoded?.height}, config: ${decoded?.config}")
        if (decoded == null || decoded.width <= 0 || decoded.height <= 0) {
            android.util.Log.e("StudioImageLoader", "Decoded bitmap is null or invalid for path=$path")
            return null
        }
        val isHardware = android.os.Build.VERSION.SDK_INT >= 26 && decoded.config == android.graphics.Bitmap.Config.HARDWARE
        val softwareBmp = if (isHardware || !decoded.isMutable) {
            android.util.Log.d("StudioImageLoader", "Converting decoded bitmap to mutable software ARGB_8888")
            val copied = decoded.copy(android.graphics.Bitmap.Config.ARGB_8888, true)
            if (copied != decoded) {
                decoded.recycle()
            }
            copied
        } else {
            decoded
        }
        return softwareBmp
    } catch (t: Throwable) {
        android.util.Log.e("StudioImageLoader", "Exception in decodeSampledBitmapFromFile for path=$path", t)
        return null
    }
}

fun extractPixelStretchBitmap(
    source: android.graphics.Bitmap,
    sliceLine: Float,
    horizontalOrientation: Boolean
): android.graphics.Bitmap {
    val srcW = source.width
    val srcH = source.height
    try {
        if (horizontalOrientation) {
            val initialX = (sliceLine * (srcW - 1)).toInt().coerceIn(0, srcW - 1)
            var targetX = initialX
            val column = IntArray(srcH)
            var foundNonTransparent = false
            
            // Check initial target column
            source.getPixels(column, 0, 1, targetX, 0, 1, srcH)
            if (column.any { ((it shr 24) and 0xff) > 5 }) {
                foundNonTransparent = true
            } else {
                // Outward content-aware scan to locate nearest non-transparent column
                for (offset in 1 until srcW) {
                    val leftX = initialX - offset
                    if (leftX >= 0) {
                        source.getPixels(column, 0, 1, leftX, 0, 1, srcH)
                        if (column.any { ((it shr 24) and 0xff) > 5 }) {
                            targetX = leftX
                            foundNonTransparent = true
                            break
                        }
                    }
                    val rightX = initialX + offset
                    if (rightX < srcW) {
                        source.getPixels(column, 0, 1, rightX, 0, 1, srcH)
                        if (column.any { ((it shr 24) and 0xff) > 5 }) {
                            targetX = rightX
                            foundNonTransparent = true
                            break
                        }
                    }
                }
            }
            
            // Fallback if fully transparent
            if (!foundNonTransparent) {
                targetX = initialX
                source.getPixels(column, 0, 1, targetX, 0, 1, srcH)
            }
            
            val sliceBmp = android.graphics.Bitmap.createBitmap(256, srcH, android.graphics.Bitmap.Config.ARGB_8888)
            val pixels = IntArray(256 * srcH)
            for (y in 0 until srcH) {
                val color = column[y]
                val rowOffset = y * 256
                for (x in 0 until 256) {
                    pixels[rowOffset + x] = color
                }
            }
            sliceBmp.setPixels(pixels, 0, 256, 0, 0, 256, srcH)
            return sliceBmp
        } else {
            val initialY = (sliceLine * (srcH - 1)).toInt().coerceIn(0, srcH - 1)
            var targetY = initialY
            val row = IntArray(srcW)
            var foundNonTransparent = false
            
            // Check initial target row
            source.getPixels(row, 0, srcW, 0, targetY, srcW, 1)
            if (row.any { ((it shr 24) and 0xff) > 5 }) {
                foundNonTransparent = true
            } else {
                // Outward content-aware scan to locate nearest non-transparent row
                for (offset in 1 until srcH) {
                    val upY = initialY - offset
                    if (upY >= 0) {
                        source.getPixels(row, 0, srcW, 0, upY, srcW, 1)
                        if (row.any { ((it shr 24) and 0xff) > 5 }) {
                            targetY = upY
                            foundNonTransparent = true
                            break
                        }
                    }
                    val downY = initialY + offset
                    if (downY < srcH) {
                        source.getPixels(row, 0, srcW, 0, downY, srcW, 1)
                        if (row.any { ((it shr 24) and 0xff) > 5 }) {
                            targetY = downY
                            foundNonTransparent = true
                            break
                        }
                    }
                }
            }
            
            // Fallback if fully transparent
            if (!foundNonTransparent) {
                targetY = initialY
                source.getPixels(row, 0, srcW, 0, targetY, srcW, 1)
            }
            
            val sliceBmp = android.graphics.Bitmap.createBitmap(srcW, 256, android.graphics.Bitmap.Config.ARGB_8888)
            val pixels = IntArray(srcW * 256)
            for (y in 0 until 256) {
                val rowOffset = y * srcW
                System.arraycopy(row, 0, pixels, rowOffset, srcW)
            }
            sliceBmp.setPixels(pixels, 0, srcW, 0, 0, srcW, 256)
            return sliceBmp
        }
    } catch (e: Exception) {
        e.printStackTrace()
        return source
    }
}

fun extractSubjectForeground(
    source: android.graphics.Bitmap,
    threshold: Float,
    subjectOpacity: Float
): android.graphics.Bitmap {
    // 2. High-performance downsampling (maintains crisp detail but avoids processing millions of pixels in Kotlin)
    val maxDimension = 1024
    var workingSource = source
    val srcW = source.width
    val srcH = source.height
    val needsResize = srcW > maxDimension || srcH > maxDimension
    if (needsResize) {
        val (newW, newH) = if (srcW > srcH) {
            maxDimension to (srcH * maxDimension / srcW)
        } else {
            (srcW * maxDimension / srcH) to maxDimension
        }
        try {
            workingSource = android.graphics.Bitmap.createScaledBitmap(source, newW, newH, true)
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    val w = workingSource.width
    val h = workingSource.height
    try {
        val result = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
        val pixels = IntArray(w * h)
        workingSource.getPixels(pixels, 0, w, 0, 0, w, h)
        
        val threshInt = threshold.toInt()
        val opacityMul = subjectOpacity
        
        // Detect if the canvas already has transparency (like text, shapes, vector icons).
        // If so, do not execute destructive luma thresholding, just apply the opacity overlay.
        var transparentCount = 0
        val sampleCount = minOf(150, pixels.size)
        val sampleStep = maxOf(1, pixels.size / sampleCount)
        var sampledPixels = 0
        for (i in 0 until pixels.size step sampleStep) {
            val a = (pixels[i] shr 24) and 0xff
            if (a < 240) {
                transparentCount++
            }
            sampledPixels++
        }
        val isAlreadyTransparent = sampledPixels > 0 && (transparentCount.toFloat() / sampledPixels.toFloat()) > 0.05f
        
        if (isAlreadyTransparent) {
            for (i in pixels.indices) {
                val color = pixels[i]
                val a = (color shr 24) and 0xff
                val r = (color shr 16) and 0xff
                val g = (color shr 8) and 0xff
                val b = color and 0xff
                val alphaMask = (a * opacityMul).toInt().coerceIn(0, 255)
                pixels[i] = (alphaMask shl 24) or (r shl 16) or (g shl 8) or b
            }
            result.setPixels(pixels, 0, w, 0, 0, w, h)
            if (needsResize && workingSource != source) {
                try { workingSource.recycle() } catch (e: Exception) {}
            }
            return result
        }
        
        // 3. Dual-path outer loop to completely remove inside-loop branching conditions
        if (threshInt >= 128) {
            val denom = 255f - threshold
            val floatDenom = if (denom <= 0f) 1f else denom
            for (i in pixels.indices) {
                val color = pixels[i]
                val a = (color shr 24) and 0xff
                val r = (color shr 16) and 0xff
                val g = (color shr 8) and 0xff
                val b = color and 0xff
                
                // Ultra-fast integer-only luminance approximation (0.299R + 0.587G + 0.114B becomes integer math)
                val luma = (r * 77 + g * 150 + b * 29) shr 8
                
                val alphaMask = if (luma > threshInt) {
                    val diff = luma - threshInt
                    val pct = (diff / floatDenom).coerceIn(0f, 1f)
                    (a * (1f - pct) * opacityMul).toInt()
                } else {
                    (a * opacityMul).toInt()
                }
                
                pixels[i] = (alphaMask shl 24) or (r shl 16) or (g shl 8) or b
            }
        } else {
            val floatThreshold = if (threshold <= 0f) 1f else threshold
            for (i in pixels.indices) {
                val color = pixels[i]
                val a = (color shr 24) and 0xff
                val r = (color shr 16) and 0xff
                val g = (color shr 8) and 0xff
                val b = color and 0xff
                
                val luma = (r * 77 + g * 150 + b * 29) shr 8
                
                val alphaMask = if (luma < threshInt) {
                    val pct = (luma / floatThreshold).coerceIn(0f, 1f)
                    (a * pct * opacityMul).toInt()
                } else {
                    (a * opacityMul).toInt()
                }
                
                pixels[i] = (alphaMask shl 24) or (r shl 16) or (g shl 8) or b
            }
        }
        
        result.setPixels(pixels, 0, w, 0, 0, w, h)
        
        if (needsResize && workingSource != source) {
            try {
                workingSource.recycle()
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
        return result
    } catch (e: Exception) {
        e.printStackTrace()
        return source
    }
}

var globalAppContext: android.content.Context? = null

data class AnchorPoint(
    val position: Offset,
    val handleIn: Offset = position,
    val handleOut: Offset = position
)

fun List<Offset>.toAnchorPoints(): List<AnchorPoint> {
    val results = mutableListOf<AnchorPoint>()
    var i = 0
    while (i < this.size) {
        val pos = this[i]
        val hIn = this.getOrNull(i + 1) ?: pos
        val hOut = this.getOrNull(i + 2) ?: pos
        results.add(AnchorPoint(pos, hIn, hOut))
        i += 3
    }
    return results
}

fun buildComposeBezierPath(path: androidx.compose.ui.graphics.Path, layer: com.example.studio.model.StudioLayer, anchors: List<AnchorPoint>) {
    if (anchors.isNotEmpty()) {
        var startNewContour = true
        var contourStartIdx = 0
        var idx = 0
        while (idx < anchors.size) {
            val current = anchors[idx]
            if (current.position.x.isNaN() || current.position.y.isNaN()) {
                if (layer.polygonEdges == 1 && idx > contourStartIdx) {
                    val first = anchors[contourStartIdx]
                    val last = anchors[idx - 1]
                    if (first != last) {
                        path.cubicTo(
                            last.handleOut.x, last.handleOut.y,
                            first.handleIn.x, first.handleIn.y,
                            first.position.x, first.position.y
                        )
                    }
                    path.close()
                }
                startNewContour = true
                idx++
                continue
            }
            if (startNewContour) {
                path.moveTo(current.position.x, current.position.y)
                contourStartIdx = idx
                startNewContour = false
            } else {
                val prev = anchors[idx - 1]
                path.cubicTo(
                    prev.handleOut.x, prev.handleOut.y,
                    current.handleIn.x, current.handleIn.y,
                    current.position.x, current.position.y
                )
            }
            idx++
        }
        if (layer.polygonEdges == 1 && anchors.isNotEmpty() && !startNewContour) {
            val first = anchors[contourStartIdx]
            val last = anchors.last()
            if (first != last) {
                path.cubicTo(
                    last.handleOut.x, last.handleOut.y,
                    first.handleIn.x, first.handleIn.y,
                    first.position.x, first.position.y
                )
            }
            path.close()
        }
    } else if (layer.brushPoints.isNotEmpty()) {
        val startPt = layer.brushPoints[0]
        path.moveTo(startPt.x, startPt.y)
        path.lineTo(startPt.x + 0.1f, startPt.y)
    }
}

fun simplifyPoints(points: List<Offset>, epsilon: Float): List<Offset> {
    if (points.size < 3) return points

    var dmax = 0f
    var index = 0
    val end = points.size - 1

    for (i in 1 until end) {
        val d = perpendicularDistance(points[i], points[0], points[end])
        if (d > dmax) {
            index = i
            dmax = d
        }
    }

    return if (dmax > epsilon) {
        val results1 = simplifyPoints(points.subList(0, index + 1), epsilon)
        val results2 = simplifyPoints(points.subList(index, points.size), epsilon)
        results1.dropLast(1) + results2
    } else {
        listOf(points[0], points[end])
    }
}

fun perpendicularDistance(pt: Offset, lineStart: Offset, lineEnd: Offset): Float {
    val dx = lineEnd.x - lineStart.x
    val dy = lineEnd.y - lineStart.y

    val mag = Math.hypot(dx.toDouble(), dy.toDouble()).toFloat()
    if (mag < 0.0001f) {
        return Math.hypot((pt.x - lineStart.x).toDouble(), (pt.y - lineStart.y).toDouble()).toFloat()
    }

    val num = Math.abs(dy * pt.x - dx * pt.y + lineEnd.x * lineStart.y - lineEnd.y * lineStart.x)
    return num / mag
}

fun cleanConsecutiveDuplicates(points: List<Offset>): List<Offset> {
    if (points.isEmpty()) return points
    val cleaned = mutableListOf<Offset>()
    cleaned.add(points[0])
    for (i in 1 until points.size) {
        val prev = cleaned.last()
        val curr = points[i]
        val distSq = (curr.x - prev.x) * (curr.x - prev.x) + (curr.y - prev.y) * (curr.y - prev.y)
        if (distSq > 1f) { // 1px threshold
            cleaned.add(curr)
        }
    }
    return cleaned
}

fun findClosestSegmentAndInsert(localPt: Offset, layer: com.example.studio.model.StudioLayer): List<Offset>? {
    val pts = layer.brushPoints
    if (pts.size < 6) return null
    val N = pts.size / 3
    var bestK = -1
    var bestT = 0.5f
    var minDistanceSq = Float.MAX_VALUE
    
    val numSegments = if (layer.polygonEdges == 1) N else N - 1
    for (k in 0 until numSegments) {
        val nextK = (k + 1) % N
        val p0 = pts[k * 3]
        val p1 = pts[k * 3 + 2]
        val p2 = pts[nextK * 3 + 1]
        val p3 = pts[nextK * 3]
        
        for (i in 0..10) {
            val t = i / 10f
            val mt = 1f - t
            val curvePt = p0 * (mt * mt * mt) + p1 * (3f * mt * mt * t) + p2 * (3f * mt * t * t) + p3 * (t * t * t)
            val dx = localPt.x - curvePt.x
            val dy = localPt.y - curvePt.y
            val distSq = dx * dx + dy * dy
            if (distSq < minDistanceSq) {
                minDistanceSq = distSq
                bestK = k
                bestT = t
            }
        }
    }
    
    if (bestK != -1 && minDistanceSq < 150f * 150f) {
        val k = bestK
        val nextK = (k + 1) % N
        val p0 = pts[k * 3]
        val p1 = pts[k * 3 + 2]
        val p2 = pts[nextK * 3 + 1]
        val p3 = pts[nextK * 3]
        val t = bestT
        val mt = 1f - t
        val newAnchor = p0 * (mt * mt * mt) + p1 * (3f * mt * mt * t) + p2 * (3f * mt * t * t) + p3 * (t * t * t)
        
        val tangent = (p1 - p0) * (3f * mt * mt) + (p2 - p1) * (6f * mt * t) + (p3 - p2) * (3f * t * t)
        val handleLength = 30f
        val unitTangent = if (tangent.getDistance() > 0f) tangent / tangent.getDistance() else Offset(1f, 0f)
        val newIn = newAnchor - unitTangent * handleLength
        val newOut = newAnchor + unitTangent * handleLength
        
        val updated = pts.toMutableList()
        val insertIndex = (bestK + 1) * 3
        updated.add(insertIndex, newAnchor)
        updated.add(insertIndex + 1, newIn)
        updated.add(insertIndex + 2, newOut)
        return updated
    }
    return null
}

fun convertFreehandToBezier(freehandPoints: List<Offset>): List<Offset> {
    if (freehandPoints.size < 2) return emptyList()
    val sampled = mutableListOf<Offset>()
    sampled.add(freehandPoints.first())
    var last = freehandPoints.first()
    for (pt in freehandPoints) {
        val dist = (pt - last).getDistance()
        if (dist > 35f) {
            sampled.add(pt)
            last = pt
        }
    }
    if (sampled.last() != freehandPoints.last()) {
        sampled.add(freehandPoints.last())
    }
    
    if (sampled.size < 2) return emptyList()
    
    val result = mutableListOf<Offset>()
    val N = sampled.size
    for (i in 0 until N) {
        val anchor = sampled[i]
        val prev = if (i > 0) sampled[i - 1] else anchor
        val next = if (i < N - 1) sampled[i + 1] else anchor
        val tangent = next - prev
        val tangentLength = tangent.getDistance()
        val handleLength = if (tangentLength > 0f) (tangentLength * 0.25f).coerceIn(10f, 60f) else 25f
        val unitTangent = if (tangentLength > 0f) tangent / tangentLength else Offset(1f, 0f)
        
        val handleIn = anchor - unitTangent * handleLength
        val handleOut = anchor + unitTangent * handleLength
        
        result.add(anchor)
        result.add(handleIn)
        result.add(handleOut)
    }
    return result
}

fun smoothBezierPoints(points: List<Offset>): List<Offset> {
    if (points.size < 3) return points
    val results = points.toMutableList()
    val numAnchors = points.size / 3
    for (i in 0 until numAnchors) {
        val posIdx = i * 3
        val current = points[posIdx]
        
        val prev = if (i > 0) points[(i - 1) * 3] else current
        val next = if (i < numAnchors - 1) points[(i + 1) * 3] else current
        
        val tangent = next - prev
        val hIn = if (i > 0) current - tangent * 0.2f else current
        val hOut = if (i < numAnchors - 1) current + tangent * 0.2f else current
        
        results[posIdx + 1] = hIn
        results[posIdx + 2] = hOut
    }
    return results
}

fun pullOutBezierHandles(points: List<Offset>): List<Offset> {
    if (points.size < 3) return points
    val results = points.toMutableList()
    val numAnchors = points.size / 3
    for (i in 0 until numAnchors) {
        val posIdx = i * 3
        val current = points[posIdx]
        
        if (points[posIdx + 1] == current && points[posIdx + 2] == current) {
            val prev = if (i > 0) points[(i - 1) * 3] else current
            val next = if (i < numAnchors - 1) points[(i + 1) * 3] else current
            
            val dir = if (next != prev) {
                val diffVec = next - prev
                val dist = kotlin.math.sqrt(diffVec.x * diffVec.x + diffVec.y * diffVec.y)
                if (dist > 0f) diffVec / dist else Offset(1f, 0f)
            } else {
                Offset(1f, 0f)
            }
            
            val offsetDist = 50f
            results[posIdx + 1] = current - dir * offsetDist
            results[posIdx + 2] = current + dir * offsetDist
        }
    }
    return results
}

fun collapseBezierHandles(points: List<Offset>): List<Offset> {
    if (points.size < 3) return points
    val results = points.toMutableList()
    val numAnchors = points.size / 3
    for (i in 0 until numAnchors) {
        val posIdx = i * 3
        val current = points[posIdx]
        results[posIdx + 1] = current
        results[posIdx + 2] = current
    }
    return results
}

fun simplifyAnchorPoints(anchors: List<AnchorPoint>, tolerance: Float = 4f): List<AnchorPoint> {
    if (anchors.isEmpty()) return anchors
    
    val contours = mutableListOf<List<AnchorPoint>>()
    var currentContour = mutableListOf<AnchorPoint>()
    for (a in anchors) {
        if (a.position.x.isNaN() || a.position.y.isNaN()) {
            if (currentContour.isNotEmpty()) {
                contours.add(currentContour)
                currentContour = mutableListOf()
            }
        } else {
            currentContour.add(a)
        }
    }
    if (currentContour.isNotEmpty()) {
        contours.add(currentContour)
    }
    
    val simplifiedContours = contours.map { contour ->
        simplifySingleContour(contour, tolerance)
    }
    
    val result = mutableListOf<AnchorPoint>()
    for (i in simplifiedContours.indices) {
        if (i > 0) {
            val nanPt = Offset(Float.NaN, Float.NaN)
            result.add(AnchorPoint(nanPt, nanPt, nanPt))
        }
        result.addAll(simplifiedContours[i])
    }
    return result
}

private fun simplifySingleContour(contour: List<AnchorPoint>, tolerance: Float): List<AnchorPoint> {
    if (contour.size <= 2) return contour
    
    val positions = contour.map { it.position }
    val keptIndices = mutableListOf<Int>()
    
    fun perpendicularDistance(pt: Offset, lineStart: Offset, lineEnd: Offset): Float {
        val dx = lineEnd.x - lineStart.x
        val dy = lineEnd.y - lineStart.y
        val mag = kotlin.math.sqrt(dx * dx + dy * dy)
        if (mag < 0.001f) {
            val ddx = pt.x - lineStart.x
            val ddy = pt.y - lineStart.y
            return kotlin.math.sqrt(ddx * ddx + ddy * ddy)
        }
        return kotlin.math.abs(dy * pt.x - dx * pt.y + lineEnd.x * lineStart.y - lineEnd.y * lineStart.x) / mag
    }

    fun rdpIndices(start: Int, end: Int) {
        if (end - start <= 1) return
        var maxDist = 0f
        var index = -1
        for (i in start + 1 until end) {
            val dist = perpendicularDistance(positions[i], positions[start], positions[end])
            if (dist > maxDist) {
                maxDist = dist
                index = i
            }
        }
        if (maxDist > tolerance) {
            rdpIndices(start, index)
            keptIndices.add(index)
            rdpIndices(index, end)
        }
    }
    
    rdpIndices(0, contour.size - 1)
    keptIndices.add(0)
    keptIndices.add(contour.size - 1)
    keptIndices.sort()
    
    return keptIndices.map { contour[it] }
}

private fun perpendicularDistanceToLine(pt: Offset, lineStart: Offset, lineEnd: Offset): Float {
    val dx = lineEnd.x - lineStart.x
    val dy = lineEnd.y - lineStart.y
    val mag = kotlin.math.sqrt(dx * dx + dy * dy)
    if (mag < 0.001f) {
        val ddx = pt.x - lineStart.x
        val ddy = pt.y - lineStart.y
        return kotlin.math.sqrt(ddx * ddx + ddy * ddy)
    }
    return kotlin.math.abs(dy * pt.x - dx * pt.y + lineEnd.x * lineStart.y - lineEnd.y * lineStart.x) / mag
}

fun convertAndroidPathToOptimalBezierAnchors(path: android.graphics.Path): List<AnchorPoint> {
    val resultAnchors = mutableListOf<AnchorPoint>()
    val pathMeasure = android.graphics.PathMeasure(path, false)
    var isFirstContour = true

    do {
        val len = pathMeasure.length
        if (len <= 0f) continue

        val step = 2.0f
        val numSamples = (len / step).toInt().coerceAtLeast(12)
        val actualStep = len / numSamples
        val pos = FloatArray(2)
        val tan = FloatArray(2)
        val rawPoints = mutableListOf<Offset>()
        val tangents = mutableListOf<Offset>()

        for (i in 0 until numSamples) {
            val dist = i * actualStep
            pathMeasure.getPosTan(dist, pos, tan)
            rawPoints.add(Offset(pos[0], pos[1]))
            val tLen = Math.hypot(tan[0].toDouble(), tan[1].toDouble()).toFloat().coerceAtLeast(0.001f)
            tangents.add(Offset(tan[0] / tLen, tan[1] / tLen))
        }

        if (rawPoints.size < 3) continue
        val n = rawPoints.size

        val cornerIndices = mutableListOf<Int>()
        for (i in 0 until n) {
            val prevIdx = (i - 3 + n) % n
            val nextIdx = (i + 3) % n
            val v1 = Offset(rawPoints[i].x - rawPoints[prevIdx].x, rawPoints[i].y - rawPoints[prevIdx].y)
            val v2 = Offset(rawPoints[nextIdx].x - rawPoints[i].x, rawPoints[nextIdx].y - rawPoints[i].y)
            val l1 = Math.hypot(v1.x.toDouble(), v1.y.toDouble()).toFloat().coerceAtLeast(0.001f)
            val l2 = Math.hypot(v2.x.toDouble(), v2.y.toDouble()).toFloat().coerceAtLeast(0.001f)
            val dot = (v1.x * v2.x + v1.y * v2.y) / (l1 * l2)
            if (dot < 0.92f) {
                cornerIndices.add(i)
            }
        }

        val filteredCorners = mutableListOf<Int>()
        if (cornerIndices.isNotEmpty()) {
            var cluster = mutableListOf<Int>()
            cluster.add(cornerIndices[0])
            for (k in 1 until cornerIndices.size) {
                val idx = cornerIndices[k]
                if (idx - cluster.last() <= 4) {
                    cluster.add(idx)
                } else {
                    val sharpest = cluster.minByOrNull { i ->
                        val pP = rawPoints[(i - 3 + n) % n]
                        val pC = rawPoints[i]
                        val pN = rawPoints[(i + 3) % n]
                        val vA = Offset(pC.x - pP.x, pC.y - pP.y)
                        val vB = Offset(pN.x - pC.x, pN.y - pC.y)
                        val lA = Math.hypot(vA.x.toDouble(), vA.y.toDouble()).toFloat().coerceAtLeast(0.001f)
                        val lB = Math.hypot(vB.x.toDouble(), vB.y.toDouble()).toFloat().coerceAtLeast(0.001f)
                        (vA.x * vB.x + vA.y * vB.y) / (lA * lB)
                    } ?: cluster[cluster.size / 2]
                    filteredCorners.add(sharpest)
                    cluster = mutableListOf(idx)
                }
            }
            if (cluster.isNotEmpty()) {
                val sharpest = cluster.minByOrNull { i ->
                    val pP = rawPoints[(i - 3 + n) % n]
                    val pC = rawPoints[i]
                    val pN = rawPoints[(i + 3) % n]
                    val vA = Offset(pC.x - pP.x, pC.y - pP.y)
                    val vB = Offset(pN.x - pC.x, pN.y - pC.y)
                    val lA = Math.hypot(vA.x.toDouble(), vA.y.toDouble()).toFloat().coerceAtLeast(0.001f)
                    val lB = Math.hypot(vB.x.toDouble(), vB.y.toDouble()).toFloat().coerceAtLeast(0.001f)
                    (vA.x * vB.x + vA.y * vB.y) / (lA * lB)
                } ?: cluster[cluster.size / 2]
                filteredCorners.add(sharpest)
            }
        }

        val effectiveCorners = if (filteredCorners.isNotEmpty()) {
            filteredCorners
        } else {
            val q = n / 4
            listOf(0, q, q * 2, q * 3)
        }

        class ContourNode(
            val sampleIndex: Int,
            val position: Offset,
            val isCorner: Boolean,
            var incomingIsStraight: Boolean = false,
            var outgoingIsStraight: Boolean = false
        )

        val contourNodes = mutableListOf<ContourNode>()
        val numC = effectiveCorners.size

        for (c in 0 until numC) {
            val startIdx = effectiveCorners[c]
            val endIdx = effectiveCorners[(c + 1) % numC]

            val segIndices = mutableListOf<Int>()
            var curr = startIdx
            while (curr != endIdx) {
                segIndices.add(curr)
                curr = (curr + 1) % n
            }
            segIndices.add(endIdx)

            val pStart = rawPoints[startIdx]
            val pEnd = rawPoints[endIdx]

            var maxDist = 0f
            for (k in 1 until segIndices.size - 1) {
                val pt = rawPoints[segIndices[k]]
                val d = perpendicularDistanceToLine(pt, pStart, pEnd)
                if (d > maxDist) {
                    maxDist = d
                }
            }

            val isStraight = maxDist < 2.5f

            val startNode = contourNodes.find { it.sampleIndex == startIdx } ?: ContourNode(
                sampleIndex = startIdx,
                position = rawPoints[startIdx],
                isCorner = true
            ).also { contourNodes.add(it) }

            if (isStraight) {
                startNode.outgoingIsStraight = true
            } else {
                startNode.outgoingIsStraight = false

                var totalAngleRad = 0.0
                for (k in 0 until segIndices.size - 1) {
                    val t1 = tangents[segIndices[k]]
                    val t2 = tangents[segIndices[k + 1]]
                    val dot = (t1.x * t2.x + t1.y * t2.y).coerceIn(-1f, 1f)
                    val cross = t1.x * t2.y - t1.y * t2.x
                    totalAngleRad += Math.abs(Math.atan2(cross.toDouble(), dot.toDouble()))
                }
                val totalAngleDeg = Math.toDegrees(totalAngleRad)

                val numSubdivisions = if (totalAngleDeg <= 110.0) {
                    1
                } else if (totalAngleDeg <= 200.0) {
                    2
                } else {
                    3
                }

                for (sub in 1..numSubdivisions) {
                    val frac = sub.toFloat() / (numSubdivisions + 1).toFloat()
                    val sIdx = segIndices[(segIndices.size * frac).toInt().coerceIn(1, segIndices.size - 2)]
                    val midNode = ContourNode(
                        sampleIndex = sIdx,
                        position = rawPoints[sIdx],
                        isCorner = false,
                        incomingIsStraight = false,
                        outgoingIsStraight = false
                    )
                    contourNodes.add(midNode)
                }
            }
        }

        contourNodes.sortBy { it.sampleIndex }

        val numNodes = contourNodes.size
        for (i in 0 until numNodes) {
            val prevNode = contourNodes[(i - 1 + numNodes) % numNodes]
            val curNode = contourNodes[i]
            val nextNode = contourNodes[(i + 1) % numNodes]

            val dPrevCorner = perpendicularDistanceToLine(
                rawPoints[(curNode.sampleIndex - 2 + n) % n],
                prevNode.position,
                curNode.position
            )
            curNode.incomingIsStraight = curNode.isCorner && dPrevCorner < 2.5f

            val dNextCorner = perpendicularDistanceToLine(
                rawPoints[(curNode.sampleIndex + 2) % n],
                curNode.position,
                nextNode.position
            )
            curNode.outgoingIsStraight = curNode.isCorner && dNextCorner < 2.5f
        }

        if (!isFirstContour) {
            val nanPt = Offset(Float.NaN, Float.NaN)
            resultAnchors.add(AnchorPoint(nanPt, nanPt, nanPt))
        }
        isFirstContour = false

        for (i in 0 until numNodes) {
            val prevNode = contourNodes[(i - 1 + numNodes) % numNodes]
            val curNode = contourNodes[i]
            val nextNode = contourNodes[(i + 1) % numNodes]

            val posPt = curNode.position
            val tanVec = tangents[curNode.sampleIndex]

            val dPrev = Math.hypot((posPt.x - prevNode.position.x).toDouble(), (posPt.y - prevNode.position.y).toDouble()).toFloat()
            val dNext = Math.hypot((nextNode.position.x - posPt.x).toDouble(), (nextNode.position.y - posPt.y).toDouble()).toFloat()

            val hIn = if (curNode.isCorner && curNode.incomingIsStraight) {
                posPt
            } else {
                val lenIn = (dPrev * 0.38f).coerceIn(4f, 250f)
                Offset(posPt.x - tanVec.x * lenIn, posPt.y - tanVec.y * lenIn)
            }

            val hOut = if (curNode.isCorner && curNode.outgoingIsStraight) {
                posPt
            } else {
                val lenOut = (dNext * 0.38f).coerceIn(4f, 250f)
                Offset(posPt.x + tanVec.x * lenOut, posPt.y + tanVec.y * lenOut)
            }

            resultAnchors.add(AnchorPoint(posPt, hIn, hOut))
        }

    } while (pathMeasure.nextContour())

    return resultAnchors
}

fun simplifyBezierPoints(points: List<Offset>, tolerance: Float = 8f): List<Offset> {
    if (points.size < 6) return points
    val anchors = points.toAnchorPoints()
    val simplifiedAnchors = simplifyAnchorPoints(anchors, tolerance)
    val results = mutableListOf<Offset>()
    for (a in simplifiedAnchors) {
        results.add(a.position)
        results.add(a.handleIn)
        results.add(a.handleOut)
    }
    return results
}

// Shaders and LightroomFilter are managed by CameraRAWFilterEngine.kt

private fun getLayerGeometryHash(layer: StudioLayer): Int {
    var result = layer.id.hashCode()
    result = 31 * result + layer.type.ordinal
    result = 31 * result + java.lang.Float.floatToIntBits(layer.width)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.height)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.cornerRadius)
    result = 31 * result + layer.polygonEdges
    result = 31 * result + java.lang.Float.floatToIntBits(layer.starInnerRadiusRatio)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.strokeThickness)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.skewX)
    result = 31 * result + java.lang.Float.floatToIntBits(layer.skewY)
    result = 31 * result + layer.brushPoints.hashCode()
    result = 31 * result + layer.bezierNodeTypes.hashCode()
    if (layer.type == com.example.studio.model.LayerType.TEXT) {
        result = 31 * result + layer.textContent.hashCode()
        result = 31 * result + java.lang.Float.floatToIntBits(layer.fontSize)
        result = 31 * result + (layer.fontPath?.hashCode() ?: 0)
        result = 31 * result + (layer.fontFamilyName?.hashCode() ?: 0)
        result = 31 * result + layer.fontIsBold.hashCode()
        result = 31 * result + layer.fontIsItalic.hashCode()
        result = 31 * result + layer.fontAlign.hashCode()
        result = 31 * result + java.lang.Float.floatToIntBits(layer.lineSpacing)
        result = 31 * result + java.lang.Float.floatToIntBits(layer.letterSpacing)
    }
    if (layer.brushPoints.isNotEmpty()) {
        result = 31 * result + layer.brushPoints.hashCode()
    }
    return result
}

private fun rotateOffset(offset: Offset, degrees: Float): Offset {
    val rad = Math.toRadians(degrees.toDouble())
    val cos = Math.cos(rad)
    val sin = Math.sin(rad)
    val rx = offset.x * cos - offset.y * sin
    val ry = offset.x * sin + offset.y * cos
    return Offset(rx.toFloat(), ry.toFloat())
}

