    override fun onInit() {
        super.onInit()
        uIntensityLoc = android.opengl.GLES20.glGetUniformLocation(program, "uIntensity")
    }

    override fun onInitialized() {
        super.onInitialized()
        applyParameters()
    }

    fun setIntensityVal(intensity: Float) {
        this.intensity = intensity
        applyParameters()
    }

    private fun applyParameters() {
