private fun safeFloat(v: Float, min: Float, max: Float, fallback: Float = 0f): Float {
    if (v.isNaN() || v.isInfinite()) return fallback
    return v.coerceIn(min, max)
}

fun applyGPUImageFilters(
    context: android.content.Context,
    originalBitmap: android.graphics.Bitmap,
    layerId: String,
    effects: List<com.example.studio.model.StudioEffect>
): android.graphics.Bitmap {
    val activeEffects = effects.filter { it.isEnabled }
    if (activeEffects.isEmpty()) return originalBitmap

    try {
        val gpuImage = jp.co.cyberagent.android.gpuimage.GPUImage(context)

        val filterGroup = jp.co.cyberagent.android.gpuimage.filter.GPUImageFilterGroup()
        var hasFilters = false

        for (effect in activeEffects) {
            when (effect) {
                is com.example.studio.model.StudioEffect.ColorBalance -> {
                    val brightnessVal = effect.parameters["Brightness"]?.value ?: 1.0f
                    val brightnessShift = safeFloat(brightnessVal - 1.0f, -1.0f, 1.0f, 0f)
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBrightnessFilter(brightnessShift))

                    val hueShift = safeFloat(effect.parameters["HueShift"]?.value ?: 0f, -360f, 360f, 0f)
                    val hueDeg = (hueShift + 360f) % 360f
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHueFilter(hueDeg))

                    val saturationVal = safeFloat(effect.parameters["Saturation"]?.value ?: 1.0f, 0.0f, 2.0f, 1.0f)
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSaturationFilter(saturationVal))
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.Invert -> {
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageColorInvertFilter())
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.Threshold -> {
                    val threshVal = safeFloat(effect.parameters["Threshold"]?.value ?: 0.5f, 0.0f, 1.0f, 0.5f)
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageLuminanceThresholdFilter(threshVal))
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.Posterize -> {
                    val levelsVal = safeFloat(effect.parameters["Levels"]?.value ?: 4f, 1f, 256f, 4f)
                    filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImagePosterizeFilter(levelsVal.toInt()))
                    hasFilters = true
                }
                is com.example.studio.model.StudioEffect.PhotoshopEffect -> {
                    when (effect.effectType) {
                        "CameraRaw", "ColorGrading", "Fast Adjusting", "color_fast_adjusting", "FastAdjusting", "fast_adj" -> {
                            val exposure = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Exposure", effect.parameters["Exposure"]?.value ?: 0f), -5f, 5f, 0f)
                            val brightness = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Brightness", effect.parameters["Brightness"]?.value ?: 0f), -100f, 100f, 0f)
                            val contrast = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Contrast", effect.parameters["Contrast"]?.value ?: 0f), -100f, 100f, 0f)
                            val highlights = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Highlights", effect.parameters["Highlights"]?.value ?: 0f), -100f, 100f, 0f)
                            val shadows = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Shadows", effect.parameters["Shadows"]?.value ?: 0f), -100f, 100f, 0f)
                            val whites = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Whites", effect.parameters["Whites"]?.value ?: 0f), -100f, 100f, 0f)
                            val blacks = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Blacks", effect.parameters["Blacks"]?.value ?: 0f), -100f, 100f, 0f)
                            val temp = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Temp", SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Temperature", effect.parameters["Temp"]?.value ?: effect.parameters["Temperature"]?.value ?: 0f)), -100f, 100f, 0f)
                            val tint = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Tint", effect.parameters["Tint"]?.value ?: 0f), -100f, 100f, 0f)
                            val vibrance = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Vibrance", effect.parameters["Vibrance"]?.value ?: 0f), -100f, 100f, 0f)
                            val saturation = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Saturation", effect.parameters["Saturation"]?.value ?: 0f), -100f, 100f, 0f)
                            val texture = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Texture", effect.parameters["Texture"]?.value ?: 0f), -100f, 100f, 0f)
                            val clarity = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Clarity", effect.parameters["Clarity"]?.value ?: 0f), -100f, 100f, 0f)
                            val dehaze = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Dehaze", effect.parameters["Dehaze"]?.value ?: 0f), -100f, 100f, 0f)
                            val profile = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Profile", effect.parameters["Profile"]?.value ?: 0f), 0f, 4f, 0f)

                            val lrFilter = LightroomFilter().apply {
                                updateParams(
                                    exposure = exposure,
                                    contrast = contrast,
                                    highlights = highlights,
                                    shadows = shadows,
                                    whites = whites,
                                    blacks = blacks,
                                    temp = temp,
                                    tint = tint,
                                    vibrance = vibrance,
                                    saturation = saturation,
                                    clarity = clarity,
                                    dehaze = dehaze,
                                    profile = profile
                                )
                            }
                            filterGroup.addFilter(lrFilter)
                            if (brightness != 0f) {
                                filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBrightnessFilter(safeFloat(brightness / 100f, -1f, 1f, 0f)))
                            }
                            hasFilters = true

                            if (texture != 0f) {
                                if (texture > 0f) {
                                    val sharpFilter = jp.co.cyberagent.android.gpuimage.filter.GPUImageSharpenFilter().apply {
                                        setSharpness(safeFloat(texture / 100f * 2.0f, 0f, 5f, 0f))
                                    }
                                    filterGroup.addFilter(sharpFilter)
                                } else {
                                    val blurFilter = jp.co.cyberagent.android.gpuimage.filter.GPUImageGaussianBlurFilter().apply {
                                        setBlurSize(safeFloat(-texture / 100f * 4.0f, 0f, 10f, 0f))
                                    }
                                    filterGroup.addFilter(blurFilter)
                                }
                            }
                        }
                        "Solarize" -> {
                            val thresh = safeFloat(effect.parameters["Threshold"]?.value ?: 0.5f, 0f, 1f, 0.5f)
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSolarizeFilter().apply {
                                setThreshold(thresh)
                            })
                            hasFilters = true
                        }
                        "Emboss" -> {
                            val heightVal = safeFloat(effect.parameters["Height"]?.value ?: 2.0f, -100f, 100f, 2f)
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageEmbossFilter().apply {
                                setIntensity(safeFloat(heightVal / 10f, 0.0f, 1.0f, 0.2f))
                            })
                            hasFilters = true
                        }
                        "FindEdges" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSobelEdgeDetectionFilter())
                            hasFilters = true
                        }
                        "ColorHalftone" -> {
                            val maxRadius = effect.parameters["MaxRadius"]?.value ?: 8f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHalftoneFilter(maxRadius / 1000f))
                            hasFilters = true
                        }
                        "Sketch" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSketchFilter())
                            hasFilters = true
                        }
                        "Mosaic" -> {
                            val cellSize = effect.parameters["CellSize"]?.value ?: 8f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImagePixelationFilter().apply {
                                setPixel(safeFloat(cellSize, 1f, 1000f, 8f))
                            })
                            hasFilters = true
                        }
                        "Twirl" -> {
                            val angleVal = effect.parameters["Angle"]?.value ?: 100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSwirlFilter().apply {
                                setAngle(angleVal / 100f)
                                setRadius(0.5f)
                            })
                            hasFilters = true
                        }
                        "Spherize" -> {
                            val amt = effect.parameters["Amount"]?.value ?: 100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBulgeDistortionFilter().apply {
                                setRadius(0.5f)
                                setScale(amt / 100f * 0.5f)
                            })
                            hasFilters = true
                        }
                        "GaussianBlur", "RadialBlur", "LensBlur" -> {
                            val radiusVal = effect.parameters["Radius"]?.value ?: effect.parameters["Amount"]?.value ?: 12f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageGaussianBlurFilter().apply {
                                setBlurSize(radiusVal / 5f)
                            })
                            hasFilters = true
                        }
                        "MotionBlur", "Wind" -> {
                            val distance = effect.parameters["Distance"]?.value ?: 15f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageGaussianBlurFilter().apply {
                                setBlurSize(distance / 6f)
                            })
                            hasFilters = true
                        }
                        "SmartSharpen", "UnsharpMask" -> {
                            val amt = effect.parameters["Amount"]?.value ?: 50f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSharpenFilter().apply {
                                setSharpness(amt / 100f * 2.0f)
                            })
                            hasFilters = true
                        }
                        "AddNoise", "Clouds", "Texture" -> {
                            val amt = (effect.parameters["Amount"]?.value ?: effect.parameters["Relief"]?.value ?: 10f) / 100f
                            filterGroup.addFilter(GPUImageNoiseFilter(safeFloat(amt, 0.05f, 1.0f, 0.1f)))
                            hasFilters = true
                        }
                        "Pinch" -> {
                            val amt = (effect.parameters["Amount"]?.value ?: 50f) / -100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBulgeDistortionFilter().apply {
                                setRadius(0.6f)
                                setScale(amt * 0.5f)
                            })
                            hasFilters = true
                        }
                        "Ripple", "Wave", "ZigZag" -> {
                            val amt = effect.parameters["Amount"]?.value ?: effect.parameters["WaveAmplitude"]?.value ?: 30f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSwirlFilter().apply {
                                setRadius(0.6f)
                                setAngle(amt / 50f)
                            })
                            hasFilters = true
                        }
                        "Despeckle", "DustScratches", "Median", "NeuralFilters" -> {
                            val smooth = effect.parameters["SmoothSkin"]?.value ?: 50f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBilateralBlurFilter().apply {
                                setDistanceNormalizationFactor(0.002f + (smooth / 100f) * 0.008f)
                            })
                            hasFilters = true
                        }
                        "Crystallize", "Pointillize" -> {
                            val cellSize = effect.parameters["CellSize"]?.value ?: 10f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageHalftoneFilter(cellSize / 1000f))
                            hasFilters = true
                        }
                        "ColoredPencil" -> {
                            val width = effect.parameters["StrokeThickness"]?.value ?: effect.parameters["PencilWidth"]?.value ?: 1.5f
                            val pressure = effect.parameters["StrokePressure"]?.value ?: effect.parameters["HandTremorSimulation"]?.value ?: 0.8f
                            val bright = effect.parameters["PaperBrightness"]?.value ?: effect.parameters["ShadowLift"]?.value ?: 0.9f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageColoredPencilFilter(width, pressure, bright))
                            hasFilters = true
                        }
                        "Cutout" -> {
                            val lvl = effect.parameters["PosterizationLevels"]?.value ?: effect.parameters["Levels"]?.value ?: 5f
                            val edgeFid = effect.parameters["EdgeSimplificationLevel"]?.value ?: effect.parameters["EdgeFidelity"]?.value ?: 0.5f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageCutoutFilter(lvl, edgeFid))
                            hasFilters = true
                        }
                        "ChromaKey" -> {
                            val kR = safeFloat(effect.parameters["KeyRed"]?.value ?: 0f, 0f, 1f, 0f)
                            val kG = safeFloat(effect.parameters["KeyGreen"]?.value ?: 1f, 0f, 1f, 1f)
                            val kB = safeFloat(effect.parameters["KeyBlue"]?.value ?: 0f, 0f, 1f, 0f)
                            val sim = safeFloat(effect.parameters["Similarity"]?.value ?: 0.35f, 0.01f, 1f, 0.35f)
                            val smooth = safeFloat(effect.parameters["Smoothness"]?.value ?: 0.15f, 0f, 1f, 0.15f)
                            val spill = safeFloat(effect.parameters["SpillSuppression"]?.value ?: 0.5f, 0f, 1f, 0.5f)
                            filterGroup.addFilter(GPUImageChromaKeyFilter(kR, kG, kB, sim, smooth, spill))
                            hasFilters = true
                        }
                        "PlasticWrap" -> {
                            val strength = effect.parameters["HighlightStrength"]?.value ?: 1.2f
                            val det = effect.parameters["Detail"]?.value ?: 3f
                            val smooth = effect.parameters["Smoothness"]?.value ?: 0.5f
                            filterGroup.addFilter(com.example.studio.ui.GPUImagePlasticWrapFilter(strength, det, smooth))
                            hasFilters = true
                        }
                        "FilmGrain" -> {
                            val amt = (effect.parameters["Amount"]?.value ?: 15f) / 100f
                            val dist = effect.parameters["GrainDistributionField"]?.value ?: 0.5f
                            val cluster = effect.parameters["GrainClusteringStrength"]?.value ?: 0.3f
                            val shadow = effect.parameters["ShadowGrainEmphasis"]?.value ?: 0.8f
                            val highlight = effect.parameters["HighlightGrainSuppression"]?.value ?: 0.9f
                            val chrom = effect.parameters["ChromaticGrainSeparation"]?.value ?: 0.4f
                            filterGroup.addFilter(GPUImageFilmGrainFilter(amt, dist, cluster, shadow, highlight, chrom))
                            hasFilters = true
                        }
                        "AccentedEdges" -> {
                            val edgeW = effect.parameters["EdgeWidth"]?.value ?: 1.8f
                            val edgeB = effect.parameters["EdgeBrightness"]?.value ?: 0.7f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageAccentedEdgesFilter(edgeW, edgeB))
                            hasFilters = true
                        }
                        "Crosshatch" -> {
                            val len = effect.parameters["StrokeLength"]?.value ?: 8f
                            val contr = effect.parameters["Contrast"]?.value ?: 0.8f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageCrosshatchFilter(len, contr))
                            hasFilters = true
                        }
                        "SumiE" -> {
                            val press = effect.parameters["StrokePressure"]?.value ?: 0.7f
                            val dark = effect.parameters["DarkArea"]?.value ?: 0.45f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageSumiEFilter(press, dark))
                            hasFilters = true
                        }
                        "OceanRipple" -> {
                            val sz = effect.parameters["RippleSize"]?.value ?: 8f
                            val mag = effect.parameters["RippleMagnitude"]?.value ?: 1f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageOceanRippleFilter(sz, mag))
                            hasFilters = true
                        }
                        "Glass" -> {
                            val dist = effect.parameters["Distortion"]?.value ?: 5f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageGlassFilter(dist))
                            hasFilters = true
                        }
                        "BasRelief" -> {
                            val det = effect.parameters["Detail"]?.value ?: 4f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageBasReliefFilter(det))
                            hasFilters = true
                        }
                        "HalftonePattern" -> {
                            val size = effect.parameters["DotScalingCurve"]?.value ?: effect.parameters["DotSize"]?.value ?: 6f
                            val contr = effect.parameters["Contrast"]?.value ?: effect.parameters["InkDensityResponse"]?.value ?: 0.7f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageHalftonePatternFilter(size, contr))
                            hasFilters = true
                        }
                        "Photocopy" -> {
                            val det = effect.parameters["EdgeCollapseStrength"]?.value ?: effect.parameters["Detail"]?.value ?: 4f
                            val dark = effect.parameters["ThresholdCurve"]?.value ?: effect.parameters["Darkness"]?.value ?: 0.8f
                            filterGroup.addFilter(com.example.studio.ui.GPUImagePhotocopyFilter(det, dark))
                            hasFilters = true
                        }
                        "Chrome" -> {
                            filterGroup.addFilter(com.example.studio.ui.GPUImageChromeFilter())
                            hasFilters = true
                        }
                        "StainedGlass" -> {
                            val size = effect.parameters["CellSize"]?.value ?: 14f
                            val thick = effect.parameters["BorderThickness"]?.value ?: 1.5f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageStainedGlassFilter(size, thick))
                            hasFilters = true
                        }
                        "Craquelure" -> {
                            val spacing = effect.parameters["CrackSpacing"]?.value ?: 15f
                            val depth = effect.parameters["CrackDepth"]?.value ?: 1.0f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageCraquelureFilter(spacing, depth))
                            hasFilters = true
                        }
                        "Texturizer" -> {
                            val scale = effect.parameters["Scaling"]?.value ?: 8f
                            val relief = effect.parameters["Relief"]?.value ?: 2f
                            filterGroup.addFilter(com.example.studio.ui.GPUImageTexturizerFilter(scale, relief))
                            hasFilters = true
                        }
                        "OilPaint", "Artistic", "BrushStrokes" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageToonFilter())
                            hasFilters = true
                        }
                        "HighPass" -> {
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageSobelEdgeDetectionFilter())
                            hasFilters = true
                        }
                        "SolidColor", "ColorOverlay" -> {
                            val r = effect.parameters["Color Red"]?.value ?: effect.parameters["Red"]?.value ?: effect.parameters["ColorRed"]?.value ?: 0f
                            val g = effect.parameters["Color Green"]?.value ?: effect.parameters["Green"]?.value ?: effect.parameters["ColorGreen"]?.value ?: 0.9f
                            val b = effect.parameters["Color Blue"]?.value ?: effect.parameters["Blue"]?.value ?: effect.parameters["ColorBlue"]?.value ?: 1.0f
                            val opacity = effect.parameters["Opacity"]?.value ?: 1.0f

                            filterGroup.addFilter(GPUImageSolidColorFilter(r, g, b, opacity))
                            hasFilters = true
                        }
                        "GradientOverlay", "PatternOverlay", "DropShadow", "InnerShadow", "InnerGlow", "OuterGlow", "BevelEmboss", "Satin", "Stroke", "BordersAndShadows", "GlassMorphism", "ReededGlass" -> {
                            val opacity = effect.parameters["Opacity"]?.value ?: 0.5f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageVignetteFilter().apply {
                                setVignetteStart(0.3f)
                                setVignetteEnd(0.7f + (1f - opacity) * 0.3f)
                            })
                            hasFilters = true
                        }
                        "LensFlare" -> {
                            val bright = (effect.parameters["Brightness"]?.value ?: 100f) / 100f
                            val shift = safeFloat(bright - 1.0f, -1.0f, 1.0f, 0f)
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBrightnessFilter(shift))
                            hasFilters = true
                        }
                        "LightingEffects" -> {
                            val intensity = effect.parameters["Intensity"]?.value ?: 50f
                            filterGroup.addFilter(GPUImageLightingFilter(intensity))
                            hasFilters = true
                        }
                        "PixelStretch" -> {
                            val slice = effect.parameters["SliceLine"]?.value ?: 0.5f
                            val orient = effect.parameters["Orientation"]?.value ?: 0f
                            val bend = effect.parameters["WarpBend"]?.value ?: 30f
                            val freq = effect.parameters["WarpFrequency"]?.value ?: 1.0f
                            filterGroup.addFilter(GPUImagePixelStretchFilter(slice, orient, bend, freq))
                            hasFilters = true
                        }
                        "Liquify" -> {
                            val size = effect.parameters["BrushSize"]?.value ?: 100f
                            filterGroup.addFilter(jp.co.cyberagent.android.gpuimage.filter.GPUImageBulgeDistortionFilter().apply {
                                setRadius(size / 300f)
                                setScale(0.3f)
                            })
                            hasFilters = true
                        }
                        "ChromaticAberration" -> {
                            val distance = effect.parameters["Distance"]?.value ?: 16f
                            val angle = effect.parameters["Angle"]?.value ?: 136f
                            filterGroup.addFilter(GPUImageChromaticAberrationFilter(distance, angle))
                            hasFilters = true
                        }
                        "Glitch" -> {
                            val height = effect.parameters["Height"]?.value ?: 119f
                            val strength = effect.parameters["Strength"]?.value ?: 23f
                            val colorShift = effect.parameters["ColorShift"]?.value ?: 8f
                            filterGroup.addFilter(GPUImageGlitchFilter(height, strength, colorShift))
                            hasFilters = true
                        }
                        "Bloom" -> {
                            val area = effect.parameters["Area"]?.value ?: 100f
                            val radius = effect.parameters["Radius"]?.value ?: 45f
                            val brightness = effect.parameters["Brightness"]?.value ?: 100f
                            val balanced = effect.parameters["Balanced Blend"]?.value ?: effect.parameters["Balanced"]?.value ?: 25f
                            filterGroup.addFilter(GPUImageBloomFilter(area, radius, brightness, balanced))
                            hasFilters = true
                        }
                        "CrossFilter" -> {
                            val count = effect.parameters["Count"]?.value ?: 4f
                            val direction = effect.parameters["Direction"]?.value ?: 45f
                            val area = effect.parameters["Area"]?.value ?: 10f
                            val brightness = effect.parameters["Brightness"]?.value ?: 50f
                            filterGroup.addFilter(GPUImageCrossFilterFilter(count, direction, area, brightness))
                            hasFilters = true
                        }
                        "InnerGlow" -> {
                            val radiusVal = effect.parameters["Radius"]?.value ?: effect.parameters["Choke"]?.value ?: 104f
                            val radius = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Radius", SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Choke", radiusVal)), 1f, 300f, 104f)
                            
                            val rVal = effect.parameters["Red"]?.value ?: 1.0f
                            val r = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Red", rVal), 0f, 1f, 1.0f)
                            
                            val gVal = effect.parameters["Green"]?.value ?: 1.0f
                            val g = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Green", gVal), 0f, 1f, 1.0f)
                            
                            val bVal = effect.parameters["Blue"]?.value ?: 1.0f
                            val b = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Blue", bVal), 0f, 1f, 1.0f)
                            
                            val hardnessVal = effect.parameters["Hardness"]?.value ?: 0.5f
                            val hardness = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_Hardness", hardnessVal), 0f, 1f, 0.5f)
                            
                            val blendModeVal = effect.parameters["BlendMode"]?.value ?: 2.0f
                            val blendMode = safeFloat(SlidersHighFreqState.get("${layerId}_effect_${effect.id}_BlendMode", blendModeVal), 0f, 6f, 2.0f)

                            filterGroup.addFilter(GPUImageInnerGlowFilter(radius, r, g, b, hardness, blendMode))
                            hasFilters = true
                        }
                        "Bevel" -> {
                            val height = effect.parameters["Height"]?.value ?: 20f
                            val smoothness = effect.parameters["Smoothness"]?.value ?: 45f
                            val highlightSize = effect.parameters["Highlight Size"]?.value ?: effect.parameters["HighlightSize"]?.value ?: 14f
                            filterGroup.addFilter(GPUImageBevelFilter(height, smoothness, highlightSize))
                            hasFilters = true
                        }
                        "Emboss2" -> {
                            val grayScale = effect.parameters["Gray Scale (=1)"]?.value ?: effect.parameters["GrayScale"]?.value ?: 0f
                            val height = effect.parameters["Height"]?.value ?: 1f
                            val amount = effect.parameters["Amount"]?.value ?: 500f
                            filterGroup.addFilter(GPUImageEmboss2Filter(grayScale, height, amount))
                            hasFilters = true
                        }
                        "Waterdrop" -> {
                            val distance = effect.parameters["Distance"]?.value ?: 100f
                            val flatness = effect.parameters["Flatness"]?.value ?: 10f
                            val height = effect.parameters["Height"]?.value ?: 3f
                            filterGroup.addFilter(GPUImageWaterdropFilter(distance, flatness, height))
                            hasFilters = true
                        }
                        "Satin2" -> {
                            val distance = effect.parameters["Distance"]?.value ?: 11f
                            val opacity = effect.parameters["Opacity"]?.value ?: 0.5f
                            val r = effect.parameters["Color Red"]?.value ?: effect.parameters["Red"]?.value ?: 0f
                            val g = effect.parameters["Color Green"]?.value ?: effect.parameters["Green"]?.value ?: 0f
                            val b = effect.parameters["Color Blue"]?.value ?: effect.parameters["Blue"]?.value ?: 0f
                            filterGroup.addFilter(GPUImageSatinFilter(distance, opacity, r, g, b))
                            hasFilters = true
                        }
                    }
                }
                else -> {}
            }
        }

        if (hasFilters) {
            if (filterGroup.filters.size == 1) {
                gpuImage.setFilter(filterGroup.filters[0])
            } else {
                gpuImage.setFilter(filterGroup)
            }
            var filtered = gpuImage.getBitmapWithFilterApplied(originalBitmap)
            if (filtered != null) {
                if (filtered.width != originalBitmap.width || filtered.height != originalBitmap.height) {
                    filtered = android.graphics.Bitmap.createScaledBitmap(filtered, originalBitmap.width, originalBitmap.height, true)
                }
                return filtered
            }
        }
    } catch (e: Throwable) {
        android.util.Log.e("GPUImage", "Failed to apply GPUImage filters", e)
    }
    return originalBitmap
}

fun Modifier.dropShadow(
    color: Color = Color.Black,
    blur: Dp = 8.dp,
    dx: Dp = 0.dp,
    dy: Dp = 0.dp,
    spread: Dp = 0.dp,
    isEnabled: Boolean = true
): Modifier = if (isEnabled) {
    this.drawBehind {
        val bPx = blur.toPx()
        val dxPx = dx.toPx()
        val dyPx = dy.toPx()
        val spreadPx = spread.toPx()
        
        val paint = Paint().asFrameworkPaint().apply {
            this.color = android.graphics.Color.argb(
                (color.alpha * 255).toInt(),
                (color.red * 255).toInt(),
                (color.green * 255).toInt(),
                (color.blue * 255).toInt()
            )
            if (bPx > 0f && !com.example.ui.theme.isLowEndOptimizationEnabled.value) {
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    try {
                        val setMethod = this.javaClass.getMethod("setRenderEffect", android.graphics.RenderEffect::class.java)
                        setMethod.invoke(this, android.graphics.RenderEffect.createBlurEffect(bPx, bPx, android.graphics.Shader.TileMode.DECAL))
                    } catch (t: Throwable) {
                        maskFilter = android.graphics.BlurMaskFilter(bPx, android.graphics.BlurMaskFilter.Blur.NORMAL)
                    }
                } else {
                    maskFilter = android.graphics.BlurMaskFilter(bPx, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        }
        val dSize = this.size
        val sizeWithSpread = dSize.copy(
            width = dSize.width + spreadPx * 2f,
            height = dSize.height + spreadPx * 2f
        )
        val topLeftWithOffset = Offset(
            dxPx - spreadPx,
            dyPx - spreadPx
        )
        this.drawContext.canvas.nativeCanvas.drawRect(
            topLeftWithOffset.x,
            topLeftWithOffset.y,
            topLeftWithOffset.x + sizeWithSpread.width,
            topLeftWithOffset.y + sizeWithSpread.height,
            paint
        )
    }
} else {
    this
}

private fun screenToCanvas(
    screenPos: Offset,
    viewportWidth: Float,
    viewportHeight: Float,
    canvasPanX: Float,
    canvasPanY: Float,
    canvasRotation: Float,
    totalScale: Float,
    centerX: Float,
    centerY: Float,
    viewportCenterY: Float = viewportHeight / 2f
): Offset {
    val p3 = Offset(
        screenPos.x - (viewportWidth / 2f + canvasPanX),
        screenPos.y - (viewportCenterY + canvasPanY)
    )
    val p2 = rotateOffset(p3, -canvasRotation)
    val p1 = p2 / totalScale.coerceAtLeast(0.001f)
    return Offset(
        p1.x + centerX,
        p1.y + centerY
    )
}

private fun screenDeltaToCanvas(
    delta: Offset,
    canvasRotation: Float,
    totalScale: Float
): Offset {
    val rotated = rotateOffset(delta, -canvasRotation)
    return rotated / totalScale.coerceAtLeast(0.001f)
}

private fun sampleColorFromLayer(
    layer: com.example.studio.model.StudioLayer,
    artRelativeX: Float,
    artRelativeY: Float,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>
): Color {
    val cacheNode = com.example.studio.ui.ParametricLayerCache.getOrCreateNode(layer.id)
    val cachedBmp = cacheNode.cachedBitmap
    val isFromCache = cachedBmp != null
    val loadedBitmap = cachedBmp ?: if (!layer.imageUri.isNullOrEmpty()) {
        imageBitmapCache[layer.imageUri]?.asAndroidBitmap()
    } else null

    var color = layer.baseColor
    if (loadedBitmap != null) {
        val localTouch = canvasToLayerLocal(Offset(artRelativeX, artRelativeY), layer)
        val px: Int
        val py: Int
        if (isFromCache) {
            val paddingPx = cacheNode.paddingPx
            px = (localTouch.x + paddingPx).toInt().coerceIn(0, loadedBitmap.width - 1)
            py = (localTouch.y + paddingPx).toInt().coerceIn(0, loadedBitmap.height - 1)
        } else {
            val pctX = if (layer.width > 0f) (localTouch.x / layer.width).coerceIn(0f, 1f) else 0f
            val pctY = if (layer.height > 0f) (localTouch.y / layer.height).coerceIn(0f, 1f) else 0f
            px = (pctX * (loadedBitmap.width - 1)).toInt().coerceIn(0, loadedBitmap.width - 1)
            py = (pctY * (loadedBitmap.height - 1)).toInt().coerceIn(0, loadedBitmap.height - 1)
        }
        try {
            color = Color(loadedBitmap.getPixel(px, py))
        } catch (e: Exception) {
            // fallback
        }
    }

    // Check for GradientOverlay
    val layerGradOverlay = layer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
    if (layerGradOverlay != null) {
        val lStopCount = (layerGradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
        val lColors = mutableListOf<Color>()
        for (i in 0 until lStopCount) {
            val rVal = layerGradOverlay.parameters["CustomStop_${i}_R"]?.value ?: 0.5f
            val gVal = layerGradOverlay.parameters["CustomStop_${i}_G"]?.value ?: 0.5f
            val bVal = layerGradOverlay.parameters["CustomStop_${i}_B"]?.value ?: 0.5f
            val aVal = layerGradOverlay.parameters["CustomStop_${i}_A"]?.value ?: 1.0f
            lColors.add(Color(rVal, gVal, bVal, aVal))
        }
        val sX = (layerGradOverlay.parameters["StartX"]?.value ?: 0f) * layer.width
        val sY = (layerGradOverlay.parameters["StartY"]?.value ?: 0f) * layer.height
        val eX = (layerGradOverlay.parameters["EndX"]?.value ?: 1f) * layer.width
        val eY = (layerGradOverlay.parameters["EndY"]?.value ?: 1f) * layer.height
        val localTouch = canvasToLayerLocal(Offset(artRelativeX, artRelativeY), layer)
        val ab = Offset(eX - sX, eY - sY)
        val ap = Offset(localTouch.x - sX, localTouch.y - sY)
        val abLenSq = ab.x * ab.x + ab.y * ab.y
        val t = if (abLenSq > 0f) {
            ((ap.x * ab.x + ap.y * ab.y) / abLenSq).coerceIn(0f, 1f)
        } else 0f
        color = interpolateMultiColor(lColors, t)
    }
    return color
}

private fun sampleCompositedColor(
    layers: List<com.example.studio.model.StudioLayer>,
    artRelativeX: Float,
    artRelativeY: Float,
    artboardWidth: Float,
    artboardHeight: Float,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>
): Color {
    var r = if (artRelativeX in 0f..artboardWidth && artRelativeY in 0f..artboardHeight) 1f else 0.0745f
    var g = if (artRelativeX in 0f..artboardWidth && artRelativeY in 0f..artboardHeight) 1f else 0.0745f
    var b = if (artRelativeX in 0f..artboardWidth && artRelativeY in 0f..artboardHeight) 1f else 0.09f
    var a = 1f

    for (layer in layers) {
        if (!layer.isVisible) continue
        val local = canvasToLayerLocal(Offset(artRelativeX, artRelativeY), layer)
        if (local.x in 0f..layer.width && local.y in 0f..layer.height) {
            val sampled = sampleColorFromLayer(layer, artRelativeX, artRelativeY, imageBitmapCache)
            var computedOpacity = layer.opacity
            var currentParentId = layer.parentGroupId
            val visited = mutableSetOf<String>()
            while (currentParentId != null && !visited.contains(currentParentId)) {
                visited.add(currentParentId)
                val p = layers.find { it.id == currentParentId }
                if (p != null) {
                    computedOpacity *= p.opacity
                    currentParentId = p.parentGroupId
                } else {
                    break
                }
            }
            val srcA = sampled.alpha * computedOpacity
            if (srcA > 0f) {
                val srcR = sampled.red
                val srcG = sampled.green
                val srcB = sampled.blue
                val destA = a
                val outA = srcA + destA * (1f - srcA)
                if (outA > 0f) {
                    r = (srcR * srcA + r * destA * (1f - srcA)) / outA
                    g = (srcG * srcA + g * destA * (1f - srcA)) / outA
                    b = (srcB * srcA + b * destA * (1f - srcA)) / outA
                    a = outA
                }
            }
        }
    }
    return Color(r, g, b, a)
}

private fun isConvexQuadrilateral(pts: List<Offset>): Boolean {
    if (pts.size != 4) return false
    val cp0 = (pts[1].x - pts[0].x) * (pts[2].y - pts[1].y) - (pts[1].y - pts[0].y) * (pts[2].x - pts[1].x)
    val cp1 = (pts[2].x - pts[1].x) * (pts[3].y - pts[2].y) - (pts[2].y - pts[1].y) * (pts[3].x - pts[2].x)
    val cp2 = (pts[3].x - pts[2].x) * (pts[0].y - pts[3].y) - (pts[3].y - pts[2].y) * (pts[0].x - pts[3].x)
    val cp3 = (pts[0].x - pts[3].x) * (pts[1].y - pts[0].y) - (pts[0].y - pts[3].y) * (pts[1].x - pts[0].x)
    
    val pCount = (if (cp0 > 0f) 1 else 0) + (if (cp1 > 0f) 1 else 0) + (if (cp2 > 0f) 1 else 0) + (if (cp3 > 0f) 1 else 0)
    return pCount == 4 || pCount == 0
}

private fun canvasToLayerLocal(canvasPos: Offset, layer: StudioLayer): Offset {
    // 1. Translation: shift relative to layer's top-left position
    val shifted = Offset(canvasPos.x - layer.positionX, canvasPos.y - layer.positionY)
    
    // 2. Rotation around pivot (layer.width * layer.pivotX, layer.height * layer.pivotY)
    val pivot = Offset(layer.width * layer.pivotX, layer.height * layer.pivotY)
    val toPivot = shifted - pivot
    val unrotated = rotateOffset(toPivot, -layer.rotation)
    val posAfterRotation = unrotated + pivot
    
    // 3. Scaling around pivot
    val unscaledX = (posAfterRotation.x - pivot.x) / layer.scaleX.coerceAtLeast(0.01f) + pivot.x
    val unscaledY = (posAfterRotation.y - pivot.y) / layer.scaleY.coerceAtLeast(0.01f) + pivot.y
    
    return Offset(unscaledX, unscaledY)
}

private fun layerLocalToCanvas(localPos: Offset, layer: StudioLayer): Offset {
    val pivot = Offset(layer.width * layer.pivotX, layer.height * layer.pivotY)
    // 1. Scale relative to pivot
    val scaledX = (localPos.x - pivot.x) * layer.scaleX + pivot.x
    val scaledY = (localPos.y - pivot.y) * layer.scaleY + pivot.y
    val scaled = Offset(scaledX, scaledY)
    
    // 2. Rotate relative to pivot
    val toPivot = scaled - pivot
    val rotated = rotateOffset(toPivot, layer.rotation)
    val posAfterRotation = rotated + pivot
    
    // 3. Translate relative to layer position
    return Offset(posAfterRotation.x + layer.positionX, posAfterRotation.y + layer.positionY)
}

open class CappedHistoryStack(private val maxLimit: Int = 40) {
    open val list = androidx.compose.runtime.mutableStateListOf<List<com.example.studio.model.StudioLayer>>()
    
    open val size: Int get() = list.size
    
    open fun isNotEmpty(): Boolean = list.isNotEmpty()
    open fun isEmpty(): Boolean = list.isEmpty()
    
    open fun add(element: List<com.example.studio.model.StudioLayer>) {
        list.add(element)
        while (list.size > maxLimit) {
            list.removeAt(0)
        }
    }
    
    open fun removeAt(index: Int): List<com.example.studio.model.StudioLayer> {
        return list.removeAt(index)
    }
    
    open fun clear() {
        list.clear()
    }
}

