    val angle: Float = 0f,
    val locked: Boolean = false,
    val isSymmetrical: Boolean = false,
    val symmetryMode: String = "Mirror", // "Mirror" (2-Way), "4-Way", "8-Way"
    val color: Long = 0xFFFF00FF // Color ARGB long (default Magenta)
)

