@Composable
fun BrushesLibraryOverlay(
    currentPreset: Int,
    onPresetChange: (Int) -> Unit,
    currentSize: Float,
    onSizeChange: (Float) -> Unit,
    currentOpacity: Float,
    onOpacityChange: (Float) -> Unit,
    currentColor: Color = Color.Black,
    currentSmoothing: Boolean = true,
    onClose: () -> Unit
) {
    Surface(
        color = SlatePanel,
        shape = RoundedCornerShape(16.dp),
        border = BorderStroke(1.2.dp, HighslateOutline),
        modifier = Modifier.padding(24.dp).fillMaxWidth(0.92f).wrapContentHeight()
    ) {
        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text("Paint Brush Library (${ALL_AVAILABLE_BRUSHES.size})", style = Typography.titleMedium, color = EnergeticYellow, fontWeight = FontWeight.Bold)
                IconButton(onClick = onClose) {
                    Icon(Icons.Default.Close, "Close", tint = TextSecondary)
                }
            }
            androidx.compose.foundation.lazy.grid.LazyVerticalGrid(
                columns = androidx.compose.foundation.lazy.grid.GridCells.Fixed(2),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
                modifier = Modifier.heightIn(max = 320.dp)
            ) {
                items(ALL_AVAILABLE_BRUSHES.size) { idx ->
                    val b = ALL_AVAILABLE_BRUSHES[idx]
                    val isSelected = b.index == currentPreset
                    Surface(
                        onClick = {
                            onPresetChange(b.index)
                            onSizeChange(b.defaultSize)
                        },
                        shape = RoundedCornerShape(10.dp),
                        color = if (isSelected) MidSlate else SlatePanel,
                        border = BorderStroke(1.dp, if (isSelected) IndustrialAmber else HighslateOutline)
                    ) {
                        Row(modifier = Modifier.padding(12.dp), verticalAlignment = Alignment.CenterVertically) {
                            Text(b.sampleChar, fontSize = 16.sp, color = IndustrialAmber)
                            Spacer(Modifier.width(8.dp))
                            Column {
                                Text(b.name, style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text(b.category, style = Typography.labelSmall, color = TextSecondary, fontSize = 10.sp)
                            }
                        }
                    }
                }
            }
        }
    }
}

fun parseFreehandStrokes(
    brushPoints: List<androidx.compose.ui.geometry.Offset>,
    defaultColor: androidx.compose.ui.graphics.Color = androidx.compose.ui.graphics.Color.Black,
    defaultSize: Float = 10f,
    defaultOpacity: Float = 1f,
    defaultPreset: Int = 0,
    defaultSmoothing: Boolean = true
): List<ParsedFreehandStroke> {
    if (brushPoints.isEmpty()) return emptyList()
    val strokesList = mutableListOf<ParsedFreehandStroke>()
    
    val rawStrokes = mutableListOf<List<androidx.compose.ui.geometry.Offset>>()
    var currentRawStroke = mutableListOf<androidx.compose.ui.geometry.Offset>()
    for (pt in brushPoints) {
        if (pt == androidx.compose.ui.geometry.Offset.Unspecified) {
            if (currentRawStroke.isNotEmpty()) {
                rawStrokes.add(currentRawStroke)
                currentRawStroke = mutableListOf()
            }
        } else {
            currentRawStroke.add(pt)
        }
    }
    if (currentRawStroke.isNotEmpty()) {
        rawStrokes.add(currentRawStroke)
    }

    var pendingEraser = false
    var pendingPreset = defaultPreset
    var pendingSize = defaultSize
    var pendingOpacity = defaultOpacity
    var pendingSmoothing = defaultSmoothing
    var pendingColor = defaultColor
    var pendingHardness = 0.5f
    var hasPendingHeader = false

    for (rawPtList in rawStrokes) {
        if (rawPtList.isEmpty()) continue

        // Check if this chunk is a 4-point header chunk
        val isSentinelHeader = rawPtList.size == 4 && rawPtList[0].x == -9999f
        val isLegacyHeader = rawPtList.size == 4 && (rawPtList[0].x in 0f..1f) && (rawPtList[1].x > 0f) && (rawPtList[3].y == 0f)

        if (isSentinelHeader) {
            pendingEraser = rawPtList[0].y > 0.5f
            pendingPreset = rawPtList[1].x.toInt()
            pendingSize = rawPtList[1].y
            pendingOpacity = rawPtList[2].x
            pendingSmoothing = rawPtList[2].y > 0.5f
            pendingHardness = rawPtList[3].x
            try {
                pendingColor = androidx.compose.ui.graphics.Color(rawPtList[3].y.toLong().toInt())
            } catch (t: Throwable) {
                pendingColor = defaultColor
            }
            hasPendingHeader = true
            continue
        } else if (isLegacyHeader) {
            pendingEraser = rawPtList[0].x > 0.5f
            pendingPreset = rawPtList[0].y.toInt()
            pendingSize = rawPtList[1].x
            pendingOpacity = rawPtList[1].y
            pendingSmoothing = rawPtList[2].x > 0.5f
            pendingHardness = rawPtList[2].y
            try {
                pendingColor = androidx.compose.ui.graphics.Color(rawPtList[3].x.toLong().toInt())
            } catch (t: Throwable) {
                pendingColor = defaultColor
            }
            hasPendingHeader = true
            continue
        }

        val strokeEraser = if (hasPendingHeader) pendingEraser else false
        val strokePreset = if (hasPendingHeader) pendingPreset else defaultPreset
        val strokeSize = if (hasPendingHeader) pendingSize else defaultSize
        val strokeOpacity = if (hasPendingHeader) pendingOpacity else defaultOpacity
        val strokeSmoothing = if (hasPendingHeader) pendingSmoothing else defaultSmoothing
        val strokeColor = if (hasPendingHeader) pendingColor else defaultColor
        val strokeHardness = if (hasPendingHeader) pendingHardness else 0.5f

        strokesList.add(
            ParsedFreehandStroke(
                isEraser = strokeEraser,
                presetIndex = strokePreset,
                size = strokeSize,
                opacity = strokeOpacity,
                smoothing = strokeSmoothing,
                hardness = strokeHardness,
                color = strokeColor,
                points = rawPtList
            )
        )
        hasPendingHeader = false
    }

    return strokesList
}

fun buildStrokeHeaderPoints(
    isEraser: Boolean,
    presetIndex: Int,
    size: Float,
    opacity: Float,
    smoothing: Boolean,
    hardness: Float = 0.5f,
    color: androidx.compose.ui.graphics.Color = androidx.compose.ui.graphics.Color.Black
): List<androidx.compose.ui.geometry.Offset> {
    return listOf(
        androidx.compose.ui.geometry.Offset(-9999f, if (isEraser) 1f else 0f),
        androidx.compose.ui.geometry.Offset(presetIndex.toFloat(), size),
        androidx.compose.ui.geometry.Offset(opacity, if (smoothing) 1f else 0f),
        androidx.compose.ui.geometry.Offset(hardness, color.toArgb().toFloat()),
        androidx.compose.ui.geometry.Offset.Unspecified
    )
}

@androidx.compose.runtime.Composable
fun <T> rememberBoundState(
    key: Any?,
    get: () -> T,
    set: (T) -> Unit
): androidx.compose.runtime.MutableState<T> {
    return remember(key) {
        object : androidx.compose.runtime.MutableState<T> {
            override var value: T
                get() = get()
                set(value) { set(value) }
            override fun component1(): T = value
            override fun component2(): (T) -> Unit = { value = it }
        }
    }
}

private fun projectPointOnRulerLine(
    px: Float,
    py: Float,
    ruler: StudioRuler,
    canvasWidth: Float,
    canvasHeight: Float,
    artboardOffsetX: Float = 0f,
    artboardOffsetY: Float = 0f
): Offset {
    val w = canvasWidth
    val h = canvasHeight
    val angleRad = (ruler.angle * Math.PI / 180.0)
    val dX: Float
    val dY: Float
    val aX: Float
    val aY: Float
    if (ruler.orientation == "Horizontal") {
        dX = Math.cos(angleRad).toFloat()
        dY = Math.sin(angleRad).toFloat()
        aX = artboardOffsetX + w / 2f
        aY = artboardOffsetY + ruler.position
    } else {
        dX = -Math.sin(angleRad).toFloat()
        dY = Math.cos(angleRad).toFloat()
        aX = artboardOffsetX + ruler.position
        aY = artboardOffsetY + h / 2f
    }
    val t = (px - aX) * dX + (py - aY) * dY
    val snappedX = aX + t * dX
    val snappedY = aY + t * dY
    return Offset(snappedX, snappedY)
}

private fun getSymmetricPoints(
    px: Float,
    py: Float,
    ruler: StudioRuler,
    canvasWidth: Float,
    canvasHeight: Float,
    artboardOffsetX: Float = 0f,
    artboardOffsetY: Float = 0f
): List<Offset> {
    if (!ruler.isSymmetrical) return emptyList()
    val w = canvasWidth
    val h = canvasHeight
    val angleRad = (ruler.angle * Math.PI / 180.0)
    val dX: Float
    val dY: Float
    val aX: Float
    val aY: Float
    if (ruler.orientation == "Horizontal") {
        dX = Math.cos(angleRad).toFloat()
        dY = Math.sin(angleRad).toFloat()
        aX = artboardOffsetX + w / 2f
        aY = artboardOffsetY + ruler.position
    } else {
        dX = -Math.sin(angleRad).toFloat()
        dY = Math.cos(angleRad).toFloat()
        aX = artboardOffsetX + ruler.position
        aY = artboardOffsetY + h / 2f
    }

    val t = (px - aX) * dX + (py - aY) * dY
    val projX = aX + t * dX
    val projY = aY + t * dY

    val results = mutableListOf<Offset>()

    when (ruler.symmetryMode) {
        "4-Way" -> {
            // 2-Way Mirror across ruler line
            val mirrX = 2f * projX - px
            val mirrY = 2f * projY - py
            results.add(Offset(mirrX, mirrY))

            // Perpendicular axis reflection
            val perpX = -dY
            val perpY = dX
            val tPerp = (px - aX) * perpX + (py - aY) * perpY
            val projPerpX = aX + tPerp * perpX
            val projPerpY = aY + tPerp * perpY

            val mirrPerpX = 2f * projPerpX - px
            val mirrPerpY = 2f * projPerpY - py
            results.add(Offset(mirrPerpX, mirrPerpY))

            val mirrBothX = 2f * aX - px
            val mirrBothY = 2f * aY - py
            results.add(Offset(mirrBothX, mirrBothY))
        }
        "8-Way" -> {
            // Radial 8-Way
            val dx = px - aX
            val dy = py - aY
            for (step in 1..7) {
                val rotAngle = step * (Math.PI / 4.0) // 45 degrees
                val cosA = Math.cos(rotAngle).toFloat()
                val sinA = Math.sin(rotAngle).toFloat()
                val rotX = aX + dx * cosA - dy * sinA
                val rotY = aY + dx * sinA + dy * cosA
                results.add(Offset(rotX, rotY))
            }
        }
        else -> {
            // Default: 2-Way Mirror across ruler line
            val mirrX = 2f * projX - px
            val mirrY = 2f * projY - py
            results.add(Offset(mirrX, mirrY))
        }
    }
    return results
}

private fun snapPointToRulers(
    px: Float,
    py: Float,
    rulers: List<StudioRuler>,
    canvasWidth: Float,
    canvasHeight: Float,
    artboardOffsetX: Float = 0f,
    artboardOffsetY: Float = 0f
): Offset {
    var bestPoints = Offset(px, py)
    var minDistanceSq = Float.MAX_VALUE
    for (ruler in rulers) {
        if (!ruler.enabled) continue
        val snapped = projectPointOnRulerLine(px, py, ruler, canvasWidth, canvasHeight, artboardOffsetX, artboardOffsetY)
        val distSq = (px - snapped.x) * (px - snapped.x) + (py - snapped.y) * (py - snapped.y)
        if (distSq < minDistanceSq) {
            minDistanceSq = distSq
            bestPoints = snapped
        }
    }
    return bestPoints
}

enum class ArtboardPlacementDirection {
    ABOVE, BELOW, LEFT, RIGHT
}

data class ArtboardData(
    val id: String = java.util.UUID.randomUUID().toString(),
    val name: String,
    val width: Float,
    val height: Float,
    val layers: List<com.example.studio.model.StudioLayer> = emptyList(),
    val renderedPdfBitmap: android.graphics.Bitmap? = null,
    val offsetX: Float = 0f,
    val offsetY: Float = 0f
)

fun importPdfToArtboards(
    context: android.content.Context,
    uri: android.net.Uri,
    scope: kotlinx.coroutines.CoroutineScope,
    onComplete: (List<ArtboardData>) -> Unit
) {
    scope.launch(kotlinx.coroutines.Dispatchers.IO) {
        val result = mutableListOf<ArtboardData>()
        try {
            val contentResolver = context.contentResolver
            val tempFile = File(context.cacheDir, "imported_${System.currentTimeMillis()}.pdf")
            contentResolver.openInputStream(uri)?.use { input ->
                tempFile.outputStream().use { output ->
                    input.copyTo(output)
                }
            }
            
            val parcelFileDescriptor = android.os.ParcelFileDescriptor.open(tempFile, android.os.ParcelFileDescriptor.MODE_READ_ONLY)
            val pdfRenderer = android.graphics.pdf.PdfRenderer(parcelFileDescriptor)
            val pageCount = pdfRenderer.pageCount
            
            val importedDir = File(context.filesDir, "pdf_imports")
            if (!importedDir.exists()) importedDir.mkdirs()
            
            var currentOffsetX = 0f
            for (i in 0 until pageCount) {
                val page = pdfRenderer.openPage(i)
                val width = page.width.toFloat()
                val height = page.height.toFloat()
                
                val bitmapWidth = (page.width * 2).coerceAtMost(2048)
                val bitmapHeight = (page.height * 2).coerceAtMost(2048)
                
                val bitmap = android.graphics.Bitmap.createBitmap(bitmapWidth, bitmapHeight, android.graphics.Bitmap.Config.ARGB_8888)
                page.render(bitmap, null, null, android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                
                val pageFile = File(importedDir, "page_${System.currentTimeMillis()}_$i.png")
                pageFile.outputStream().use { out ->
                    bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, out)
                }
                
                page.close()
                
                val layerId = java.util.UUID.randomUUID().toString()
                val pdfImageLayer = com.example.studio.model.StudioLayer(
                    id = layerId,
                    name = "PDF Page ${i + 1}",
                    type = com.example.studio.model.LayerType.IMAGE_CARD,
                    positionX = 0f,
                    positionY = 0f,
                    width = width,
                    height = height,
                    imageUri = pageFile.absolutePath
                )
                
                val artboardId = java.util.UUID.randomUUID().toString()
                result.add(
                    ArtboardData(
                        id = artboardId,
                        name = "PDF Page ${i + 1}",
                        width = width,
                        height = height,
                        layers = listOf(pdfImageLayer),
                        renderedPdfBitmap = bitmap,
                        offsetX = currentOffsetX,
                        offsetY = 0f
                    )
                )
                currentOffsetX += width + 400f
            }
            pdfRenderer.close()
            parcelFileDescriptor.close()
            tempFile.delete()
        } catch (e: Exception) {
            e.printStackTrace()
            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                android.widget.Toast.makeText(context, "Failed to parse PDF: ${e.localizedMessage}", android.widget.Toast.LENGTH_LONG).show()
            }
        }
        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
            onComplete(result)
        }
    }
}

fun isDownloadableAsset(url: String): Boolean {
    val lower = url.lowercase()
    return lower.endsWith(".ttf") || lower.endsWith(".otf") || 
           lower.endsWith(".png") || lower.endsWith(".jpg") || 
           lower.endsWith(".jpeg") || lower.endsWith(".webp") || 
           lower.endsWith(".zip")
}

fun triggerAssetDownload(
    context: android.content.Context,
    urlStr: String,
    targetType: String,
    workspaceViewModel: com.example.studio.viewmodel.WorkspaceViewModel,
    scope: kotlinx.coroutines.CoroutineScope,
    onAssetSaved: (String) -> Unit
) {
    android.widget.Toast.makeText(context, "Direct download started...", android.widget.Toast.LENGTH_SHORT).show()
    scope.launch(kotlinx.coroutines.Dispatchers.IO) {
        try {
            val connection = java.net.URL(urlStr).openConnection() as java.net.HttpURLConnection
            connection.requestMethod = "GET"
            connection.connect()
            
            if (connection.responseCode == 200) {
                val contentDisposition = connection.getHeaderField("Content-Disposition")
                var filename = ""
                if (!contentDisposition.isNullOrEmpty()) {
                    val index = contentDisposition.indexOf("filename=")
                    if (index > 0) {
                        filename = contentDisposition.substring(index + 9).replace("\"", "").trim()
                    }
                }
                if (filename.isEmpty()) {
                    filename = urlStr.substring(urlStr.lastIndexOf('/') + 1)
                    if (filename.indexOf('?') > 0) {
                        filename = filename.substring(0, filename.indexOf('?'))
                    }
                }
                if (filename.isEmpty()) {
                    filename = "asset_" + System.currentTimeMillis() + if (targetType == "Font") ".ttf" else ".png"
                }
                
                if (filename.endsWith(".zip", ignoreCase = true)) {
                    val zipInputStream = java.util.zip.ZipInputStream(connection.inputStream)
                    var entry = zipInputStream.nextEntry
                    val fontsDir = File(context.filesDir, "fonts")
                    if (!fontsDir.exists()) fontsDir.mkdirs()
                    
                    var count = 0
                    while (entry != null) {
                        if (!entry.isDirectory) {
                            val entryName = entry.name
                            val ext = entryName.substring(entryName.lastIndexOf('.') + 1).lowercase()
                            if (ext == "ttf" || ext == "otf") {
                                val outFontFile = File(fontsDir, File(entryName).name)
                                outFontFile.outputStream().use { fos ->
                                    zipInputStream.copyTo(fos)
                                }
                                val fontName = outFontFile.nameWithoutExtension.replace("_", " ").replace("-", " ")
                                workspaceViewModel.addCustomFont(fontName, outFontFile.absolutePath, "Display")
                                count++
                            } else if (ext in listOf("png", "jpg", "jpeg", "webp")) {
                                val imagesDir = File(context.filesDir, "downloaded_images")
                                if (!imagesDir.exists()) imagesDir.mkdirs()
                                val outImgFile = File(imagesDir, File(entryName).name)
                                outImgFile.outputStream().use { fos ->
                                    zipInputStream.copyTo(fos)
                                }
                                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                    onAssetSaved(outImgFile.absolutePath)
                                }
                                count++
                            }
                        }
                        zipInputStream.closeEntry()
                        entry = zipInputStream.nextEntry
                    }
                    zipInputStream.close()
                    kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                        android.widget.Toast.makeText(context, "ZIP Extracted successfully! $count items imported.", android.widget.Toast.LENGTH_LONG).show()
                    }
                } else {
                    val extension = if (filename.contains(".")) filename.substring(filename.lastIndexOf('.')) else ""
                    if (targetType == "Font" || extension.lowercase() in listOf(".ttf", ".otf")) {
                        val fontsDir = File(context.filesDir, "fonts")
                        if (!fontsDir.exists()) fontsDir.mkdirs()
                        val fontFile = File(fontsDir, filename)
                        connection.inputStream.use { pin ->
                            fontFile.outputStream().use { pout ->
                                pin.copyTo(pout)
                            }
                        }
                        val fontName = fontFile.nameWithoutExtension.replace("_", " ").replace("-", " ")
                        workspaceViewModel.addCustomFont(fontName, fontFile.absolutePath, "Display")
                        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                            android.widget.Toast.makeText(context, "Font '$fontName' added directly/selectable!", android.widget.Toast.LENGTH_LONG).show()
                        }
                    } else {
                        val imagesDir = File(context.filesDir, "downloaded_images")
                        if (!imagesDir.exists()) imagesDir.mkdirs()
                        val imageFile = File(imagesDir, filename)
                        connection.inputStream.use { pin ->
                            imageFile.outputStream().use { pout ->
                                pin.copyTo(pout)
                            }
                        }
                        kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                            onAssetSaved(imageFile.absolutePath)
                        }
                    }
                }
            } else {
                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                    android.widget.Toast.makeText(context, "Network download returned: ${connection.responseCode}", android.widget.Toast.LENGTH_LONG).show()
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
            kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                android.widget.Toast.makeText(context, "Error downloading: ${e.localizedMessage}", android.widget.Toast.LENGTH_SHORT).show()
            }
        }
    }
}

