@Composable
fun BrushStudioControlPane(
    currentPreset: Int = 0,
    currentSize: Float = 10f,
    currentOpacity: Float = 1f,
    currentColor: Color = Color.Black,
    currentSmoothing: Boolean = true,
    updateBrushParams: (Float?, Float?, Boolean?, Int?, Color?, Float?) -> Unit = { _, _, _, _, _, _ -> },
    onOpenBrushesLibrary: () -> Unit = {},
    activeBrushIndex: Int = 0,
    onActiveBrushIndexChange: (Int) -> Unit = {},
    brushSize: Float = 10f,
    onBrushSizeChange: (Float) -> Unit = {},
    brushOpacity: Float = 1f,
    onBrushOpacityChange: (Float) -> Unit = {},
    brushHardness: Float = 0.5f,
    onBrushHardnessChange: (Float) -> Unit = {},
