    onBrushColorChange: (Color) -> Unit = {},
    gridEnabled: Boolean = false,
    onGridEnabledChange: (Boolean) -> Unit = {},
    rulerEnabled: Boolean = false,
    onRulerEnabledChange: (Boolean) -> Unit = {},
    rulerOrientation: String = "Horizontal",
    onRulerOrientationChange: (String) -> Unit = {},
    rulerPosition: Float = 0f,
    onRulerPositionChange: (Float) -> Unit = {},
    activeTool: String = "Brush",
    eraserSize: Float = 20f,
    onEraserSizeChange: (Float) -> Unit = {},
    eraserHardness: Float = 0.5f,
    onEraserHardnessChange: (Float) -> Unit = {},
    projectColorProfile: String = "RGB",
    selectedCmykProfile: String = "",
    modifier: Modifier = Modifier
) {
    Column(
        modifier = modifier
            .fillMaxWidth()
            .padding(12.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        if (activeTool == "Eraser") {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.AutoFixNormal,
                        contentDescription = "Eraser",
                        tint = EnergeticYellow,
                        modifier = Modifier.size(20.dp)
                    )
                    Spacer(Modifier.width(8.dp))
                    Text("Eraser Tool Config", style = Typography.titleSmall, color = TextPrimary, fontWeight = FontWeight.Bold)
                }
                Button(
                    onClick = onOpenBrushesLibrary,
                    colors = ButtonDefaults.buttonColors(containerColor = MidSlate),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp)
                ) {
                    Icon(imageVector = Icons.Default.Brush, contentDescription = null, tint = IndustrialAmber, modifier = Modifier.size(16.dp))
                    Spacer(Modifier.width(4.dp))
                    Text("Brushes (${ALL_AVAILABLE_BRUSHES.size})", style = Typography.labelSmall, color = TextPrimary)
                }
            }

            PrecisionJogWheel(
                value = eraserSize,
                onValueChange = { newSize ->
                    onEraserSizeChange(newSize)
                    updateBrushParams(newSize, null, null, null, null, null)
                },
                valueRange = 1f..300f,
                label = "Eraser Size (px)",
                isInt = true
            )

            PrecisionJogWheel(
                value = eraserHardness * 100f,
                onValueChange = { newHardness ->
                    val h = newHardness / 100f
                    onEraserHardnessChange(h)
                    updateBrushParams(null, null, null, null, null, h)
                },
                valueRange = 0f..100f,
                label = "Eraser Hardness (%)",
                isInt = true
            )
        } else {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                val activeBrush = ALL_AVAILABLE_BRUSHES.find { it.index == currentPreset } ?: ALL_AVAILABLE_BRUSHES[0]
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        imageVector = Icons.Default.Brush,
                        contentDescription = "Brush",
                        tint = IndustrialAmber,
                        modifier = Modifier.size(20.dp)
                    )
                    Spacer(Modifier.width(8.dp))
                    Column {
                        Text(activeBrush.name, style = Typography.titleSmall, color = TextPrimary, fontWeight = FontWeight.Bold)
                        Text("${activeBrush.category} • Preset #${activeBrush.index}", style = Typography.labelSmall, color = TextSecondary, fontSize = 10.sp)
                    }
                }

                Button(
                    onClick = onOpenBrushesLibrary,
                    colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp)
                ) {
                    Icon(imageVector = Icons.Default.LibraryBooks, contentDescription = null, tint = Color.Black, modifier = Modifier.size(16.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Library (${ALL_AVAILABLE_BRUSHES.size})", style = Typography.labelSmall, color = Color.Black, fontWeight = FontWeight.Bold)
                }
            }

            // Quick Preset Selection Carousel
            Text("Quick Presets", style = Typography.labelSmall, color = TextSecondary)
            androidx.compose.foundation.lazy.LazyRow(
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                items(ALL_AVAILABLE_BRUSHES.size) { idx ->
                    val b = ALL_AVAILABLE_BRUSHES[idx]
                    val isSelected = b.index == currentPreset
                    Surface(
                        onClick = {
                            updateBrushParams(b.defaultSize, null, null, b.index, null, null)
                        },
                        shape = RoundedCornerShape(8.dp),
                        color = if (isSelected) MidSlate else Color(0xFF131317),
                        border = BorderStroke(1.dp, if (isSelected) IndustrialAmber else HighslateOutline.copy(alpha = 0.5f)),
                        modifier = Modifier.padding(vertical = 2.dp)
                    ) {
                        Row(
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = if (b.sampleChar.isNotEmpty()) b.sampleChar else "✎",
                                fontSize = 12.sp,
                                color = if (isSelected) EnergeticYellow else TextSecondary
                            )
                            Spacer(Modifier.width(6.dp))
                            Text(
                                text = b.name,
                                style = Typography.labelSmall,
                                color = if (isSelected) TextPrimary else TextSecondary,
                                fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal
