                        }
                    }
                }
            }

            PrecisionJogWheel(
                value = currentSize,
                onValueChange = { newSize ->
                    onBrushSizeChange(newSize)
                    updateBrushParams(newSize, null, null, null, null, null)
                },
                valueRange = 1f..300f,
                label = "Brush Size (px)",
                isInt = true
            )

            PrecisionJogWheel(
                value = currentOpacity * 100f,
                onValueChange = { newOpacity ->
                    val op = newOpacity / 100f
                    onBrushOpacityChange(op)
                    updateBrushParams(null, op, null, null, null, null)
                },
                valueRange = 0f..100f,
                label = "Opacity (%)",
                isInt = true
            )

            PrecisionJogWheel(
                value = brushHardness * 100f,
                onValueChange = { newHardness ->
                    val h = newHardness / 100f
                    onBrushHardnessChange(h)
                    updateBrushParams(null, null, null, null, null, h)
                },
                valueRange = 0f..100f,
                label = "Hardness (%)",
                isInt = true
            )

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text("Streamline / Smoothing", style = Typography.labelMedium, color = TextPrimary)
                Switch(
                    checked = currentSmoothing,
                    onCheckedChange = { smooth ->
                        updateBrushParams(null, null, smooth, null, null, null)
                    },
                    colors = SwitchDefaults.colors(checkedThumbColor = IndustrialAmber)
                )
            }
        }
    }
}

