            }
        }

        // Active Selected Guide Controls
        if (activeRuler != null) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "Guide: ${activeRuler.name} (${activeRuler.orientation})",
                    style = Typography.labelSmall,
                    fontSize = 11.sp,
                    color = EnergeticYellow,
                    fontWeight = FontWeight.Bold
                )

                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                    Button(
                        onClick = {
                            settings.onRulersChange(currentRulers.filter { it.id != activeRuler.id })
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF331C1C)),
                        border = BorderStroke(0.5.dp, Color(0xFFFF5252)),
                        shape = RoundedCornerShape(4.dp),
                        contentPadding = PaddingValues(horizontal = 6.dp, vertical = 2.dp),
                        modifier = Modifier.height(26.dp)
                    ) {
                        Text("Delete Guide", fontSize = 9.sp, color = Color(0xFFFF5252), fontWeight = FontWeight.Bold)
                    }

                    if (currentRulers.size > 1) {
                        Button(
                            onClick = {
                                settings.onRulersChange(emptyList())
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF222630)),
                            border = BorderStroke(0.5.dp, HighslateOutline),
                            shape = RoundedCornerShape(4.dp),
                            contentPadding = PaddingValues(horizontal = 6.dp, vertical = 2.dp),
                            modifier = Modifier.height(26.dp)
                        ) {
                            Text("Clear All", fontSize = 9.sp, color = TextSecondary, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }

            PrecisionJogWheel(
                value = activeRuler.position,
                onValueChange = { newPos ->
                    settings.onRulersChange(currentRulers.map { if (it.id == activeRuler.id) it.copy(position = newPos) else it })
                },
                valueRange = -2000f..4000f,
                label = "Guide Position (px)",
                isInt = true
            )

            PrecisionJogWheel(
                value = activeRuler.angle,
                onValueChange = { newAng ->
                    settings.onRulersChange(currentRulers.map { if (it.id == activeRuler.id) it.copy(angle = newAng) else it })
                },
                valueRange = -180f..180f,
                label = "Guide Rotation Angle (°)",
                isInt = true
            )
        } else {
            Text("No guide created yet. Tap '+ Horizontal' or '+ Vertical' above to add alignment guides.", style = Typography.labelSmall, fontSize = 10.sp, color = TextSecondary)
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun WorkspaceScreen(modifier: Modifier = Modifier) {
    val context = androidx.compose.ui.platform.LocalContext.current
    globalAppContext = context.applicationContext
    val workspaceViewModel: WorkspaceViewModel = viewModel()

    LaunchedEffect(Unit) {
        val pref = context.getSharedPreferences("studio_prefs", android.content.Context.MODE_PRIVATE)
        workspaceLayoutMode = pref.getString("workspace_layout_mode", "Classic") ?: "Classic"
        toolPanelSide = pref.getString("tool_panel_side", "Left") ?: "Left"
        controlBarPosition = pref.getString("control_bar_position", "Top") ?: "Top"
    }

    val previousProjects by workspaceViewModel.previousProjects.collectAsStateWithLifecycle()
    val customFonts by workspaceViewModel.customFonts.collectAsStateWithLifecycle()
    val scope = rememberCoroutineScope()
    val rasterGraphicsLayer = androidx.compose.ui.graphics.rememberGraphicsLayer()


    val configuration = androidx.compose.ui.platform.LocalConfiguration.current
    val systemLandscape = configuration.orientation == android.content.res.Configuration.ORIENTATION_LANDSCAPE ||
                          configuration.screenWidthDp > configuration.screenHeightDp
    var manualLandscapeOverride by remember { mutableStateOf<Boolean?>(null) }
    val isLandscape = manualLandscapeOverride ?: systemLandscape

    LaunchedEffect(configuration.orientation) {
        manualLandscapeOverride = null
    }

    val displayMetrics = context.resources.displayMetrics
    val screenWidth = displayMetrics.widthPixels.toFloat()
    val screenHeight = displayMetrics.heightPixels.toFloat()
    val deviceAspect = if (screenWidth > 0f) screenHeight / screenWidth else 1350f / 1080f
    val defaultHeightStr = (1080f * deviceAspect).toInt().toString()

    // Base Workspace State properties
    var projectId by remember { mutableStateOf("") }
    var projectName by remember { mutableStateOf("") }
    var projectDpi by remember { mutableStateOf(300) }
    var canvasWidth by remember { mutableStateOf(1080f) }
    var canvasHeight by remember { mutableStateOf(1080f * deviceAspect) }
    var projectColorProfile by remember { mutableStateOf("RGB") }
    var selectedCmykProfile by remember { mutableStateOf("Coated FOGRA39 (Premium Glossy)") }

    var artboards by remember {
        mutableStateOf(
            listOf(
                ArtboardData(
                    id = "default",
                    name = "Artboard 1",
                    width = 1080f,
                    height = 1350f,
                    layers = emptyList()
                )
            )
        )
    }
    var selectedArtboardId by remember { mutableStateOf("default") }
    
    var layers by remember {
        mutableStateOf(emptyList<com.example.studio.model.StudioLayer>())
    }
    var selectedLayerId by remember { mutableStateOf("") }
    var showPerformanceOptimizerDialog by remember { mutableStateOf(false) }
    var showWelcomeCommunityDialog by remember { mutableStateOf(true) }
    var showExportProgressDialog by remember { mutableStateOf(false) }
    var exportProgressValue by remember { mutableStateOf(0f) }
    var exportProgressText by remember { mutableStateOf("Preparing export...") }
    var exportJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }


    val projectHistoryManager = remember(projectId) {
        com.example.studio.model.ProjectHistoryManager(context, scope, 40)
    }

    val undoStack = remember(projectHistoryManager, artboards, selectedArtboardId, selectedLayerId, projectName, canvasWidth, canvasHeight, projectDpi, layers) {
        object : CappedHistoryStack(40) {
            override val size: Int get() = projectHistoryManager.undoStack.size
            override fun isNotEmpty(): Boolean = projectHistoryManager.undoStack.isNotEmpty()
            override fun isEmpty(): Boolean = projectHistoryManager.undoStack.isEmpty()
            override fun add(element: List<com.example.studio.model.StudioLayer>) {
                val currentMemento = com.example.studio.model.ProjectMemento(
                    artboards = artboards.map {
                        if (it.id == selectedArtboardId) {
                            it.copy(layers = layers)
                        } else {
                            it
                        }
                    },
                    selectedArtboardId = selectedArtboardId,
                    selectedLayerId = selectedLayerId,
                    projectName = projectName,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    projectDpi = projectDpi
                )
                projectHistoryManager.pushState(currentMemento)
            }
            override fun removeAt(index: Int): List<com.example.studio.model.StudioLayer> {
                return layers
            }
            override fun clear() {
                projectHistoryManager.undoStack.clear()
            }
        }
    }

    val redoStack = remember(projectHistoryManager, artboards, selectedArtboardId, selectedLayerId, projectName, canvasWidth, canvasHeight, projectDpi, layers) {
        object : CappedHistoryStack(40) {
            override val size: Int get() = projectHistoryManager.redoStack.size
            override fun isNotEmpty(): Boolean = projectHistoryManager.redoStack.isNotEmpty()
            override fun isEmpty(): Boolean = projectHistoryManager.redoStack.isEmpty()
            override fun add(element: List<com.example.studio.model.StudioLayer>) {
                // REDO stack addition is handled internally by projectHistoryManager when undo is performed
            }
            override fun removeAt(index: Int): List<com.example.studio.model.StudioLayer> {
                return layers
            }
            override fun clear() {
                projectHistoryManager.redoStack.clear()
            }
        }
    }
    var showRenameProjectDialog by remember { mutableStateOf(false) }
    var projectRenameValue by remember { mutableStateOf("") }

    var showFontScannerDialog by remember { mutableStateOf(false) }
    var discoveredFonts by remember { mutableStateOf<List<com.example.studio.ui.FontScanner.DiscoveredFont>>(emptyList()) }
    val selectedFontIndexes = remember { androidx.compose.runtime.mutableStateMapOf<Int, Boolean>() }
    var selectedFontCount by remember { mutableStateOf(0) }
    var isFontScanning by remember { mutableStateOf(false) }
    var isBatchImportingFonts by remember { mutableStateOf(false) }
    var fontScanStatusMessage by remember { mutableStateOf("") }
    val selectedFoldersToScan = remember { androidx.compose.runtime.mutableStateMapOf<String, Boolean>().apply {
        put("Download", true)
        put("Fonts", true)
        put("Documents", false)
        put("MediaStore", true)
        put("Root", false)
    } }

    var hasStoragePermission by remember {
        mutableStateOf(
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
                true
            } else {
                androidx.core.content.ContextCompat.checkSelfPermission(
                    context,
                    android.Manifest.permission.READ_EXTERNAL_STORAGE
                ) == android.content.pm.PackageManager.PERMISSION_GRANTED
            }
        )
    }

    // Multi-artboard engine states are declared at the top of WorkspaceScreen

