    var showImportOptionMenu by remember { mutableStateOf(false) }
    var showElementsImportDialog by remember { mutableStateOf(false) }
    var showImportImageSelectionDialog by remember { mutableStateOf(false) }
    var showImportFontSelectionDialog by remember { mutableStateOf(false) }
    var showWebBrowserOverlay by remember { mutableStateOf(false) }
    var showPngSearchOverlay by remember { mutableStateOf(false) }
    var webBrowserTargetType by remember { mutableStateOf("Image") } // "Image" or "Font"
    var webBrowserUrl by remember { mutableStateOf("https://unsplash.com") }
    var showVisualsOverlayHub by remember { mutableStateOf(false) }

    // Initial layers are declared at the top of WorkspaceScreen

    LaunchedEffect(layers) {
        artboards = artboards.map {
            if (it.id == selectedArtboardId) {
                it.copy(layers = layers)
            } else {
                it
            }
        }
    }

    fun com.example.studio.model.StudioLayer.deepCloneForClipboard(): com.example.studio.model.StudioLayer {
        val clonedEffects = this.effects.map { effect ->
            when (effect) {
                is com.example.studio.model.StudioEffect.GaussianBlur -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
                is com.example.studio.model.StudioEffect.InnerGlow -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
                is com.example.studio.model.StudioEffect.ColorBalance -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
                is com.example.studio.model.StudioEffect.Invert -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
                is com.example.studio.model.StudioEffect.Threshold -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
                is com.example.studio.model.StudioEffect.Posterize -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
                is com.example.studio.model.StudioEffect.PhotoshopEffect -> effect.copy(
                    id = java.util.UUID.randomUUID().toString(),
                    parameters = effect.parameters.mapValues { (_, value) -> value.copy() }
                )
            }
        }
        val clonedPoints = ArrayList(this.brushPoints)
        return this.copy(
            id = java.util.UUID.randomUUID().toString(),
            effects = clonedEffects,
            brushPoints = clonedPoints
        )
    }

    // selectedLayerId is declared at the top of WorkspaceScreen
    var activeClipboard by remember { mutableStateOf<com.example.studio.model.StudioLayer?>(null) }

    LaunchedEffect(selectedArtboardId) {
        val activeArtboard = artboards.find { it.id == selectedArtboardId }
        if (activeArtboard != null) {
            layers = activeArtboard.layers
        }
    }

    val selectArtboard: (String) -> Unit = { targetId ->
        artboards = artboards.map {
            if (it.id == selectedArtboardId) {
                it.copy(layers = layers)
            } else {
                it
            }
        }
        selectedArtboardId = targetId
        val targetArtboard = artboards.find { it.id == targetId }
        if (targetArtboard != null) {
            layers = targetArtboard.layers
        }
        selectedLayerId = ""
    }

    val selectArtboardAndLayer: (String, String) -> Unit = { artId, layId ->
        artboards = artboards.map {
            if (it.id == selectedArtboardId) {
                it.copy(layers = layers)
            } else {
                it
            }
        }
        selectedArtboardId = artId
        val targetArtboard = artboards.find { it.id == artId }
        if (targetArtboard != null) {
            layers = targetArtboard.layers
        }
        selectedLayerId = layId
    }

    val addArtboard: (String, Float, Float, ArtboardPlacementDirection, Float) -> Unit = { name, w, h, direction, spacing ->
        val newId = java.util.UUID.randomUUID().toString()
        val target = artboards.find { it.id == selectedArtboardId }
        val (newX, newY) = if (target != null) {
            val tw = target.width
            val th = target.height
            val tx = target.offsetX
            val ty = target.offsetY
            when (direction) {
                ArtboardPlacementDirection.RIGHT -> Pair(tx + tw + spacing, ty)
                ArtboardPlacementDirection.LEFT -> Pair(tx - w - spacing, ty)
                ArtboardPlacementDirection.BELOW -> Pair(tx, ty + th + spacing)
                ArtboardPlacementDirection.ABOVE -> Pair(tx, ty - h - spacing)
            }
        } else {
            Pair(0f, 0f)
        }
        val newArtboard = ArtboardData(
            id = newId,
            name = name.ifBlank { "Artboard ${artboards.size + 1}" },
            width = w.coerceIn(100f, 8000f),
            height = h.coerceIn(100f, 8000f),
            layers = emptyList(),
            offsetX = newX,
            offsetY = newY
        )
        artboards = artboards.map {
            if (it.id == selectedArtboardId) {
                it.copy(layers = layers)
            } else {
                it
            }
        } + newArtboard
        
        selectedArtboardId = newId
        layers = emptyList()
        selectedLayerId = ""
    }

    val duplicateArtboard: (ArtboardData) -> Unit = { source ->
        val newId = java.util.UUID.randomUUID().toString()
        val spacing = 100f
        val sourceLayers = if (source.id == selectedArtboardId) layers else source.layers
        val clonedLayers = sourceLayers.map { originalLayer ->
            val newLayerId = java.util.UUID.randomUUID().toString()
            com.aistudio.zenithstudio.rpxwtq.EffectStackManager.duplicateFiltersForLayer(originalLayer.id, newLayerId)
            com.example.studio.ui.ParametricLayerCache.duplicateNode(originalLayer.id, newLayerId)
            originalLayer.copy(
                id = newLayerId,
                effects = originalLayer.effects.map { eff -> eff.duplicate() }
            )
        }
        val newArtboard = ArtboardData(
            id = newId,
            name = "${source.name} Copy",
            width = source.width,
            height = source.height,
            layers = clonedLayers,
            offsetX = source.offsetX + source.width + spacing,
            offsetY = source.offsetY
        )
        artboards = artboards.map {
            if (it.id == selectedArtboardId) it.copy(layers = layers) else it
        } + newArtboard
        selectedArtboardId = newId
        layers = clonedLayers
        selectedLayerId = clonedLayers.firstOrNull()?.id ?: ""
    }

    val pdfLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            importPdfToArtboards(context, it, scope) { importedArtboards ->
                if (importedArtboards.isNotEmpty()) {
                    artboards = artboards + importedArtboards
                    selectedArtboardId = importedArtboards.first().id
                    layers = importedArtboards.first().layers
                    selectedLayerId = ""
                    android.widget.Toast.makeText(context, "Successfully converted ${importedArtboards.size} PDF pages to active workspaces!", android.widget.Toast.LENGTH_LONG).show()
                }
            }
        }
    }
    var snapVerticalLine by remember { mutableStateOf<Float?>(null) }
    var snapHorizontalLine by remember { mutableStateOf<Float?>(null) }
    var snapIndicatorMsg by remember { mutableStateOf<String?>(null) }
    var activeTool by remember { mutableStateOf("Move") } // Brush, Move, Shapes, Text
    var penSubTool by remember { mutableStateOf("Standard") } // Standard, Freeform, AddAnchor, DeleteAnchor, ConvertPoint
    var freeformPenPoints by remember { mutableStateOf<List<Offset>>(emptyList()) }
    var shapeBuilderMode by remember { mutableStateOf("Merge") } // "Merge", "Subtract"
    var shapeBuilderTurnIntoPath by remember { mutableStateOf(true) }
    var isDraggingBezierNode by remember { mutableStateOf(false) }
    val shapeBuilderDragPoints = remember { mutableStateListOf<Offset>() }

    // History stacks are declared lower down after canvas size variables are initialized

    // State managers for dynamic brush parameters
    var brushSize by remember { mutableStateOf(16f) }
    var eraserSize by remember { mutableStateOf(24f) }
    var eraserHardness by remember { mutableStateOf(0.5f) }
    var brushHardness by remember { mutableStateOf(0.5f) }
    var brushOpacity by remember { mutableStateOf(1.0f) }
    var brushColor by remember { mutableStateOf(Color(0xFFFFB300)) }
    var brushSmoothing by remember { mutableStateOf(true) }
    var brushPresetIndex by remember { mutableStateOf(0) }
    val strokeTracker = remember { OpenGLBrushRenderer.HighPerformanceStrokeTracker() }
    val strokeDrawTrigger = remember { mutableStateOf(0) }
    var debounceUpdateLayerJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }
    var currentStrokePoints by remember { mutableStateOf<List<Offset>>(emptyList()) }
    val sharedTransformMatrix = remember { androidx.compose.ui.graphics.Matrix() }
    var reusableBackdropBitmap by remember { mutableStateOf<android.graphics.Bitmap?>(null) }
    var activeBezierPointIndex by remember { mutableStateOf(-1) }
    var lastPenClickTime by remember { mutableStateOf(0L) }
    var lastPenClickIndex by remember { mutableStateOf(-1) }
    var keepBezierSymmetrical by remember { mutableStateOf(true) }
    var warpRepeatMode by remember { mutableStateOf("Off") }
    var warpRepeatX by remember { mutableStateOf(1f) }
    var warpRepeatY by remember { mutableStateOf(1f) }
    var warpPhaseX by remember { mutableStateOf(0f) }
    var warpPhaseY by remember { mutableStateOf(0f) }
    var warpInterpolation by remember { mutableStateOf(true) }
    var warpTarget by remember { mutableStateOf("Layer") }
    var warpMeshDivisionX by remember { mutableStateOf(3) }
    var warpMeshDivisionY by remember { mutableStateOf(3) }
    var activeWarpNodeIndex by remember { mutableStateOf(-1) }

    LaunchedEffect(selectedLayerId) {
        val sel = layers.find { it.id == selectedLayerId }
        if (sel == null || sel.type != com.example.studio.model.LayerType.VECTOR_BEZIER) {
            activeBezierPointIndex = -1
        } else if (!(sel.brushPoints.size == 3 && activeBezierPointIndex == 0)) {
            activeBezierPointIndex = -1
        }
        activeWarpNodeIndex = -1
        if (activeTool == "Perspective" || activeTool == "Mesh" || (activeTool == "Pen" && sel != null && sel.type != com.example.studio.model.LayerType.VECTOR_BEZIER)) {
            activeTool = "Move"
        }
        if (sel != null) {
            warpRepeatMode = sel.warpRepeatMode
            warpRepeatX = sel.warpRepeatX
            warpRepeatY = sel.warpRepeatY
            warpPhaseX = sel.warpPhaseX
            warpPhaseY = sel.warpPhaseY
            warpInterpolation = sel.warpInterpolation
            warpTarget = sel.warpTarget
            warpMeshDivisionX = sel.warpMeshDivisionX
            warpMeshDivisionY = sel.warpMeshDivisionY
        }
    }
    var initialWarpPointsStr by remember { mutableStateOf("") }
    var activeGradientStopIndex by remember { mutableStateOf(-1) }
    var showGradientColorPickerDialog by remember { mutableStateOf(false) }
    var penCursorOffset by remember { mutableStateOf<Offset?>(null) }

    var isResizingActive by remember { mutableStateOf(false) }
    var activeResizingLayerId by remember { mutableStateOf<String?>(null) }
    var liveDragScaleX by remember { mutableStateOf(1.0f) }
    var liveDragScaleY by remember { mutableStateOf(1.0f) }
    var liveDragPivotX by remember { mutableStateOf(-1f) }
    var liveDragPivotY by remember { mutableStateOf(-1f) }
    var shapeAnchorMode by remember { mutableStateOf("CENTER") } // "CENTER", "OPPOSITE", "ORIGIN"
    var showShapeAnchorMenu by remember { mutableStateOf(false) }
    var startingLayerForResize by remember { mutableStateOf<com.example.studio.model.StudioLayer?>(null) }

    // Floating UI selector for adding specific shapes
    var showAddShapeDialog by remember { mutableStateOf(false) }
    var showBrushesLibrary by remember { mutableStateOf(false) }

    val currentSessionOpt by workspaceViewModel.sessionState.collectAsStateWithLifecycle()
    val currentSession = currentSessionOpt ?: CanvasSessionState(projectId = projectId)

    var rulers by rememberBoundState(
        key = currentSession,
        get = { currentSession.rulers },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(rulers = newValue) } }
    )
    var selectedRulerId by rememberBoundState(
        key = currentSession,
        get = { currentSession.selectedRulerId },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(selectedRulerId = newValue) } }
    )
    val activeRuler = rulers.find { it.id == selectedRulerId } ?: rulers.firstOrNull() ?: StudioRuler()
    val rulerEnabled = activeRuler.enabled
    val rulerOrientation = activeRuler.orientation
    val rulerPosition = activeRuler.position
    val rulerAngle = activeRuler.angle
    val rulerLocked = activeRuler.locked

    var gridEnabled by rememberBoundState(
        key = currentSession,
        get = { currentSession.gridEnabled },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(gridEnabled = newValue) } }
    )
    var showExportResolutionDialog by remember { mutableStateOf(false) }
    var snapToRuler by rememberBoundState(
        key = currentSession,
        get = { currentSession.snapToRuler },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(snapToRuler = newValue) } }
    )
    var allRulersLocked by rememberBoundState(
        key = currentSession,
        get = { currentSession.allRulersLocked },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(allRulersLocked = newValue) } }
    )
    var gridColumns by rememberBoundState(
        key = currentSession,
        get = { currentSession.gridColumns },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(gridColumns = newValue) } }
    )
    var gridRows by rememberBoundState(
        key = currentSession,
        get = { currentSession.gridRows },
        set = { newValue -> workspaceViewModel.updateSession { it.copy(gridRows = newValue) } }
    )
    var activeGridType by remember { mutableStateOf("Standard") }
    var polarGridCenterX by remember { mutableStateOf(0.5f) }
    var polarGridCenterY by remember { mutableStateOf(0.5f) }
    var isLeftToolbarExpanded by remember { mutableStateOf(true) }
    var isRightSidebarExpanded by remember { mutableStateOf(true) }

    LaunchedEffect(canvasGridVisibleSetting) {
        gridEnabled = canvasGridVisibleSetting
    }

    LaunchedEffect(activeTool) {
        if (activeTool == "Pen") {
            val activeArtboard = artboards.find { it.id == selectedArtboardId } ?: artboards.firstOrNull()
            val artW = activeArtboard?.width ?: 1080f
            val artH = activeArtboard?.height ?: 1080f
            penCursorOffset = Offset(artW / 2f, artH / 2f)
        } else {
            penCursorOffset = null
        }
    }

    val rightPadding = if (isLandscape && isRightSidebarExpanded) 320.dp else 0.dp
    val bottomPadding = if (workspaceLayoutMode == "Mobile" && isMobileBottomDockVisible) 80.dp else 0.dp
    val layersEndPadding = if (isLandscape && isRightSidebarExpanded) 332.dp else 12.dp

    var fontSearchQuery by remember { mutableStateOf("") }
    var selectedCategoryFilter by remember { mutableStateOf("All") }

    var favoriteFontsList by remember { mutableStateOf(getFavoriteFonts(context)) }

    val performFontScan: () -> Unit = {
        isFontScanning = true
        val activeFolders = selectedFoldersToScan.filter { it.value }.keys.toSet()
        val foldersStr = activeFolders.joinToString(", ")
        fontScanStatusMessage = "Crawling ($foldersStr)..."
        scope.launch {
            try {
                discoveredFonts = FontScanner.scanLocalFonts(context, activeFolders)
                selectedFontIndexes.clear()
                selectedFontCount = discoveredFonts.size
                fontScanStatusMessage = if (discoveredFonts.isEmpty()) {
                    "No design fonts (.ttf/.otf) found in chosen directories."
                } else {
                    "Discovered ${discoveredFonts.size} custom design typography files!"
                }
            } catch (e: Exception) {
                fontScanStatusMessage = "Scanning failed: ${e.localizedMessage}"
            } finally {
                isFontScanning = false
            }
        }
    }

    val storagePermissionLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        hasStoragePermission = isGranted
        if (isGranted) {
            performFontScan()
        } else {
            android.widget.Toast.makeText(context, "Storage scanner permission declined. Use Manual Pick instead or grant in settings.", android.widget.Toast.LENGTH_LONG).show()
        }
    }

    val requestOrPromptStoragePermission: () -> Unit = {
        val hasPerm = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.R) {
            android.os.Environment.isExternalStorageManager() ||
            androidx.core.content.ContextCompat.checkSelfPermission(
                context,
                android.Manifest.permission.READ_EXTERNAL_STORAGE
            ) == android.content.pm.PackageManager.PERMISSION_GRANTED
        } else {
            androidx.core.content.ContextCompat.checkSelfPermission(
                context,
                android.Manifest.permission.READ_EXTERNAL_STORAGE
            ) == android.content.pm.PackageManager.PERMISSION_GRANTED
        }

        if (hasPerm) {
            hasStoragePermission = true
            performFontScan()
        } else {
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.R) {
                android.widget.Toast.makeText(context, "Zenith Studio needs All Files Access for auto font directory scan. Grant it in Settings.", android.widget.Toast.LENGTH_LONG).show()
                try {
                    val intent = android.content.Intent(android.provider.Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION).apply {
                        data = android.net.Uri.fromParts("package", context.packageName, null)
                        addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
                    }
                    context.startActivity(intent)
                } catch (e: Exception) {
                    try {
                        val intent = android.content.Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                            data = android.net.Uri.fromParts("package", context.packageName, null)
                            addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
                        }
                        context.startActivity(intent)
                    } catch (ex: Exception) {
                        ex.printStackTrace()
                    }
                }
            } else {
                storagePermissionLauncher.launch(android.Manifest.permission.READ_EXTERNAL_STORAGE)
            }
        }
    }

    val fontPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let {
            try {
                val contentResolver = context.contentResolver
                var displayName = "imported_font_${System.currentTimeMillis()}.ttf"
                val cursor = contentResolver.query(it, null, null, null, null)
                cursor?.use { c ->
                    if (c.moveToFirst()) {
                        val nameIndex = c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                        if (nameIndex != -1) {
                            val name = c.getString(nameIndex)
                            if (!name.isNullOrEmpty()) {
                                displayName = name
                            }
                        }
                    }
                }
                
                val fontsDir = java.io.File(context.filesDir, "fonts")
                if (!fontsDir.exists()) {
                    fontsDir.mkdirs()
                }
                val destFile = java.io.File(fontsDir, displayName)
                contentResolver.openInputStream(it)?.use { input ->
                    destFile.outputStream().use { output ->
                        input.copyTo(output)
                    }
                }
                
                android.widget.Toast.makeText(context, "Font imported: ${destFile.nameWithoutExtension}", android.widget.Toast.LENGTH_SHORT).show()
                
                val cleanName = destFile.nameWithoutExtension.replace("_", " ").replace("-", " ")
                val category = if (cleanName.contains("script", ignoreCase = true)) {
                    "Script"
                } else if (cleanName.contains("hand", ignoreCase = true) || cleanName.contains("write", ignoreCase = true)) {
                    "Handwritten"
                } else if (cleanName.contains("mono", ignoreCase = true)) {
                    "Monospace"
                } else if (cleanName.contains("serif", ignoreCase = true)) {
                    "Serif"
                } else {
                    "Display"
                }
                workspaceViewModel.addCustomFont(cleanName, destFile.absolutePath, category)

                if (selectedLayerId.isNotEmpty()) {
                    val targetL = layers.find { it.id == selectedLayerId }
                    if (targetL != null && targetL.type == LayerType.TEXT) {
                        val cleanName = destFile.nameWithoutExtension.replace("_", " ").replace("-", " ")
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { l ->
                            if (l.id == selectedLayerId) {
                                l.copy(
                                    fontPath = destFile.absolutePath,
                                    fontFamilyName = cleanName
                                )
                            } else l
                        }
                    }
                }
            } catch (e: Exception) {
                e.printStackTrace()
                android.widget.Toast.makeText(context, "Failed to import font", android.widget.Toast.LENGTH_SHORT).show()
            }
        }
    }

    val folderPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.OpenDocumentTree()
    ) { uri: android.net.Uri? ->
        uri?.let { treeUri ->
            try {
                val path = treeUri.path ?: ""
                val decodedPath = if (path.contains(":")) {
                    java.net.URLDecoder.decode(path.substringAfterLast(":"), "UTF-8")
                } else {
                    treeUri.lastPathSegment ?: "Custom Folder"
                }

                val fullPath = if (path.contains("primary:")) {
                    val sub = java.net.URLDecoder.decode(path.substringAfter("primary:"), "UTF-8")
                    "/storage/emulated/0/$sub"
                } else if (decodedPath.startsWith("/")) {
                    decodedPath
                } else {
                    decodedPath
                }

                if (fullPath.isNotEmpty()) {
                    selectedFoldersToScan[fullPath] = true
                    fontScanStatusMessage = "Added folder target: $fullPath"
                    android.widget.Toast.makeText(context, "Target folder added: $decodedPath", android.widget.Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    val imageBitmapCache = remember { mutableStateMapOf<String, androidx.compose.ui.graphics.ImageBitmap>() }
    LaunchedEffect(imageBitmapCache.size) {
        if (imageBitmapCache.size > 25) {
            val keysToRemove = imageBitmapCache.keys.take(imageBitmapCache.size - 25)
            keysToRemove.forEach { imageBitmapCache.remove(it) }
        }
    }
    // Global processedImageBitmapCache is used
    val loadingUris = remember { mutableStateOf(emptySet<String>()) }
    val failedUris = remember { mutableStateOf(emptySet<String>()) }
    val infiniteTransition = androidx.compose.animation.core.rememberInfiniteTransition(label = "pulse")
    val pulseAlphaState = infiniteTransition.animateFloat(
        initialValue = 0.3f,
        targetValue = 0.8f,
        animationSpec = androidx.compose.animation.core.infiniteRepeatable(
            animation = androidx.compose.animation.core.tween(1000, easing = androidx.compose.animation.core.FastOutSlowInEasing),
            repeatMode = androidx.compose.animation.core.RepeatMode.Reverse
        ),
        label = "pulse"
    )
    val pulseAlpha = if (com.example.ui.theme.isLowEndOptimizationEnabled.value) 0.6f else pulseAlphaState.value
    val spinAngleState = infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = androidx.compose.animation.core.infiniteRepeatable(
            animation = androidx.compose.animation.core.tween(1500, easing = androidx.compose.animation.core.LinearEasing),
            repeatMode = androidx.compose.animation.core.RepeatMode.Restart
        ),
        label = "spin"
    )
    val spinAngle = if (com.example.ui.theme.isLowEndOptimizationEnabled.value) 0f else spinAngleState.value
    LaunchedEffect(artboards, layers) {
        val allImages = (artboards.flatMap { it.layers } + layers)
            .filter { it.type == LayerType.IMAGE_CARD && !it.imageUri.isNullOrEmpty() }
        val currentImageUris = allImages.mapNotNull { it.imageUri }.toSet()
        
        val cacheKeys = imageBitmapCache.keys.toList()
        cacheKeys.forEach { key ->
            if (key !in currentImageUris) {
                imageBitmapCache.remove(key)
            }
        }
        
        val failedKeys = failedUris.value
        val staleFailedKeys = failedKeys.filter { it !in currentImageUris }
        if (staleFailedKeys.isNotEmpty()) {
            failedUris.value = failedKeys - staleFailedKeys.toSet()
        }
        
        // Proactively register any pre-rendered PDF bitmaps into the cache
        artboards.forEach { artboard ->
            if (artboard.renderedPdfBitmap != null) {
                artboard.layers.forEach { layer ->
                    if (layer.type == LayerType.IMAGE_CARD && !layer.imageUri.isNullOrEmpty()) {
                        try {
                            imageBitmapCache[layer.imageUri] = artboard.renderedPdfBitmap.asImageBitmap()
                            com.example.studio.ui.ParametricLayerCache.invalidate(layer.id)
                        } catch (t: Throwable) {
                            t.printStackTrace()
                        }
                    }
                }
            }
        }

        allImages.forEach { layer ->
            val uriStr = layer.imageUri
            if (!uriStr.isNullOrEmpty()) {
                if (!imageBitmapCache.containsKey(uriStr) && !loadingUris.value.contains(uriStr) && !failedUris.value.contains(uriStr)) {
                    // Check if we can find a pre-rendered PDF bitmap first
                    val preRendered = artboards.find { art -> art.renderedPdfBitmap != null && art.layers.any { l -> l.imageUri == uriStr } }?.renderedPdfBitmap
                    if (preRendered != null) {
                        try {
                            imageBitmapCache[uriStr] = preRendered.asImageBitmap()
                            com.example.studio.ui.ParametricLayerCache.invalidate(layer.id)
                        } catch (t: Throwable) {
                            t.printStackTrace()
                        }
                    } else {
                        // Mark as loading immediately on main thread to prevent duplicate triggers
                        loadingUris.value = loadingUris.value + uriStr
                        
                        // Launch parallel loading job on the persistent screen scope so it doesn't get cancelled by drag/transforms
                        scope.launch(Dispatchers.Main) {
                            try {
                                val loaded = withContext(Dispatchers.IO) {
                                    try {
                                        // First decode only bounds to prevent loading massive texture files directly
                                        val sizeOptions = android.graphics.BitmapFactory.Options().apply {
                                            inJustDecodeBounds = true
                                        }
                                        if (uriStr.startsWith("content://")) {
                                            val uri = android.net.Uri.parse(uriStr)
                                            try {
                                                context.contentResolver.openInputStream(uri)?.use { stream ->
                                                    android.graphics.BitmapFactory.decodeStream(stream, null, sizeOptions)
                                                }
                                            } catch (err: Throwable) {
                                                android.util.Log.e("StudioImageLoader", "Failed to decode bounds for content URI: $uriStr", err)
                                            }
                                        } else {
                                            val cleanPath = if (uriStr.startsWith("file://")) uriStr.substring(7) else uriStr
                                            val file = java.io.File(cleanPath)
                                            var decodedBounds = false
                                            if (file.exists()) {
                                                android.graphics.BitmapFactory.decodeFile(file.absolutePath, sizeOptions)
                                                decodedBounds = true
                                            }
                                            if (!decodedBounds) {
                                                val filename = file.name
                                                val importedDir = java.io.File(context.filesDir, "imported_images")
                                                val sub1 = java.io.File(importedDir, filename)
                                                if (sub1.exists()) {
                                                    android.graphics.BitmapFactory.decodeFile(sub1.absolutePath, sizeOptions)
                                                    decodedBounds = true
                                                } else {
                                                    val sub2 = java.io.File(context.filesDir, filename)
                                                    if (sub2.exists()) {
                                                        android.graphics.BitmapFactory.decodeFile(sub2.absolutePath, sizeOptions)
                                                        decodedBounds = true
                                                    } else {
                                                        val alternativeFile = java.io.File(context.filesDir, cleanPath)
                                                        if (alternativeFile.exists()) {
                                                            android.graphics.BitmapFactory.decodeFile(alternativeFile.absolutePath, sizeOptions)
                                                            decodedBounds = true
                                                        }
                                                    }
                                                }
                                            }
                                        }

                                        val width = sizeOptions.outWidth
                                        val height = sizeOptions.outHeight
                                        var inSampleSize = 1
                                        val maxDimension = 1080 // Downsample to match device screen resolution for live editing
                                        while ((width / inSampleSize) > maxDimension || (height / inSampleSize) > maxDimension) {
                                            inSampleSize *= 2
                                        }
                                        
                                        val isOpaque = sizeOptions.outMimeType == "image/jpeg" || sizeOptions.outMimeType == "image/heic"
                                        val hardwareSupported = android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O
                                        
                                        val options = android.graphics.BitmapFactory.Options().apply {
                                            this.inSampleSize = inSampleSize
                                            if (hardwareSupported) {
                                                inPreferredConfig = android.graphics.Bitmap.Config.ARGB_8888
                                                inMutable = true
                                            } else {
                                                inPreferredConfig = if (isOpaque) android.graphics.Bitmap.Config.RGB_565 else android.graphics.Bitmap.Config.ARGB_8888
                                                inMutable = true
                                            }
                                            inPremultiplied = true
                                            inScaled = false
                                        }
                                        android.util.Log.d("StudioImageLoader", "Loading image: $uriStr, calculated inSampleSize: $inSampleSize")
                                        val decodedRaw = if (uriStr.startsWith("content://")) {
                                            val uri = android.net.Uri.parse(uriStr)
                                            context.contentResolver.openInputStream(uri)?.use { stream ->
                                                android.graphics.BitmapFactory.decodeStream(stream, null, options)
                                            }
                                        } else {
                                            val cleanPath = if (uriStr.startsWith("file://")) uriStr.substring(7) else uriStr
                                            val file = java.io.File(cleanPath)
                                            var resultBmp: android.graphics.Bitmap? = null
                                            if (file.exists()) {
                                                resultBmp = android.graphics.BitmapFactory.decodeFile(file.absolutePath, options)
                                            }
                                            if (resultBmp == null) {
                                                val filename = file.name
                                                val importedDir = java.io.File(context.filesDir, "imported_images")
                                                val sub1 = java.io.File(importedDir, filename)
                                                if (sub1.exists()) {
                                                    resultBmp = android.graphics.BitmapFactory.decodeFile(sub1.absolutePath, options)
                                                } else {
                                                    val sub2 = java.io.File(context.filesDir, filename)
                                                    if (sub2.exists()) {
                                                        resultBmp = android.graphics.BitmapFactory.decodeFile(sub2.absolutePath, options)
                                                    } else {
                                                        val alternativeFile = java.io.File(context.filesDir, cleanPath)
                                                        if (alternativeFile.exists()) {
                                                            resultBmp = android.graphics.BitmapFactory.decodeFile(alternativeFile.absolutePath, options)
                                                        }
                                                    }
                                                }
                                            }
                                            resultBmp
                                        }
                                        android.util.Log.d("StudioImageLoader", "Loader cache decoding uri=$uriStr, decodedRaw=$decodedRaw")
                                        if (decodedRaw != null && decodedRaw.width > 0 && decodedRaw.height > 0) {
                                            val softwareBmp = if (decodedRaw.isMutable && decodedRaw.config == android.graphics.Bitmap.Config.ARGB_8888) {
                                                decodedRaw
                                            } else {
                                                val copied = decodedRaw.copy(android.graphics.Bitmap.Config.ARGB_8888, true)
                                                if (copied != null) {
                                                    if (copied != decodedRaw) decodedRaw.recycle()
                                                    copied
                                                } else {
                                                    decodedRaw
                                                }
                                            }
                                            softwareBmp.asImageBitmap()
                                        } else {
                                            android.util.Log.e("StudioImageLoader", "Loader cache decode failed for uri=$uriStr")
                                            null
                                        }
                                    } catch (t: Throwable) {
                                        android.util.Log.e("StudioImageLoader", "Failed to decode bitmap from $uriStr", t)
                                        null
                                    }
                                }
                                if (loaded != null) {
                                    imageBitmapCache[uriStr] = loaded
                                    allImages.forEach { l ->
                                        if (l.imageUri == uriStr) {
                                            com.example.studio.ui.ParametricLayerCache.invalidate(l.id)
                                        }
                                    }
                                } else {
                                    failedUris.value = failedUris.value + uriStr
                                }
                            } finally {
                                loadingUris.value = loadingUris.value - uriStr
                            }
                        }
                    }
                }
            }
        }
    }

    var scaleFactor by remember { mutableStateOf(1.0f) }
    var canvasPanX by remember { mutableStateOf(0f) }
    var canvasPanY by remember { mutableStateOf(0f) }
    var canvasRotation by remember { mutableStateOf(0f) }

    var isThermalThrottleActiveState by remember { mutableStateOf(false) }

    androidx.compose.runtime.DisposableEffect(context) {
        val powerManager = context.getSystemService(android.os.PowerManager::class.java)
        var listener: android.os.PowerManager.OnThermalStatusChangedListener? = null
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q && powerManager != null) {
            listener = android.os.PowerManager.OnThermalStatusChangedListener { status ->
                val active = status >= android.os.PowerManager.THERMAL_STATUS_MODERATE
                isThermalThrottleActiveState = active
                com.example.studio.ui.isThermalThrottleActive = active
            }
            try {
                powerManager.addThermalStatusListener(listener)
                val currentStatus = powerManager.currentThermalStatus
                val active = currentStatus >= android.os.PowerManager.THERMAL_STATUS_MODERATE
                isThermalThrottleActiveState = active
                com.example.studio.ui.isThermalThrottleActive = active
            } catch (e: Exception) {
                android.util.Log.e("ThermalHAL", "Failed to register thermal status listener", e)
            }
        }
        onDispose {
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q && powerManager != null && listener != null) {
                try {
                    powerManager.removeThermalStatusListener(listener)
                } catch (e: Exception) {
                    android.util.Log.e("ThermalHAL", "Failed to unregister thermal status listener", e)
                }
            }
        }
    }

    // Start Unidirectional Asynchronous Event Loop
    androidx.compose.runtime.LaunchedEffect(Unit) {
        com.example.studio.ui.CanvasEventLoop.startProcessing(
            onUpdateTransform = { panX, panY, scale, rotation ->
                canvasPanX = panX
                canvasPanY = panY
                scaleFactor = scale
                canvasRotation = rotation
            },
            onUpdateSlider = { layerId, effectId, paramName, newValue ->
                layers = layers.map { layer ->
                    if (layer.id == layerId) {
                        val updatedEffects = layer.effects.map { eff ->
                            if (eff.id == effectId) {
                                eff.updateParameter(paramName, newValue)
                            } else eff
                        }
                        layer.copy(effects = updatedEffects)
                    } else layer
                }
            },
            onUpdateLayerProp = { layerId, propName, newValue ->
                layers = layers.map { layer ->
                    if (layer.id == layerId) {
                        when (propName) {
                            "opacity" -> layer.copy(opacity = newValue)
                            "positionX" -> layer.copy(positionX = newValue)
                            "positionY" -> layer.copy(positionY = newValue)
                            else -> layer
                        }
                    } else layer
                }
            }
        )
    }

    var isCanvasLocked by remember { mutableStateOf(false) }
    var isCanvasControlMinimized by remember { mutableStateOf(false) }
    var isMultiSelectMode by remember { mutableStateOf(false) }
    var selectedLayersSet by remember { mutableStateOf(setOf<String>()) }
    var collapsedGroupIds by remember { mutableStateOf(setOf<String>()) }

    // Collapsible Panel States
    var isLayersPanelVisible by remember { mutableStateOf(false) }
    var isBottomPanelVisible by remember { mutableStateOf(false) }
    var showEffectsGallery by remember { mutableStateOf(false) }
    var showZenithEffectsOverlay by remember { mutableStateOf(false) }
    var activeFullScreenSheet by remember { mutableStateOf<String?>(null) }

    val isAnyParametersPanelOpen = if (isLandscape) {
        isRightSidebarExpanded
    } else {
        isBottomPanelVisible || activeFullScreenSheet != null || showZenithEffectsOverlay || showBrushesLibrary || showEffectsGallery
    }

    LaunchedEffect(isAnyParametersPanelOpen) {
