        }
    }

    val showGradientControls = if (isLandscape) {
        isRightSidebarExpanded && activeFullScreenSheet == "Color"
    } else {
        activeFullScreenSheet == "Color"
    }

    // Layer Renaming States
    var renamingLayerId by remember { mutableStateOf<String?>(null) }
    var renamingLayerName by remember { mutableStateOf("") }

    // Selected effect ID mapping
    val selectedLayer = layers.find { it.id == selectedLayerId }
    var selectedEffectIndex by remember { mutableStateOf(0) }

    // Optimization cached states to avoid frame GC pressure inside DrawScope loops
    val pathCache = remember { SparseArray<Path>() }
    val pathPointsCountCache = remember { SparseIntArray() }
    val dashEffect8 = remember { PathEffect.dashPathEffect(floatArrayOf(8f, 8f)) }
    val dashEffect12 = remember { PathEffect.dashPathEffect(floatArrayOf(12f, 8f)) }

    // Canvas size initialization state variables (metrics declared at the top of WorkspaceScreen)
    var isProjectInitialized by remember { mutableStateOf(false) }
    var canvasWidthInput by remember { mutableStateOf("1080") }
    var canvasHeightInput by remember { mutableStateOf(defaultHeightStr) }
    var selectedPresetIndex by remember { mutableStateOf(0) }
    
    var showExportSettingsDialog by remember { mutableStateOf(false) }
    var exportMultiplier by remember { mutableFloatStateOf(1.0f) }
    var exportIsCmyk by remember { mutableStateOf(false) }
    var isBackgroundTransparent by remember { mutableStateOf(false) }
    var selectedExportFormatCategory by remember { mutableStateOf("JPEG") }
    var exportJpegQuality by remember { mutableFloatStateOf(90f) }
    var exportDpiPreset by remember { mutableStateOf("300 DPI") }
    
    // canvasWidth, canvasHeight, projectHistoryManager, and stacks are initialized at the top of WorkspaceScreen

    var isAlightImporting by remember { mutableStateOf(false) }
    var alightImportErrorMsg by remember { mutableStateOf<String?>(null) }

    var isSvgImporting by remember { mutableStateOf(false) }
    var svgImportErrorMsg by remember { mutableStateOf<String?>(null) }

    val alightXmlPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let { xmlUri ->
            isAlightImporting = true
            alightImportErrorMsg = null
            
            scope.launch {
                try {
                    context.contentResolver.openInputStream(xmlUri)?.use { inputStream ->
                        val activeW = canvasWidthInput.toFloatOrNull() ?: 1080f
                        val activeH = canvasHeightInput.toFloatOrNull() ?: 1350f
                        val parsed = AlightXmlEngine.parseAlightXml(inputStream, activeW, activeH)
                        
                        if (parsed.layers.isEmpty()) {
                            isAlightImporting = false
                            alightImportErrorMsg = "No compatible shapes or text layers found in Alight Motion XML template."
                            return@launch
                        }

                        // Set canvas dimensions and project details
                        canvasWidth = parsed.canvasWidth
                        canvasHeight = parsed.canvasHeight
                        canvasWidthInput = parsed.canvasWidth.toInt().toString()
                        canvasHeightInput = parsed.canvasHeight.toInt().toString()
                        projectDpi = 300

                        val nid = UUID.randomUUID().toString()
                        projectId = nid
                        projectName = "Alight Motion Import"
                        layers = parsed.layers
                        selectedLayerId = if (parsed.layers.isNotEmpty()) parsed.layers[0].id else ""
                        workspaceViewModel.initializeSession(nid)
                        isProjectInitialized = true

                        workspaceViewModel.saveProject(nid, projectName, parsed.canvasWidth, parsed.canvasHeight, parsed.layers, dpi = 300)
                        android.widget.Toast.makeText(context, "Alight Motion XML imported successfully with ${parsed.layers.size} layers!", android.widget.Toast.LENGTH_LONG).show()
                    }
                } catch (e: Throwable) {
                    e.printStackTrace()
                    isAlightImporting = false
                    alightImportErrorMsg = "Alight XML Parsing Failure: " + (e.localizedMessage ?: e.javaClass.simpleName)
                } finally {
                    isAlightImporting = false
                }
            }
        }
    }

    fun convertSvgCommandsToStudioLayer(commands: List<com.aistudio.zenithstudio.rpxwtq.ui.canvas.ParsedPathCommand>, index: Int): com.example.studio.model.StudioLayer? {
        if (commands.isEmpty()) return null
        
        val anchors = mutableListOf<AnchorPoint>()
        var isClosed = false
        
        for (cmd in commands) {
            when (cmd.type) {
                com.aistudio.zenithstudio.rpxwtq.ui.canvas.SvgNodeType.MOVE -> {
                    val pt = cmd.points.getOrNull(0) ?: Offset.Zero
                    val newAnchor = AnchorPoint(position = pt, handleIn = pt, handleOut = pt)
                    anchors.add(newAnchor)
                }
                com.aistudio.zenithstudio.rpxwtq.ui.canvas.SvgNodeType.LINE -> {
                    val pt = cmd.points.getOrNull(0) ?: Offset.Zero
                    if (anchors.isEmpty()) {
                        val first = AnchorPoint(position = pt, handleIn = pt, handleOut = pt)
                        anchors.add(first)
                    } else {
                        val prevIndex = anchors.size - 1
                        val prev = anchors[prevIndex]
                        anchors[prevIndex] = prev.copy(handleOut = prev.position)
                        
                        val newAnchor = AnchorPoint(position = pt, handleIn = pt, handleOut = pt)
                        anchors.add(newAnchor)
                    }
                }
                com.aistudio.zenithstudio.rpxwtq.ui.canvas.SvgNodeType.CUBIC_BEZIER -> {
                    val cp1 = cmd.points.getOrNull(0) ?: Offset.Zero
                    val cp2 = cmd.points.getOrNull(1) ?: Offset.Zero
                    val dest = cmd.points.getOrNull(2) ?: Offset.Zero
                    
                    if (anchors.isEmpty()) {
                        val first = AnchorPoint(position = dest, handleIn = cp2, handleOut = dest)
                        anchors.add(first)
                    } else {
                        val prevIndex = anchors.size - 1
                        val prev = anchors[prevIndex]
                        anchors[prevIndex] = prev.copy(handleOut = cp1)
                        
                        val newAnchor = AnchorPoint(position = dest, handleIn = cp2, handleOut = dest)
                        anchors.add(newAnchor)
                    }
                }
                com.aistudio.zenithstudio.rpxwtq.ui.canvas.SvgNodeType.CLOSE -> {
                    isClosed = true
                }
            }
        }
        
        if (anchors.isEmpty()) return null
        
        // Auto-simplify imported paths with tolerance to prevent massive anchor points
        val simplifiedAnchors = if (anchors.size > 2) {
            simplifyAnchorPoints(anchors, tolerance = 4f)
        } else {
            anchors
        }
        
        val brushPoints = mutableListOf<Offset>()
        for (a in simplifiedAnchors) {
            brushPoints.add(a.position)
            brushPoints.add(a.handleIn)
            brushPoints.add(a.handleOut)
        }
        
        var minX = Float.MAX_VALUE
        var minY = Float.MAX_VALUE
        var maxX = -Float.MAX_VALUE
        var maxY = -Float.MAX_VALUE
        
        for (a in simplifiedAnchors) {
            val pts = listOf(a.position, a.handleIn, a.handleOut)
            for (p in pts) {
                if (p.x < minX) minX = p.x
                if (p.y < minY) minY = p.y
                if (p.x > maxX) maxX = p.x
                if (p.y > maxY) maxY = p.y
            }
        }
        
        val width = if (maxX > minX) maxX - minX else 100f
        val height = if (maxY > minY) maxY - minY else 100f
        
        val normalizedBrushPoints = brushPoints.map { pt ->
            Offset(pt.x - minX, pt.y - minY)
        }
        
        // Extract style details from first command that specifies them
        val firstWithStyle = commands.find { it.fillColor != null || it.strokeColor != null }
        val parsedFill = firstWithStyle?.fillColor
        val parsedStroke = firstWithStyle?.strokeColor
        val parsedWidth = firstWithStyle?.strokeWidth ?: 3f
        
        val baseColor: Color
        val strokeThickness: Float
        
        if (parsedFill != null && parsedFill != Color.Transparent) {
            baseColor = parsedFill
            strokeThickness = -1f // Fill
        } else if (parsedStroke != null && parsedStroke != Color.Transparent) {
            baseColor = parsedStroke
            strokeThickness = parsedWidth
        } else {
            baseColor = Color(0xFF00E5FF) // default vibrant cyan fallback
            strokeThickness = 3f
        }
        
        return com.example.studio.model.StudioLayer(
            id = java.util.UUID.randomUUID().toString(),
            name = "SVG Vector Shape ${index + 1}",
            type = com.example.studio.model.LayerType.VECTOR_BEZIER,
            positionX = if (minX != Float.MAX_VALUE) minX else 100f,
            positionY = if (minY != Float.MAX_VALUE) minY else 100f,
            width = width,
            height = height,
            brushPoints = normalizedBrushPoints,
            polygonEdges = if (isClosed) 1 else 0,
            strokeThickness = strokeThickness,
            baseColor = baseColor
        )
    }

    val svgPickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetContent()
    ) { uri: android.net.Uri? ->
        uri?.let { svgUri ->
            isSvgImporting = true
            svgImportErrorMsg = null
            
            scope.launch {
                try {
                    val svgEngine = com.aistudio.zenithstudio.rpxwtq.ui.canvas.SvgVectorEngine(context)
                    val commands = svgEngine.importSvgFromUri(svgUri)
                    
                    if (commands.isEmpty()) {
                        isSvgImporting = false
                        svgImportErrorMsg = "No path definitions found in the selected SVG file."
                        return@launch
                    }
                    
                    // Group SVG commands by separate sub-paths (separated by MOVE commands)
                    val subPaths = mutableListOf<MutableList<com.aistudio.zenithstudio.rpxwtq.ui.canvas.ParsedPathCommand>>()
                    for (cmd in commands) {
                        if (cmd.type == com.aistudio.zenithstudio.rpxwtq.ui.canvas.SvgNodeType.MOVE || subPaths.isEmpty()) {
                            subPaths.add(mutableListOf(cmd))
                        } else {
                            subPaths.last().add(cmd)
                        }
                    }
                    
                    val newLayers = mutableListOf<com.example.studio.model.StudioLayer>()
                    for ((index, subPath) in subPaths.withIndex()) {
                        val layer = convertSvgCommandsToStudioLayer(subPath, index)
                        if (layer != null) {
                            newLayers.add(layer)
                        }
                    }
                    
                    if (newLayers.isEmpty()) {
                        isSvgImporting = false
                        svgImportErrorMsg = "Could not parse any valid vector paths from SVG file."
                        return@launch
                    }
                    
                    // Add imported layers to active workspace
                    layers = layers + newLayers
                    selectedLayerId = newLayers.first().id
                    
                    android.widget.Toast.makeText(context, "Successfully imported ${newLayers.size} vector paths from SVG!", android.widget.Toast.LENGTH_LONG).show()
                } catch (e: Throwable) {
                    e.printStackTrace()
                    isSvgImporting = false
                    svgImportErrorMsg = "SVG Import Failure: " + (e.localizedMessage ?: e.javaClass.simpleName)
                } finally {
                    isSvgImporting = false
                }
            }
        }
    }


    val imagePickerLauncher = androidx.activity.compose.rememberLauncherForActivityResult(
        contract = androidx.activity.result.contract.ActivityResultContracts.GetMultipleContents()
    ) { uris: List<android.net.Uri> ->
        if (uris.isNotEmpty()) {
            scope.launch {
                val newLayersList = mutableListOf<com.example.studio.model.StudioLayer>()
                var offsetX = 0f
                var offsetY = 0f
                
                val importedDir = java.io.File(context.filesDir, "imported_images").apply {
                    if (!exists()) mkdirs()
                }

                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                    for (uri in uris) {
                        try {
                            val uniqueName = "imported_${System.currentTimeMillis()}_${java.util.UUID.randomUUID().toString().take(6)}"
                            val tempFile = java.io.File(importedDir, "$uniqueName.png")

                            // Create a temporary cache file to copy the stream content first.
                            // This ensures we only read the URI once, preventing stream permission reuse issues.
                            val rawTempFile = java.io.File(context.cacheDir, "raw_import_${System.currentTimeMillis()}_${java.util.UUID.randomUUID().toString().take(6)}.tmp")
                            try {
                                context.contentResolver.openInputStream(uri)?.use { inputStream ->
                                    rawTempFile.outputStream().use { outputStream ->
                                        inputStream.copyTo(outputStream)
                                    }
                                }
                            } catch (e: Exception) {
                                android.util.Log.e("StudioImageLoader", "Failed to copy uri stream for $uri", e)
                                if (rawTempFile.exists()) rawTempFile.delete()
                                continue
                            }

                            if (!rawTempFile.exists() || rawTempFile.length() == 0L) {
                                android.util.Log.e("StudioImageLoader", "Copied temp file is empty or missing for $uri")
                                if (rawTempFile.exists()) rawTempFile.delete()
                                continue
                            }

                            // Now decode the dimensions from the local rawTempFile safely
                            val sizeOptions = android.graphics.BitmapFactory.Options().apply {
                                inJustDecodeBounds = true
                            }
                            android.graphics.BitmapFactory.decodeFile(rawTempFile.absolutePath, sizeOptions)

                            val width = sizeOptions.outWidth
                            val height = sizeOptions.outHeight
                            
                            if (width <= 0 || height <= 0) {
                                android.util.Log.e("StudioImageLoader", "Invalid dimensions: ${width}x${height} for $uri")
                                if (rawTempFile.exists()) rawTempFile.delete()
                                continue
                            }

                            var inSampleSize = 1
                            val maxDimension = 1080
                            while ((width / inSampleSize) > maxDimension || (height / inSampleSize) > maxDimension) {
                                inSampleSize *= 2
                            }

                            val options = android.graphics.BitmapFactory.Options().apply {
                                this.inSampleSize = inSampleSize
                                            val isOpaque = sizeOptions.outMimeType == "image/jpeg" || sizeOptions.outMimeType == "image/heic"
                                            inPreferredConfig = if (isOpaque) android.graphics.Bitmap.Config.RGB_565 else android.graphics.Bitmap.Config.ARGB_8888
                                inPremultiplied = true
                                inScaled = false
                                inMutable = true
                            }

                            val decodedBitmap = try {
                                android.graphics.BitmapFactory.decodeFile(rawTempFile.absolutePath, options)
                            } catch (oom: OutOfMemoryError) {
                                try {
                                    options.inSampleSize = inSampleSize * 2
                                    android.graphics.BitmapFactory.decodeFile(rawTempFile.absolutePath, options)
                                } catch (e: Exception) {
                                    null
                                }
                            }

                            // delete raw cache file
                            if (rawTempFile.exists()) {
                                rawTempFile.delete()
                            }

                            if (decodedBitmap != null && decodedBitmap.width > 0 && decodedBitmap.height > 0) {
                                val softwareBitmap = if (decodedBitmap.isMutable && decodedBitmap.config == android.graphics.Bitmap.Config.ARGB_8888) {
                                    decodedBitmap
                                } else {
                                    val copied = decodedBitmap.copy(android.graphics.Bitmap.Config.ARGB_8888, true)
                                    if (copied != null) {
                                        if (copied != decodedBitmap) decodedBitmap.recycle()
                                        copied
                                    } else {
                                        decodedBitmap
                                    }
                                }

                                tempFile.outputStream().use { outputStream ->
                                    softwareBitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, outputStream)
                                }

                                val imageW = softwareBitmap.width
                                val imageH = softwareBitmap.height

                                var initialW = 400f
                                var initialH = 400f
                                if (imageW > 0 && imageH > 0) {
                                    val aspectRatio = imageW.toFloat() / imageH.toFloat()
                                    if (aspectRatio > 1.0f) {
                                        initialW = 400f
                                        initialH = 400f / aspectRatio
                                    } else {
                                        initialH = 400f
                                        initialW = 400f * aspectRatio
                                    }
                                }

                                val newLayer = com.example.studio.model.StudioLayer(
                                    name = "Gallery Image ${newLayersList.size + layers.size + 1}",
                                    type = com.example.studio.model.LayerType.IMAGE_CARD,
                                    positionX = 150f + offsetX,
                                    positionY = 200f + offsetY,
                                    width = initialW,
                                    height = initialH,
                                    baseColor = Color.Transparent,
                                    imageUri = tempFile.absolutePath,
                                    isAspectLocked = true
                                )
                                newLayersList.add(newLayer)
                                offsetX += 40f
                                offsetY += 40f

                                softwareBitmap.recycle()
                            } else {
                                android.util.Log.e("StudioImageLoader", "Decoded bitmap is null or invalid for temp file of $uri")
                            }
                        } catch (e: Exception) {
                            android.util.Log.e("StudioImageLoader", "Error copying/decoding gallery image: $uri", e)
                        }
                    }
                }

                if (newLayersList.isNotEmpty()) {
                    undoStack.add(layers)
                    redoStack.clear()
                    layers = newLayersList + layers
                    selectedLayerId = newLayersList.first().id
                    android.widget.Toast.makeText(context, "Successfully imported ${newLayersList.size} images from gallery!", android.widget.Toast.LENGTH_SHORT).show()
                }
            }
        }
    }

    // Background Auto-Save Side-Effect with Debounced Transaction History Synchronization
    LaunchedEffect(artboards, selectedArtboardId, canvasWidth, canvasHeight, projectName, projectId, projectDpi, layers, com.aistudio.zenithstudio.rpxwtq.EffectStackManager.changeCounter.value) {
        if (isProjectInitialized && projectId.isNotEmpty()) {
            // Debounce threshold of 2000ms to prevent micro-stutters on Snapdragon 888 chipset
            val delayMs = if (isThermalThrottleActive) 4000L else 2000L
            kotlinx.coroutines.delay(delayMs)
            
            val currentMemento = com.example.studio.model.ProjectMemento(
                artboards = artboards.map {
                    if (it.id == selectedArtboardId) {
                        it.copy(layers = layers)
                    } else {
                        it
                    }
                },
                selectedArtboardId = selectedArtboardId,
                selectedLayerId = selectedLayerId,
                projectName = projectName,
                canvasWidth = canvasWidth,
                canvasHeight = canvasHeight,
                projectDpi = projectDpi
            )

            // 1. Non-blocking workspace save to Room Database
            workspaceViewModel.saveWorkspace(
                id = projectId,
                name = projectName,
                width = canvasWidth,
                height = canvasHeight,
                artboards = currentMemento.artboards,
                selectedArtboardId = selectedArtboardId,
                dpi = projectDpi
            )

            // 2. Offscreen atomic serialization of active Undo/Redo history tree on Dispatchers.IO
            projectHistoryManager.serializeAndSaveHistory(projectId, currentMemento)
        }
    }

    LaunchedEffect(activeTool, rulerEnabled) {
        if (activeTool == "Ruler" || (rulerEnabled && rulers.size <= 1)) {
            if (rulers.size <= 1 || (rulers.size == 1 && rulers[0].id == "default_ruler")) {
                val h = if (canvasHeight > 0) canvasHeight else 1000f
                val w = if (canvasWidth > 0) canvasWidth else 1000f
                rulers = listOf(
                    StudioRuler(id = "r_h1", name = "Top Guideline", enabled = true, orientation = "Horizontal", position = h / 3f, angle = 0f, locked = false),
                    StudioRuler(id = "r_h2", name = "Bottom Guideline", enabled = true, orientation = "Horizontal", position = 2 * h / 3f, angle = 0f, locked = false),
                    StudioRuler(id = "r_v1", name = "Left Guideline", enabled = true, orientation = "Vertical", position = w / 3f, angle = 0f, locked = false),
                    StudioRuler(id = "r_v2", name = "Right Guideline", enabled = true, orientation = "Vertical", position = 2 * w / 3f, angle = 0f, locked = false)
                )
                selectedRulerId = "r_h1"
            }
            isBottomPanelVisible = true
        }
    }

    LaunchedEffect(activeTool, isProjectInitialized) {
        if (isProjectInitialized && (activeTool == "Brush" || activeTool == "Pen" || activeTool == "Eraser")) {
            isBottomPanelVisible = true
            activeFullScreenSheet = "Brush"
        }
    }

    LaunchedEffect(activeFullScreenSheet) {
        if (activeFullScreenSheet == null && (activeTool == "Brush" || activeTool == "Pen" || activeTool == "Eraser")) {
            activeTool = "Move"
        }
    }

    var viewportWidth by remember { mutableStateOf(1200f) }
    var viewportHeight by remember { mutableStateOf(1200f) }

    val fitScale = remember(viewportWidth, viewportHeight, canvasWidth, canvasHeight) {
        val scaleW = viewportWidth / canvasWidth
        val scaleH = viewportHeight / canvasHeight
        minOf(scaleW, scaleH) * 0.85f // 15% safety margin on mobile
    }
    val currentLayersState = remember { androidx.compose.runtime.derivedStateOf { layers } }
    val currentActiveToolState = remember { androidx.compose.runtime.derivedStateOf { activeTool } }
    val currentSelectedLayerIdState = remember { androidx.compose.runtime.derivedStateOf { selectedLayerId } }
    val currentViewportWidthState = remember { androidx.compose.runtime.derivedStateOf { viewportWidth } }
    val currentViewportHeightState = remember { androidx.compose.runtime.derivedStateOf { viewportHeight } }
    val visibleViewportCenterY = if (activeFullScreenSheet != null) {
        viewportHeight * 0.26f
    } else {
        viewportHeight * 0.38f
    }
    val currentVisibleViewportCenterYState = remember { androidx.compose.runtime.derivedStateOf { visibleViewportCenterY } }
    val currentArtboardsState = remember { androidx.compose.runtime.derivedStateOf { artboards } }
    val currentSelectedArtboardIdState = remember { androidx.compose.runtime.derivedStateOf { selectedArtboardId } }
    val currentPenSubToolState = remember { androidx.compose.runtime.derivedStateOf { penSubTool } }
    val currentBrushColorState = remember { androidx.compose.runtime.derivedStateOf { brushColor } }
    val currentBrushSizeState = remember { androidx.compose.runtime.derivedStateOf { brushSize } }
    val currentBrushOpacityState = remember { androidx.compose.runtime.derivedStateOf { brushOpacity } }
    val currentBrushSmoothingState = remember { androidx.compose.runtime.derivedStateOf { brushSmoothing } }
    val currentBrushPresetIndexState = remember { androidx.compose.runtime.derivedStateOf { brushPresetIndex } }
    val currentBrushHardnessState = remember { androidx.compose.runtime.derivedStateOf { brushHardness } }
    val currentEraserSizeState = remember { androidx.compose.runtime.derivedStateOf { eraserSize } }
    val currentEraserHardnessState = remember { androidx.compose.runtime.derivedStateOf { eraserHardness } }
    val currentScaleFactorState = remember { androidx.compose.runtime.derivedStateOf { scaleFactor } }
    val currentCanvasRotationState = remember { androidx.compose.runtime.derivedStateOf { canvasRotation } }
    val currentCanvasPanXState = remember { androidx.compose.runtime.derivedStateOf { canvasPanX } }
