    }
    
    val workspaceCenterX = remember(minWorkspaceX, maxWorkspaceX) {
        (minWorkspaceX + maxWorkspaceX) / 2f
    }
    val workspaceCenterY = remember(minWorkspaceY, maxWorkspaceY) {
        (minWorkspaceY + maxWorkspaceY) / 2f
    }
    
    val currentWorkspaceCenterXState = remember { androidx.compose.runtime.derivedStateOf { workspaceCenterX } }
    val currentWorkspaceCenterYState = remember { androidx.compose.runtime.derivedStateOf { workspaceCenterY } }

