    val currentRulerAngleState = remember { androidx.compose.runtime.derivedStateOf { rulerAngle } }
    val currentSnapToRulerState = remember { androidx.compose.runtime.derivedStateOf { snapToRuler } }
    val currentRulersState = remember { androidx.compose.runtime.derivedStateOf { rulers } }
    val currentSelectedRulerIdState = remember { androidx.compose.runtime.derivedStateOf { selectedRulerId } }
    val currentAllRulersLockedState = remember { androidx.compose.runtime.derivedStateOf { allRulersLocked } }

    val labelPaint = remember {
        android.graphics.Paint().apply {
            isAntiAlias = true
            typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.BOLD)
        }
    }

    val executeArtworkExport: (List<ArtboardData>, Float, Boolean, String) -> Unit = { targetArtboards, mult, cmyk, format ->
        val exportList = if (targetArtboards.isEmpty()) {
            artboards.find { it.id == selectedArtboardId }?.let { listOf(it) } ?: listOf(ArtboardData(selectedArtboardId, "Canvas", canvasWidth, canvasHeight, layers))
        } else targetArtboards

        android.widget.Toast.makeText(context, "Exporting ${exportList.size} $format artwork(s) to Gallery...", android.widget.Toast.LENGTH_SHORT).show()
        showExportProgressDialog = true
        exportProgressValue = 0f
        exportProgressText = "Preparing export..."
        exportJob = scope.launch {
            try {
                var successCount = 0
                for (index in exportList.indices) {
                    val art = exportList[index]
                    val artLayers = if (art.id == selectedArtboardId) layers else art.layers
                    val targetW = art.width * mult
                    val targetH = art.height * mult
                    
                    val exportedBitmap = withContext(Dispatchers.Default) {
                        exportCanvasToBitmap(
                            context = context,
                            canvasWidth = art.width,
                            canvasHeight = art.height,
                            layers = artLayers,
                            imageBitmapCache = imageBitmapCache,
                            targetWidth = targetW,
                            targetHeight = targetH,
                            isCmyk = cmyk,
                            isBackgroundTransparent = isBackgroundTransparent,
                            warpMeshDivisionX = warpMeshDivisionX,
                            warpMeshDivisionY = warpMeshDivisionY,
                            warpRepeatMode = warpRepeatMode,
                            warpRepeatX = warpRepeatX,
                            warpRepeatY = warpRepeatY,
                            warpPhaseX = warpPhaseX,
                            warpPhaseY = warpPhaseY,
                            warpInterpolation = warpInterpolation,
                            warpTarget = warpTarget,
                            onProgress = { p, txt ->
                                scope.launch(Dispatchers.Main) {
                                    exportProgressValue = p
                                    exportProgressText = txt
                                }
                            }
                        )
                    }
                    
                    exportProgressText = "Saving to Gallery..."
                    val sanitizeName = art.name.replace(Regex("[^a-zA-Z0-9_-]"), "_")
                    val uniqueSuffix = "${System.currentTimeMillis()}_${index + 1}"
                    val filename = (if (projectName.isBlank()) "Masterpiece" else projectName) + "_" + sanitizeName + "_" + (if (cmyk) "CMYK_" else "RGB_") + targetW.toInt() + "x" + targetH.toInt() + "_" + uniqueSuffix
                    val uri = withContext(Dispatchers.IO) {
                        saveBitmapToGallery(context, exportedBitmap, filename, projectDpi, format)
                    }
                    if (!exportedBitmap.isRecycled) {
                        exportedBitmap.recycle()
                    }
                    if (uri != null) successCount++
                }
                
                if (successCount > 0) {
                    android.widget.Toast.makeText(context, "Exported $successCount artwork(s) successfully as $format!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    android.widget.Toast.makeText(context, "Export failed. Please check device state.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                android.widget.Toast.makeText(context, "Export cancelled.", android.widget.Toast.LENGTH_SHORT).show()
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            } finally {
                showExportProgressDialog = false
            }
        }
    }

    val executeSvgExport: (List<ArtboardData>) -> Unit = { targetArtboards ->
        val exportList = if (targetArtboards.isEmpty()) {
            artboards.find { it.id == selectedArtboardId }?.let { listOf(it) } ?: listOf(ArtboardData(selectedArtboardId, "Canvas", canvasWidth, canvasHeight, layers))
        } else targetArtboards

        android.widget.Toast.makeText(context, "Exporting ${exportList.size} Vector SVG(s)...", android.widget.Toast.LENGTH_SHORT).show()
        showExportProgressDialog = true
        exportProgressValue = 0f
        exportProgressText = "Preparing SVG export..."
        exportJob = scope.launch {
            try {
                var successCount = 0
                for (index in exportList.indices) {
                    exportProgressValue = index.toFloat() / exportList.size
                    exportProgressText = "Exporting SVG ${index + 1} of ${exportList.size}..."
                    kotlinx.coroutines.yield()
                    
                    val art = exportList[index]
                    val artLayers = if (art.id == selectedArtboardId) layers else art.layers
                    val sanitizeName = art.name.replace(Regex("[^a-zA-Z0-9_-]"), "_")
                    val artProjectName = (if (projectName.isBlank()) "Masterpiece" else projectName) + "_" + sanitizeName
                    val uri = withContext(Dispatchers.IO) {
                        saveSvgToDownloads(context, artProjectName, art.width, art.height, artLayers)
                    }
                    if (uri != null) successCount++
                }
                if (successCount > 0) {
                    android.widget.Toast.makeText(context, "Exported $successCount SVG file(s) successfully to Download/StudioExports!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    android.widget.Toast.makeText(context, "SVG export failed. Check storage permissions.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                android.widget.Toast.makeText(context, "SVG Export cancelled.", android.widget.Toast.LENGTH_SHORT).show()
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "SVG Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            } finally {
                showExportProgressDialog = false
            }
        }
    }


    val executeAlightXmlExport: (List<ArtboardData>) -> Unit = { targetArtboards ->
        val exportList = if (targetArtboards.isEmpty()) {
            artboards.find { it.id == selectedArtboardId }?.let { listOf(it) } ?: listOf(ArtboardData(selectedArtboardId, "Canvas", canvasWidth, canvasHeight, layers))
        } else targetArtboards

        android.widget.Toast.makeText(context, "Exporting ${exportList.size} Alight Motion XML template(s)...", android.widget.Toast.LENGTH_SHORT).show()
        showExportProgressDialog = true
        exportProgressValue = 0f
        exportProgressText = "Preparing Alight XML export..."
        exportJob = scope.launch {
            try {
                var successCount = 0
                for (index in exportList.indices) {
                    exportProgressValue = index.toFloat() / exportList.size
                    exportProgressText = "Exporting XML ${index + 1} of ${exportList.size}..."
                    kotlinx.coroutines.yield()
                    
                    val art = exportList[index]
                    val artLayers = if (art.id == selectedArtboardId) layers else art.layers
                    val sanitizeName = art.name.replace(Regex("[^a-zA-Z0-9_-]"), "_")
                    val filename = (if (projectName.isBlank()) "AlightScene" else projectName) + "_" + sanitizeName + "_" + System.currentTimeMillis() + "_" + (index + 1)
                    val uri = AlightXmlEngine.saveAlightXmlToDownloads(
                        context = context,
                        projectName = filename,
                        canvasWidth = art.width,
                        canvasHeight = art.height,
                        layers = artLayers
                    )
                    if (uri != null) successCount++
                }
                if (successCount > 0) {
                    android.widget.Toast.makeText(context, "Exported $successCount Alight XML file(s) successfully to Download/AlightExports!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    android.widget.Toast.makeText(context, "Export failed. Please check device state.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                android.widget.Toast.makeText(context, "Alight XML Export cancelled.", android.widget.Toast.LENGTH_SHORT).show()
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "Alight XML Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            } finally {
                showExportProgressDialog = false
            }
        }
    }

    val executePdfExport: (List<ArtboardData>) -> Unit = { targetArtboards ->
        val exportList = if (targetArtboards.isEmpty()) {
            artboards.find { it.id == selectedArtboardId }?.let { listOf(it) } ?: listOf(ArtboardData(selectedArtboardId, "Canvas", canvasWidth, canvasHeight, layers))
        } else targetArtboards

        android.widget.Toast.makeText(context, "Exporting artwork as PDF (${exportList.size} page(s))...", android.widget.Toast.LENGTH_SHORT).show()
        showExportProgressDialog = true
        exportProgressValue = 0f
        exportProgressText = "Preparing PDF export..."
        exportJob = scope.launch {
            try {
                val pdfDocument = android.graphics.pdf.PdfDocument()
                var pageNum = 1
                for (art in exportList) {
                    val artLayers = if (art.id == selectedArtboardId) layers else art.layers
                    val targetW = art.width
                    val targetH = art.height
                    
                    val exportedBitmap = withContext(Dispatchers.Default) {
                        exportCanvasToBitmap(
                            context = context,
                            canvasWidth = art.width,
                            canvasHeight = art.height,
                            layers = artLayers,
                            imageBitmapCache = imageBitmapCache,
                            targetWidth = targetW,
                            targetHeight = targetH,
                            isCmyk = false,
                            isBackgroundTransparent = isBackgroundTransparent,
                            warpMeshDivisionX = warpMeshDivisionX,
                            warpMeshDivisionY = warpMeshDivisionY,
                            warpRepeatMode = warpRepeatMode,
                            warpRepeatX = warpRepeatX,
                            warpRepeatY = warpRepeatY,
                            warpPhaseX = warpPhaseX,
                            warpPhaseY = warpPhaseY,
                            warpInterpolation = warpInterpolation,
                            warpTarget = warpTarget,
                            onProgress = { p, txt ->
                                scope.launch(Dispatchers.Main) {
                                    exportProgressValue = p
                                    exportProgressText = txt
                                }
                            }
                        )
                    }
                    
                    val pageInfo = android.graphics.pdf.PdfDocument.PageInfo.Builder(targetW.toInt(), targetH.toInt(), pageNum++).create()
                    val page = pdfDocument.startPage(pageInfo)
                    val canvas = page.canvas
                    val paint = android.graphics.Paint()
                    canvas.drawBitmap(exportedBitmap, 0f, 0f, paint)
                    pdfDocument.finishPage(page)
                    if (!exportedBitmap.isRecycled) {
                        exportedBitmap.recycle()
                    }
                }
                
                val filename = (if (projectName.isBlank()) "Masterpiece" else projectName) + "_" + System.currentTimeMillis() + ".pdf"
                val resolver = context.contentResolver
                val contentValues = android.content.ContentValues().apply {
                    put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME, filename)
                    put(android.provider.MediaStore.MediaColumns.MIME_TYPE, "application/pdf")
                    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {
                        put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH, android.os.Environment.DIRECTORY_DOCUMENTS + "/PhotoshopExports")
                    }
                }
                
                val uri = resolver.insert(android.provider.MediaStore.Files.getContentUri("external"), contentValues)
                if (uri != null) {
                    resolver.openOutputStream(uri)?.use { os ->
                        pdfDocument.writeTo(os)
                    }
                    pdfDocument.close()
                    android.widget.Toast.makeText(context, "Successfully exported PDF (${exportList.size} page(s)) to Documents/PhotoshopExports!", android.widget.Toast.LENGTH_LONG).show()
                } else {
                    pdfDocument.close()
                    android.widget.Toast.makeText(context, "Failed to create PDF file entry.", android.widget.Toast.LENGTH_LONG).show()
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                android.widget.Toast.makeText(context, "PDF Export cancelled.", android.widget.Toast.LENGTH_SHORT).show()
            } catch (e: Throwable) {
                android.widget.Toast.makeText(context, "PDF Export error: ${e.localizedMessage ?: e.javaClass.simpleName}", android.widget.Toast.LENGTH_LONG).show()
            } finally {
                showExportProgressDialog = false
            }
        }
    }

    val onExportArtwork: () -> Unit = {
        artboards = artboards.map {
