    } else {
        @Composable
        fun DesignPhase() {
        @Composable
        fun RenderBottomEffectPanel(isLandscapeMode: Boolean) {
            val activeArtboard = artboards.find { it.id == selectedArtboardId } ?: artboards.firstOrNull()
            val artW = activeArtboard?.width ?: 1080f
            val artH = activeArtboard?.height ?: 1080f
            val rulerSettings = remember(rulers, selectedRulerId, snapToRuler, allRulersLocked) {
                WorkspaceRulerSettings(
                    rulers = rulers,
                    onRulersChange = { rulers = it },
                    selectedRulerId = selectedRulerId,
                    onSelectedRulerIdChange = { selectedRulerId = it },
                    snapToRuler = snapToRuler,
                    onSnapToRulerChange = { snapToRuler = it },
                    allRulersLocked = allRulersLocked,
                    onAllRulersLockedChange = { allRulersLocked = it }
                )
            }
            CompositionLocalProvider(LocalRulerSettings provides rulerSettings) {
                BottomEffectPanel(
                artboardWidth = artW,
                artboardHeight = artH,
                onClearPathCache = { /* pathCache.clear() */ },
                workspaceViewModel = workspaceViewModel,
                selectedLayer = selectedLayer,
                onOpenColorPickerDialog = { idx ->
                    activeGradientStopIndex = idx
                    showGradientColorPickerDialog = true
                },
                selectedEffectIndex = selectedEffectIndex,
                onSelectEffectIndex = { selectedEffectIndex = it },
                onAddEffect = { effect ->
                    if (selectedLayer != null) {
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                layer.copy(effects = layer.effects + effect)
                            } else layer
                        }
                    }
                },
                onUpdateEffectParam = { effectId, paramName, newValue ->
                    if (selectedLayer != null) {
                        com.aistudio.zenithstudio.rpxwtq.EffectStackManager.notifySliderInteraction()
                        com.example.studio.ui.CanvasEventLoop.emit(
                            com.example.studio.ui.CanvasEvent.UpdateSlider(
                                layerId = selectedLayer.id,
                                effectId = effectId,
                                paramName = paramName,
                                value = newValue
                            )
                        )
                    }
                },
                onRemoveEffect = { effectId ->
                    if (selectedLayer != null) {
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                layer.copy(effects = layer.effects.filter { it.id != effectId })
                            } else layer
                        }
                    }
                },
                onDuplicateEffect = { effectId ->
                    if (selectedLayer != null) {
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                val effectToDuplicate = layer.effects.find { it.id == effectId }
                                if (effectToDuplicate != null) {
                                    val duplicated = effectToDuplicate.duplicate()
                                    val idx = layer.effects.indexOf(effectToDuplicate)
                                    val newList = layer.effects.toMutableList()
                                    newList.add(idx + 1, duplicated)
                                    layer.copy(effects = newList)
                                } else layer
                            } else layer
                        }
                    }
                },
                onToggleEffectEnabled = { effectId ->
                    if (selectedLayer != null) {
                        undoStack.add(layers)
                        redoStack.clear()
                        layers = layers.map { layer ->
                            if (layer.id == selectedLayer.id) {
                                val updatedEffects = layer.effects.map { eff ->
                                    if (eff.id == effectId) {
                                        eff.toggleEnabled()
                                    } else eff
                                }
                                layer.copy(effects = updatedEffects)
                            } else layer
                        }
                    }
                },
                onUpdateLayer = { updatedLayer ->
                    layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                },
                onCloseBottomPanel = {
                    isBottomPanelVisible = false
                    selectedLayerId = ""
                },
                onOpenEffectsGallery = { showEffectsGallery = true },
                onOpenZenithEffects = { showZenithEffectsOverlay = true },
                onOpenBrushesLibrary = { showBrushesLibrary = true },
                activeTool = activeTool,
                brushSize = brushSize,
                onBrushSizeChange = { brushSize = it },
                onBrushOpacityChange = { brushOpacity = it },
                brushOpacity = brushOpacity,
                brushColor = brushColor,
                onBrushColorChange = { brushColor = it },
                brushSmoothing = brushSmoothing,
                onBrushSmoothingChange = { brushSmoothing = it },
                brushPresetIndex = brushPresetIndex,
                onBrushPresetIndexChange = { brushPresetIndex = it },
                brushHardness = brushHardness,
                onBrushHardnessChange = { brushHardness = it },
                eraserSize = eraserSize,
                onEraserSizeChange = { eraserSize = it },
                eraserHardness = eraserHardness,
                onEraserHardnessChange = { eraserHardness = it },
                fontSearchQuery = fontSearchQuery,
                onFontSearchQueryChange = { fontSearchQuery = it },
                selectedCategoryFilter = selectedCategoryFilter,
                onSelectedCategoryFilterChange = { selectedCategoryFilter = it },
                onImportFontClick = { showFontScannerDialog = true },
                onExportCanvas = onExportArtwork,
                gridEnabled = gridEnabled,
                onGridEnabledChange = { gridEnabled = it },
                rulerEnabled = rulerEnabled,
                onRulerEnabledChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(enabled = value) else it } },
                rulerOrientation = rulerOrientation,
                onRulerOrientationChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(orientation = value) else it } },
                rulerPosition = rulerPosition,
                onRulerPositionChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(position = value) else it } },
                gridColumns = gridColumns,
                onGridColumnsChange = { gridColumns = it },
                gridRows = gridRows,
                onGridRowsChange = { gridRows = it },
                rulerAngle = rulerAngle,
                onRulerAngleChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(angle = value) else it } },
                rulerLocked = rulerLocked,
                onRulerLockedChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(locked = value) else it } },
                snapToRuler = snapToRuler,
                onSnapToRulerChange = { snapToRuler = it },
                activeFullScreenSheet = activeFullScreenSheet,
                onActiveFullScreenSheetChange = { activeFullScreenSheet = it },
                isLandscape = isLandscapeMode,
                projectColorProfile = projectColorProfile,
                selectedCmykProfile = selectedCmykProfile
            )
            }
        }

        // App Workspace UI Grid Root
        Box(
            modifier = modifier
                .fillMaxSize()
                .background(DarkOnyx)
                .windowInsetsPadding(WindowInsets.safeDrawing.exclude(WindowInsets.ime))
        ) {
            // -- FLOATING PLATFORM CONTROL SHELF --
            val shelfAlignment = if (controlBarPosition == "Bottom") Alignment.BottomCenter else Alignment.TopCenter
            val shelfBottomPadding = if (controlBarPosition == "Bottom") {
                var pad = 12.dp
                if (workspaceLayoutMode == "Mobile" && isMobileBottomDockVisible) pad += 80.dp
                if (isBottomPanelVisible && activeFullScreenSheet == null && selectedLayer != null && !isLandscape) pad += 68.dp
                if (activeFullScreenSheet != null && !isLandscape) {
                    pad += if (activeFullScreenSheet == "Ruler" || activeFullScreenSheet == "Grid") 260.dp else 400.dp
                }
                pad
            } else 0.dp
            val shelfTopPadding = if (controlBarPosition == "Top") 8.dp else 0.dp

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .align(shelfAlignment)
                    .padding(top = shelfTopPadding, bottom = shelfBottomPadding, start = 8.dp, end = 8.dp)
                    .zIndex(18f)
            ) {
                TopControlShelf(
                activeTool = activeTool,
                onToolChange = {
                    activeTool = it
                    if (it == "Brush" || it == "Pen" || it == "Eraser") {
                        isBottomPanelVisible = true
                        activeFullScreenSheet = "Brush"
                    }
                },
                isLeftToolbarExpanded = isLeftToolbarExpanded,
                onToggleLeftToolbar = { isLeftToolbarExpanded = !isLeftToolbarExpanded },
                onUndo = {
                    val filterUndone = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.performUndo()
                    val currentMemento = com.example.studio.model.ProjectMemento(
                        artboards = artboards.map {
                            if (it.id == selectedArtboardId) it.copy(layers = layers) else it
                        },
                        selectedArtboardId = selectedArtboardId,
                        selectedLayerId = selectedLayerId,
                        projectName = projectName,
                        canvasWidth = canvasWidth,
                        canvasHeight = canvasHeight,
                        projectDpi = projectDpi
                    )
                    val prev = projectHistoryManager.performUndo(currentMemento)
                    if (prev != null) {
                        artboards = prev.artboards
                        selectedArtboardId = prev.selectedArtboardId
                        val activeArt = prev.artboards.find { it.id == prev.selectedArtboardId } ?: prev.artboards.firstOrNull()
                        layers = activeArt?.layers ?: emptyList()
                        selectedLayerId = prev.selectedLayerId
                        projectName = prev.projectName
                        canvasWidth = prev.canvasWidth
                        canvasHeight = prev.canvasHeight
                        projectDpi = prev.projectDpi
                        advancedBrushResultCache.clear()
                    } else if (filterUndone) {
                        // Force recomposition to refresh rendered layers with undone filter state
                        layers = layers.map { it.copy() }
                    }
                },
                onRedo = {
                    val filterRedone = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.performRedo()
                    val currentMemento = com.example.studio.model.ProjectMemento(
                        artboards = artboards.map {
                            if (it.id == selectedArtboardId) it.copy(layers = layers) else it
                        },
                        selectedArtboardId = selectedArtboardId,
                        selectedLayerId = selectedLayerId,
                        projectName = projectName,
                        canvasWidth = canvasWidth,
                        canvasHeight = canvasHeight,
                        projectDpi = projectDpi
                    )
                    val next = projectHistoryManager.performRedo(currentMemento)
                    if (next != null) {
                        artboards = next.artboards
                        selectedArtboardId = next.selectedArtboardId
                        val activeArt = next.artboards.find { it.id == next.selectedArtboardId } ?: next.artboards.firstOrNull()
                        layers = activeArt?.layers ?: emptyList()
                        selectedLayerId = next.selectedLayerId
                        projectName = next.projectName
                        canvasWidth = next.canvasWidth
                        canvasHeight = next.canvasHeight
                        projectDpi = next.projectDpi
                        advancedBrushResultCache.clear()
                    } else if (filterRedone) {
                        // Force recomposition to refresh rendered layers with redone filter state
                        layers = layers.map { it.copy() }
                    }
                },
                canUndo = undoStack.isNotEmpty() || com.aistudio.zenithstudio.rpxwtq.EffectStackManager.canUndo(),
                canRedo = redoStack.isNotEmpty() || com.aistudio.zenithstudio.rpxwtq.EffectStackManager.canRedo(),
                layersPanelVisible = isLayersPanelVisible,
                onToggleLayersPanel = { isLayersPanelVisible = !isLayersPanelVisible },
                bottomPanelVisible = isBottomPanelVisible,
                onToggleBottomPanel = { isBottomPanelVisible = !isBottomPanelVisible },
                onExitWorkspace = {
                    if (projectId.isNotEmpty()) {
                        val currentMemento = com.example.studio.model.ProjectMemento(
                            artboards = artboards.map {
                                if (it.id == selectedArtboardId) {
                                    it.copy(layers = layers)
                                } else {
                                    it
                                }
                            },
                            selectedArtboardId = selectedArtboardId,
                            selectedLayerId = selectedLayerId,
                            projectName = projectName,
                            canvasWidth = canvasWidth,
                            canvasHeight = canvasHeight,
                            projectDpi = projectDpi
                        )
                        // Force save of workspace immediately on exit
                        workspaceViewModel.saveWorkspace(
                            id = projectId,
                            name = projectName,
                            width = canvasWidth,
                            height = canvasHeight,
                            artboards = currentMemento.artboards,
                            selectedArtboardId = selectedArtboardId,
                            dpi = projectDpi
                        )
                        // Save a thumbnail
                        scope.launch(kotlinx.coroutines.Dispatchers.IO) {
                            try {
                                val bitmap = exportCanvasToBitmap(
                                    context = context,
                                    canvasWidth = canvasWidth,
                                    canvasHeight = canvasHeight,
                                    layers = currentMemento.artboards.find { it.id == selectedArtboardId }?.layers ?: emptyList(),
                                    imageBitmapCache = imageBitmapCache,
                                    targetWidth = 1080f,
                                    targetHeight = 1350f,
                                    isBackgroundTransparent = false,
                                    isThumbnail = true
                                )
                                val thumbFile = java.io.File(context.filesDir, "thumb_${projectId}.png")
                                java.io.FileOutputStream(thumbFile).use { out ->
                                    bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 80, out)
                                }
                            } catch (e: Exception) {
                                e.printStackTrace()
                            }
                        }
                        projectHistoryManager.serializeAndSaveHistory(projectId, currentMemento)
                    }

                    // Reset workspace when exiting to main menu
                    isProjectInitialized = false
                    isLayersPanelVisible = false
                    isBottomPanelVisible = false
                    projectId = ""
                    projectName = ""
                    layers = emptyList()
                    selectedLayerId = ""
                    activeTool = "Move"
                    imageBitmapCache.clear()
                    advancedBrushResultCache.clear()
                    workspaceViewModel.clearSession()
                },
                onExportCanvas = onExportArtwork,
                isLandscape = isLandscape,
                onToggleOrientation = {
                    manualLandscapeOverride = !isLandscape
                },
                onOpenPerformanceOptimizer = {
                    globalShowPerformanceOptimizerDialog = true
                },
                toolPanelSide = toolPanelSide,
                onToggleToolPanelSide = {
                    val nextSide = if (toolPanelSide == "Left") "Right" else "Left"
                    toolPanelSide = nextSide
                    context.getSharedPreferences("studio_prefs", android.content.Context.MODE_PRIVATE).edit().putString("tool_panel_side", nextSide).apply()
                },
                controlBarPosition = controlBarPosition,
                onToggleControlBarPosition = {
                    val nextPos = if (controlBarPosition == "Top") "Bottom" else "Top"
                    controlBarPosition = nextPos
                    context.getSharedPreferences("studio_prefs", android.content.Context.MODE_PRIVATE).edit().putString("control_bar_position", nextPos).apply()
                }
            )
            }

            if (globalShowPerformanceOptimizerDialog) {
                com.example.studio.ui.dialogs.PerformanceOptimizerDialog(
                    onDismissRequest = { globalShowPerformanceOptimizerDialog = false }
                )
            }

            if (showRenameProjectDialog) {
                AlertDialog(
                    onDismissRequest = { showRenameProjectDialog = false },
                    title = { Text("Rename Design Masterpiece", color = TextPrimary, style = Typography.titleMedium) },
                    text = {
                        OutlinedTextField(
                            value = projectRenameValue,
                            onValueChange = { projectRenameValue = it },
                            label = { Text("Design Title", style = Typography.bodyMedium) },
                            textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = IndustrialAmber,
                                focusedLabelColor = IndustrialAmber,
                                cursorColor = IndustrialAmber,
                                unfocusedBorderColor = HighslateOutline,
                                unfocusedLabelColor = TextSecondary
                            ),
                            singleLine = true,
                            modifier = Modifier.fillMaxWidth()
                        )
                    },
                    confirmButton = {
                        Button(
                            onClick = {
                                if (projectRenameValue.isNotBlank()) {
                                    projectName = projectRenameValue
                                }
                                showRenameProjectDialog = false
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber)
                        ) {
                            Text("SAVE", color = DarkOnyx, fontWeight = FontWeight.Bold, style = Typography.bodyMedium)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showRenameProjectDialog = false }) {
                            Text("CANCEL", color = TextSecondary, style = Typography.bodyMedium)
                        }
                    },
                    containerColor = SlatePanel,
                    shape = RoundedCornerShape(12.dp)
                )
            }

            // -- MAIN CREATIVE CORE LAYOUT --
            Box(
                modifier = Modifier.fillMaxSize()
            ) {
                // MOBILE BOTTOM DOCK (Mobile Layout style)
                androidx.compose.animation.AnimatedVisibility(
                    visible = workspaceLayoutMode == "Mobile" && isMobileBottomDockVisible && activeFullScreenSheet == null && !showZenithEffectsOverlay && !showBrushesLibrary && !showEffectsGallery && !showAddShapeDialog && !showVisualsOverlayHub,
                    enter = slideInVertically(initialOffsetY = { it }) + fadeIn(),
                    exit = slideOutVertically(targetOffsetY = { it }) + fadeOut(),
                    modifier = Modifier
                        .align(Alignment.BottomCenter)
                        .zIndex(15f)
                ) {
                    MobileBottomDock(
                        activeTool = activeTool,
                        onSelectTool = { tool ->
                            activeTool = tool
                            if (tool == "Brush" || tool == "Pen" || tool == "Eraser") {
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Brush"
                            }
                            if (tool == "Shapes") {
                                showAddShapeDialog = true
                            } else if (tool == "Import") {
                                showImportOptionMenu = true
                                activeTool = "Move"
                            } else if (tool == "Text") {
                                val newL = StudioLayer(
                                    name = "Text Layer",
                                    type = LayerType.TEXT,
                                    positionX = 350f,
                                    positionY = 450f,
                                    width = 350f,
                                    height = 100f,
                                    baseColor = Color.Black,
                                    textContent = "Text Layer"
                                )
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = listOf(newL) + layers
                                selectedLayerId = newL.id
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Shape"
                                activeTool = "Move"
                            } else if (tool == "Grid") {
                                gridEnabled = true
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Grid"
                            } else if (tool == "Ruler") {
                                rulers = rulers.map { r -> if (r.id == selectedRulerId) r.copy(enabled = true) else r }
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Ruler"
                            } else if (tool == "Visuals") {
                                showVisualsOverlayHub = true
                                activeTool = "Move"
                            }
                        },
                        isBottomPanelVisible = isBottomPanelVisible,
                        activeFullScreenSheet = activeFullScreenSheet,
                        showZenithEffectsOverlay = showZenithEffectsOverlay,
                        onClose = { isMobileBottomDockVisible = false }
                    )
                }

                // GLOWING TOGGLE BUTTON (to restore Mobile Bottom Dock)
                androidx.compose.animation.AnimatedVisibility(
                    visible = workspaceLayoutMode == "Mobile" && !isMobileBottomDockVisible,
                    enter = fadeIn() + scaleIn(),
                    exit = fadeOut() + scaleOut(),
                    modifier = Modifier
                        .align(Alignment.BottomCenter)
                        .padding(bottom = 16.dp)
                        .zIndex(15f)
                ) {
                    Button(
                        onClick = { isMobileBottomDockVisible = true },
                        colors = ButtonDefaults.buttonColors(containerColor = SlatePanel.copy(alpha = 0.9f)),
                        border = BorderStroke(1.2.dp, IndustrialAmber),
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier
                            .height(40.dp)
                            .testTag("restore_bottom_dock_button")
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Default.Construction,
                                contentDescription = "Restore Toolbar",
                                tint = IndustrialAmber,
                                modifier = Modifier.size(16.dp)
                            )
                            Text(
                                text = "Show Tools",
                                style = Typography.labelMedium,
                                fontWeight = FontWeight.Bold,
                                color = TextPrimary
                            )
                        }
                    }
                }

                // COMPACT FLOATING TOOLBAR
                val dockAlignment = if (toolPanelSide == "Right") Alignment.TopEnd else Alignment.TopStart
                val dockStartPadding = if (toolPanelSide == "Right") 0.dp else 8.dp
                val dockEndPadding = if (toolPanelSide == "Right") 8.dp else 0.dp

                androidx.compose.animation.AnimatedVisibility(
                    visible = isLeftToolbarExpanded && workspaceLayoutMode == "Classic",
                    enter = if (toolPanelSide == "Right") slideInHorizontally(initialOffsetX = { it }) + fadeIn() else slideInHorizontally(initialOffsetX = { -it }) + fadeIn(),
                    exit = if (toolPanelSide == "Right") slideOutHorizontally(targetOffsetX = { it }) + fadeOut() else slideOutHorizontally(targetOffsetX = { -it }) + fadeOut(),
                    modifier = Modifier
                        .align(dockAlignment)
                        .padding(start = dockStartPadding, end = dockEndPadding)
                        .zIndex(15f)
                ) {
                    LeftsideToolDock(
                        activeTool = activeTool,
                        onSelectTool = {
                            activeTool = it
                            if (it == "Brush" || it == "Pen" || it == "Eraser") {
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Brush"
                            }
                            if (it == "Shapes") {
                                showAddShapeDialog = true
                            } else if (it == "Import") {
                                showImportOptionMenu = true
                                activeTool = "Move"
                            } else if (it == "Text") {
                                val newL = StudioLayer(
                                    name = "Text Layer",
                                    type = LayerType.TEXT,
                                    positionX = 350f,
                                    positionY = 450f,
                                    width = 350f,
                                    height = 100f,
                                    baseColor = Color.Black,
                                    textContent = "Text Layer"
                                )
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = listOf(newL) + layers
                                selectedLayerId = newL.id
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Shape"
                                activeTool = "Move"
                            } else if (it == "Grid") {
                                gridEnabled = true
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Grid"
                            } else if (it == "Ruler") {
                                rulers = rulers.map { r -> if (r.id == selectedRulerId) r.copy(enabled = true) else r }
                                isBottomPanelVisible = true
                                activeFullScreenSheet = "Ruler"
                            } else if (it == "Visuals") {
                                showVisualsOverlayHub = true
                                activeTool = "Move"
                            }
                        },
                        isBottomPanelVisible = isBottomPanelVisible,
                        activeFullScreenSheet = activeFullScreenSheet,
                        showZenithEffectsOverlay = showZenithEffectsOverlay,
                        toolPanelSide = toolPanelSide,
                        controlBarPosition = controlBarPosition
                    )
                }

                // Central Workspace Canvas Container - Full Background immersive view
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(end = rightPadding, bottom = bottomPadding)
                        .graphicsLayer {
                            clip = true
                        }
                        .onSizeChanged { size ->
                            viewportWidth = size.width.toFloat()
                            viewportHeight = size.height.toFloat()
                        }
                        .testTag("canvas_viewport"),
                    contentAlignment = Alignment.Center
                ) {
                    // Chess board / transparency checker grid background simulation
                    Canvas(
                        modifier = Modifier
                            .fillMaxSize()
                            .graphicsLayer {
                                clip = true
                            }
                            .pointerInput(Unit) {
                                awaitPointerEventScope {
                                    while (true) {
                                        val event = awaitPointerEvent()
                                        val position = event.changes.firstOrNull()?.position
                                        if (position != null) {
                                            lastPointerPosition = position
                                        }
                                    }
                                }
                            }
                            .drawBehind {
                                // Super-performant, single-draw background fill for the entire workspace
                                drawRect(
                                    color = Color(0xFF0B0F19), // Deep Obsidian Midnight Blue
                                    topLeft = Offset.Zero,
                                    size = size
                                )
                            }
                            // Single unified pointer input block combining Tap selection, multi-touch Pan/Zoom/Rotate, and single-finger Layer Move/Resize/Draw
                            .pointerInput(Unit) {
                                awaitEachGesture {
                                    val down = awaitFirstDown(requireUnconsumed = false)
                                    var dragMode: String? = null
                                    var isTransforming = false
                                    var hasMovedPastSlop = false
                                    val touchSlop = viewConfiguration.touchSlop
                                    var accumOffset = Offset.Zero

                                    var activeScale = scaleFactor
                                    var activePanX = canvasPanX
                                    var activePanY = canvasPanY
                                    var activeRotation = canvasRotation

                                    val totalScale = currentFitScaleState.value * currentScaleFactorState.value; val ts = totalScale
                                    var lyrs = currentLayersState.value
                                    var selId = currentSelectedLayerIdState.value
                                    val isLocked = lyrs.find { it.id == selId }?.isAlphaLocked == true
                                    val tool = currentActiveToolState.value
                                    val artboards = currentArtboardsState.value
                                    var selectedArtboardId = currentSelectedArtboardIdState.value
                                    val showGradientControls = currentShowGradientControlsState.value
                                    val penSubTool = currentPenSubToolState.value
                                    val brushColor = currentBrushColorState.value
                                    val brushSize = currentBrushSizeState.value
                                    val brushOpacity = currentBrushOpacityState.value
                                    val brushSmoothing = currentBrushSmoothingState.value
                                    val brushPresetIndex = currentBrushPresetIndexState.value
                                    val brushHardness = currentBrushHardnessState.value
                                    val eraserSize = currentEraserSizeState.value
                                    val eraserHardness = currentEraserHardnessState.value

                                    val visibleViewportCenterY = currentVisibleViewportCenterYState.value

                                    val localStartOffset = screenToCanvas(
                                        screenPos = down.position,
                                        viewportWidth = currentViewportWidthState.value,
                                        viewportHeight = currentViewportHeightState.value,
                                        canvasPanX = canvasPanX,
                                        canvasPanY = canvasPanY,
                                        canvasRotation = canvasRotation,
                                        totalScale = ts,
                                        centerX = currentWorkspaceCenterXState.value,
                                        centerY = currentWorkspaceCenterYState.value,
                                        viewportCenterY = visibleViewportCenterY
                                    )
                                    val localStartX = localStartOffset.x
                                    val localStartY = localStartOffset.y

                                    // Dynamic secondary artboard selection on touch down
                                    val clickedArtboard = artboards.find { art ->
                                        localStartX >= art.offsetX && localStartX <= (art.offsetX + art.width) &&
                                        localStartY >= art.offsetY && localStartY <= (art.offsetY + art.height)
                                    }
                                    if (clickedArtboard != null && clickedArtboard.id != selectedArtboardId) {
                                        selectArtboard(clickedArtboard.id)
                                        selectedArtboardId = clickedArtboard.id
                                        lyrs = clickedArtboard.layers
                                        val topLayer = clickedArtboard.layers.firstOrNull { it.isVisible }
                                        if (topLayer != null) {
                                            selId = topLayer.id
                                            selectedLayerId = topLayer.id
                                        } else {
                                            selId = ""
                                            selectedLayerId = ""
                                        }
                                    }

                                    val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                    val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                    val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                    val artboardWidth = activeArtboard?.width ?: 1080f
                                    val artboardHeight = activeArtboard?.height ?: 1350f

                                    if (GradientEyedropperState.isActive) {
                                        dragMode = "eyedropper"
                                        GradientEyedropperState.touchPoint = localStartOffset
                                        
                                        // Immediately sample color on down
                                        val artRelativeX = localStartX - artboardOffsetX
                                        val artRelativeY = localStartY - artboardOffsetY
                                        val liveSampledColor = sampleCompositedColor(
                                            layers = layers,
                                            artRelativeX = artRelativeX,
                                            artRelativeY = artRelativeY,
                                            artboardWidth = artboardWidth,
                                            artboardHeight = artboardHeight,
                                            imageBitmapCache = imageBitmapCache
                                        )
                                        
                                        if (GradientEyedropperState.onColorSampled != null) {
                                            GradientEyedropperState.liveSampledColor = liveSampledColor
                                        } else {
                                            val currentSelected = lyrs.find { it.id == selId }
                                            if (currentSelected != null) {
                                                if (GradientEyedropperState.isSamplingForSolidColor) {
                                                    layers = layers.map { layer ->
                                                        if (layer.id == currentSelected.id) {
                                                            layer.copy(baseColor = liveSampledColor)
                                                        } else layer
                                                    }
                                                } else {
                                                    val targetStopIndex = activeGradientStopIndex.coerceIn(0, 100)
                                                    layers = layers.map { layer ->
                                                        if (layer.id == currentSelected.id) {
                                                            val updatedEffects = layer.effects.map { eff ->
                                                                if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                    val map = eff.parameters.toMutableMap()
                                                                    map["CustomStop_${targetStopIndex}_R"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_R", liveSampledColor.red, 0f, 1f)
                                                                    map["CustomStop_${targetStopIndex}_G"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_G", liveSampledColor.green, 0f, 1f)
                                                                    map["CustomStop_${targetStopIndex}_B"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_B", liveSampledColor.blue, 0f, 1f)
                                                                    map["CustomStop_${targetStopIndex}_A"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_A", liveSampledColor.alpha, 0f, 1f)
                                                                    eff.copy(parameters = map)
                                                                } else eff
                                                            }
                                                            layer.copy(effects = updatedEffects)
                                                        } else layer
                                                    }
                                                }
                                            }
                                        }
                                    }

                                    val isDrawingTool = tool == "Brush" || tool == "Eraser" || tool == "Pen"
                                    val artboardStartX = localStartX - artboardOffsetX
                                    val artboardStartY = localStartY - artboardOffsetY

                                    // Is the touch starting inside the active artboard?
                                    val isTouchInActiveArtboard = !isDrawingTool || (artboardStartX >= 0f && artboardStartX <= artboardWidth &&
                                                                  artboardStartY >= 0f && artboardStartY <= artboardHeight)

                                    var draggedRulerId: String? = null
                                    if (tool == "Ruler" || activeFullScreenSheet == "Ruler" || currentRulersState.value.isNotEmpty()) {
                                        val threshold = 35f / ts.coerceAtLeast(0.3f)
                                        var nearestRuler: StudioRuler? = null
                                        var minDistance = Float.MAX_VALUE
                                        for (ruler in currentRulersState.value) {
                                            if (!ruler.enabled) continue
                                            val dist = if (ruler.angle != 0f) {
                                                val angleRad = (ruler.angle * Math.PI / 180.0)
                                                val dX: Float
                                                val dY: Float
                                                val aX: Float
                                                val aY: Float
                                                if (ruler.orientation == "Horizontal") {
                                                    dX = Math.cos(angleRad).toFloat()
                                                    dY = Math.sin(angleRad).toFloat()
                                                    aX = artboardOffsetX + artboardWidth / 2f
                                                    aY = artboardOffsetY + ruler.position
                                                } else {
                                                    dX = -Math.sin(angleRad).toFloat()
                                                    dY = Math.cos(angleRad).toFloat()
                                                    aX = artboardOffsetX + ruler.position
                                                    aY = artboardOffsetY + artboardHeight / 2f
                                                }
                                                val t = (localStartX - aX) * dX + (localStartY - aY) * dY
                                                val closestX = aX + t * dX
                                                val closestY = aY + t * dY
                                                val distSq = (localStartX - closestX) * (localStartX - closestX) + (localStartY - closestY) * (localStartY - closestY)
                                                Math.sqrt(distSq.toDouble()).toFloat()
                                            } else {
                                                val visualPos = if (ruler.orientation == "Horizontal") {
                                                    artboardOffsetY + ruler.position
                                                } else {
                                                    artboardOffsetX + ruler.position
                                                }
                                                if (ruler.orientation == "Horizontal") {
                                                    Math.abs(localStartY - visualPos)
                                                } else {
                                                    Math.abs(localStartX - visualPos)
                                                }
                                            }
                                            if (dist < threshold && dist < minDistance) {
                                                minDistance = dist
                                                nearestRuler = ruler
                                            }
                                        }
                                        if (nearestRuler != null) {
                                            draggedRulerId = nearestRuler.id
                                            selectedRulerId = nearestRuler.id
                                        }
                                    }

                                    var lastEvent = down

                                     var isNearBezier = false
                                     val currentSelectedForNearCheck = lyrs.find { it.id == selId }
                                     if (currentSelectedForNearCheck != null && currentSelectedForNearCheck.type == LayerType.VECTOR_BEZIER && tool == "Pen") {
                                         val thresholdTemp = 48f / ts.coerceAtLeast(0.3f)
                                         val thresholdTempSq = thresholdTemp * thresholdTemp
                                         if (currentSelectedForNearCheck.brushPoints.isNotEmpty()) {
                                             var nearestIndex = -1
                                             var minDistanceSq = Float.MAX_VALUE
                                             for (idx in currentSelectedForNearCheck.brushPoints.indices) {
                                                 val pt = currentSelectedForNearCheck.brushPoints[idx]
                                                 val canvasPt = layerLocalToCanvas(pt, currentSelectedForNearCheck)
                                                 val dx = (localStartOffset.x - artboardOffsetX) - canvasPt.x
                                                 val dy = (localStartOffset.y - artboardOffsetY) - canvasPt.y
                                                 val distSq = dx * dx + dy * dy
                                                 if (distSq < thresholdTempSq) {
                                                     if (idx % 3 != 0) {
                                                         val anchorIdx = (idx / 3) * 3
                                                         if (anchorIdx in currentSelectedForNearCheck.brushPoints.indices &&
                                                             currentSelectedForNearCheck.brushPoints[idx] == currentSelectedForNearCheck.brushPoints[anchorIdx]) {
                                                             continue
                                                         }
                                                     }
                                                     if (distSq < minDistanceSq) {
                                                         minDistanceSq = distSq
                                                         nearestIndex = idx
                                                     }
                                                 }
                                             }
                                             if (nearestIndex >= 0) {
                                                 activeBezierPointIndex = nearestIndex
                                                 isNearBezier = true
                                             }
                                         }
                                    }

                                    var isTransformingSelectedLayer = false

                                    do {
                                        val event = awaitPointerEvent()
                                        val activePointers = event.changes.filter { it.pressed }
                                        isDraggingBezierNode = (dragMode == "bezier" || dragMode == "pen_draw_handles")

                                        if (activePointers.size >= 2) {
                                            isTransforming = true
                                            dragMode = null

                                            val currentSelectedForPinch = lyrs.find { it.id == selId }
                                            val isShapeOrVectorLayer = currentSelectedForPinch != null && !currentSelectedForPinch.isAlphaLocked &&
                                                (currentSelectedForPinch.type != LayerType.FREEHAND_DRAWING || currentSelectedForPinch.brushPoints.isNotEmpty())

                                            var shouldTransformLayer = isTransformingSelectedLayer
                                            if (!shouldTransformLayer && isShapeOrVectorLayer && currentSelectedForPinch != null) {
                                                val p0 = activePointers[0].position
                                                val p1 = activePointers[1].position
                                                val midPointScreen = (p0 + p1) / 2f
                                                val midCanvas = screenToCanvas(
                                                    screenPos = midPointScreen,
                                                    viewportWidth = currentViewportWidthState.value,
                                                    viewportHeight = currentViewportHeightState.value,
                                                    canvasPanX = canvasPanX,
                                                    canvasPanY = canvasPanY,
                                                    canvasRotation = canvasRotation,
                                                    totalScale = ts,
                                                    centerX = currentWorkspaceCenterXState.value,
                                                    centerY = currentWorkspaceCenterYState.value,
                                                    viewportCenterY = visibleViewportCenterY
                                                )
                                                val midArtboard = Offset(midCanvas.x - artboardOffsetX, midCanvas.y - artboardOffsetY)
                                                val localMid = canvasToLayerLocal(midArtboard, currentSelectedForPinch)
                                                val touchPadding = 140f / ts.coerceAtLeast(0.3f)
                                                if (localMid.x >= -touchPadding && localMid.x <= currentSelectedForPinch.width + touchPadding &&
                                                    localMid.y >= -touchPadding && localMid.y <= currentSelectedForPinch.height + touchPadding) {
                                                    shouldTransformLayer = true
                                                }
                                            }

                                            if (shouldTransformLayer && currentSelectedForPinch != null) {
                                                isTransformingSelectedLayer = true
                                                val zoom = event.calculateZoom()
                                                val rotation = event.calculateRotation()
                                                val pan = event.calculatePan()
                                                val panCanvas = screenDeltaToCanvas(pan, canvasRotation, ts)

                                                if (zoom != 1f || rotation != 0f || pan != Offset.Zero) {
                                                    layers = layers.map { layer ->
                                                        if (layer.id == currentSelectedForPinch.id && !layer.isAlphaLocked) {
                                                            val newScaleX = (layer.scaleX * zoom).coerceIn(0.05f, 20f)
                                                            val newScaleY = (layer.scaleY * zoom).coerceIn(0.05f, 20f)
                                                            val newRot = (layer.rotation + rotation) % 360f
                                                            layer.copy(
                                                                scaleX = newScaleX,
                                                                scaleY = newScaleY,
                                                                rotation = newRot,
                                                                positionX = layer.positionX + panCanvas.x,
                                                                positionY = layer.positionY + panCanvas.y
                                                            )
                                                        } else layer
                                                    }
                                                }
                                                event.changes.forEach { it.consume() }
                                            } else {
                                                val isLocked = currentIsCanvasLockedState.value
                                                val zoom = if (isLocked) 1f else event.calculateZoom()
                                                val rotation = if (isLocked) 0f else event.calculateRotation()
                                                val pan = if (isLocked) Offset.Zero else event.calculatePan()

                                                if (zoom != 1f) {
                                                    activeScale = (activeScale * zoom).coerceIn(0.1f, 100.0f)
                                                }
                                                if (rotation != 0f) {
                                                    activeRotation = (activeRotation + rotation) % 360f
                                                }
                                                if (pan != Offset.Zero) {
                                                    val snappedNewPanX = activePanX + pan.x
                                                    val snappedNewPanY = activePanY + pan.y
                                                    val snappedFinalX = if (Math.abs(snappedNewPanX) < 2f) 0f else snappedNewPanX
                                                    val snappedFinalY = if (Math.abs(snappedNewPanY) < 2f) 0f else snappedNewPanY
                                                    activePanX = snappedFinalX
                                                    activePanY = snappedFinalY
                                                }

                                                scaleFactor = activeScale
                                                canvasPanX = activePanX
                                                canvasPanY = activePanY
                                                canvasRotation = activeRotation

                                                com.example.studio.ui.CanvasEventLoop.emit(
                                                    com.example.studio.ui.CanvasEvent.UpdateTransform(activePanX, activePanY, activeScale, activeRotation)
                                                )

                                                event.changes.forEach { it.consume() }
                                            }
                                        } else if (activePointers.size == 1 && !isTransforming) {
                                            val pointer = activePointers[0]
                                            val position = pointer.position
                                            val prevPosition = pointer.previousPosition
                                            val diff = position - prevPosition

                                            accumOffset += diff

                                            if (!hasMovedPastSlop) {
                                                if (accumOffset.getDistance() > touchSlop || (tool == "Brush" || tool == "Eraser")) {
                                                    hasMovedPastSlop = true

                                                    if (dragMode == "eyedropper") {
                                                        // Keep eyedropper mode active! Do not overwrite it with another tool/action.
                                                    } else if ((tool == "Brush" || tool == "Eraser") && isTouchInActiveArtboard) {
                                                        var targetId = selId
                                                        var currentSelected = lyrs.find { it.id == selId }

                                                        if (tool == "Eraser" && currentSelected == null && lyrs.isNotEmpty()) {
                                                            currentSelected = lyrs.find { it.type == LayerType.FREEHAND_DRAWING } ?: lyrs.first()
                                                            targetId = currentSelected.id
                                                            selectedLayerId = currentSelected.id
                                                        }

                                                        val needsNewLayer = if (tool == "Brush") {
                                                            currentSelected == null || currentSelected.type != LayerType.FREEHAND_DRAWING
                                                        } else {
                                                            currentSelected == null
                                                        }

                                                        if (needsNewLayer) {
                                                            val newL = StudioLayer(
                                                                name = if (tool == "Eraser") "Eraser Layer" else "Drawing Layer ${lyrs.filter { it.type == LayerType.FREEHAND_DRAWING }.size + 1}",
                                                                type = LayerType.FREEHAND_DRAWING,
                                                                positionX = 0f,
                                                                positionY = 0f,
                                                                width = artboardWidth,
                                                                height = artboardHeight,
                                                                baseColor = brushColor,
                                                                effects = listOf(
                                                                    PhotoshopEffectTemplates.create(effectType = "BrushConfig").let { eff ->
                                                                        var updated = eff.updateParameter("Size", brushSize)
                                                                        updated = updated.updateParameter("Opacity", brushOpacity)
                                                                        updated = updated.updateParameter("Smoothing", if (brushSmoothing) 1.0f else 0.0f)
                                                                        updated = updated.updateParameter("Preset", brushPresetIndex.toFloat())
                                                                        updated
                                                                    }
                                                                ),
                                                                brushPoints = emptyList()
                                                            )
                                                            undoStack.add(layers)
                                                            redoStack.clear()
                                                            layers = listOf(newL) + layers
                                                            selectedLayerId = newL.id
                                                            targetId = newL.id
                                                        }
                                                        strokeTracker.clear()
                                                        var snappedStartX = localStartX
                                                        var snappedStartY = localStartY
                                                        if (snapToRuler && currentRulersState.value.any { it.enabled }) {
                                                            val snapped = snapPointToRulers(
                                                                px = localStartX,
                                                                py = localStartY,
                                                                rulers = currentRulersState.value,
                                                                canvasWidth = currentCanvasWidthState.value,
                                                                canvasHeight = currentCanvasHeightState.value,
                                                                artboardOffsetX = artboardOffsetX,
                                                                artboardOffsetY = artboardOffsetY
                                                            )
                                                            snappedStartX = snapped.x
                                                            snappedStartY = snapped.y
                                                        }
                                                        strokeTracker.clear()
                                                        val activeL = layers.find { it.id == targetId }
                                                        val artboardStartX = (snappedStartX - artboardOffsetX).coerceIn(0f, artboardWidth)
                                                        val artboardStartY = (snappedStartY - artboardOffsetY).coerceIn(0f, artboardHeight)
                                                        val mappedStart = if (activeL != null) canvasToLayerLocal(Offset(artboardStartX, artboardStartY), activeL) else Offset(artboardStartX, artboardStartY)
                                                        strokeTracker.addPoint(mappedStart.x, mappedStart.y)
                                                        OpenGLBrushRenderer.WetInkRenderer.init(
                                                            (activeL?.width?.toInt() ?: artboardWidth.toInt()).coerceAtLeast(1),
                                                            (activeL?.height?.toInt() ?: artboardHeight.toInt()).coerceAtLeast(1)
                                                        )
                                                        val initX = mappedStart.x
                                                        val initY = mappedStart.y
                                                        OpenGLBrushRenderer.WetInkRenderer.drawInitialPoint(
                                                            point = Offset(initX, initY),
                                                            color = if (tool == "Eraser") androidx.compose.ui.graphics.Color.Black else brushColor,
                                                            size = if (tool == "Eraser") eraserSize else brushSize,
                                                            opacity = if (tool == "Eraser") 1.0f else brushOpacity,
                                                            presetIndex = if (tool == "Eraser") 0 else brushPresetIndex,
                                                            smoothing = if (tool == "Eraser") true else brushSmoothing
                                                        )
                                                        strokeDrawTrigger.value++
                                                    } else {
                                                        val currentSelected = lyrs.find { it.id == selId }
                                                        if (currentSelected != null && !currentSelected.isAlphaLocked) {
                                                            val handleTL = layerLocalToCanvas(Offset(0f, 0f), currentSelected)
                                                            val handleTR = layerLocalToCanvas(Offset(currentSelected.width, 0f), currentSelected)
                                                            val handleBL = layerLocalToCanvas(Offset(0f, currentSelected.height), currentSelected)
                                                            val handleBR = layerLocalToCanvas(Offset(currentSelected.width, currentSelected.height), currentSelected)
                                                            
                                                            val handleT = layerLocalToCanvas(Offset(currentSelected.width / 2f, 0f), currentSelected)
                                                            val handleB = layerLocalToCanvas(Offset(currentSelected.width / 2f, currentSelected.height), currentSelected)
                                                            val handleL = layerLocalToCanvas(Offset(0f, currentSelected.height / 2f), currentSelected)
                                                            val handleR = layerLocalToCanvas(Offset(currentSelected.width, currentSelected.height / 2f), currentSelected)
                                                            
                                                            val artStartX = localStartX - artboardOffsetX
                                                            val artStartY = localStartY - artboardOffsetY
                                                            
                                                            val dxTL = (artStartX - handleTL.x) * ts
                                                            val dyTL = (artStartY - handleTL.y) * ts
                                                            val distTL = dxTL * dxTL + dyTL * dyTL

                                                            val dxTR = (artStartX - handleTR.x) * ts
                                                            val dyTR = (artStartY - handleTR.y) * ts
                                                            val distTR = dxTR * dxTR + dyTR * dyTR

                                                            val dxBL = (artStartX - handleBL.x) * ts
                                                            val dyBL = (artStartY - handleBL.y) * ts
                                                            val distBL = dxBL * dxBL + dyBL * dyBL

                                                            val dxBR = (artStartX - handleBR.x) * ts
                                                            val dyBR = (artStartY - handleBR.y) * ts
                                                            val distBR = dxBR * dxBR + dyBR * dyBR

                                                            val dxT = (artStartX - handleT.x) * ts
                                                            val dyT = (artStartY - handleT.y) * ts
                                                            val distT = dxT * dxT + dyT * dyT

                                                            val dxB = (artStartX - handleB.x) * ts
                                                            val dyB = (artStartY - handleB.y) * ts
                                                            val distB = dxB * dxB + dyB * dyB

                                                            val dxL = (artStartX - handleL.x) * ts
                                                            val dyL = (artStartY - handleL.y) * ts
                                                            val distL = dxL * dxL + dyL * dyL

                                                            val dxR = (artStartX - handleR.x) * ts
                                                            val dyR = (artStartY - handleR.y) * ts
                                                            val distR = dxR * dxR + dyR * dyR

                                                            val cornerHitPx = with(this) { 56.dp.toPx() }
                                                            val resThresholdSq = cornerHitPx * cornerHitPx

                                                            var matchedResizeHandle: String? = null
                                                            var minResizeDistSq = Float.MAX_VALUE

                                                            val resizeDistances = listOf(
                                                                Pair("resize_tl", distTL),
                                                                Pair("resize_tr", distTR),
                                                                Pair("resize_bl", distBL),
                                                                Pair("resize_br", distBR),
                                                                Pair("resize_t", distT),
                                                                Pair("resize_b", distB),
                                                                Pair("resize_l", distL),
                                                                Pair("resize_r", distR)
                                                            )

                                                            for (item in resizeDistances) {
                                                                if (item.second < resThresholdSq && item.second < minResizeDistSq) {
                                                                    minResizeDistSq = item.second
                                                                    matchedResizeHandle = item.first
                                                                }
                                                            }
                                                            // If no handle was directly clicked, check if they clicked on the edges
                                                            if (matchedResizeHandle == null) {
                                                                fun distToSegmentSq(p: androidx.compose.ui.geometry.Offset, v: androidx.compose.ui.geometry.Offset, w: androidx.compose.ui.geometry.Offset): Float {
                                                                    val l2 = (v.x - w.x) * (v.x - w.x) + (v.y - w.y) * (v.y - w.y)
                                                                    if (l2 == 0f) return (p.x - v.x) * (p.x - v.x) + (p.y - v.y) * (p.y - v.y)
                                                                    var t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2
                                                                    t = Math.max(0f, Math.min(1f, t))
                                                                    val proj = androidx.compose.ui.geometry.Offset(v.x + t * (w.x - v.x), v.y + t * (w.y - v.y))
                                                                    return (p.x - proj.x) * (p.x - proj.x) + (p.y - proj.y) * (p.y - proj.y)
                                                                }
                                                                val ptScreen = androidx.compose.ui.geometry.Offset(artStartX * ts, artStartY * ts)
                                                                val tlScreen = androidx.compose.ui.geometry.Offset(handleTL.x * ts, handleTL.y * ts)
                                                                val trScreen = androidx.compose.ui.geometry.Offset(handleTR.x * ts, handleTR.y * ts)
                                                                val blScreen = androidx.compose.ui.geometry.Offset(handleBL.x * ts, handleBL.y * ts)
                                                                val brScreen = androidx.compose.ui.geometry.Offset(handleBR.x * ts, handleBR.y * ts)

                                                                val distEdgeT = distToSegmentSq(ptScreen, tlScreen, trScreen)
                                                                val distEdgeB = distToSegmentSq(ptScreen, blScreen, brScreen)
                                                                val distEdgeL = distToSegmentSq(ptScreen, tlScreen, blScreen)
                                                                val distEdgeR = distToSegmentSq(ptScreen, trScreen, brScreen)
                                                                val edgeDistances = listOf(
                                                                    Pair("resize_t", distEdgeT),
                                                                    Pair("resize_b", distEdgeB),
                                                                    Pair("resize_l", distEdgeL),
                                                                    Pair("resize_r", distEdgeR)
                                                                )
                                                                val edgeHitPx = with(this) { 44.dp.toPx() }
                                                                val edgeThresholdSq = edgeHitPx * edgeHitPx
                                                                for (item in edgeDistances) {
                                                                    if (item.second < edgeThresholdSq && item.second < minResizeDistSq) {
                                                                        minResizeDistSq = item.second
                                                                        matchedResizeHandle = item.first
                                                                    }
                                                                }
                                                            }
                                                             
                                                            val distBr = distBR

                                                            isNearBezier = false
                                                            if (currentSelected.type == LayerType.VECTOR_BEZIER && tool == "Pen") {
                                                                val artRelativeStartTouch = Offset(localStartOffset.x - artboardOffsetX, localStartOffset.y - artboardOffsetY)
                                                                val touchLocal = canvasToLayerLocal(artRelativeStartTouch, currentSelected)
                                                                val thresholdTemp = 48f / ts.coerceAtLeast(0.3f)
                                                                val thresholdTempSq = thresholdTemp * thresholdTemp
                                                                if (currentSelected.brushPoints.isNotEmpty()) {
                                                                    var nearestIndex = -1
                                                                    var minDistanceSq = Float.MAX_VALUE
                                                                    for (idx in currentSelected.brushPoints.indices) {
                                                                        val pt = currentSelected.brushPoints[idx]
                                                                        val canvasPt = layerLocalToCanvas(pt, currentSelected)
                                                                        val dx = (localStartOffset.x - artboardOffsetX) - canvasPt.x
                                                                        val dy = (localStartOffset.y - artboardOffsetY) - canvasPt.y
                                                                        val distSq = dx * dx + dy * dy
                                                                        if (distSq < thresholdTempSq) {
                                                                            if (idx % 3 != 0) {
                                                                                val anchorIdx = (idx / 3) * 3
                                                                                if (anchorIdx in currentSelected.brushPoints.indices &&
                                                                                    currentSelected.brushPoints[idx] == currentSelected.brushPoints[anchorIdx]) {
                                                                                    continue
                                                                                }
                                                                            }
                                                                            if (distSq < minDistanceSq) {
                                                                                minDistanceSq = distSq
                                                                                nearestIndex = idx
                                                                            }
                                                                        }
                                                                    }
                                                                    if (nearestIndex >= 0) {
                                                                        activeBezierPointIndex = nearestIndex
                                                                        isNearBezier = true
                                                                        
                                                                        // Double-tap node symmetry toggle between SMOOTH and CORNER
                                                                        val clickTime = System.currentTimeMillis()
                                                                        if (clickTime - lastPenClickTime < 350L && lastPenClickIndex == nearestIndex) {
                                                                            val k = nearestIndex / 3
                                                                            val currentTypes = currentSelected.bezierNodeTypes.toMutableList()
                                                                            while (currentTypes.size <= k) {
                                                                                currentTypes.add("SMOOTH")
                                                                            }
                                                                            val oldType = currentTypes[k]
                                                                            val newType = if (oldType == "CORNER") "SMOOTH" else "CORNER"
                                                                            currentTypes[k] = newType
                                                                            
                                                                            snapIndicatorMsg = "Node ${k + 1} Symmetery: $newType"
                                                                            
                                                                            val updatedLyr = currentSelected.copy(bezierNodeTypes = currentTypes)
                                                                            layers = layers.map { if (it.id == currentSelected.id) updatedLyr else it }
                                                                            com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                                            /* pathCache.clear() */
                                                                        }
                                                                        lastPenClickTime = clickTime
                                                                        lastPenClickIndex = nearestIndex
                                                                    }
                                                                }
                                                            }

                                                            // Gradient overlay linear handles click/drag match detection on-canvas
                                                            var matchedGradientOption = false
                                                            val gradOverlay = currentSelected.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                                            val gradientTypeOrdinal = (gradOverlay?.parameters["GradientType"]?.value ?: 0f).toInt()
                                                            
                                                            if (gradOverlay != null && showGradientControls) { // Support all gradient overlays on-canvas
                                                                val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
                                                                val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
                                                                
                                                                val hasCustomHandles = gradOverlay.parameters["StartX"] != null
                                                                val startX: Float
                                                                val startY: Float
                                                                val endX: Float
                                                                val endY: Float
                                                                if (hasCustomHandles) {
                                                                    startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * currentSelected.width
                                                                    startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * currentSelected.height
                                                                    endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * currentSelected.width
                                                                    endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * currentSelected.height
                                                                } else {
                                                                    val rads = Math.toRadians(goAngle.toDouble())
                                                                    val cos = Math.cos(rads).toFloat()
                                                                    val sin = Math.sin(rads).toFloat()
                                                                    startX = currentSelected.width / 2f - (currentSelected.width / 2f * cos * goScale)
                                                                    startY = currentSelected.height / 2f - (currentSelected.height / 2f * sin * goScale)
                                                                    endX = currentSelected.width / 2f + (currentSelected.width / 2f * cos * goScale)
                                                                    endY = currentSelected.height / 2f + (currentSelected.height / 2f * sin * goScale)
                                                                }
                                                                
                                                                val artRelativeStartTouch = Offset(localStartOffset.x - artboardOffsetX, localStartOffset.y - artboardOffsetY)
                                                                val touchLocal = canvasToLayerLocal(artRelativeStartTouch, currentSelected)
                                                                val handleThreshold = 80f / ts.coerceAtLeast(0.5f)
                                                                val handleThresholdSq = handleThreshold * handleThreshold
                                                                
                                                                val startCanvas = layerLocalToCanvas(Offset(startX, startY), currentSelected)
                                                                val endCanvas = layerLocalToCanvas(Offset(endX, endY), currentSelected)
                                                                
                                                                val distToStartSq = (artRelativeStartTouch.x - startCanvas.x) * (artRelativeStartTouch.x - startCanvas.x) + (artRelativeStartTouch.y - startCanvas.y) * (artRelativeStartTouch.y - startCanvas.y)
                                                                val distToEndSq = (artRelativeStartTouch.x - endCanvas.x) * (artRelativeStartTouch.x - endCanvas.x) + (artRelativeStartTouch.y - endCanvas.y) * (artRelativeStartTouch.y - endCanvas.y)
                                                                
                                                                if (GradientEyedropperState.isActive) {
                                                                    val artRelativeX = artRelativeStartTouch.x
                                                                    val artRelativeY = artRelativeStartTouch.y
                                                                    val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                                    val artboardWidth = activeArtboard?.width ?: 1080f
                                                                    val artboardHeight = activeArtboard?.height ?: 1350f
                                                                    val sampledColor = sampleCompositedColor(
                                                                        layers = layers,
                                                                        artRelativeX = artRelativeX,
                                                                        artRelativeY = artRelativeY,
                                                                        artboardWidth = artboardWidth,
                                                                        artboardHeight = artboardHeight,
                                                                        imageBitmapCache = imageBitmapCache
                                                                    )
                                                                    
                                                                    val targetStopIndex = activeGradientStopIndex.coerceIn(0, 100)
                                                                    layers = layers.map { layer ->
                                                                        if (layer.id == currentSelected.id) {
                                                                            val updatedEffects = layer.effects.map { eff ->
                                                                                if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                    val map = eff.parameters.toMutableMap()
                                                                                    map["CustomStop_${targetStopIndex}_R"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_R", sampledColor.red, 0f, 1f)
                                                                                    map["CustomStop_${targetStopIndex}_G"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_G", sampledColor.green, 0f, 1f)
                                                                                    map["CustomStop_${targetStopIndex}_B"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_B", sampledColor.blue, 0f, 1f)
                                                                                    map["CustomStop_${targetStopIndex}_A"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_A", sampledColor.alpha, 0f, 1f)
                                                                                    eff.copy(parameters = map)
                                                                                } else eff
                                                                            }
                                                                            layer.copy(effects = updatedEffects)
                                                                        } else layer
                                                                    }
                                                                    GradientEyedropperState.isActive = false
                                                                    android.widget.Toast.makeText(context, "Color sampled successfully!", android.widget.Toast.LENGTH_SHORT).show()
                                                                    matchedGradientOption = true
                                                                } else if (distToStartSq < handleThresholdSq) {
                                                                    dragMode = "gradient_start"
                                                                    matchedGradientOption = true
                                                                } else if (distToEndSq < handleThresholdSq) {
                                                                    dragMode = "gradient_end"
                                                                    matchedGradientOption = true
                                                                } else {
                                                                    val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
                                                                    var nearestStopIdx = -1
                                                                    var minStopSq = Float.MAX_VALUE
                                                                    for (idx in 0 until stopCount) {
                                                                        val fraction = gradOverlay.parameters["CustomStop_${idx}_Pos"]?.value ?: (idx.toFloat() / (stopCount - 1).coerceAtLeast(1))
                                                                        val stopX = startX + (endX - startX) * fraction
                                                                        val stopY = startY + (endY - startY) * fraction
                                                                        val stopCanvas = layerLocalToCanvas(Offset(stopX, stopY), currentSelected)
                                                                        val distSq = (artRelativeStartTouch.x - stopCanvas.x) * (artRelativeStartTouch.x - stopCanvas.x) + (artRelativeStartTouch.y - stopCanvas.y) * (artRelativeStartTouch.y - stopCanvas.y)
                                                                        if (distSq < handleThresholdSq && distSq < minStopSq) {
                                                                            minStopSq = distSq
                                                                            nearestStopIdx = idx
                                                                        }
                                                                    }
                                                                    if (nearestStopIdx != -1) {
                                                                        dragMode = "gradient_stop"
                                                                        activeGradientStopIndex = nearestStopIdx
                                                                        matchedGradientOption = true
                                                                        
                                                                        // Update selected stop parameter
                                                                        layers = layers.map { layer ->
                                                                            if (layer.id == currentSelected.id) {
                                                                                val updatedEffects = layer.effects.map { eff ->
                                                                                    if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                        val map = eff.parameters.toMutableMap()
                                                                                        map["SelectedStopIndex"] = com.example.studio.model.EffectParameter("SelectedStopIndex", nearestStopIdx.toFloat(), 0f, 10f)
                                                                                        eff.copy(parameters = map)
                                                                                    } else eff
                                                                                }
                                                                                layer.copy(effects = updatedEffects)
                                                                            } else layer
                                                                        }
                                                                    } else {
                                                                        // Check projection to add new color stop
                                                                        val proj = projectPointOnSegment(
                                                                            px = touchLocal.x, py = touchLocal.y,
                                                                            ax = startX, ay = startY,
                                                                            bx = endX, by = endY
                                                                        )
                                                                        val tFraction = proj.first
                                                                        val projX = proj.second
                                                                        val projY = proj.third
                                                                        
                                                                        val dx = touchLocal.x - projX
                                                                        val dy = touchLocal.y - projY
                                                                        val localDist = kotlin.math.sqrt(dx * dx + dy * dy)
                                                                        val distInScreenPx = localDist * ts
                                                                        val densityValue = this.density
                                                                        val distInDp = distInScreenPx / densityValue
                                                                        
                                                                        if (false && false) {
                                                                                    // Interpolate the colors list
                                                                                    val goPresetIdx = (gradOverlay.parameters["Preset"]?.value ?: 0f).toInt().coerceIn(0, 7)
                                                                                    val customColorsList = mutableListOf<androidx.compose.ui.graphics.Color>()
                                                                                    for (idx in 0 until stopCount) {
                                                                                        val rKey = "CustomStop_${idx}_R"
                                                                                        val gKey = "CustomStop_${idx}_G"
                                                                                        val bKey = "CustomStop_${idx}_B"
                                                                                        val rVal = gradOverlay.parameters[rKey]?.value ?: when(idx) {
                                                                                            0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                                                                                            1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                                                                                            else -> 0.5f
                                                                                        }
                                                                                        val gVal = gradOverlay.parameters[gKey]?.value ?: when(idx) {
                                                                                            0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                                                                                            1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                                                                                            else -> 0.5f
                                                                                        }
                                                                                        val bVal = gradOverlay.parameters[bKey]?.value ?: when(idx) {
                                                                                            0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                                                                                            1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                                                                                            else -> 0.5f
                                                                                        }
                                                                                        customColorsList.add(Color(rVal, gVal, bVal))
                                                                                    }
                                                                                    val previewColors = if (goPresetIdx == 7) {
                                                                                        customColorsList
                                                                                    } else {
                                                                                        gradientPresets[goPresetIdx.coerceIn(0, gradientPresets.size - 1)]
                                                                                    }
                                                                                    val interpolatedColor = interpolateMultiColor(previewColors, tFraction)
                                                                                    
                                                                                    undoStack.add(layers)
                                                                                    redoStack.clear()
                                                                                    var tempTargetedIndex = stopCount
                                                                                    layers = layers.map { layer ->
                                                                                        if (layer.id == currentSelected.id) {
                                                                                            val updatedEffects = layer.effects.map { eff ->
                                                                                                if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                                    val map = eff.parameters.toMutableMap()
                                                                                                    val count = stopCount + 1
                                                                                                    map["Preset"] = com.example.studio.model.EffectParameter("Preset", 7f, 0f, 10f) // switch to custom stops
                                                                                                    map["CustomStopCount"] = com.example.studio.model.EffectParameter("CustomStopCount", (stopCount + 1).toFloat(), 0f, 10f)
                                                                                                     
                                                                                                     // Gather and sort all stops (including alpha!)
                                                                                                     val allStops = (0 until stopCount).map { i ->
                                                                                                         val posVal = map["CustomStop_${i}_Pos"]?.value ?: (i.toFloat() / (stopCount - 1).coerceAtLeast(1))
                                                                                                         val rVal = map["CustomStop_${i}_R"]?.value ?: 0.5f
                                                                                                         val gVal = map["CustomStop_${i}_G"]?.value ?: 0.5f
                                                                                                         val bVal = map["CustomStop_${i}_B"]?.value ?: 0.5f
                                                                                                         val aVal = map["CustomStop_${i}_A"]?.value ?: 1.0f
                                                                                                         Triple(posVal, Color(rVal, gVal, bVal, aVal), aVal)
                                                                                                     }.toMutableList()
                                                                                                     
                                                                                                     // Append new stop at calculated tFraction projection coordinate
                                                                                                     allStops.add(Triple(tFraction, interpolatedColor, 1.0f))
                                                                                                     allStops.sortBy { it.first }
                                                                                                     
                                                                                                     val newSortedIndex = allStops.indexOfFirst { it.first == tFraction }.coerceIn(0, allStops.size - 1)
                                                                                                     
                                                                                                     // Write back keys sequentially to preserve perfect indexing
                                                                                                     for (idx in allStops.indices) {
                                                                                                         val stopNode = allStops[idx]
                                                                                                         map["CustomStop_${idx}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_Pos", stopNode.first, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_R"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_R", stopNode.second.red, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_G"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_G", stopNode.second.green, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_B"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_B", stopNode.second.blue, 0f, 1f)
                                                                                                         map["CustomStop_${idx}_A"] = com.example.studio.model.EffectParameter("CustomStop_${idx}_A", stopNode.third, 0f, 1f)
                                                                                                     }
                                                                                                     
                                                                                                     tempTargetedIndex = newSortedIndex
                                                                                                     activeGradientStopIndex = newSortedIndex
                                                                                                     map["SelectedStopIndex"] = com.example.studio.model.EffectParameter("SelectedStopIndex", newSortedIndex.toFloat(), 0f, 10f)
                                                                                                     /*
                                                                                                    // Populate existing custom stops with previewColors if switching preset format
                                                                                                    for (i in previewColors.indices) {
                                                                                                        val col = previewColors[i]
                                                                                                        map["CustomStop_${i}_R"] = com.example.studio.model.EffectParameter("CustomStop_${i}_R", col.red, 0f, 1f)
                                                                                                        map["CustomStop_${i}_G"] = com.example.studio.model.EffectParameter("CustomStop_${i}_G", col.green, 0f, 1f)
                                                                                                        map["CustomStop_${i}_B"] = com.example.studio.model.EffectParameter("CustomStop_${i}_B", col.blue, 0f, 1f)
                                                                                                        map["CustomStop_${i}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${i}_Pos", i.toFloat() / (previewColors.size - 1).coerceAtLeast(1), 0f, 1f)
                                                                                                    }
                                                                                                    
                                                                                                    map["CustomStop_${stopCount}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_Pos", tFraction, 0f, 1f)
                                                                                                    map["CustomStop_${stopCount}_R"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_R", interpolatedColor.red, 0f, 1f)
                                                                                                    map["CustomStop_${stopCount}_G"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_G", interpolatedColor.green, 0f, 1f)
                                                                                                    map["CustomStop_${stopCount}_B"] = com.example.studio.model.EffectParameter("CustomStop_${stopCount}_B", interpolatedColor.blue, 0f, 1f)
                                                                                                    */
                                                                                                    eff.copy(parameters = map)
                                                                                                } else eff
                                                                                            }
                                                                                            layer.copy(effects = updatedEffects)
                                                                                        } else layer
                                                                                    }
                                                                                    dragMode = "gradient_stop"
                                                                                    activeGradientStopIndex = tempTargetedIndex
                                                                                    matchedGradientOption = true
                                                                                    showGradientColorPickerDialog = true
                                                                                }
                                                                            }
                                                                }
                                                            }

                                                            val gThreshold = 60f / ts.coerceAtLeast(0.3f)
                                                            val gThresholdSq = gThreshold * gThreshold
                                                            if (activeTool == "Perspective" && currentSelected != null) {
                                                                val corners = if (currentSelected.perspWarpPointsStr.isEmpty()) {
                                                                    listOf(
                                                                        Offset(0f, 0f),
                                                                        Offset(currentSelected.width, 0f),
                                                                        Offset(currentSelected.width, currentSelected.height),
                                                                        Offset(0f, currentSelected.height)
                                                                    )
                                                                } else {
                                                                    parseWarpPointsStr(currentSelected.perspWarpPointsStr)
                                                                }
                                                                
                                                                val handles = corners + listOf(
                                                                    (corners[0] + corners[1]) / 2f,
                                                                    (corners[1] + corners[2]) / 2f,
                                                                    (corners[2] + corners[3]) / 2f,
                                                                    (corners[3] + corners[0]) / 2f
                                                                )
                                                                
                                                                val artStartX = localStartX - artboardOffsetX
                                                                val artStartY = localStartY - artboardOffsetY
                                                                
                                                                var nearestIdx = -1
                                                                var minD = Float.MAX_VALUE
                                                                val threshold = 56f / ts.coerceAtLeast(0.3f)
                                                                val thresholdSq = threshold * threshold
                                                                
                                                                for (i in handles.indices) {
                                                                    val canvasPt = if (warpTarget == "Canvas") handles[i] else layerLocalToCanvas(handles[i], currentSelected)
                                                                    val dx = artStartX - canvasPt.x
                                                                    val dy = artStartY - canvasPt.y
                                                                    val distSq = dx * dx + dy * dy
                                                                    if (distSq < thresholdSq && distSq < minD) {
                                                                        minD = distSq
                                                                        nearestIdx = i
                                                                    }
                                                                }
                                                                
                                                                if (nearestIdx != -1) {
                                                                    undoStack.add(layers)
                                                                    redoStack.clear()
                                                                    dragMode = "warp_perspective"
                                                                    activeWarpNodeIndex = nearestIdx
                                                                    initialWarpPointsStr = formatWarpPointsStr(corners)
                                                                } else {
                                                                    val isEmptyLayerSelected = currentSelected.type == LayerType.FREEHAND_DRAWING && currentSelected.brushPoints.isEmpty()
                                                                    val isLocked = currentSelected.isAlphaLocked
                                                                    dragMode = if (isEmptyLayerSelected || isLocked) null else "move"
                                                                }
                                                            } else if (activeTool == "Mesh" && currentSelected != null) {
                                                                val cols = warpMeshDivisionX
                                                                val rows = warpMeshDivisionY
                                                                val nodes = parseMeshWarpPointsStr(currentSelected.meshWarpPointsStr, cols, rows, currentSelected.width, currentSelected.height, warpTarget, currentSelected)
                                                                
                                                                val artStartX = localStartX - artboardOffsetX
                                                                val artStartY = localStartY - artboardOffsetY
                                                                val touchCanvas = Offset(artStartX, artStartY)
                                                                
                                                                var targetDragMode: String? = null
                                                                var minD = Float.MAX_VALUE
                                                                val threshold = 48f / ts.coerceAtLeast(0.3f)
                                                                val thresholdSq = threshold * threshold
                                                                
                                                                // First check if we tapped near any of the active selected node's handles
                                                                if (activeWarpNodeIndex != -1 && activeWarpNodeIndex in nodes.indices) {
                                                                    val selNode = nodes[activeWarpNodeIndex]
                                                                    
                                                                    val hRightAbs = selNode.main + selNode.hHandle
                                                                    val hLeftAbs = selNode.main - selNode.hHandle
                                                                    val vBottomAbs = selNode.main + selNode.vHandle
                                                                    val vTopAbs = selNode.main - selNode.vHandle
                                                                    
                                                                    val hRightCanvas = if (warpTarget == "Canvas") hRightAbs else layerLocalToCanvas(hRightAbs, currentSelected)
                                                                    val hLeftCanvas = if (warpTarget == "Canvas") hLeftAbs else layerLocalToCanvas(hLeftAbs, currentSelected)
                                                                    val vBottomCanvas = if (warpTarget == "Canvas") vBottomAbs else layerLocalToCanvas(vBottomAbs, currentSelected)
                                                                    val vTopCanvas = if (warpTarget == "Canvas") vTopAbs else layerLocalToCanvas(vTopAbs, currentSelected)
                                                                    
                                                                    val handleCanvasPoints = listOf(hRightCanvas, hLeftCanvas, vBottomCanvas, vTopCanvas)
                                                                    val handleModes = listOf("warp_mesh_h_right", "warp_mesh_h_left", "warp_mesh_v_bottom", "warp_mesh_v_top")
                                                                    
                                                                    for (i in 0 until 4) {
                                                                        val dx = touchCanvas.x - handleCanvasPoints[i].x
                                                                        val dy = touchCanvas.y - handleCanvasPoints[i].y
                                                                        val dSq = dx * dx + dy * dy
                                                                        if (dSq < thresholdSq && dSq < minD) {
                                                                            minD = dSq
                                                                            targetDragMode = handleModes[i]
                                                                        }
                                                                    }
                                                                }
                                                                
                                                                if (targetDragMode == null) {
                                                                    var nearestMainIdx = -1
                                                                    for (i in nodes.indices) {
                                                                        val mainAbs = nodes[i].main
                                                                        val mainCanvas = if (warpTarget == "Canvas") mainAbs else layerLocalToCanvas(mainAbs, currentSelected)
                                                                        val dx = touchCanvas.x - mainCanvas.x
                                                                        val dy = touchCanvas.y - mainCanvas.y
                                                                        val dSq = dx * dx + dy * dy
                                                                        if (dSq < thresholdSq && dSq < minD) {
                                                                            minD = dSq
                                                                            nearestMainIdx = i
                                                                        }
                                                                    }
                                                                    if (nearestMainIdx != -1) {
                                                                        activeWarpNodeIndex = nearestMainIdx
                                                                        targetDragMode = "warp_mesh_main"
                                                                        undoStack.add(layers)
                                                                        redoStack.clear()
                                                                    }
                                                                } else {
                                                                    undoStack.add(layers)
                                                                    redoStack.clear()
                                                                }
                                                                
                                                                dragMode = targetDragMode
                                                            } else if (matchedGradientOption) {
                                                                // Handled on-canvas gradient selection/stops append
                                                            } else if (matchedResizeHandle != null && !isLocked && !isNearBezier) {
                                                                val isEmptyLayerSelected = currentSelected != null && currentSelected.type == LayerType.FREEHAND_DRAWING && currentSelected.brushPoints.isEmpty()
                                                                if (!isEmptyLayerSelected) {
                                                                    dragMode = matchedResizeHandle
                                                                    isResizingActive = true
                                                                    activeResizingLayerId = selId
                                                                    startingLayerForResize = currentSelected
                                                                    liveDragScaleX = 1.0f
                                                                    liveDragScaleY = 1.0f
                                                                    liveDragPivotX = -1f
                                                                    liveDragPivotY = -1f
                                                                }
                                                            } else if (tool == "Shape Builder") {
                                                                dragMode = "shape_builder"
                                                                val clickPt = Offset(localStartX - artboardOffsetX, localStartY - artboardOffsetY)
                                                                shapeBuilderDragPoints.clear()
                                                                shapeBuilderDragPoints.add(clickPt)
                                                            } else if (tool == "Pen" && isTouchInActiveArtboard) {
                                                                if (penSubTool == "Freeform") {
                                                                     dragMode = "freeform_draw"
                                                                     val clickPt = Offset((localStartX - artboardOffsetX).coerceIn(0f, artboardWidth), (localStartY - artboardOffsetY).coerceIn(0f, artboardHeight))
                                                                     freeformPenPoints = listOf(clickPt)
                                                                 } else if (isNearBezier) {
                                                                     dragMode = "bezier"
                                                                 } else if (penSubTool == "AddAnchor" && currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                                     val clickPt = Offset((localStartX - artboardOffsetX).coerceIn(0f, artboardWidth), (localStartY - artboardOffsetY).coerceIn(0f, artboardHeight))
                                                                     val clickLocal = canvasToLayerLocal(clickPt, currentSelected)
                                                                     val updated = findClosestSegmentAndInsert(clickLocal, currentSelected)
                                                                     if (updated != null) {
                                                                         undoStack.add(layers)
                                                                         redoStack.clear()
                                                                         layers = layers.map {
                                                                             if (it.id == currentSelected.id) {
                                                                                 it.copy(brushPoints = updated)
                                                                             } else it
                                                                         }
                                                                         dragMode = "bezier"
                                                                         activeBezierPointIndex = updated.size - 3
                                                                         com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                                         /* pathCache.clear() */
                                                                     } else {
                                                                         dragMode = null
                                                                     }
                                                                 } else if (penSubTool == "DeleteAnchor" && currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                                     if (isNearBezier && activeBezierPointIndex % 3 == 0) {
                                                                         val k = activeBezierPointIndex / 3
                                                                         val updatedPoints = currentSelected.brushPoints.toMutableList()
                                                                         if (k * 3 in updatedPoints.indices) {
                                                                             updatedPoints.removeAt(k * 3)
                                                                             if (k * 3 in updatedPoints.indices) updatedPoints.removeAt(k * 3)
                                                                             if (k * 3 in updatedPoints.indices) updatedPoints.removeAt(k * 3)
                                                                             
                                                                             undoStack.add(layers)
                                                                             redoStack.clear()
                                                                             layers = layers.map {
                                                                                 if (it.id == currentSelected.id) {
                                                                                     it.copy(brushPoints = updatedPoints)
                                                                                 } else it
                                                                             }
                                                                             activeBezierPointIndex = if (updatedPoints.isNotEmpty()) {
                                                                                 (k * 3).coerceAtMost(updatedPoints.size - 3)
                                                                             } else -1
                                                                             com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                                             /* pathCache.clear() */
                                                                         }
                                                                     }
                                                                     dragMode = null
                                                                 } else if (penSubTool == "ConvertPoint" && currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                                     if (isNearBezier && activeBezierPointIndex % 3 == 0) {
                                                                         val k = activeBezierPointIndex / 3
                                                                         val currentTypes = currentSelected.bezierNodeTypes.toMutableList()
                                                                         while (currentTypes.size <= k) {
                                                                             currentTypes.add("SMOOTH")
                                                                         }
                                                                         val oldType = currentTypes[k]
                                                                         val newType = if (oldType == "CORNER") "SMOOTH" else "CORNER"
                                                                         currentTypes[k] = newType
                                                                         
                                                                         undoStack.add(layers)
                                                                         redoStack.clear()
                                                                         layers = layers.map {
                                                                             if (it.id == currentSelected.id) {
                                                                                 it.copy(bezierNodeTypes = currentTypes)
                                                                             } else it
                                                                         }
                                                                         dragMode = "bezier"
                                                                         com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                                         /* pathCache.clear() */
                                                                     } else {
                                                                         dragMode = null
                                                                     }
                                                                 } else if (isNearBezier) {
                                                                     dragMode = "bezier"
                                                                 } else {
                                                                     dragMode = "pen_draw_handles"
                                                                val clickPt = Offset((localStartX - artboardOffsetX).coerceIn(0f, artboardWidth), (localStartY - artboardOffsetY).coerceIn(0f, artboardHeight))
                                                                val currentSelected = lyrs.find { it.id == selId }
                                                                if (currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                                    val clickLocal = canvasToLayerLocal(clickPt, currentSelected)
                                                                    val updatedPoints = currentSelected.brushPoints + clickLocal + clickLocal + clickLocal
                                                                    undoStack.add(layers)
                                                                    redoStack.clear()
                                                                    layers = layers.map {
                                                                        if (it.id == currentSelected.id) {
                                                                            it.copy(brushPoints = updatedPoints)
                                                                        } else it
                                                                    }
                                                                    activeBezierPointIndex = updatedPoints.size - 3
                                                                    com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                                    /* pathCache.clear() */
                                                                } else {
                                                                    val newL = StudioLayer(
                                                                        name = "Pen Vector Path ${layers.filter { it.type == LayerType.VECTOR_BEZIER }.size + 1}",
                                                                        type = LayerType.VECTOR_BEZIER,
                                                                        positionX = 0f,
                                                                        positionY = 0f,
                                                                        width = artboardWidth,
                                                                        height = artboardHeight,
                                                                        baseColor = brushColor,
                                                                        brushPoints = listOf(clickPt, clickPt, clickPt)
                                                                    )
                                                                    undoStack.add(layers)
                                                                    redoStack.clear()
                                                                    layers = listOf(newL) + layers
                                                                    selectedLayerId = newL.id
                                                                    selId = newL.id
                                                                    activeBezierPointIndex = 0
                                                                    com.example.studio.ui.ParametricLayerCache.invalidate(newL.id)
                                                                 }
                                                                 }
                                                                 if (false) {
                                                                    /* pathCache.clear() */
                                                                }
                                                            } else if (isNearBezier) {
                                                                dragMode = "bezier"
                                                            } else {
                                                                val isEmptyLayerSelected = currentSelected != null && currentSelected.type == LayerType.FREEHAND_DRAWING && currentSelected.brushPoints.isEmpty()
                                                                dragMode = if (isEmptyLayerSelected || isLocked) null else "move"
                                                            }
                                                        } else {
                                                            val isEmptyLayerSelected = currentSelected != null && currentSelected.type == LayerType.FREEHAND_DRAWING && currentSelected.brushPoints.isEmpty()
                                                            dragMode = if (isEmptyLayerSelected || isLocked) null else "move"
                                                        }
                                                    }
                                                }
                                            }

                                            if (hasMovedPastSlop) {
                                                val localChangeOffset = screenToCanvas(
                                                    screenPos = position,
                                                    viewportWidth = currentViewportWidthState.value,
                                                    viewportHeight = currentViewportHeightState.value,
                                                    canvasPanX = canvasPanX,
                                                    canvasPanY = canvasPanY,
                                                    canvasRotation = canvasRotation,
                                                    totalScale = ts,
                                                    centerX = currentWorkspaceCenterXState.value,
                                                    centerY = currentWorkspaceCenterYState.value,
                                                    viewportCenterY = visibleViewportCenterY
                                                )
                                                val localChangeX = localChangeOffset.x
                                                val localChangeY = localChangeOffset.y

                                                val localDragOffset = screenDeltaToCanvas(
                                                    delta = diff,
                                                    canvasRotation = canvasRotation,
                                                    totalScale = ts
                                                )
                                                val localDragX = localDragOffset.x
                                                val localDragY = localDragOffset.y

                                                if (dragMode == "eyedropper") {
                                                    val artRelativeX = localChangeX - artboardOffsetX
                                                    val artRelativeY = localChangeY - artboardOffsetY
                                                    GradientEyedropperState.touchPoint = Offset(localChangeX, localChangeY)
                                                    
                                                    val liveSampledColor = sampleCompositedColor(
                                                        layers = layers,
                                                        artRelativeX = artRelativeX,
                                                        artRelativeY = artRelativeY,
                                                        artboardWidth = artboardWidth,
                                                        artboardHeight = artboardHeight,
                                                        imageBitmapCache = imageBitmapCache
                                                    )
                                                    
                                                    if (GradientEyedropperState.onColorSampled != null) {
                                                        GradientEyedropperState.liveSampledColor = liveSampledColor
                                                    } else {
                                                        val currentSelected = lyrs.find { it.id == selId }
                                                        if (currentSelected != null) {
                                                            if (GradientEyedropperState.isSamplingForSolidColor) {
                                                                layers = layers.map { layer ->
                                                                    if (layer.id == currentSelected.id) {
                                                                        layer.copy(baseColor = liveSampledColor)
                                                                    } else layer
                                                                }
                                                            } else {
                                                                val targetStopIndex = activeGradientStopIndex.coerceIn(0, 100)
                                                                layers = layers.map { layer ->
                                                                    if (layer.id == currentSelected.id) {
                                                                        val updatedEffects = layer.effects.map { eff ->
                                                                            if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                val map = eff.parameters.toMutableMap()
                                                                                map["CustomStop_${targetStopIndex}_R"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_R", liveSampledColor.red, 0f, 1f)
                                                                                map["CustomStop_${targetStopIndex}_G"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_G", liveSampledColor.green, 0f, 1f)
                                                                                map["CustomStop_${targetStopIndex}_B"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_B", liveSampledColor.blue, 0f, 1f)
                                                                                map["CustomStop_${targetStopIndex}_A"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_A", liveSampledColor.alpha, 0f, 1f)
                                                                                eff.copy(parameters = map)
                                                                            } else eff
                                                                        }
                                                                        layer.copy(effects = updatedEffects)
                                                                    } else layer
                                                                }
                                                            }
                                                        }
                                                    }
                                                    event.changes.forEach { it.consume() }
                                                } else if ((tool == "Brush" || tool == "Eraser") && isTouchInActiveArtboard) {
                                                    var snappedX = localChangeX
                                                    var snappedY = localChangeY
                                                    val activeRulerForStroke = currentRulersState.value.firstOrNull { it.enabled }
                                                    if (snapToRuler && activeRulerForStroke != null) {
                                                        val snapped = projectPointOnRulerLine(
                                                            px = localChangeX,
                                                            py = localChangeY,
                                                            ruler = activeRulerForStroke,
                                                            canvasWidth = currentCanvasWidthState.value,
                                                            canvasHeight = currentCanvasHeightState.value,
                                                            artboardOffsetX = artboardOffsetX,
                                                            artboardOffsetY = artboardOffsetY
                                                        )
                                                        snappedX = snapped.x
                                                        snappedY = snapped.y
                                                    }
                                                    val activeMoveL = lyrs.find { it.id == selId }
                                                    val artboardX = (snappedX - artboardOffsetX).coerceIn(0f, artboardWidth)
                                                    val artboardY = (snappedY - artboardOffsetY).coerceIn(0f, artboardHeight)
                                                    val mappedMove = if (activeMoveL != null) canvasToLayerLocal(Offset(artboardX, artboardY), activeMoveL) else Offset(artboardX, artboardY)
                                                    strokeTracker.addPoint(mappedMove.x, mappedMove.y)
                                                    val brushSizeVal = brushSize
                                                    val brushOpacityVal = brushOpacity
                                                    val brushColorVal = brushColor
                                                    val presetVal = brushPresetIndex
                                                    val smoothVal = brushSmoothing
                                                    val currentPointsList = strokeTracker.getPointsList()
                                                    
                                                    OpenGLBrushRenderer.WetInkRenderer.drawSegments(
                                                        points = currentPointsList,
                                                        color = if (tool == "Eraser") androidx.compose.ui.graphics.Color.Black else brushColorVal,
                                                        size = if (tool == "Eraser") eraserSize else brushSizeVal,
                                                        opacity = if (tool == "Eraser") 1.0f else brushOpacityVal,
                                                        presetIndex = if (tool == "Eraser") 0 else presetVal,
                                                        smoothing = if (tool == "Eraser") true else smoothVal
                                                    )

                                                    if (activeRulerForStroke != null && activeRulerForStroke.isSymmetrical && currentPointsList.isNotEmpty()) {
                                                        val symPointsLists = mutableListOf<MutableList<Offset>>()
                                                        for (primaryPt in currentPointsList) {
                                                            val canvasPt = if (activeMoveL != null) layerLocalToCanvas(primaryPt, activeMoveL) else primaryPt
                                                            val syms = getSymmetricPoints(
                                                                px = canvasPt.x + artboardOffsetX,
                                                                py = canvasPt.y + artboardOffsetY,
                                                                ruler = activeRulerForStroke,
                                                                canvasWidth = currentCanvasWidthState.value,
                                                                canvasHeight = currentCanvasHeightState.value,
                                                                artboardOffsetX = artboardOffsetX,
                                                                artboardOffsetY = artboardOffsetY
                                                            )
                                                            for (i in syms.indices) {
                                                                if (i >= symPointsLists.size) {
                                                                    symPointsLists.add(mutableListOf())
                                                                }
                                                                val symArtX = (syms[i].x - artboardOffsetX).coerceIn(0f, artboardWidth)
                                                                val symArtY = (syms[i].y - artboardOffsetY).coerceIn(0f, artboardHeight)
                                                                val mappedSym = if (activeMoveL != null) canvasToLayerLocal(Offset(symArtX, symArtY), activeMoveL) else Offset(symArtX, symArtY)
                                                                symPointsLists[i].add(mappedSym)
                                                            }
                                                        }
                                                        for (symList in symPointsLists) {
                                                            OpenGLBrushRenderer.WetInkRenderer.drawSegments(
                                                                points = symList,
                                                                color = if (tool == "Eraser") androidx.compose.ui.graphics.Color.Black else brushColorVal,
                                                                size = if (tool == "Eraser") eraserSize else brushSizeVal,
                                                                opacity = if (tool == "Eraser") 1.0f else brushOpacityVal,
                                                                presetIndex = if (tool == "Eraser") 0 else presetVal,
                                                                smoothing = if (tool == "Eraser") true else smoothVal
                                                            )
                                                        }
                                                    }

                                                    strokeDrawTrigger.value++
                                                    pathCache.remove(999999)
                                                    pathCache.remove(1999999)
                                                } else if ((tool == "Ruler" || activeFullScreenSheet == "Ruler" || currentRulersState.value.isNotEmpty()) && draggedRulerId != null) {
                                                    val activeId = draggedRulerId
                                                    val activeR = currentRulersState.value.find { it.id == activeId }
                                                    if (activeR != null && !activeR.locked && !currentAllRulersLockedState.value) {
                                                        val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                        val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                        val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                        val newPos = if (activeR.orientation == "Horizontal") {
                                                            localChangeY - artboardOffsetY
                                                        } else {
                                                            localChangeX - artboardOffsetX
                                                        }
                                                        rulers = currentRulersState.value.map {
                                                            if (it.id == activeId) it.copy(position = newPos) else it
                                                        }
                                                    }
                                                } else {
                                                    if (dragMode == "warp_perspective") {
                                                         val currentSelected = layers.find { it.id == selId }
                                                         if (currentSelected != null && activeWarpNodeIndex != -1) {
                                                             val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                             val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                             val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                             val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                             val localTouch = if (warpTarget == "Canvas") artboardRelativeTouch else canvasToLayerLocal(artboardRelativeTouch, currentSelected)
                                                             
                                                             val corners = if (currentSelected.perspWarpPointsStr.isEmpty()) {
                                                                 listOf(
                                                                     Offset(0f, 0f),
                                                                     Offset(currentSelected.width, 0f),
                                                                     Offset(currentSelected.width, currentSelected.height),
                                                                     Offset(0f, currentSelected.height)
                                                                 )
                                                             } else {
                                                                 parseWarpPointsStr(currentSelected.perspWarpPointsStr)
                                                             }.toMutableList()
                                                             
                                                             if (activeWarpNodeIndex in 0..7) {
                                                                 val initialCorners = if (initialWarpPointsStr.isEmpty()) {
                                                                     listOf(
                                                                         Offset(0f, 0f),
                                                                         Offset(currentSelected.width, 0f),
                                                                         Offset(currentSelected.width, currentSelected.height),
                                                                         Offset(0f, currentSelected.height)
                                                                     )
                                                                 } else {
                                                                     parseWarpPointsStr(initialWarpPointsStr)
                                                                 }
                                                                 
                                                                 val initialHandlePos = when (activeWarpNodeIndex) {
                                                                     in 0..3 -> initialCorners[activeWarpNodeIndex]
                                                                     4 -> (initialCorners[0] + initialCorners[1]) / 2f
                                                                     5 -> (initialCorners[1] + initialCorners[2]) / 2f
                                                                     6 -> (initialCorners[2] + initialCorners[3]) / 2f
                                                                     7 -> (initialCorners[3] + initialCorners[0]) / 2f
                                                                     else -> Offset.Zero
                                                                 }
                                                                 
                                                                 val delta = localTouch - initialHandlePos
                                                                 val newCorners = corners.toMutableList()
                                                                 if (activeWarpNodeIndex < 4) {
                                                                     newCorners[activeWarpNodeIndex] = initialCorners[activeWarpNodeIndex] + delta
                                                                 } else {
                                                                     val constrainedDelta = delta
                                                                     when (activeWarpNodeIndex) {
                                                                         4 -> {
                                                                             newCorners[0] = initialCorners[0] + constrainedDelta
                                                                             newCorners[1] = initialCorners[1] + constrainedDelta
                                                                         }
                                                                         5 -> {
                                                                             newCorners[1] = initialCorners[1] + constrainedDelta
                                                                             newCorners[2] = initialCorners[2] + constrainedDelta
                                                                         }
                                                                         6 -> {
                                                                             newCorners[2] = initialCorners[2] + constrainedDelta
                                                                             newCorners[3] = initialCorners[3] + constrainedDelta
                                                                         }
                                                                         7 -> {
                                                                             newCorners[3] = initialCorners[3] + constrainedDelta
                                                                             newCorners[0] = initialCorners[0] + constrainedDelta
                                                                         }
                                                                     }
                                                                 }
                                                                 
                                                                 
                                                                     val updatedStr = formatWarpPointsStr(newCorners)
                                                                     layers = layers.map { layer ->
                                                                         if (layer.id == selId) {
                                                                             layer.copy(perspWarpPointsStr = updatedStr)
                                                                         } else layer
                                                                     }
                                                                     com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                                                                     /* pathCache.clear() */
                                                                 
                                                             }
                                                         }
                                                     } else if (dragMode != null && dragMode!!.startsWith("warp_mesh")) {
                                                         val currentSelected = layers.find { it.id == selId }
                                                         if (currentSelected != null && activeWarpNodeIndex != -1) {
                                                             val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                             val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                             val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                             val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                             
                                                             val cols = warpMeshDivisionX
                                                             val rows = warpMeshDivisionY
                                                             val nodes = parseMeshWarpPointsStr(currentSelected.meshWarpPointsStr, cols, rows, currentSelected.width, currentSelected.height, warpTarget, currentSelected).toMutableList()
                                                             
                                                             if (activeWarpNodeIndex in nodes.indices) {
                                                                 val localTouch = if (warpTarget == "Canvas") artboardRelativeTouch else canvasToLayerLocal(artboardRelativeTouch, currentSelected)
                                                                 val mainPt = nodes[activeWarpNodeIndex].main
                                                                 
                                                                 val updatedNode = when (dragMode) {
                                                                     "warp_mesh_main" -> {
                                                                         nodes[activeWarpNodeIndex].copy(main = localTouch)
                                                                     }
                                                                     "warp_mesh_h_right" -> {
                                                                         nodes[activeWarpNodeIndex].copy(hHandle = localTouch - mainPt)
                                                                     }
                                                                     "warp_mesh_h_left" -> {
                                                                         nodes[activeWarpNodeIndex].copy(hHandle = mainPt - localTouch)
                                                                     }
                                                                     "warp_mesh_v_bottom" -> {
                                                                         nodes[activeWarpNodeIndex].copy(vHandle = localTouch - mainPt)
                                                                     }
                                                                     "warp_mesh_v_top" -> {
                                                                         nodes[activeWarpNodeIndex].copy(vHandle = mainPt - localTouch)
                                                                     }
                                                                     else -> nodes[activeWarpNodeIndex]
                                                                 }
                                                                 
                                                                 nodes[activeWarpNodeIndex] = updatedNode
                                                                 val updatedStr = formatMeshWarpPointsStr(nodes)
                                                                 layers = layers.map { layer ->
                                                                     if (layer.id == selId) {
                                                                         layer.copy(meshWarpPointsStr = updatedStr)
                                                                     } else layer
                                                                 }
                                                                 com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                                                                 /* pathCache.clear() */
                                                             }
                                                         }
                                                     } else if (dragMode != null && dragMode.startsWith("resize")) {
                                                        val startL = startingLayerForResize
                                                        if (startL != null) {
                                                            val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                             val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                             val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                             val artboardRelativeTouch = Offset(localChangeX - artboardOffsetX, localChangeY - artboardOffsetY)
                                                             val localTouch = canvasToLayerLocal(artboardRelativeTouch, startL)
                                                            val anchorMode = currentShapeAnchorModeState.value

                                                            var targetW = startL.width
                                                            var targetH = startL.height
                                                            var pivotX = startL.width / 2f
                                                            var pivotY = startL.height / 2f

                                                            when (anchorMode) {
                                                                "OPPOSITE" -> {
                                                                    when (dragMode) {
                                                                        "resize_br" -> {
                                                                            targetW = localTouch.x
                                                                            targetH = localTouch.y
                                                                            pivotX = 0f
                                                                            pivotY = 0f
                                                                        }
                                                                        "resize_tl" -> {
                                                                            targetW = startL.width - localTouch.x
                                                                            targetH = startL.height - localTouch.y
                                                                            pivotX = startL.width
                                                                            pivotY = startL.height
                                                                        }
                                                                        "resize_tr" -> {
                                                                            targetW = localTouch.x
                                                                            targetH = startL.height - localTouch.y
                                                                            pivotX = 0f
                                                                            pivotY = startL.height
                                                                        }
                                                                        "resize_bl" -> {
                                                                            targetW = startL.width - localTouch.x
                                                                            targetH = localTouch.y
                                                                            pivotX = startL.width
                                                                            pivotY = 0f
                                                                        }
                                                                        "resize_r" -> {
                                                                            targetW = localTouch.x
                                                                            targetH = startL.height
                                                                            pivotX = 0f
                                                                            pivotY = startL.height / 2f
                                                                        }
                                                                        "resize_l" -> {
                                                                            targetW = startL.width - localTouch.x
                                                                            targetH = startL.height
                                                                            pivotX = startL.width
                                                                            pivotY = startL.height / 2f
                                                                        }
                                                                        "resize_b" -> {
                                                                            targetW = startL.width
                                                                            targetH = localTouch.y
                                                                            pivotX = startL.width / 2f
                                                                            pivotY = 0f
                                                                        }
                                                                        "resize_t" -> {
                                                                            targetW = startL.width
                                                                            targetH = startL.height - localTouch.y
                                                                            pivotX = startL.width / 2f
                                                                            pivotY = startL.height
                                                                        }
                                                                    }
                                                                }
                                                                "ORIGIN" -> {
                                                                    pivotX = 0f
                                                                    pivotY = 0f
                                                                    when (dragMode) {
                                                                        "resize_tl" -> {
                                                                            targetW = Math.abs(localTouch.x)
                                                                            targetH = Math.abs(localTouch.y)
                                                                        }
                                                                        "resize_tr" -> {
                                                                            targetW = localTouch.x
                                                                            targetH = Math.abs(localTouch.y)
                                                                        }
                                                                        "resize_bl" -> {
                                                                            targetW = Math.abs(localTouch.x)
                                                                            targetH = localTouch.y
                                                                        }
                                                                        "resize_l" -> {
                                                                            targetW = Math.abs(localTouch.x)
                                                                            targetH = startL.height
                                                                        }
                                                                        "resize_t" -> {
                                                                            targetW = startL.width
                                                                            targetH = Math.abs(localTouch.y)
                                                                        }
                                                                        else -> {
                                                                            targetW = localTouch.x
                                                                            targetH = localTouch.y
                                                                        }
                                                                    }
                                                                }
                                                                else -> { // "CENTER"
                                                                    pivotX = startL.width / 2f
                                                                    pivotY = startL.height / 2f
                                                                    targetW = 2f * Math.abs(localTouch.x - pivotX)
                                                                    targetH = 2f * Math.abs(localTouch.y - pivotY)
                                                                }
                                                            }

                                                            val minW = 20f
                                                            val minH = 20f
                                                            var scX = (targetW / startL.width.coerceAtLeast(1f)).coerceAtLeast(minW / startL.width.coerceAtLeast(1f))
                                                            var scY = (targetH / startL.height.coerceAtLeast(1f)).coerceAtLeast(minH / startL.height.coerceAtLeast(1f))

                                                            if (dragMode == "resize_t" || dragMode == "resize_b") {
                                                                scX = 1.0f
                                                            } else if (dragMode == "resize_l" || dragMode == "resize_r") {
                                                                scY = 1.0f
                                                            } else {
                                                                if (startL.isAspectLocked) {
                                                                    val scale = if (Math.abs(scX - 1f) >= Math.abs(scY - 1f)) scX else scY
                                                                    scX = scale
                                                                    scY = scale
                                                                }
                                                            }

                                                            liveDragScaleX = scX
                                                            liveDragScaleY = scY
                                                            liveDragPivotX = pivotX
                                                            liveDragPivotY = pivotY
                                                        }
                                                    } else if (1 == 2) {
                                                        layers = layers.map { layer ->
                                                            if (layer.id == selId && !layer.isAlphaLocked) {
                                                                val initialW = (localChangeX - layer.positionX).coerceIn(20f, 2000f)
                                                                 val initialH = (localChangeY - layer.positionY).coerceIn(20f, 2000f)
                                                                 val (newW, computedNewH) = if (layer.isAspectLocked) {
                                                                     val ratio = if (layer.height > 0f) layer.width / layer.height else 1f
                                                                     val scaleFromWidth = Math.abs(initialW - layer.width) >= Math.abs(initialH - layer.height)
                                                                     if (scaleFromWidth) {
                                                                         val computedH = (initialW / ratio).coerceIn(20f, 2000f)
                                                                         Pair(computedH * ratio, computedH)
                                                                     } else {
                                                                         val computedW = (initialH * ratio).coerceIn(20f, 2000f)
                                                                         Pair(computedW, computedW / ratio)
                                                                     }
                                                                 } else {
                                                                     Pair(initialW, initialH)
                                                                 }
                                                                val newH = if (layer.isAspectLocked) computedNewH else (localChangeY - layer.positionY).coerceIn(20f, 2000f)
                                                                layer.copy(width = newW, height = newH)
                                                            } else layer
                                                        }
                                                    } else if (dragMode == "gradient_start") {
                                                        val currentSelected = layers.find { it.id == selId }
                                                        if (currentSelected != null) {
                                                            val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                            val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                            val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                            val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                            val localTouch = canvasToLayerLocal(artboardRelativeTouch, currentSelected)
                                                            scope.launch(kotlinx.coroutines.Dispatchers.Default) {
                                                                val startRatioX = localTouch.x / currentSelected.width.coerceAtLeast(1f)
                                                                val startRatioY = localTouch.y / currentSelected.height.coerceAtLeast(1f)
                                                                val nextLayers = layers.map { layer ->
                                                                    if (layer.id == selId) {
                                                                        val updatedEffects = layer.effects.map { eff ->
                                                                            if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                val map = eff.parameters.toMutableMap()
                                                                                if (map["EndX"] == null) {
                                                                                    val goScale = (map["Scale"]?.value ?: 100f) / 100f
                                                                                    val goAngle = map["Angle"]?.value ?: 90f
                                                                                    val rads = Math.toRadians(goAngle.toDouble())
                                                                                    val cos = Math.cos(rads).toFloat()
                                                                                    val sin = Math.sin(rads).toFloat()
                                                                                    val defaultEndX = (currentSelected.width / 2f + (currentSelected.width / 2f * cos * goScale)) / currentSelected.width.coerceAtLeast(1f)
                                                                                    val defaultEndY = (currentSelected.height / 2f + (currentSelected.height / 2f * sin * goScale)) / currentSelected.height.coerceAtLeast(1f)
                                                                                    map["EndX"] = com.example.studio.model.EffectParameter("EndX", defaultEndX, 0f, 1f)
                                                                                    map["EndY"] = com.example.studio.model.EffectParameter("EndY", defaultEndY, 0f, 1f)
                                                                                }
                                                                                map["StartX"] = com.example.studio.model.EffectParameter("StartX", startRatioX, 0f, 1f)
                                                                                map["StartY"] = com.example.studio.model.EffectParameter("StartY", startRatioY, 0f, 1f)
                                                                                eff.copy(parameters = map)
                                                                            } else eff
                                                                        }
                                                                        layer.copy(effects = updatedEffects)
                                                                    } else layer
                                                                }
                                                                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                                    layers = nextLayers
                                                                }
                                                            }
                                                        }
                                                    } else if (dragMode == "gradient_end") {
                                                        val currentSelected = layers.find { it.id == selId }
                                                        if (currentSelected != null) {
                                                            val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                            val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                            val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                            val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                            val localTouch = canvasToLayerLocal(artboardRelativeTouch, currentSelected)
                                                            scope.launch(kotlinx.coroutines.Dispatchers.Default) {
                                                                val endRatioX = localTouch.x / currentSelected.width.coerceAtLeast(1f)
                                                                val endRatioY = localTouch.y / currentSelected.height.coerceAtLeast(1f)
                                                                val nextLayers = layers.map { layer ->
                                                                    if (layer.id == selId) {
                                                                        val updatedEffects = layer.effects.map { eff ->
                                                                            if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                                val map = eff.parameters.toMutableMap()
                                                                                if (map["StartX"] == null) {
                                                                                    val goScale = (map["Scale"]?.value ?: 100f) / 100f
                                                                                    val goAngle = map["Angle"]?.value ?: 90f
                                                                                    val rads = Math.toRadians(goAngle.toDouble())
                                                                                    val cos = Math.cos(rads).toFloat()
                                                                                    val sin = Math.sin(rads).toFloat()
                                                                                    val defaultStartX = (currentSelected.width / 2f - (currentSelected.width / 2f * cos * goScale)) / currentSelected.width.coerceAtLeast(1f)
                                                                                    val defaultStartY = (currentSelected.height / 2f - (currentSelected.height / 2f * sin * goScale)) / currentSelected.height.coerceAtLeast(1f)
                                                                                    map["StartX"] = com.example.studio.model.EffectParameter("StartX", defaultStartX, 0f, 1f)
                                                                                    map["StartY"] = com.example.studio.model.EffectParameter("StartY", defaultStartY, 0f, 1f)
                                                                                }
                                                                                map["EndX"] = com.example.studio.model.EffectParameter("EndX", endRatioX, 0f, 1f)
                                                                                map["EndY"] = com.example.studio.model.EffectParameter("EndY", endRatioY, 0f, 1f)
                                                                                eff.copy(parameters = map)
                                                                            } else eff
                                                                        }
                                                                        layer.copy(effects = updatedEffects)
                                                                    } else layer
                                                                }
                                                                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                                                                    layers = nextLayers
                                                                }
                                                            }
                                                        }
                                                    } else if (dragMode == "gradient_stop") {
                                                        val currentSelected = layers.find { it.id == selId }
                                                        val gradOverlay = currentSelected?.effects?.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                                        if (currentSelected != null && gradOverlay != null) {
                                                            val hasCustomHandles = gradOverlay.parameters["StartX"] != null
                                                            val startX: Float
                                                            val startY: Float
                                                            val endX: Float
                                                            val endY: Float
                                                            if (hasCustomHandles) {
                                                                startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * currentSelected.width
                                                                startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * currentSelected.height
                                                                endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * currentSelected.width
                                                                endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * currentSelected.height
                                                            } else {
                                                                val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
                                                                val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
                                                                val rads = Math.toRadians(goAngle.toDouble())
                                                                val cos = Math.cos(rads).toFloat()
                                                                val sin = Math.sin(rads).toFloat()
                                                                startX = currentSelected.width / 2f - (currentSelected.width / 2f * cos * goScale)
                                                                startY = currentSelected.height / 2f - (currentSelected.height / 2f * sin * goScale)
                                                                endX = currentSelected.width / 2f + (currentSelected.width / 2f * cos * goScale)
                                                                endY = currentSelected.height / 2f + (currentSelected.height / 2f * sin * goScale)
                                                            }
                                                            
                                                            val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                            val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                            val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                            val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                            val localTouch = canvasToLayerLocal(artboardRelativeTouch, currentSelected)
                                                            val ab = Offset(endX - startX, endY - startY)
                                                            val ap = Offset(localTouch.x - startX, localTouch.y - startY)
                                                            val abLenSq = ab.x * ab.x + ab.y * ab.y
                                                            val tFraction = if (abLenSq > 0f) {
                                                                ((ap.x * ab.x + ap.y * ab.y) / abLenSq).coerceIn(0f, 1f)
                                                            } else 0f
                                                             
                                                            layers = layers.map { layer ->
                                                                if (layer.id == selId) {
                                                                    val updatedEffects = layer.effects.map { eff ->
                                                                        if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                            val map = eff.parameters.toMutableMap()
                                                                            map["CustomStop_${activeGradientStopIndex}_Pos"] = com.example.studio.model.EffectParameter("CustomStop_${activeGradientStopIndex}_Pos", tFraction, 0f, 1f)
                                                                            eff.copy(parameters = map)
                                                                        } else eff
                                                                    }
                                                                    layer.copy(effects = updatedEffects)
                                                                } else layer
                                                            }
                                                        }
                                                    } else if (dragMode == "bezier") {
                                                        layers = layers.map { layer ->
                                                            if (layer.id == selId && !layer.isAlphaLocked && layer.type == LayerType.VECTOR_BEZIER) {
                                                                val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                                 val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                                 val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                                 val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                                 val localCtrl = canvasToLayerLocal(artboardRelativeTouch, layer)
                                                                val updatedPoints = layer.brushPoints.toMutableList()
                                                                val idx = activeBezierPointIndex
                                                                 if (idx in updatedPoints.indices) {
                                                                     if (idx % 3 == 0) {
                                                                         val oldPos = updatedPoints[idx]
                                                                         val hasNoHandles = (idx + 1 in updatedPoints.indices && updatedPoints[idx + 1] == oldPos) &&
                                                                                            (idx + 2 in updatedPoints.indices && updatedPoints[idx + 2] == oldPos)
                                                                         if (tool == "Pen" && hasNoHandles) {
                                                                             val delta = localCtrl - oldPos
                                                                             if (idx + 1 in updatedPoints.indices) {
                                                                                 updatedPoints[idx + 1] = oldPos - delta
                                                                             }
                                                                             if (idx + 2 in updatedPoints.indices) {
                                                                                 updatedPoints[idx + 2] = oldPos + delta
                                                                             }
                                                                         } else {
                                                                             val delta = localCtrl - oldPos
                                                                             updatedPoints[idx] = localCtrl
                                                                             if (idx + 1 in updatedPoints.indices) {
                                                                                 updatedPoints[idx + 1] = updatedPoints[idx + 1] + delta
                                                                             }
                                                                             if (idx + 2 in updatedPoints.indices) {
                                                                                 updatedPoints[idx + 2] = updatedPoints[idx + 2] + delta
                                                                             }
                                                                         }
                                                                     } else {
                                                                         val k = idx / 3
                                                                         val isCorner = layer.bezierNodeTypes.getOrNull(k) == "CORNER"
                                                                         updatedPoints[idx] = localCtrl
                                                                         if (!isCorner) {
                                                                             val anchorPos = updatedPoints[k * 3]
                                                                             val otherHandleIndex = if (idx % 3 == 1) k * 3 + 2 else k * 3 + 1
                                                                             if (otherHandleIndex in updatedPoints.indices) {
                                                                                 if (keepBezierSymmetrical) {
                                                                                     updatedPoints[otherHandleIndex] = anchorPos * 2f - localCtrl
                                                                                 } else {
                                                                                     val otherHandleCurrent = updatedPoints[otherHandleIndex]
                                                                                     val otherHandleDist = (otherHandleCurrent - anchorPos).getDistance()
                                                                                     val draggedHandleVector = localCtrl - anchorPos
                                                                                     val draggedHandleDist = draggedHandleVector.getDistance()
                                                                                     if (draggedHandleDist > 0.001f) {
                                                                                         val normalizedOpposite = androidx.compose.ui.geometry.Offset(-draggedHandleVector.x / draggedHandleDist, -draggedHandleVector.y / draggedHandleDist)
                                                                                         updatedPoints[otherHandleIndex] = anchorPos + (normalizedOpposite * otherHandleDist)
                                                                                     }
                                                                                 }
                                                                             }
                                                                         }
                                                                     }
                                                                 }
                                                                layer.copy(brushPoints = updatedPoints)
                                                            } else layer
                                                        }
                                                        com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                                                        /* pathCache.clear() */
                                                    } else if (dragMode == "shape_builder") {
                                                         val clickPt = Offset(localChangeX - artboardOffsetX, localChangeY - artboardOffsetY)
                                                         shapeBuilderDragPoints.add(clickPt)
                                                    } else if (dragMode == "freeform_draw") {
                                                         val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                         val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                         val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                         val artboardRelativeTouch = Offset(localChangeX - artboardOffsetX, localChangeY - artboardOffsetY)
                                                         val clickPt = Offset(artboardRelativeTouch.x.coerceIn(0f, artboardWidth), artboardRelativeTouch.y.coerceIn(0f, artboardHeight))
                                                         freeformPenPoints = freeformPenPoints + clickPt
                                                     } else if (dragMode == "pen_draw_handles") {
                                                        layers = layers.map { layer ->
                                                            if (layer.id == selId && layer.type == LayerType.VECTOR_BEZIER) {
                                                                val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                                                val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                                                                val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                                                                val artboardRelativeTouch = Offset(localChangeOffset.x - artboardOffsetX, localChangeOffset.y - artboardOffsetY)
                                                                val localCtrl = canvasToLayerLocal(artboardRelativeTouch, layer)
                                                                val updatedPoints = layer.brushPoints.toMutableList()
                                                                val idx = activeBezierPointIndex
                                                                if (idx in updatedPoints.indices && idx + 2 in updatedPoints.indices) {
                                                                    val startLocal = updatedPoints[idx]
                                                                    val delta = localCtrl - startLocal
                                                                    
                                                                    val k = idx / 3
                                                                    val isCorner = layer.bezierNodeTypes.getOrNull(k) == "CORNER"
                                                                    
                                                                    updatedPoints[idx + 2] = startLocal + delta // The handle being dragged (handleOut)
                                                                    if (!isCorner) {
                                                                        updatedPoints[idx + 1] = startLocal - delta // The opposite handle (handleIn)
                                                                    }
                                                                }
                                                                layer.copy(brushPoints = updatedPoints)
                                                            } else layer
                                                        }
                                                        com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                                                        /* pathCache.clear() */
                                                    } else if (dragMode == "move") {
                                                         val hasGradOverlay = layers.find { it.id == selId }?.effects?.any { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } ?: false
                                                         if (!hasGradOverlay) {
                                                             val primaryLayer = layers.find { it.id == selId } ?: layers.find { it.id in selectedLayersSet }
                                                             var finalDragX = localDragX
                                                             var finalDragY = localDragY

                                                             if (primaryLayer != null) {
                                                                 var tempFinalX = primaryLayer.positionX + localDragX
                                                                 var tempFinalY = primaryLayer.positionY + localDragY

                                                                 val snapThreshold = 4f / ts.coerceAtLeast(0.1f) // Scaled by zoom for softer stickiness
                                                                 val canvasW = currentCanvasWidthState.value
                                                                 val canvasH = currentCanvasHeightState.value

                                                                 val activeGridEnabled = currentGridEnabledState.value
                                                                 val activeGridColumns = currentGridColumnsState.value
                                                                 val activeGridRows = currentGridRowsState.value
                                                                 val activeRulerEnabled = currentRulerEnabledState.value
                                                                 val activeRulerOrientation = currentRulerOrientationState.value
                                                                 val activeRulerPosition = currentRulerPositionState.value
                                                                 val activeRulerAngle = currentRulerAngleState.value
                                                                 val activeSnapToRuler = currentSnapToRulerState.value

                                                                 var locSnapVerticalLine: Float? = null
                                                                 var locSnapHorizontalLine: Float? = null
                                                                 var locSnapIndicatorMsg: String? = null
                                                                 var matchedXVal: Float? = null
                                                                 var matchedXLabel: String? = null
                                                                 var matchedYVal: Float? = null
                                                                 var matchedYLabel: String? = null

                                                                 // 1. Grid Snapping
                                                                 if (activeGridEnabled) {
                                                                     val cols = activeGridColumns.coerceIn(1, 200)
                                                                     val rows = activeGridRows.coerceIn(1, 200)
                                                                     val colWidth = canvasW / cols
                                                                     val rowHeight = canvasH / rows

                                                                     var closestGridX = Float.MAX_VALUE
                                                                     var bestSnappedX = tempFinalX
                                                                     for (i in 0..cols) {
                                                                         val gridLineX = i * colWidth
                                                                         val dLeft = Math.abs(tempFinalX - gridLineX)
                                                                         if (dLeft < snapThreshold && dLeft < closestGridX) {
                                                                             closestGridX = dLeft
                                                                             bestSnappedX = gridLineX
                                                                         }
                                                                         val dRight = Math.abs((tempFinalX + primaryLayer.width) - gridLineX)
                                                                         if (dRight < snapThreshold && dRight < closestGridX) {
                                                                             closestGridX = dRight
                                                                             bestSnappedX = gridLineX - primaryLayer.width
                                                                         }
                                                                         val dMid = Math.abs((tempFinalX + primaryLayer.width / 2f) - gridLineX)
                                                                         if (dMid < snapThreshold && dMid < closestGridX) {
                                                                             closestGridX = dMid
                                                                             bestSnappedX = gridLineX - primaryLayer.width / 2f
                                                                         }
                                                                     }
                                                                     if (closestGridX < snapThreshold) {
                                                                         tempFinalX = bestSnappedX
                                                                         val possibleLineL = Math.round(bestSnappedX / colWidth) * colWidth
                                                                         val possibleLineR = Math.round((bestSnappedX + primaryLayer.width) / colWidth) * colWidth
                                                                         val possibleLineM = Math.round((bestSnappedX + primaryLayer.width / 2f) / colWidth) * colWidth
                                                                         locSnapVerticalLine = when {
                                                                             Math.abs(bestSnappedX - possibleLineL) < 1f -> possibleLineL
                                                                             Math.abs((bestSnappedX + primaryLayer.width) - possibleLineR) < 1f -> possibleLineR
                                                                             else -> possibleLineM
                                                                         }
                                                                         locSnapIndicatorMsg = "Snapped to Grid X"
                                                                     }

                                                                     var closestGridY = Float.MAX_VALUE
                                                                     var bestSnappedY = tempFinalY
                                                                     for (j in 0..rows) {
                                                                         val gridLineY = j * rowHeight
                                                                         val dTop = Math.abs(tempFinalY - gridLineY)
                                                                         if (dTop < snapThreshold && dTop < closestGridY) {
                                                                             closestGridY = dTop
                                                                             bestSnappedY = gridLineY
                                                                         }
                                                                         val dBot = Math.abs((tempFinalY + primaryLayer.height) - gridLineY)
                                                                         if (dBot < snapThreshold && dBot < closestGridY) {
                                                                             closestGridY = dBot
                                                                             bestSnappedY = gridLineY - primaryLayer.height
                                                                         }
                                                                         val dMidY = Math.abs((tempFinalY + primaryLayer.height / 2f) - gridLineY)
                                                                         if (dMidY < snapThreshold && dMidY < closestGridY) {
                                                                             closestGridY = dMidY
                                                                             bestSnappedY = gridLineY - primaryLayer.height / 2f
                                                                         }
                                                                     }
                                                                     if (closestGridY < snapThreshold) {
                                                                         tempFinalY = bestSnappedY
                                                                         val possibleLineT = Math.round(bestSnappedY / rowHeight) * rowHeight
                                                                         val possibleLineB = Math.round((bestSnappedY + primaryLayer.height) / rowHeight) * rowHeight
                                                                         val possibleLineM = Math.round((bestSnappedY + primaryLayer.height / 2f) / rowHeight) * rowHeight
                                                                         locSnapHorizontalLine = when {
                                                                             Math.abs(bestSnappedY - possibleLineT) < 1f -> possibleLineT
                                                                             Math.abs((bestSnappedY + primaryLayer.height) - possibleLineB) < 1f -> possibleLineB
                                                                             else -> possibleLineM
                                                                         }
                                                                         locSnapIndicatorMsg = if (locSnapVerticalLine != null) "Snapped to Grid Intersection" else "Snapped to Grid Y"
                                                                     }
                                                                 }

                                                                 // 2. Center Snapping && Axis Snapping && Sides Snapping
                                                                 if (!activeGridEnabled) {
                                                                     try {
                                                                         val activeArtItem = artboards.find { it.id == selectedArtboardId }
                                                                         val localArtW = activeArtItem?.width ?: canvasW
                                                                         val localArtH = activeArtItem?.height ?: canvasH

                                                                         val canvasMinX = 0f
                                                                         val canvasMaxX = if (localArtW.isFinite()) localArtW else canvasW
                                                                         val canvasMinY = 0f
                                                                         val canvasMaxY = if (localArtH.isFinite()) localArtH else canvasH
                                                                         val canvasCenterX = canvasMaxX / 2f
                                                                         val canvasCenterY = canvasMaxY / 2f

                                                                         if (tempFinalX.isFinite() && tempFinalY.isFinite() && primaryLayer.width.isFinite() && primaryLayer.height.isFinite()) {
                                                                             val objCenterX = tempFinalX + primaryLayer.width / 2f
                                                                             val objCenterY = tempFinalY + primaryLayer.height / 2f

                                                                             var bestSnappedX = tempFinalX
                                                                             var closestXDist = Float.MAX_VALUE

                                                                             val dMidX = Math.abs(objCenterX - canvasCenterX)
                                                                             if (dMidX < snapThreshold && dMidX < closestXDist) {
                                                                                 closestXDist = dMidX
                                                                                 bestSnappedX = canvasCenterX - primaryLayer.width / 2f
                                                                                 matchedXVal = canvasCenterX
                                                                                 matchedXLabel = "Canvas Center"
                                                                             }
                                                                             val dLeft = Math.abs(tempFinalX - canvasMinX)
                                                                             if (dLeft < snapThreshold && dLeft < closestXDist) {
                                                                                 closestXDist = dLeft
                                                                                 bestSnappedX = canvasMinX
                                                                                 matchedXVal = canvasMinX
                                                                                 matchedXLabel = "Left Edge"
                                                                             }
                                                                             val dRight = Math.abs((tempFinalX + primaryLayer.width) - canvasMaxX)
                                                                             if (dRight < snapThreshold && dRight < closestXDist) {
                                                                                 closestXDist = dRight
                                                                                 bestSnappedX = canvasMaxX - primaryLayer.width
                                                                                 matchedXVal = canvasMaxX
                                                                                 matchedXLabel = "Right Edge"
                                                                             }

                                                                             if (closestXDist < snapThreshold) {
                                                                                 tempFinalX = bestSnappedX
                                                                                 locSnapVerticalLine = matchedXVal
                                                                                 locSnapIndicatorMsg = "Snapped to $matchedXLabel"
                                                                             }

                                                                             var bestSnappedY = tempFinalY
                                                                             var closestYDist = Float.MAX_VALUE

                                                                             val dMidY = Math.abs(objCenterY - canvasCenterY)
                                                                             if (dMidY < snapThreshold && dMidY < closestYDist) {
                                                                                 closestYDist = dMidY
                                                                                 bestSnappedY = canvasCenterY - primaryLayer.height / 2f
                                                                                 matchedYVal = canvasCenterY
                                                                                 matchedYLabel = "Canvas Center"
                                                                             }
                                                                             val dTop = Math.abs(tempFinalY - canvasMinY)
                                                                             if (dTop < snapThreshold && dTop < closestYDist) {
                                                                                 closestYDist = dTop
                                                                                 bestSnappedY = canvasMinY
                                                                                 matchedYVal = canvasMinY
                                                                                 matchedYLabel = "Top Edge"
                                                                             }
                                                                             val dBot = Math.abs((tempFinalY + primaryLayer.height) - canvasMaxY)
                                                                             if (dBot < snapThreshold && dBot < closestYDist) {
                                                                                 closestYDist = dBot
                                                                                 bestSnappedY = canvasMaxY - primaryLayer.height
                                                                                 matchedYVal = canvasMaxY
                                                                                 matchedYLabel = "Bottom Edge"
                                                                             }

                                                                             if (closestYDist < snapThreshold) {
                                                                                 tempFinalY = bestSnappedY
                                                                                 locSnapHorizontalLine = matchedYVal
                                                                                 if (matchedXVal != null) {
                                                                                     locSnapIndicatorMsg = "Snapped to Intersection ($matchedXLabel & $matchedYLabel)"
                                                                                 } else {
                                                                                     locSnapIndicatorMsg = "Snapped to $matchedYLabel"
                                                                                 }
                                                                             }
                                                                         }
                                                                     } catch (e: Exception) {
                                                                         locSnapVerticalLine = null
                                                                         locSnapHorizontalLine = null
                                                                         locSnapIndicatorMsg = null
                                                                     }
                                                                 }

                                                                 // 3. Ruler Snapping on proximity
                                                                 // 2b. Relative Layer-to-Layer Alignment & Snapping
                                                                 if (!activeGridEnabled && currentLayersState.value.size > 1) {
                                                                     val otherSnapLayers = currentLayersState.value.filter { it.id != primaryLayer.id && it.isVisible }
                                                                     val pL = tempFinalX
                                                                     val pR = tempFinalX + primaryLayer.width
                                                                     val pCX = tempFinalX + primaryLayer.width / 2f
                                                                     val pT = tempFinalY
                                                                     val pB = tempFinalY + primaryLayer.height
                                                                     val pCY = tempFinalY + primaryLayer.height / 2f
                                                                     val relSnapThreshold = 3f / ts.coerceAtLeast(0.1f)

                                                                     for (otherL in otherSnapLayers) {
                                                                         val oL = otherL.positionX
                                                                         val oR = otherL.positionX + otherL.width
                                                                         val oCX = otherL.positionX + otherL.width / 2f
                                                                         val oT = otherL.positionY
                                                                         val oB = otherL.positionY + otherL.height
                                                                         val oCY = otherL.positionY + otherL.height / 2f

                                                                         if (Math.abs(pL - oL) < relSnapThreshold) {
                                                                             tempFinalX = oL
                                                                             locSnapVerticalLine = oL
                                                                             locSnapIndicatorMsg = "Relative Align: Left to ${otherL.name}"
                                                                         } else if (Math.abs(pR - oR) < relSnapThreshold) {
                                                                             tempFinalX = oR - primaryLayer.width
                                                                             locSnapVerticalLine = oR
                                                                             locSnapIndicatorMsg = "Relative Align: Right to ${otherL.name}"
                                                                         } else if (Math.abs(pCX - oCX) < relSnapThreshold) {
                                                                             tempFinalX = oCX - primaryLayer.width / 2f
                                                                             locSnapVerticalLine = oCX
                                                                             locSnapIndicatorMsg = "Relative Align: Center to ${otherL.name}"
                                                                         }

                                                                         if (Math.abs(pT - oT) < relSnapThreshold) {
                                                                             tempFinalY = oT
                                                                             locSnapHorizontalLine = oT
                                                                             locSnapIndicatorMsg = "Relative Align: Top to ${otherL.name}"
                                                                         } else if (Math.abs(pB - oB) < relSnapThreshold) {
                                                                             tempFinalY = oB - primaryLayer.height
                                                                             locSnapHorizontalLine = oB
                                                                             locSnapIndicatorMsg = "Relative Align: Bottom to ${otherL.name}"
                                                                         } else if (Math.abs(pCY - oCY) < relSnapThreshold) {
                                                                             tempFinalY = oCY - primaryLayer.height / 2f
                                                                             locSnapHorizontalLine = oCY
                                                                             locSnapIndicatorMsg = "Relative Align: Center to ${otherL.name}"
                                                                         }
                                                                     }
                                                                 }

                                                                 if (activeRulerEnabled && activeSnapToRuler) {
                                                                     val proxThreshold = 4f / ts.coerceAtLeast(0.1f)
                                                                     var bestSnappedRulerX = tempFinalX
                                                                     var closestRulerXDist = Float.MAX_VALUE
                                                                     var matchedRulerXVal: Float? = null
                                                                     var didSnapRulerX = false

                                                                     var bestSnappedRulerY = tempFinalY
                                                                     var closestRulerYDist = Float.MAX_VALUE
                                                                     var matchedRulerYVal: Float? = null
                                                                     var didSnapRulerY = false

                                                                     for (ruler in currentRulersState.value) {
                                                                         if (!ruler.enabled) continue

                                                                         if (ruler.angle != 0f) {
                                                                             val angleRad = (ruler.angle * Math.PI / 180.0)
                                                                             val dX: Float
                                                                             val dY: Float
                                                                             val aX: Float
                                                                             val aY: Float
                                                                             if (ruler.orientation == "Horizontal") {
                                                                                 dX = Math.cos(angleRad).toFloat()
                                                                                 dY = Math.sin(angleRad).toFloat()
                                                                                 aX = artboardOffsetX + 1080f / 2f
                                                                                 aY = artboardOffsetY + ruler.position
                                                                             } else {
                                                                                 dX = -Math.sin(angleRad).toFloat()
                                                                                 dY = Math.cos(angleRad).toFloat()
                                                                                 aX = artboardOffsetX + ruler.position
                                                                                 aY = artboardOffsetY + 1350f / 2f
                                                                             }
                                                                             val sCenterX = tempFinalX + primaryLayer.width / 2f
                                                                             val sCenterY = tempFinalY + primaryLayer.height / 2f
                                                                             val t = (sCenterX - aX) * dX + (sCenterY - aY) * dY
                                                                             val snappedCenterX = aX + t * dX
                                                                             val snappedCenterY = aY + t * dY
                                                                             val distSq = (sCenterX - snappedCenterX) * (sCenterX - snappedCenterX) + (sCenterY - snappedCenterY) * (sCenterY - snappedCenterY)
                                                                             val dist = Math.sqrt(distSq.toDouble()).toFloat()
                                                                             if (dist < proxThreshold && dist < closestRulerXDist && dist < closestRulerYDist) {
                                                                                 bestSnappedRulerX = tempFinalX + (snappedCenterX - sCenterX)
                                                                                 bestSnappedRulerY = tempFinalY + (snappedCenterY - sCenterY)
                                                                                 didSnapRulerX = true
                                                                                 didSnapRulerY = true
                                                                                 closestRulerXDist = dist
                                                                                 closestRulerYDist = dist
                                                                                 matchedRulerXVal = ruler.position
                                                                                 matchedRulerYVal = ruler.position
                                                                             }
                                                                         } else if (ruler.orientation == "Vertical") {
                                                                             val lLeft = tempFinalX
                                                                             val lRight = tempFinalX + primaryLayer.width
                                                                             val lCenter = tempFinalX + primaryLayer.width / 2f

                                                                             val dLeft = Math.abs(lLeft - ruler.position)
                                                                             if (dLeft < proxThreshold && dLeft < closestRulerXDist) {
                                                                                 closestRulerXDist = dLeft
                                                                                 bestSnappedRulerX = ruler.position
                                                                                 matchedRulerXVal = ruler.position
                                                                                 didSnapRulerX = true
                                                                             }

                                                                             val dRight = Math.abs(lRight - ruler.position)
                                                                             if (dRight < proxThreshold && dRight < closestRulerXDist) {
                                                                                 closestRulerXDist = dRight
                                                                                 bestSnappedRulerX = ruler.position - primaryLayer.width
                                                                                 matchedRulerXVal = ruler.position
                                                                                 didSnapRulerX = true
                                                                             }

                                                                             val dCent = Math.abs(lCenter - ruler.position)
                                                                             if (dCent < proxThreshold && dCent < closestRulerXDist) {
                                                                                 closestRulerXDist = dCent
                                                                                 bestSnappedRulerX = ruler.position - primaryLayer.width / 2f
                                                                                 matchedRulerXVal = ruler.position
                                                                                 didSnapRulerX = true
                                                                             }
                                                                         } else {
                                                                             val lTop = tempFinalY
                                                                             val lBottom = tempFinalY + primaryLayer.height
                                                                             val lCenterY = tempFinalY + primaryLayer.height / 2f

                                                                             val dTop = Math.abs(lTop - ruler.position)
                                                                             if (dTop < proxThreshold && dTop < closestRulerYDist) {
                                                                                 closestRulerYDist = dTop
                                                                                 bestSnappedRulerY = ruler.position
                                                                                 matchedRulerYVal = ruler.position
                                                                                 didSnapRulerY = true
                                                                             }

                                                                             val dBot = Math.abs(lBottom - ruler.position)
                                                                             if (dBot < proxThreshold && dBot < closestRulerYDist) {
                                                                                 closestRulerYDist = dBot
                                                                                 bestSnappedRulerY = ruler.position - primaryLayer.height
                                                                                 matchedRulerYVal = ruler.position
                                                                                 didSnapRulerY = true
                                                                             }

                                                                             val dCentY = Math.abs(lCenterY - ruler.position)
                                                                             if (dCentY < proxThreshold && dCentY < closestRulerYDist) {
                                                                                 closestRulerYDist = dCentY
                                                                                 bestSnappedRulerY = ruler.position - primaryLayer.height / 2f
                                                                                 matchedRulerYVal = ruler.position
                                                                                 didSnapRulerY = true
                                                                             }
                                                                         }
                                                                     }

                                                                     if (didSnapRulerX) {
                                                                         tempFinalX = bestSnappedRulerX
                                                                         locSnapVerticalLine = matchedRulerXVal
                                                                     }
                                                                     if (didSnapRulerY) {
                                                                         tempFinalY = bestSnappedRulerY
                                                                         locSnapHorizontalLine = matchedRulerYVal
                                                                     }

                                                                     if (didSnapRulerX || didSnapRulerY) {
                                                                         val hasSnappedDiagonal = currentRulersState.value.any { it.enabled && it.angle != 0f && (it.position == matchedRulerXVal || it.position == matchedRulerYVal) }
                                                                         locSnapIndicatorMsg = when {
                                                                             hasSnappedDiagonal -> "Snapped to Diagonal Guideline"
                                                                             didSnapRulerX && didSnapRulerY -> "Snapped to Guidelines Intersection"
                                                                             didSnapRulerX -> "Snapped to Vertical Guideline"
                                                                             else -> "Snapped to Horizontal Guideline"
                                                                         }
                                                                     }
                                                                 }

                                                                 finalDragX = tempFinalX - primaryLayer.positionX
                                                                 finalDragY = tempFinalY - primaryLayer.positionY
                                                                 snapVerticalLine = locSnapVerticalLine
                                                                 snapHorizontalLine = locSnapHorizontalLine
                                                                 snapIndicatorMsg = locSnapIndicatorMsg
                                                             }

                                                             val targetIds = if (isMultiSelectMode) selectedLayersSet else setOf(selId)
                                                             layers = layers.map { layer ->
                                                                 if (targetIds.contains(layer.id) && !layer.isAlphaLocked) {
                                                                     layer.copy(
                                                                         positionX = layer.positionX + finalDragX,
                                                                         positionY = layer.positionY + finalDragY
                                                                     )
                                                                 } else layer
                                                             }
                                                         }
                                                    }
                                                }
                                                pointer.consume()
                                            }
                                        }
                                    } while (event.changes.any { it.pressed })

                                    // Gesture over: finalize actions
                                    if (isResizingActive && activeResizingLayerId != null && startingLayerForResize != null) {
                                        val targetId = activeResizingLayerId
                                        val startL = startingLayerForResize
                                        val finalDragScaleXSnapshot = liveDragScaleX
                                        val finalDragScaleYSnapshot = liveDragScaleY
                                        if (targetId != null && startL != null) {
                                            undoStack.add(layers)
                                            redoStack.clear()
                                            layers = layers.map { layer ->
                                                if (layer.id == targetId) {
                                                    val newW = (startL.width * finalDragScaleXSnapshot).coerceIn(20f, 5000f)
                                                    val newH = (startL.height * finalDragScaleYSnapshot).coerceIn(20f, 5000f)
                                                    val anchorMode = currentShapeAnchorModeState.value
                                                    val (newX, newY) = when (anchorMode) {
                                                        "ORIGIN" -> Pair(startL.positionX, startL.positionY)
                                                        "OPPOSITE" -> when (dragMode) {
                                                            "resize_br", "resize_r", "resize_b" -> Pair(startL.positionX, startL.positionY)
                                                            "resize_tl" -> Pair(startL.positionX + startL.width - newW, startL.positionY + startL.height - newH)
                                                            "resize_tr" -> Pair(startL.positionX, startL.positionY + startL.height - newH)
                                                            "resize_bl" -> Pair(startL.positionX + startL.width - newW, startL.positionY)
                                                            "resize_l" -> Pair(startL.positionX + startL.width - newW, startL.positionY)
                                                            "resize_t" -> Pair(startL.positionX, startL.positionY + startL.height - newH)
                                                            else -> Pair(startL.positionX + (startL.width - newW) / 2f, startL.positionY + (startL.height - newH) / 2f)
                                                        }
                                                        else -> Pair(startL.positionX + (startL.width - newW) / 2f, startL.positionY + (startL.height - newH) / 2f)
                                                    }
                                                    val scX = newW / startL.width.coerceAtLeast(1f)
                                                    val scY = newH / startL.height.coerceAtLeast(1f)
                                                    val updatedPerspStr = if (layer.perspWarpPointsStr.isNotEmpty()) {
                                                        val corners = parseWarpPointsStr(layer.perspWarpPointsStr)
                                                        val scaled = corners.map { Offset(it.x * scX, it.y * scY) }
                                                        formatWarpPointsStr(scaled)
                                                    } else layer.perspWarpPointsStr
                                                    val updatedMeshStr = if (layer.meshWarpPointsStr.isNotEmpty()) {
                                                        val cols = warpMeshDivisionX
                                                        val rows = warpMeshDivisionY
                                                        val nodes = parseMeshWarpPointsStr(layer.meshWarpPointsStr, cols, rows, startL.width, startL.height, layer.warpTarget, startL)
                                                        val scaled = nodes.map { n ->
                                                            n.copy(
                                                                main = Offset(n.main.x * scX, n.main.y * scY),
                                                                hHandle = Offset(n.hHandle.x * scX, n.hHandle.y * scY),
                                                                vHandle = Offset(n.vHandle.x * scX, n.vHandle.y * scY)
                                                            )
                                                        }
                                                        formatMeshWarpPointsStr(scaled)
                                                    } else layer.meshWarpPointsStr
                                                    
                                                    val updatedBrushPoints = if (startL.brushPoints.isNotEmpty()) {
                                                        startL.brushPoints.map { p -> Offset(p.x * scX, p.y * scY) }
                                                    } else layer.brushPoints
                                                    
                                                    layer.copy(
                                                        width = newW,
                                                        height = newH,
                                                        positionX = newX,
                                                        positionY = newY,
                                                        perspWarpPointsStr = updatedPerspStr,
                                                        meshWarpPointsStr = updatedMeshStr,
                                                        brushPoints = updatedBrushPoints
                                                    )
                                                } else layer
                                            }
                                        }
                                    }
                                     if (dragMode == "eyedropper") {
                                         val finalTouchPoint = GradientEyedropperState.touchPoint ?: localStartOffset
                                         val artRelativeX = finalTouchPoint.x - artboardOffsetX
                                         val artRelativeY = finalTouchPoint.y - artboardOffsetY
                                         
                                         val sampledColor = sampleCompositedColor(
                                             layers = layers,
                                             artRelativeX = artRelativeX,
                                             artRelativeY = artRelativeY,
                                             artboardWidth = artboardWidth,
                                             artboardHeight = artboardHeight,
                                             imageBitmapCache = imageBitmapCache
                                         )
                                         
                                         val callback = GradientEyedropperState.onColorSampled
                                         if (callback != null) {
                                             GradientEyedropperState.isActive = false
                                             GradientEyedropperState.touchPoint = null
                                             GradientEyedropperState.liveSampledColor = null
                                             GradientEyedropperState.onColorSampled = null
                                             callback.invoke(sampledColor)
                                         } else {
                                             val currentSelected = lyrs.find { it.id == selId }
                                             if (currentSelected != null) {
                                                 if (GradientEyedropperState.isSamplingForSolidColor) {
                                                     layers = layers.map { layer ->
                                                         if (layer.id == currentSelected.id) {
                                                             layer.copy(baseColor = sampledColor)
                                                         } else layer
                                                     }
                                                     android.widget.Toast.makeText(context, "Solid color sampled: RGB(${(sampledColor.red * 255).toInt()}, ${(sampledColor.green * 255).toInt()}, ${(sampledColor.blue * 255).toInt()})", android.widget.Toast.LENGTH_SHORT).show()
                                                 } else {
                                                     val targetStopIndex = activeGradientStopIndex.coerceIn(0, 100)
                                                     layers = layers.map { layer ->
                                                         if (layer.id == currentSelected.id) {
                                                             val updatedEffects = layer.effects.map { eff ->
                                                                 if (eff is com.example.studio.model.StudioEffect.PhotoshopEffect && eff.effectType == "GradientOverlay") {
                                                                     val map = eff.parameters.toMutableMap()
                                                                     map["CustomStop_${targetStopIndex}_R"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_R", sampledColor.red, 0f, 1f)
                                                                     map["CustomStop_${targetStopIndex}_G"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_G", sampledColor.green, 0f, 1f)
                                                                     map["CustomStop_${targetStopIndex}_B"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_B", sampledColor.blue, 0f, 1f)
                                                                     map["CustomStop_${targetStopIndex}_A"] = com.example.studio.model.EffectParameter("CustomStop_${targetStopIndex}_A", sampledColor.alpha, 0f, 1f)
                                                                     eff.copy(parameters = map)
                                                                 } else eff
                                                             }
                                                             layer.copy(effects = updatedEffects)
                                                         } else layer
                                                     }
                                                     android.widget.Toast.makeText(context, "Gradient stop color sampled: RGB(${(sampledColor.red * 255).toInt()}, ${(sampledColor.green * 255).toInt()}, ${(sampledColor.blue * 255).toInt()})", android.widget.Toast.LENGTH_SHORT).show()
                                                 }
                                             }
                                             GradientEyedropperState.isActive = false
                                             GradientEyedropperState.isSamplingForSolidColor = false
                                             GradientEyedropperState.liveSampledColor = null
                                             GradientEyedropperState.touchPoint = null
                                         }
                                     }

                                     if (isTransformingSelectedLayer) {
                                         undoStack.add(layers)
                                         redoStack.clear()
                                         isTransformingSelectedLayer = false
                                     }

                                    isResizingActive = false
                                    activeResizingLayerId = null
                                    startingLayerForResize = null
                                    liveDragScaleX = 1.0f
                                    liveDragScaleY = 1.0f
                                    liveDragPivotX = -1f
                                    liveDragPivotY = -1f

                                    snapVerticalLine = null
                                    snapHorizontalLine = null
                                    snapIndicatorMsg = null
                                    if (!isTransforming) {
                                        // Keep activeBezierPointIndex selected on gesture over to support tap-to-edit
                                         if (dragMode == "shape_builder" && shapeBuilderDragPoints.size >= 2) {
                                             val activeArtboard = artboards.find { it.id == selectedArtboardId }
                                             if (activeArtboard != null) {
                                                 val artboardWidth = activeArtboard.width
                                                 val artboardHeight = activeArtboard.height
                                                 
                                                 // Find all layers on this artboard that are vector types
                                                 val vectorLayers = layers.filter {
                                                     it.type != com.example.studio.model.LayerType.IMAGE_CARD &&
                                                     it.type != com.example.studio.model.LayerType.TEXT &&
                                                     it.type != com.example.studio.model.LayerType.GROUP &&
                                                     it.type != com.example.studio.model.LayerType.ADJUSTMENT_LAYER
                                                 }
                                                 
                                                 // Find intersecting layers
                                                 val intersectingLayers = vectorLayers.filter { layer ->
                                                     val left = layer.positionX
                                                     val top = layer.positionY
                                                     val right = layer.positionX + layer.width
                                                     val bottom = layer.positionY + layer.height
                                                     
                                                     shapeBuilderDragPoints.any { pt ->
                                                         pt.x >= left - 25f && pt.x <= right + 25f &&
                                                         pt.y >= top - 25f && pt.y <= bottom + 25f
                                                     }
                                                 }
                                                                                                if (intersectingLayers.isNotEmpty()) {
                                                      
                                                      fun getAndroidPathForLayer(lyr: com.example.studio.model.StudioLayer): android.graphics.Path {
                                                          val path = when (lyr.type) {
                                                              com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                                                                  val ap = lyr.brushPoints.toAnchorPoints()
                                                                  val p = android.graphics.Path()
                                                                  var startNewContour = true
                                                                  var contourStartIdx = 0
                                                                  var idx = 0
                                                                  while (idx < ap.size) {
                                                                      val current = ap[idx]
                                                                      if (current.position.x.isNaN() || current.position.y.isNaN()) {
                                                                          if (lyr.polygonEdges == 1 && idx > contourStartIdx) {
                                                                              val first = ap[contourStartIdx]
                                                                              val last = ap[idx - 1]
                                                                              if (first != last) {
                                                                                  p.cubicTo(
                                                                                      last.handleOut.x, last.handleOut.y,
                                                                                      first.handleIn.x, first.handleIn.y,
                                                                                      first.position.x, first.position.y
                                                                                  )
                                                                              }
                                                                              p.close()
                                                                          }
                                                                          startNewContour = true
                                                                          idx++
                                                                          continue
                                                                      }
                                                                      if (startNewContour) {
                                                                          p.moveTo(current.position.x, current.position.y)
                                                                          contourStartIdx = idx
                                                                          startNewContour = false
                                                                      } else {
                                                                          val prev = ap[idx - 1]
                                                                          p.cubicTo(
                                                                              prev.handleOut.x, prev.handleOut.y,
                                                                              current.handleIn.x, current.handleIn.y,
                                                                              current.position.x, current.position.y
                                                                          )
                                                                      }
                                                                      idx++
                                                                  }
                                                                  if (lyr.polygonEdges == 1 && ap.isNotEmpty() && !startNewContour) {
                                                                      val first = ap[contourStartIdx]
                                                                      val last = ap.last()
                                                                      if (first != last) {
                                                                          p.cubicTo(
                                                                              last.handleOut.x, last.handleOut.y,
                                                                              first.handleIn.x, first.handleIn.y,
                                                                              first.position.x, first.position.y
                                                                          )
                                                                      }
                                                                      p.close()
                                                                  }
                                                                  p
                                                              }
                                                              com.example.studio.model.LayerType.VECTOR_RECT -> {
                                                                  val p = android.graphics.Path()
                                                                  if (lyr.cornerRadius > 0f) {
                                                                      p.addRoundRect(android.graphics.RectF(0f, 0f, lyr.width, lyr.height), lyr.cornerRadius, lyr.cornerRadius, android.graphics.Path.Direction.CW)
                                                                  } else {
                                                                      p.addRect(android.graphics.RectF(0f, 0f, lyr.width, lyr.height), android.graphics.Path.Direction.CW)
                                                                  }
                                                                  p
                                                              }
                                                              com.example.studio.model.LayerType.VECTOR_CIRCLE -> {
                                                                  val p = android.graphics.Path()
                                                                  val radius = lyr.width / 2f
                                                                  p.addCircle(radius, lyr.height / 2f, radius, android.graphics.Path.Direction.CW)
                                                                  p
                                                              }
                                                              com.example.studio.model.LayerType.VECTOR_OVAL -> {
                                                                  val p = android.graphics.Path()
                                                                  p.addOval(android.graphics.RectF(0f, 0f, lyr.width, lyr.height), android.graphics.Path.Direction.CW)
                                                                  p
                                                              }
                                                              com.example.studio.model.LayerType.VECTOR_LINE -> {
                                                                  val p = android.graphics.Path()
                                                                  p.moveTo(0f, 0f)
                                                                  p.lineTo(lyr.width, lyr.height)
                                                                  p
                                                              }
                                                              com.example.studio.model.LayerType.VECTOR_TRIANGLE,
                                                              com.example.studio.model.LayerType.VECTOR_PENTAGON,
                                                              com.example.studio.model.LayerType.VECTOR_HEXAGON -> {
                                                                  val p = android.graphics.Path()
                                                                  val edges = if (lyr.type == com.example.studio.model.LayerType.VECTOR_HEXAGON) {
                                                                      if (lyr.polygonEdges in 3..25) lyr.polygonEdges else 6
                                                                  } else if (lyr.type == com.example.studio.model.LayerType.VECTOR_PENTAGON) {
                                                                      if (lyr.polygonEdges in 3..25) lyr.polygonEdges else 5
                                                                  } else {
                                                                      if (lyr.polygonEdges in 3..25) lyr.polygonEdges else 3
                                                                  }
                                                                  val cx = lyr.width / 2f
                                                                  val cy = lyr.height / 2f
                                                                  val rx = lyr.width / 2f
                                                                  val ry = lyr.height / 2f
                                                                  for (i in 0 until edges) {
                                                                      val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                                                                      val x = (cx + rx * Math.cos(angle)).toFloat()
                                                                      val y = (cy + ry * Math.sin(angle)).toFloat()
                                                                      if (i == 0) p.moveTo(x, y) else p.lineTo(x, y)
                                                                  }
                                                                  p.close()
                                                                  p
                                                              }
                                                              com.example.studio.model.LayerType.VECTOR_STAR -> {
                                                                  val p = android.graphics.Path()
                                                                  val cx = lyr.width / 2f
                                                                  val cy = lyr.height / 2f
                                                                  val rOuter = lyr.width / 2f
                                                                  val rInner = rOuter * lyr.starInnerRadiusRatio.coerceIn(0.01f, 0.99f)
                                                                  val pointsCount = if (lyr.polygonEdges >= 3) lyr.polygonEdges else 5
                                                                  var angle = Math.PI / 2.0 * 3.0
                                                                  val step = Math.PI / pointsCount
                                                                  p.moveTo(
                                                                      (cx + Math.cos(angle) * rOuter).toFloat(),
                                                                      (cy + Math.sin(angle) * rOuter).toFloat()
                                                                  )
                                                                  for (i in 0..(pointsCount * 2)) {
                                                                      val r = if (i % 2 == 0) rOuter else rInner
                                                                      p.lineTo(
                                                                          (cx + Math.cos(angle) * r).toFloat(),
                                                                          (cy + Math.sin(angle) * r).toFloat()
                                                                      )
                                                                      angle += step
                                                                  }
                                                                  p.close()
                                                                  p
                                                              }
                                                              else -> {
                                                                  createComplexShapePath(
                                                                      lyr.type, lyr.width, lyr.height,
                                                                      lyr.polygonEdges, lyr.starInnerRadiusRatio,
                                                                      lyr.skewX, lyr.skewY, lyr.cornerRadius
                                                                  ).asAndroidPath()
                                                              }
                                                          }
                                                          val matrix = android.graphics.Matrix()
                                                          matrix.postTranslate(lyr.positionX, lyr.positionY)
                                                          path.transform(matrix)
                                                          return path
                                                      }
                                                      
                                                      try {
                                                          val tracePathToPoints: (android.graphics.Path) -> List<List<Offset>> = { path ->
                                                              val pathMeasure = android.graphics.PathMeasure(path, false)
                                                              val contoursList = mutableListOf<List<Offset>>()
                                                              val distanceStep = 4.0f
                                                              val pos = FloatArray(2)
                                                              do {
                                                                  val len = pathMeasure.length
                                                                  if (len > 0f) {
                                                                      val contourPoints = mutableListOf<Offset>()
                                                                      var distance = 0f
                                                                      while (distance < len) {
                                                                          pathMeasure.getPosTan(distance, pos, null)
                                                                          contourPoints.add(Offset(pos[0], pos[1]))
                                                                          distance += distanceStep
                                                                      }
                                                                      var simplified = cleanConsecutiveDuplicates(simplifyPoints(contourPoints, epsilon = 1.2f))
                                                                      if (simplified.size >= 3) {
                                                                          val first = simplified.first()
                                                                          val last = simplified.last()
                                                                          val dSq = (last.x - first.x) * (last.x - first.x) + (last.y - first.y) * (last.y - first.y)
                                                                          if (dSq < 25f) {
                                                                              simplified = simplified.dropLast(1)
                                                                          }
                                                                      }
                                                                      if (simplified.isNotEmpty()) {
                                                                          contoursList.add(simplified)
                                                                      }
                                                                  }
                                                              } while (pathMeasure.nextContour())
                                                              contoursList
                                                          }

                                                          val convertPathToLayer: (android.graphics.Path, com.example.studio.model.StudioLayer, String) -> com.example.studio.model.StudioLayer? = { path, styleLayer, name ->
                                                              if (path.isEmpty) {
                                                                  null
                                                              } else {
                                                                  val bounds = android.graphics.RectF()
                                                                  path.computeBounds(bounds, true)
                                                                  
                                                                  val bLeft = bounds.left
                                                                  val bTop = bounds.top
                                                                  val bWidth = bounds.width().coerceAtLeast(10f)
                                                                  val bHeight = bounds.height().coerceAtLeast(10f)
                                                                  
                                                                  val optimalAnchors = convertAndroidPathToOptimalBezierAnchors(path)
                                                                  if (optimalAnchors.isEmpty()) {
                                                                      null
                                                                  } else {
                                                                      val normalizedBrushPoints = mutableListOf<Offset>()
                                                                      for (anchor in optimalAnchors) {
                                                                          if (anchor.position.x.isNaN() || anchor.position.y.isNaN()) {
                                                                              val nanPt = Offset(Float.NaN, Float.NaN)
                                                                              normalizedBrushPoints.add(nanPt)
                                                                              normalizedBrushPoints.add(nanPt)
                                                                              normalizedBrushPoints.add(nanPt)
                                                                          } else {
                                                                              normalizedBrushPoints.add(Offset(anchor.position.x - bLeft, anchor.position.y - bTop))
                                                                              normalizedBrushPoints.add(Offset(anchor.handleIn.x - bLeft, anchor.handleIn.y - bTop))
                                                                              normalizedBrushPoints.add(Offset(anchor.handleOut.x - bLeft, anchor.handleOut.y - bTop))
                                                                          }
                                                                      }
                                                                      
                                                                      com.example.studio.model.StudioLayer(
                                                                          name = name,
                                                                          type = com.example.studio.model.LayerType.VECTOR_BEZIER,
                                                                          positionX = bLeft,
                                                                          positionY = bTop,
                                                                          width = bWidth,
                                                                          height = bHeight,
                                                                          baseColor = styleLayer.baseColor,
                                                                          brushPoints = normalizedBrushPoints,
                                                                          polygonEdges = 1,
                                                                          opacity = styleLayer.opacity,
                                                                          isVisible = styleLayer.isVisible,
                                                                          blendMode = styleLayer.blendMode
                                                                      )
                                                                  }
                                                              }
                                                          }

                                                          undoStack.add(layers)
                                                          redoStack.clear()

                                                          if (shapeBuilderMode == "Merge") {
                                                              val baseLayer = intersectingLayers.first()
                                                              val otherLayers = intersectingLayers.drop(1)
                                                              val styleLayer = intersectingLayers.find { it.id == selectedLayerId } ?: intersectingLayers.last()

                                                              val resultPath = getAndroidPathForLayer(baseLayer)
                                                              for (other in otherLayers) {
                                                                  val otherPath = getAndroidPathForLayer(other)
                                                                  resultPath.op(resultPath, otherPath, android.graphics.Path.Op.UNION)
                                                              }

                                                              val mergedLayer = convertPathToLayer(resultPath, styleLayer, "Merged Shape")
                                                              if (mergedLayer != null) {
                                                                  val intersectingIds = intersectingLayers.map { it.id }.toSet()
                                                                  val filteredLayers = layers.filterNot { it.id in intersectingIds }
                                                                  
                                                                  layers = listOf(mergedLayer) + filteredLayers
                                                                  selectedLayerId = mergedLayer.id
                                                                  com.example.studio.ui.ParametricLayerCache.invalidate(mergedLayer.id)
                                                                  /* pathCache.clear() */

                                                                  if (currentShapeBuilderTurnIntoPathState.value) {
                                                                      activeTool = "Pen"
                                                                      android.widget.Toast.makeText(context, "Successfully merged " + intersectingLayers.size + " shapes into an editable path!", android.widget.Toast.LENGTH_SHORT).show()
                                                                  } else {
                                                                      android.widget.Toast.makeText(context, "Successfully merged " + intersectingLayers.size + " shapes!", android.widget.Toast.LENGTH_SHORT).show()
                                                                  }
                                                              } else {
                                                                  android.widget.Toast.makeText(context, "Merge resulted in an empty shape", android.widget.Toast.LENGTH_SHORT).show()
                                                              }
                                                          
                                                                                                                     } else if (shapeBuilderMode == "Subtract") {
                                                               if (intersectingLayers.size < 2) {
                                                                   android.widget.Toast.makeText(context, "Drag over 2 or more overlapping shapes to subtract", android.widget.Toast.LENGTH_SHORT).show()
                                                               } else {
                                                                   // Under the current layers system, index 0 is at the top/front visually, and larger index is at the bottom/back.
                                                                   // Therefore, the bottom/back layer is the last item in intersectingLayers, and top/front layers are preceding items.
                                                                   val baseLayer = intersectingLayers.last()
                                                                   val otherLayers = intersectingLayers.dropLast(1)
                                                                   val styleLayer = baseLayer

                                                                   val resultPath = getAndroidPathForLayer(baseLayer)
                                                                   for (other in otherLayers) {
                                                                       val otherPath = getAndroidPathForLayer(other)
                                                                       resultPath.op(resultPath, otherPath, android.graphics.Path.Op.DIFFERENCE)
                                                                   }

                                                                   val subtractedLayer = convertPathToLayer(resultPath, styleLayer, baseLayer.name)
                                                                   val intersectingIds = intersectingLayers.map { it.id }.toSet()
                                                                   val finalUpdatedLayersList = mutableListOf<com.example.studio.model.StudioLayer>()

                                                                   for (lyr in layers) {
                                                                       if (lyr.id == baseLayer.id) {
                                                                           if (subtractedLayer != null) {
                                                                               finalUpdatedLayersList.add(subtractedLayer)
                                                                           }
                                                                       } else if (lyr.id !in intersectingIds) {
                                                                           finalUpdatedLayersList.add(lyr)
                                                                       }
                                                                   }

                                                                   if (subtractedLayer != null) {
                                                                       layers = finalUpdatedLayersList
                                                                       selectedLayerId = subtractedLayer.id
                                                                       com.example.studio.ui.ParametricLayerCache.invalidate(subtractedLayer.id)
                                                                       /* pathCache.clear() */

                                                                       if (currentShapeBuilderTurnIntoPathState.value) {
                                                                           activeTool = "Pen"
                                                                           android.widget.Toast.makeText(context, "Successfully subtracted top shapes from bottom shape into an editable path!", android.widget.Toast.LENGTH_SHORT).show()
                                                                       } else {
                                                                           android.widget.Toast.makeText(context, "Successfully subtracted top shapes!", android.widget.Toast.LENGTH_SHORT).show()
                                                                       }
                                                                   } else {
                                                                       layers = finalUpdatedLayersList
                                                                       if (layers.isNotEmpty()) {
                                                                           selectedLayerId = layers.last().id
                                                                       } else {
                                                                           selectedLayerId = ""
                                                                       }
                                                                       /* pathCache.clear() */
                                                                       android.widget.Toast.makeText(context, "Subtraction fully consumed the bottom shape", android.widget.Toast.LENGTH_SHORT).show()
                                                                   }
                                                               }
                                                           }
                                                     } catch (e: Exception) {
                                                         e.printStackTrace()
                                                     }
                                                 } else {
                                                     android.widget.Toast.makeText(context, "Drag over overlapping vector shapes to combine or subtract", android.widget.Toast.LENGTH_SHORT).show()
                                                 }
                                             }
                                             shapeBuilderDragPoints.clear()
                                         }
                                         if (dragMode == "freeform_draw" && freeformPenPoints.size >= 2) {
                                             val bezierPoints = convertFreehandToBezier(freeformPenPoints)
                                             if (bezierPoints.isNotEmpty()) {
                                                 val currentSelected = lyrs.find { it.id == selId }
                                                 if (currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                     undoStack.add(layers)
                                                     redoStack.clear()
                                                     layers = layers.map {
                                                         if (it.id == currentSelected.id) {
                                                             it.copy(brushPoints = bezierPoints)
                                                         } else it
                                                     }
                                                     activeBezierPointIndex = 0
                                                     com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                 } else {
                                                     val newL = StudioLayer(
                                                         name = "Freeform Vector Path ${layers.filter { it.type == LayerType.VECTOR_BEZIER }.size + 1}",
                                                         type = LayerType.VECTOR_BEZIER,
                                                         positionX = 0f,
                                                         positionY = 0f,
                                                         width = artboardWidth,
                                                         height = artboardHeight,
                                                         baseColor = brushColor,
                                                         brushPoints = bezierPoints
                                                     )
                                                     undoStack.add(layers)
                                                     redoStack.clear()
                                                     layers = listOf(newL) + layers
                                                     selectedLayerId = newL.id
                                                     activeBezierPointIndex = 0
                                                     com.example.studio.ui.ParametricLayerCache.invalidate(newL.id)
                                                 }
                                             }
                                             freeformPenPoints = emptyList()
                                         }
                                         if (dragMode == "bezier") {
                                             val activeLayer = layers.find { it.id == selId }
                                             if (activeLayer != null && activeLayer.type == LayerType.VECTOR_BEZIER && activeLayer.brushPoints.isNotEmpty()) {
                                                 val updatedPoints = activeLayer.brushPoints
                                                 val minX = updatedPoints.minOfOrNull { it.x } ?: 0f
                                                 val minY = updatedPoints.minOfOrNull { it.y } ?: 0f
                                                 val maxX = updatedPoints.maxOfOrNull { it.x } ?: 0f
                                                 val maxY = updatedPoints.maxOfOrNull { it.y } ?: 0f
                                                 
                                                 if (minX != 0f || minY != 0f || maxX != activeLayer.width || maxY != activeLayer.height) {
                                                     val newPositionX = activeLayer.positionX + minX
                                                     val newPositionY = activeLayer.positionY + minY
                                                     val newWidth = (maxX - minX).coerceAtLeast(10f)
                                                     val newHeight = (maxY - minY).coerceAtLeast(10f)
                                                     
                                                     val oldPivotLocalX = activeLayer.width * activeLayer.pivotX
                                                     val oldPivotLocalY = activeLayer.height * activeLayer.pivotY
                                                     val newPivotX = ((oldPivotLocalX - minX) / newWidth).coerceIn(0f, 1f)
                                                     val newPivotY = ((oldPivotLocalY - minY) / newHeight).coerceIn(0f, 1f)
                                                     
                                                     val shiftedPoints = updatedPoints.map { Offset(it.x - minX, it.y - minY) }
                                                     
                                                     layers = layers.map { layer ->
                                                         if (layer.id == activeLayer.id) {
                                                             layer.copy(
                                                                 positionX = newPositionX,
                                                                 positionY = newPositionY,
                                                                 width = newWidth,
                                                                 height = newHeight,
                                                                 pivotX = newPivotX,
                                                                 pivotY = newPivotY,
                                                                 brushPoints = shiftedPoints
                                                             )
                                                         } else layer
                                                     }
                                                     
                                                     com.example.studio.ui.ParametricLayerCache.invalidate(activeLayer.id)
                                                     /* pathCache.clear() */
                                                 }
                                             }
                                         }
                                        dragMode = null
                                        isDraggingBezierNode = false
                                        if (hasMovedPastSlop) {
                                            if ((tool == "Brush" || tool == "Eraser") && strokeTracker.pointCount > 0) {
                                                val targetId = selectedLayerId
                                                if (targetId.isNotEmpty()) {
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    val strokePointsList = strokeTracker.getPointsList()
                                                    val strokeToCommitHeader = if (tool == "Eraser") {
                                                        buildStrokeHeaderPoints(
                                                            isEraser = true,
                                                            presetIndex = 0,
                                                            size = eraserSize,
                                                            opacity = 1.0f,
                                                            smoothing = true,
                                                            hardness = eraserHardness
                                                        )
                                                    } else {
                                                        buildStrokeHeaderPoints(
                                                            isEraser = false,
                                                            presetIndex = brushPresetIndex,
                                                            size = brushSize,
                                                            opacity = brushOpacity,
                                                            smoothing = brushSmoothing,
                                                            hardness = brushHardness,
                                                            color = brushColor
                                                        )
                                                    }
                                                    layers = layers.map { layer ->
                                                        val isEligible = if (tool == "Eraser") {
                                                            layer.id == targetId
                                                        } else {
                                                            layer.id == targetId && layer.type == LayerType.FREEHAND_DRAWING
                                                        }
                                                        if (isEligible) {
                                                            pathCache.remove(layer.id.hashCode())
                                                            pathCache.remove(layer.id.hashCode() + 1000000)
                                                            val mappedPoints = strokePointsList
                                                            var strokeToCommitWrapped = strokeToCommitHeader + mappedPoints

                                                            val activeRulerForStroke = currentRulersState.value.firstOrNull { it.enabled }
                                                            if (activeRulerForStroke != null && activeRulerForStroke.isSymmetrical && mappedPoints.isNotEmpty()) {
                                                                val symPointsLists = mutableListOf<MutableList<Offset>>()
                                                                for (pt in mappedPoints) {
                                                                    val canvasPt = layerLocalToCanvas(pt, layer)
                                                                    val syms = getSymmetricPoints(
                                                                        px = canvasPt.x + artboardOffsetX,
                                                                        py = canvasPt.y + artboardOffsetY,
                                                                        ruler = activeRulerForStroke,
                                                                        canvasWidth = currentCanvasWidthState.value,
                                                                        canvasHeight = currentCanvasHeightState.value,
                                                                        artboardOffsetX = artboardOffsetX,
                                                                        artboardOffsetY = artboardOffsetY
                                                                    )
                                                                    for (i in syms.indices) {
                                                                        if (i >= symPointsLists.size) {
                                                                            symPointsLists.add(mutableListOf())
                                                                        }
                                                                        val symArtX = (syms[i].x - artboardOffsetX).coerceIn(0f, artboardWidth)
                                                                        val symArtY = (syms[i].y - artboardOffsetY).coerceIn(0f, artboardHeight)
                                                                        val mappedSym = canvasToLayerLocal(Offset(symArtX, symArtY), layer)
                                                                        symPointsLists[i].add(mappedSym)
                                                                    }
                                                                }
                                                                for (symList in symPointsLists) {
                                                                    if (symList.isNotEmpty()) {
                                                                        strokeToCommitWrapped = strokeToCommitWrapped + androidx.compose.ui.geometry.Offset.Unspecified + strokeToCommitHeader + symList
                                                                    }
                                                                }
                                                            }

                                                            val updatedPoints = if (layer.brushPoints.isNotEmpty()) {
                                                                layer.brushPoints + androidx.compose.ui.geometry.Offset.Unspecified + strokeToCommitWrapped
                                                            } else {
                                                                strokeToCommitWrapped
                                                            }
                                                            layer.copy(brushPoints = updatedPoints)
                                                        } else layer
                                                    }
                                                }
                                                strokeTracker.clear()
                                                OpenGLBrushRenderer.WetInkRenderer.clear()
                                                pathCache.remove(999999)
                                                pathCache.remove(1999999)
                                            }
                                        } else {
                                            // Handle Tap Selection
                                            val tapOffset = down.position
                                            val localOffset = screenToCanvas(
                                                screenPos = tapOffset,
                                                viewportWidth = currentViewportWidthState.value,
                                                viewportHeight = currentViewportHeightState.value,
                                                canvasPanX = canvasPanX,
                                                canvasPanY = canvasPanY,
                                                canvasRotation = canvasRotation,
                                                totalScale = ts,
                                                centerX = currentWorkspaceCenterXState.value,
                                                centerY = currentWorkspaceCenterYState.value,
                                                viewportCenterY = visibleViewportCenterY
                                             )
                                             val localX = localOffset.x
                                            val localY = localOffset.y
                                            if (tool == "Pen" && isTouchInActiveArtboard) {
                                                val outerClickPt = Offset((localX - artboardOffsetX).coerceIn(0f, artboardWidth), (localY - artboardOffsetY).coerceIn(0f, artboardHeight))
                                                val outerCurrentSelected = lyrs.find { it.id == selId }
                                                if (penSubTool == "AddAnchor" && outerCurrentSelected != null && outerCurrentSelected.type == LayerType.VECTOR_BEZIER) {
                                                    val clickLocal = canvasToLayerLocal(outerClickPt, outerCurrentSelected)
                                                    val updated = findClosestSegmentAndInsert(clickLocal, outerCurrentSelected)
                                                    if (updated != null) {
                                                         undoStack.add(layers)
                                                         redoStack.clear()
                                                         layers = layers.map {
                                                             if (it.id == outerCurrentSelected.id) {
                                                                 it.copy(brushPoints = updated)
                                                             } else it
                                                         }
                                                         activeBezierPointIndex = updated.size - 3
                                                         com.example.studio.ui.ParametricLayerCache.invalidate(outerCurrentSelected.id)
                                                         /* pathCache.clear() */
                                                    }
                                                } else if (penSubTool == "DeleteAnchor" && outerCurrentSelected != null && outerCurrentSelected.type == LayerType.VECTOR_BEZIER) {
                                                    if (isNearBezier && activeBezierPointIndex % 3 == 0) {
                                                         val k = activeBezierPointIndex / 3
                                                         val updatedPoints = outerCurrentSelected.brushPoints.toMutableList()
                                                         if (k * 3 in updatedPoints.indices) {
                                                             updatedPoints.removeAt(k * 3)
                                                             if (k * 3 in updatedPoints.indices) updatedPoints.removeAt(k * 3)
                                                             if (k * 3 in updatedPoints.indices) updatedPoints.removeAt(k * 3)
                                                             undoStack.add(layers)
                                                             redoStack.clear()
                                                             layers = layers.map {
                                                                 if (it.id == outerCurrentSelected.id) {
                                                                     it.copy(brushPoints = updatedPoints)
                                                                 } else it
                                                             }
                                                             activeBezierPointIndex = if (updatedPoints.isNotEmpty()) {
                                                                 (k * 3).coerceAtMost(updatedPoints.size - 3)
                                                             } else -1
                                                             com.example.studio.ui.ParametricLayerCache.invalidate(outerCurrentSelected.id)
                                                             /* pathCache.clear() */
                                                         }
                                                    }
                                                } else if (penSubTool == "ConvertPoint" && outerCurrentSelected != null && outerCurrentSelected.type == LayerType.VECTOR_BEZIER) {
                                                    if (isNearBezier && activeBezierPointIndex % 3 == 0) {
                                                         val k = activeBezierPointIndex / 3
                                                         val currentTypes = outerCurrentSelected.bezierNodeTypes.toMutableList()
                                                         while (currentTypes.size <= k) {
                                                             currentTypes.add("SMOOTH")
                                                         }
                                                         val oldType = currentTypes[k]
                                                         val newType = if (oldType == "CORNER") "SMOOTH" else "CORNER"
                                                         currentTypes[k] = newType
                                                         undoStack.add(layers)
                                                         redoStack.clear()
                                                         layers = layers.map {
                                                             if (it.id == outerCurrentSelected.id) {
                                                                 it.copy(bezierNodeTypes = currentTypes)
                                                             } else it
                                                         }
                                                         com.example.studio.ui.ParametricLayerCache.invalidate(outerCurrentSelected.id)
                                                         /* pathCache.clear() */
                                                    }
                                                } else {
                                                    if (!isNearBezier) {
                                                        val clickPt = Offset((localX - artboardOffsetX).coerceIn(0f, artboardWidth), (localY - artboardOffsetY).coerceIn(0f, artboardHeight))
                                                        val currentSelected = lyrs.find { it.id == selId }
                                                        if (currentSelected != null && currentSelected.type == LayerType.VECTOR_BEZIER) {
                                                            val clickLocal = canvasToLayerLocal(clickPt, currentSelected)
                                                            val updatedPoints = currentSelected.brushPoints + clickLocal + clickLocal + clickLocal
                                                            undoStack.add(layers)
                                                            redoStack.clear()
                                                            layers = layers.map {
                                                                if (it.id == currentSelected.id) {
                                                                    it.copy(brushPoints = updatedPoints)
                                                                } else it
                                                            }
                                                            activeBezierPointIndex = updatedPoints.size - 3
                                                            com.example.studio.ui.ParametricLayerCache.invalidate(currentSelected.id)
                                                            /* pathCache.clear() */
                                                        } else {
                                                            val newL = StudioLayer(
                                                                name = "Pen Vector Path ${lyrs.filter { it.type == LayerType.VECTOR_BEZIER }.size + 1}",
                                                                type = LayerType.VECTOR_BEZIER,
                                                                positionX = 0f,
                                                                positionY = 0f,
                                                                width = artboardWidth,
                                                                height = artboardHeight,
                                                                baseColor = brushColor,
                                                                brushPoints = listOf(clickPt, clickPt, clickPt)
                                                            )
                                                            undoStack.add(layers)
                                                            redoStack.clear()
                                                            layers = listOf(newL) + layers
                                                            selectedLayerId = newL.id
                                                            selId = newL.id
                                                            activeBezierPointIndex = 0
                                                            com.example.studio.ui.ParametricLayerCache.invalidate(newL.id)
                                                            /* pathCache.clear() */
                                                        }
                                                    }
                                                }
                                             } else {
                                                 var clicked: com.example.studio.model.StudioLayer? = null
                                                 var foundArtId = selectedArtboardId
                                                 for (art in artboards) {
                                                     val artLayers = if (art.id == selectedArtboardId) layers else art.layers
                                                     val found = artLayers.find { layer ->
                                                         layer.isVisible && !layer.isAlphaLocked &&
                                                         layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING &&
                                                         localX >= (art.offsetX + layer.positionX) &&
                                                         localX <= (art.offsetX + layer.positionX + layer.width) &&
                                                         localY >= (art.offsetY + layer.positionY) &&
                                                         localY <= (art.offsetY + layer.positionY + layer.height)
                                                     }
                                                     if (found != null) {
                                                         clicked = found
                                                         foundArtId = art.id
                                                         break
                                                     }
                                                 }
                                                 if (clicked != null) {
                                                     selectArtboardAndLayer(foundArtId, clicked.id)
                                                 } else {
                                                     val clickedArtboard = artboards.find { art ->
                                                         localX >= art.offsetX && localX <= (art.offsetX + art.width) &&
                                                         localY >= art.offsetY && localY <= (art.offsetY + art.height)
                                                     }
                                                     if (clickedArtboard != null) {
                                                         selectArtboard(clickedArtboard.id)
                                                     }
                                                 }
                                             }
                                        }
                                    }
                                }
                            }
                    ) {
                        try {
                            if (pathCache.size() > 1024) {
                                // Smart selective trim: only garbage-collect old path hashes that aren't in current layers
                                val activeHashes = layers.map { getLayerGeometryHash(it) }.toSet()
                                val gridCacheKey = -9999 xor (canvasWidth.toInt() shl 16) xor canvasHeight.toInt()
                                val keysToRemove = mutableListOf<Int>()
                                for (i in 0 until pathCache.size()) {
                                    val key = pathCache.keyAt(i)
                                    if (key != gridCacheKey && key !in activeHashes && key != 999999 && key != 1999999) {
                                        keysToRemove.add(key)
                                    }
                                }
                                for (key in keysToRemove) {
                                    pathCache.remove(key)
                                }
                                if (pathCache.size() > 1024) {
                                    /* pathCache.clear() */
                                }
                            }

                            val totalScale = fitScale * scaleFactor; val ts = totalScale
                            // Non-destructive rendering pipeline passes
                            withTransform({
                                translate(left = currentViewportWidthState.value / 2f + canvasPanX, top = visibleViewportCenterY + canvasPanY)
                                rotate(degrees = canvasRotation, pivot = Offset.Zero)
                                scale(scaleX = ts, scaleY = ts, pivot = Offset.Zero)
                                translate(left = -currentWorkspaceCenterXState.value, top = -currentWorkspaceCenterYState.value)
                            }) {
                                // Loop through all artboards side-by-side
                                artboards.forEachIndexed { artboardIndex, artboard ->
                                    val artboardOffset = artboardPositions[artboardIndex]
                                    val isSelected = artboard.id == selectedArtboardId
                                    val artboardLayers = if (isSelected) layers else artboard.layers
                                    val canvasWidth = artboard.width
                                    val canvasHeight = artboard.height
                                    val layers = artboardLayers

                                    // Draw Artboard Label/Title above the boundaries
                                    withTransform({
                                        translate(left = artboardOffset.x, top = artboardOffset.y)
                                    }) {
                                        val paintText = labelPaint.apply {
                                            color = if (isSelected) android.graphics.Color.WHITE else android.graphics.Color.parseColor("#7E7E9A")
                                            textSize = 14f / ts.coerceAtLeast(0.3f)
                                            isAntiAlias = true
                                            typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.BOLD)
                                        }
                                        val labelText = "${artboard.name} (${artboard.width.toInt()}x${artboard.height.toInt()} px)"
                                        drawContext.canvas.nativeCanvas.drawText(
                                            labelText,
                                            0f,
                                            -16f / ts.coerceAtLeast(0.3f),
                                            paintText
                                        )
                                    }

                                    withTransform({
                                        translate(left = artboardOffset.x, top = artboardOffset.y)
                                        clipRect(left = 0f, top = 0f, right = artboard.width, bottom = artboard.height)
                                    }) {
                                        // 1. Solid backdrop fill for canvas limits
                                        drawRect(
                                            color = Color.White,
                                            topLeft = Offset.Zero,
                                            size = Size(canvasWidth, canvasHeight)
                                        )

                                // 2. Gorgeous, zero-lag, ultra-modern blueprint grid compiled into a single GPU call
                                val gridCacheKey = -9999 xor (canvasWidth.toInt() shl 16) xor canvasHeight.toInt()
                                var gridPath = pathCache.get(gridCacheKey)
                                if (gridPath == null) {
                                    val newPath = Path()
                                    val gridSpacing = 100f
                                    var gy = gridSpacing
                                    while (gy < canvasHeight) {
                                        newPath.moveTo(0f, gy)
                                        newPath.lineTo(canvasWidth, gy)
                                        gy += gridSpacing
                                    }
                                    var gx = gridSpacing
                                    while (gx < canvasWidth) {
                                        newPath.moveTo(gx, 0f)
                                        newPath.lineTo(gx, canvasHeight)
                                        gx += gridSpacing
                                    }
                                    gridPath = newPath
                                    pathCache.put(gridCacheKey, newPath)
                                }
                                drawPath(
                                    path = gridPath,
                                    color = Color(0xFFE5E5EA),
                                    style = Stroke(width = 1f)
                                )

                                // 3. Canvas boundary outline border
                                drawRect(
                                    color = Color(0xFF1E1E24),
                                    topLeft = Offset.Zero,
                                    size = Size(canvasWidth, canvasHeight),
                                    style = Stroke(width = 2.5f)
                                )

                                for (index in layers.indices.reversed()) {
                                    val originalLayer = layers[index]
                                    if (!originalLayer.isVisible) continue
                                    if (isLayerShieldedByAdjustment(layers, index, 0)) continue

                                    val isVisibleOnScreen = com.example.studio.ui.isLayerVisibleInViewport(
                                        layer = originalLayer,
                                        viewportWidth = currentViewportWidthState.value,
                                        viewportHeight = currentViewportHeightState.value,
                                        panX = canvasPanX,
                                        panY = canvasPanY,
                                        scale = ts,
                                        canvasWidth = currentCanvasWidthState.value,
                                        canvasHeight = currentCanvasHeightState.value
                                    )
                                    if (!isVisibleOnScreen) continue
                                    val layerOpacity = originalLayer.opacity
                                    val composeBlendMode = originalLayer.blendMode.toComposeBlendMode()

                                    // Non-destructive shadow copy applying dynamic adjustment color FX
                                    val layer = originalLayer

                                    val beneathLayer = if (index + 1 < layers.size) layers[index + 1] else null

                                                                         drawLayerWithFullPipeline(
                                        layer = layer,
                                        allLayers = layers,
                                        layerOpacity = layerOpacity,
                                        selectedLayerId = selectedLayerId,
                                        pathCache = pathCache,
                                        pathPointsCountCache = pathPointsCountCache,
                                        totalScale = totalScale,
                                        dashEffect = dashEffect8,
                                        imageBitmapCache = imageBitmapCache,
                                        composeBlendMode = composeBlendMode,
                                        sharedTransformMatrix = sharedTransformMatrix,
                                        activeTool = activeTool,
                                        liveDragScaleX = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleX else 1.0f,
                                        liveDragScaleY = if (isResizingActive && layer.id == activeResizingLayerId) liveDragScaleY else 1.0f,
                                        liveDragPivotX = if (isResizingActive && layer.id == activeResizingLayerId) liveDragPivotX else -1f,
                                        liveDragPivotY = if (isResizingActive && layer.id == activeResizingLayerId) liveDragPivotY else -1f,
                                        viewportWidth = currentViewportWidthState.value,
                                        viewportHeight = currentViewportHeightState.value,
                                        panX = canvasPanX,
                                        panY = canvasPanY,
                                        canvasWidth = canvasWidth,
                                        canvasHeight = canvasHeight,
                                        pulseAlpha = pulseAlpha,
                                        spinAngle = spinAngle,
                                        activeBezierPointIndex = activeBezierPointIndex,
                                        activeWarpNodeIndex = activeWarpNodeIndex,
                                        warpRepeatMode = warpRepeatMode,
                                        warpRepeatX = warpRepeatX,
                                        warpRepeatY = warpRepeatY,
                                        warpPhaseX = warpPhaseX,
                                        warpPhaseY = warpPhaseY,
                                        warpInterpolation = warpInterpolation,
                                        warpTarget = warpTarget,
                                        warpMeshDivisionX = warpMeshDivisionX,
                                        warpMeshDivisionY = warpMeshDivisionY,
                                        isDraggingBezierNode = isDraggingBezierNode,
                                        showGradientControls = showGradientControls,
                                        isRasterizing = false,
                                        backdropProvider = {
                                            val computedBackdrop = generateBackdropForLayer(
                                                layers = layers,
                                                currentIndex = layers.indexOfFirst { it.id == layer.id },
                                                canvasWidth = canvasWidth,
                                                canvasHeight = canvasHeight,
                                                imageBitmapCache = imageBitmapCache,
                                                pathCache = pathCache,
                                                pathPointsCountCache = pathPointsCountCache,
                                                existingBitmap = reusableBackdropBitmap,
                                                warpMeshDivisionX = warpMeshDivisionX,
                                                warpMeshDivisionY = warpMeshDivisionY,
                                                warpRepeatMode = warpRepeatMode,
                                                warpRepeatX = warpRepeatX,
                                                warpRepeatY = warpRepeatY,
                                                warpPhaseX = warpPhaseX,
                                                warpPhaseY = warpPhaseY,
                                                warpInterpolation = warpInterpolation,
                                                warpTarget = warpTarget
                                            )
                                            if (computedBackdrop != null) {
                                                reusableBackdropBitmap = computedBackdrop
                                            }
                                            computedBackdrop
                                        }
                                    )

                                }

                                if (gridEnabled) {
                                    val w = canvasWidth
                                    val h = canvasHeight
                                    val cols = gridColumns.coerceIn(1, 200)
                                    val rows = gridRows.coerceIn(1, 200)
                                    val gridColor = Color(0xFF00E5FF).copy(alpha = 0.55f)
                                    val accentGridColor = Color(0xFFFFCC00).copy(alpha = 0.65f)
                                    val strokeW = 1.6f / totalScale.coerceAtLeast(0.5f)

                                    when (activeGridType) {
                                        "Polar", "Polar Grid", "Radial" -> {
                                            val centerX = w * polarGridCenterX.coerceIn(0f, 1f)
                                            val centerY = h * polarGridCenterY.coerceIn(0f, 1f)
                                            val maxRadius = Math.hypot(
                                                Math.max(centerX, w - centerX).toDouble(),
                                                Math.max(centerY, h - centerY).toDouble()
                                            ).toFloat()
                                            val ringCount = rows.coerceIn(2, 60)
                                            val spokeCount = (cols * 2).coerceIn(4, 120)

                                            // 1. Concentric Dividers (Circles)
                                            for (r in 1..ringCount) {
                                                val radius = (maxRadius / ringCount) * r
                                                val isMajorRing = r == ringCount || r % 5 == 0
                                                val ringColor = if (isMajorRing) accentGridColor else gridColor
                                                val ringWidth = if (isMajorRing) strokeW * 1.8f else strokeW
                                                drawCircle(
                                                    color = ringColor,
                                                    center = Offset(centerX, centerY),
                                                    radius = radius,
                                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = ringWidth)
                                                )
                                            }

                                            // 2. Radial Dividers (Spokes/Rays)
                                            val angleStep = (2.0 * Math.PI / spokeCount)
                                            for (s in 0 until spokeCount) {
                                                val angle = angleStep * s
                                                val endX = centerX + Math.cos(angle).toFloat() * maxRadius
                                                val endY = centerY + Math.sin(angle).toFloat() * maxRadius
                                                val isCardinalAxis = (s % (spokeCount / 4.coerceAtLeast(1))) == 0
                                                val spokeColor = if (isCardinalAxis) accentGridColor else gridColor
                                                val spokeWidth = if (isCardinalAxis) strokeW * 1.8f else strokeW
                                                drawLine(
                                                    color = spokeColor,
                                                    start = Offset(centerX, centerY),
                                                    end = Offset(endX, endY),
                                                    strokeWidth = spokeWidth
                                                )
                                            }

                                            // 3. Polar Grid Center Origin Node & Target Indicator
                                            drawCircle(
                                                color = accentGridColor,
                                                center = Offset(centerX, centerY),
                                                radius = 6f / totalScale.coerceAtLeast(0.5f)
                                            )
                                            drawCircle(
                                                color = accentGridColor,
                                                center = Offset(centerX, centerY),
                                                radius = 16f / totalScale.coerceAtLeast(0.5f),
                                                style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW * 1.2f)
                                            )
                                        }
                                        "Isometric" -> {
                                            val stepX = w / cols.coerceAtLeast(2)
                                            for (i in 0..cols) {
                                                val x = i * stepX
                                                drawLine(color = gridColor, start = Offset(x, 0f), end = Offset(x, h), strokeWidth = strokeW)
                                            }
                                            val totalDiagonals = ((w + h * 1.732f) / stepX).toInt().coerceIn(4, 200)
                                            for (k in -totalDiagonals..totalDiagonals) {
                                                val startX = k * stepX
                                                val endX = startX + h * 1.732f
                                                drawLine(color = gridColor.copy(alpha = 0.45f), start = Offset(startX, 0f), end = Offset(endX, h), strokeWidth = strokeW * 0.8f)

                                                val startX2 = k * stepX
                                                val endX2 = startX2 - h * 1.732f
                                                drawLine(color = gridColor.copy(alpha = 0.45f), start = Offset(startX2, 0f), end = Offset(endX2, h), strokeWidth = strokeW * 0.8f)
                                            }
                                        }
                                        "Radial" -> {
                                            val centerX = w / 2f
                                            val centerY = h / 2f
                                            val maxRadius = Math.hypot(w.toDouble(), h.toDouble()).toFloat() / 2f
                                            val ringCount = cols.coerceAtLeast(4)
                                            for (r in 1..ringCount) {
                                                val radius = (maxRadius / ringCount) * r
                                                drawCircle(
                                                    color = gridColor,
                                                    center = Offset(centerX, centerY),
                                                    radius = radius,
                                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW)
                                                )
                                            }
                                            val spokes = 12
                                            for (s in 0 until spokes) {
                                                val angle = (Math.PI * 2 / spokes) * s
                                                val endX = centerX + Math.cos(angle).toFloat() * maxRadius
                                                val endY = centerY + Math.sin(angle).toFloat() * maxRadius
                                                drawLine(color = gridColor, start = Offset(centerX, centerY), end = Offset(endX, endY), strokeWidth = strokeW)
                                            }
                                        }
                                        "Bento" -> {
                                            // Bento layout grid
                                            val phi = 1.61803398875f
                                            val phiX1 = w / phi
                                            val phiX2 = w - phiX1
                                            val phiY1 = h / phi
                                            val phiY2 = h - phiY1

                                            drawLine(color = accentGridColor, start = Offset(phiX1, 0f), end = Offset(phiX1, h), strokeWidth = strokeW * 1.5f)
                                            drawLine(color = accentGridColor, start = Offset(phiX2, 0f), end = Offset(phiX2, h), strokeWidth = strokeW * 1.5f)
                                            drawLine(color = accentGridColor, start = Offset(0f, phiY1), end = Offset(w, phiY1), strokeWidth = strokeW * 1.5f)
                                            drawLine(color = accentGridColor, start = Offset(0f, phiY2), end = Offset(w, phiY2), strokeWidth = strokeW * 1.5f)

                                            // Draw standard sub-divisions
                                            val colWidth = w / cols
                                            val rowHeight = h / rows
                                            for (i in 0..cols) {
                                                val x = i * colWidth
                                                drawLine(color = gridColor, start = Offset(x, 0f), end = Offset(x, h), strokeWidth = strokeW * 0.7f)
                                            }
                                            for (j in 0..rows) {
                                                val y = j * rowHeight
                                                drawLine(color = gridColor, start = Offset(0f, y), end = Offset(w, y), strokeWidth = strokeW * 0.7f)
                                            }
                                        }
                                        "Golden Ratio" -> {
                                            // Golden Ratio Grid: Phi Section Lines, Focal Points, Golden Triangles & Fibonacci Spiral
                                            val phi = 1.61803398875f
                                            val invPhi = 0.61803398875f
                                            val invPhi2 = 0.38196601125f

                                            val phiX1 = w * invPhi2
                                            val phiX2 = w * invPhi
                                            val phiY1 = h * invPhi2
                                            val phiY2 = h * invPhi

                                            val goldenColor = Color(0xFFFFC107).copy(alpha = 0.85f)
                                            val phiSubColor = Color(0xFF00E5FF).copy(alpha = 0.45f)
                                            val spiralColor = Color(0xFFFF5722).copy(alpha = 0.95f)

                                            // Primary Phi Section Lines
                                            drawLine(color = goldenColor, start = Offset(phiX1, 0f), end = Offset(phiX1, h), strokeWidth = strokeW * 2f)
                                            drawLine(color = goldenColor, start = Offset(phiX2, 0f), end = Offset(phiX2, h), strokeWidth = strokeW * 2f)
                                            drawLine(color = goldenColor, start = Offset(0f, phiY1), end = Offset(w, phiY1), strokeWidth = strokeW * 2f)
                                            drawLine(color = goldenColor, start = Offset(0f, phiY2), end = Offset(w, phiY2), strokeWidth = strokeW * 2f)

                                            // Focal Points Intersections with adaptive target indicators
                                            val focalRadius = 5f / totalScale.coerceAtLeast(0.5f)
                                            val focalRingRadius = 12f / totalScale.coerceAtLeast(0.5f)
                                            val focalPoints = listOf(
                                                Offset(phiX1, phiY1),
                                                Offset(phiX2, phiY1),
                                                Offset(phiX1, phiY2),
                                                Offset(phiX2, phiY2)
                                            )
                                            for (fp in focalPoints) {
                                                drawCircle(color = goldenColor, center = fp, radius = focalRadius)
                                                drawCircle(color = goldenColor, center = fp, radius = focalRingRadius, style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW * 0.8f))
                                            }

                                            // Secondary Phi Subdivisions (Sub-golden ratios)
                                            val phiX0 = w * (invPhi2 * invPhi2)
                                            val phiX3 = w * (1f - invPhi2 * invPhi2)
                                            val phiY0 = h * (invPhi2 * invPhi2)
                                            val phiY3 = h * (1f - invPhi2 * invPhi2)

                                            drawLine(color = phiSubColor, start = Offset(phiX0, 0f), end = Offset(phiX0, h), strokeWidth = strokeW * 0.8f)
                                            drawLine(color = phiSubColor, start = Offset(phiX3, 0f), end = Offset(phiX3, h), strokeWidth = strokeW * 0.8f)
                                            drawLine(color = phiSubColor, start = Offset(0f, phiY0), end = Offset(w, phiY0), strokeWidth = strokeW * 0.8f)
                                            drawLine(color = phiSubColor, start = Offset(0f, phiY3), end = Offset(w, phiY3), strokeWidth = strokeW * 0.8f)

                                            // Golden Triangles (Diagonals adapting to canvas aspect ratio)
                                            drawLine(color = goldenColor.copy(alpha = 0.5f), start = Offset(0f, h), end = Offset(w, 0f), strokeWidth = strokeW * 1.2f)
                                            val angle = Math.atan2(h.toDouble(), w.toDouble())
                                            val p1X = (h * Math.sin(angle) * Math.cos(angle)).toFloat()
                                            val p1Y = h - (h * Math.sin(angle) * Math.sin(angle)).toFloat()
                                            drawLine(color = goldenColor.copy(alpha = 0.5f), start = Offset(0f, 0f), end = Offset(p1X, p1Y), strokeWidth = strokeW * 1.2f)

                                            val p2X = w - (h * Math.sin(angle) * Math.cos(angle)).toFloat()
                                            val p2Y = (h * Math.sin(angle) * Math.sin(angle)).toFloat()
                                            drawLine(color = goldenColor.copy(alpha = 0.5f), start = Offset(w, h), end = Offset(p2X, p2Y), strokeWidth = strokeW * 1.2f)

                                            // Golden Ratio Increasing Squares Grid (Fibonacci Section Squares)
                                            val squareBorderColor = Color(0xFFFFD54F).copy(alpha = 0.85f)
                                            var l = 0f
                                            var t = 0f
                                            var r = w
                                            var b = h
                                            var orientation = if (w >= h) 0 else 1

                                            for (step in 0 until 12) {
                                                val currW = r - l
                                                val currH = b - t
                                                if (currW < 2f || currH < 2f) break

                                                when (orientation % 4) {
                                                    0 -> {
                                                        val s = currH.coerceAtMost(currW)
                                                        val cutR = l + s
                                                        drawRect(
                                                            color = squareBorderColor,
                                                            topLeft = Offset(l, t),
                                                            size = androidx.compose.ui.geometry.Size(s, s),
                                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW * 1.5f)
                                                        )
                                                        drawLine(color = phiSubColor, start = Offset(cutR, t), end = Offset(cutR, b), strokeWidth = strokeW * 1.2f)
                                                        l = cutR
                                                    }
                                                    1 -> {
                                                        val s = currW.coerceAtMost(currH)
                                                        val cutB = t + s
                                                        drawRect(
                                                            color = squareBorderColor,
                                                            topLeft = Offset(r - s, t),
                                                            size = androidx.compose.ui.geometry.Size(s, s),
                                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW * 1.5f)
                                                        )
                                                        drawLine(color = phiSubColor, start = Offset(l, cutB), end = Offset(r, cutB), strokeWidth = strokeW * 1.2f)
                                                        t = cutB
                                                    }
                                                    2 -> {
                                                        val s = currH.coerceAtMost(currW)
                                                        val cutL = r - s
                                                        drawRect(
                                                            color = squareBorderColor,
                                                            topLeft = Offset(cutL, b - s),
                                                            size = androidx.compose.ui.geometry.Size(s, s),
                                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW * 1.5f)
                                                        )
                                                        drawLine(color = phiSubColor, start = Offset(cutL, t), end = Offset(cutL, b), strokeWidth = strokeW * 1.2f)
                                                        r = cutL
                                                    }
                                                    3 -> {
                                                        val s = currW.coerceAtMost(currH)
                                                        val cutT = b - s
                                                        drawRect(
                                                            color = squareBorderColor,
                                                            topLeft = Offset(l, cutT),
                                                            size = androidx.compose.ui.geometry.Size(s, s),
                                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW * 1.5f)
                                                        )
                                                        drawLine(color = phiSubColor, start = Offset(l, cutT), end = Offset(r, cutT), strokeWidth = strokeW * 1.2f)
                                                        b = cutT
                                                    }
                                                }
                                                orientation++
                                            }
                                        }
                                        else -> {
                                            // Standard Modular / Column grid layout
                                            val colWidth = w / cols
                                            val rowHeight = h / rows
                                            for (i in 0..cols) {
                                                val x = i * colWidth
                                                drawLine(color = gridColor, start = Offset(x, 0f), end = Offset(x, h), strokeWidth = strokeW)
                                            }
                                            for (j in 0..rows) {
                                                val y = j * rowHeight
                                                drawLine(color = gridColor, start = Offset(0f, y), end = Offset(w, y), strokeWidth = strokeW)
                                            }
                                        }
                                    }
                                }



                                // Listen to the high-frequency trigger without recomposing the whole UI
                                val _strokeTrigger = strokeDrawTrigger.value

                                if (isSelected && OpenGLBrushRenderer.WetInkRenderer.isInitialized()) {
                                    val isFreehandSelected = layers.any { it.id == selectedLayerId && it.type == com.example.studio.model.LayerType.FREEHAND_DRAWING }
                                    if (!isFreehandSelected && activeTool != "Eraser") {
                                        OpenGLBrushRenderer.WetInkRenderer.getWetInkBitmap()?.let { b ->
                                            drawImage(
                                                image = b.asImageBitmap(),
                                                topLeft = Offset.Zero,
                                                blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
                                            )
                                        }
                                    }
                                }

                                // Draw Electric Cyan Snapping / Alignment Guide Lines
                                if (isSelected) {
                                    snapVerticalLine?.let { snapX ->
                                        // Styled vertical line and inline badge
                                        drawLine(
                                            color = Color(0xFF00E5FF),
                                            start = Offset(snapX, 0f),
                                            end = Offset(snapX, canvasHeight),
                                            strokeWidth = 3f / ts.coerceAtLeast(0.5f)
                                        )
                                        
                                        val textPaint = android.graphics.Paint().apply {
                                            color = android.graphics.Color.WHITE
                                            textSize = 13f / ts.coerceAtLeast(0.3f)
                                            typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.BOLD)
                                            isAntiAlias = true
                                        }
                                        
                                        val bgPaint = android.graphics.Paint().apply {
                                            color = android.graphics.Color.parseColor("#161F32")
                                            style = android.graphics.Paint.Style.FILL
                                            isAntiAlias = true
                                        }
                                        
                                        val borderPaint = android.graphics.Paint().apply {
                                            color = android.graphics.Color.parseColor("#00E5FF")
                                            style = android.graphics.Paint.Style.STROKE
                                            strokeWidth = 1.5f / ts.coerceAtLeast(0.5f)
                                            isAntiAlias = true
                                        }
                                    
                                    val text = snapIndicatorMsg ?: "Snapped"
                                    val textWidth = textPaint.measureText(text)
                                    val textHeight = textPaint.fontMetrics.descent - textPaint.fontMetrics.ascent
                                     
                                    val paddingX = 14f / ts.coerceAtLeast(0.5f)
                                    val paddingY = 7f / ts.coerceAtLeast(0.5f)
                                     
                                    val badgeWidth = textWidth + paddingX * 2
                                    val badgeHeight = textHeight + paddingY * 2
                                     
                                    val badgeX = snapX - badgeWidth / 2f
                                    val badgeY = (canvasHeight * 0.15f) - badgeHeight / 2f
                                    val safeBadgeX = badgeX.coerceIn(0f, canvasWidth - badgeWidth)
                                     
                                    val rectF = android.graphics.RectF(safeBadgeX, badgeY, safeBadgeX + badgeWidth, badgeY + badgeHeight)
                                    val rx = 6f / ts.coerceAtLeast(0.5f)
                                    drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, bgPaint)
                                    drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, borderPaint)
                                     
                                    val textX = safeBadgeX + paddingX
                                    val textY = badgeY + paddingY - textPaint.fontMetrics.ascent
                                    drawContext.canvas.nativeCanvas.drawText(text, textX, textY, textPaint)
                                }
                                snapHorizontalLine?.let { snapY ->
                                    drawLine(
                                        color = Color(0xFF00E5FF),
                                        start = Offset(0f, snapY),
                                        end = Offset(canvasWidth, snapY),
                                        strokeWidth = 3f / ts.coerceAtLeast(0.5f)
                                    )
                                    
                                    if (snapVerticalLine == null) {
                                         val textPaint = android.graphics.Paint().apply {
                                             color = android.graphics.Color.WHITE
                                             textSize = 13f / ts.coerceAtLeast(0.3f)
                                             typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.BOLD)
                                             isAntiAlias = true
                                         }
                                         
                                         val bgPaint = android.graphics.Paint().apply {
                                             color = android.graphics.Color.parseColor("#161F32")
                                             style = android.graphics.Paint.Style.FILL
                                             isAntiAlias = true
                                         }
                                         
                                         val borderPaint = android.graphics.Paint().apply {
                                             color = android.graphics.Color.parseColor("#00E5FF")
                                             style = android.graphics.Paint.Style.STROKE
                                             strokeWidth = 1.5f / ts.coerceAtLeast(0.5f)
                                             isAntiAlias = true
                                         }
                                         
                                         val text = snapIndicatorMsg ?: "Snapped"
                                         val textWidth = textPaint.measureText(text)
                                         val textHeight = textPaint.fontMetrics.descent - textPaint.fontMetrics.ascent
                                         
                                         val paddingX = 14f / ts.coerceAtLeast(0.5f)
                                         val paddingY = 7f / ts.coerceAtLeast(0.5f)
                                         
                                         val badgeWidth = textWidth + paddingX * 2
                                         val badgeHeight = textHeight + paddingY * 2
                                         
                                         val badgeX = (canvasWidth * 0.15f) - badgeWidth / 2f
                                         val badgeY = snapY - badgeHeight / 2f
                                         val safeBadgeY = badgeY.coerceIn(0f, canvasHeight - badgeHeight)
                                         
                                         val rectF = android.graphics.RectF(badgeX.coerceAtLeast(0f), safeBadgeY, badgeX.coerceAtLeast(0f) + badgeWidth, safeBadgeY + badgeHeight)
                                         val rx = 6f / ts.coerceAtLeast(0.5f)
                                         drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, bgPaint)
                                         drawContext.canvas.nativeCanvas.drawRoundRect(rectF, rx, rx, borderPaint)
                                         
                                         val textX = badgeX.coerceAtLeast(0f) + paddingX
                                         val textY = safeBadgeY + paddingY - textPaint.fontMetrics.ascent
                                         drawContext.canvas.nativeCanvas.drawText(text, textX, textY, textPaint)
                                    }
                                } // End of snapHorizontalLine?.let call

                                // Draw Freeform Pen Drawing Preview Path
                                if (activeTool == "Pen" && penSubTool == "Freeform" && selectedArtboardId == artboard.id && freeformPenPoints.size >= 2) {
                                    val ts = totalScale.coerceAtLeast(0.5f)
                                    val freeformPath = androidx.compose.ui.graphics.Path().apply {
                                        val start = freeformPenPoints.first()
                                        moveTo(start.x, start.y)
                                        for (i in 1 until freeformPenPoints.size) {
                                            val pt = freeformPenPoints[i]
                                            lineTo(pt.x, pt.y)
                                        }
                                    }
                                    drawPath(
                                        path = freeformPath,
                                        color = brushColor.copy(alpha = 0.85f),
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                            width = 4.5f / ts,
                                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                                        )
                                    )
                                    drawPath(
                                        path = freeformPath,
                                        color = brushColor.copy(alpha = 0.3f),
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                            width = 12f / ts,
                                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                                        )
                                    )
                                }

                                // Draw Shape Builder Swipe Preview Path
                                if (activeTool == "Shape Builder" && selectedArtboardId == artboard.id && shapeBuilderDragPoints.size >= 2) {
                                    val ts = totalScale.coerceAtLeast(0.5f)
                                    val swipePath = androidx.compose.ui.graphics.Path().apply {
                                        val start = shapeBuilderDragPoints.first()
                                        moveTo(start.x, start.y)
                                        for (i in 1 until shapeBuilderDragPoints.size) {
                                            val pt = shapeBuilderDragPoints[i]
                                            lineTo(pt.x, pt.y)
                                        }
                                    }
                                    drawPath(
                                        path = swipePath,
                                        color = androidx.compose.ui.graphics.Color(0xFF00E5FF),
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                            width = 6f / ts,
                                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                                        )
                                    )
                                    drawPath(
                                        path = swipePath,
                                        color = androidx.compose.ui.graphics.Color(0xFF00E5FF).copy(alpha = 0.3f),
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                            width = 16f / ts,
                                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                                        )
                                    )
                                }

                                // Draw Eyedropper Live Magnifier Cursor
                                if (GradientEyedropperState.isActive) {
                                    GradientEyedropperState.touchPoint?.let { cursor ->
                                        val ts = totalScale.coerceAtLeast(0.5f)
                                        val artboardOffsetX = artboard.offsetX
                                        val artboardOffsetY = artboard.offsetY
                                        
                                        // Sample live color for the cursor preview
                                        val artRelativeX = cursor.x - artboardOffsetX
                                        val artRelativeY = cursor.y - artboardOffsetY
                                        val liveSampledColor = sampleCompositedColor(
                                            layers = layers,
                                            artRelativeX = artRelativeX,
                                            artRelativeY = artRelativeY,
                                            artboardWidth = artboard.width,
                                            artboardHeight = artboard.height,
                                            imageBitmapCache = imageBitmapCache
                                        )

                                        // 1. Draw outer glowing/shadow circle
                                        drawCircle(
                                            color = Color.Black.copy(alpha = 0.4f),
                                            radius = 28f / ts,
                                            center = cursor,
                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 6f / ts)
                                        )
                                        
                                        // 2. Draw white container border
                                        drawCircle(
                                            color = Color.White,
                                            radius = 26f / ts,
                                            center = cursor,
                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 4f / ts)
                                        )
                                        
                                        // 3. Fill the center with the live-sampled color
                                        drawCircle(
                                            color = liveSampledColor,
                                            radius = 22f / ts,
                                            center = cursor
                                         )
                                         
                                         // 4. Draw high-contrast reticle
                                         val crosshairLength = 8f / ts
                                         val reticleColor = if (liveSampledColor.red * 0.299f + liveSampledColor.green * 0.587f + liveSampledColor.blue * 0.114f > 0.5f) {
                                             Color.Black
                                         } else {
                                             Color.White
                                         }
                                         
                                         drawLine(
                                             color = reticleColor,
                                             start = Offset(cursor.x - crosshairLength, cursor.y),
                                             end = Offset(cursor.x + crosshairLength, cursor.y),
                                             strokeWidth = 2f / ts
                                         )
                                         drawLine(
                                             color = reticleColor,
                                             start = Offset(cursor.x, cursor.y - crosshairLength),
                                             end = Offset(cursor.x, cursor.y + crosshairLength),
                                             strokeWidth = 2f / ts
                                         )
                                     }
                                 }

                                // Draw Virtual Pen Cursor Reticle
                                if (activeTool == "Pen") {
                                    penCursorOffset?.let { cursor ->
                                        val ts = totalScale.coerceAtLeast(0.5f)
                                        val reticleColor = androidx.compose.ui.graphics.Color(0xFFFFB300) // IndustrialAmber
                                        
                                        // 1. Crosshair lines extending from center
                                        val crosshairLength = 35f / ts
                                        val crosshairWidth = 1.8f / ts
                                        
                                        // Horizontal
                                        drawLine(
                                            color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.8f),
                                            start = androidx.compose.ui.geometry.Offset(cursor.x - crosshairLength, cursor.y),
                                            end = androidx.compose.ui.geometry.Offset(cursor.x + crosshairLength, cursor.y),
                                            strokeWidth = crosshairWidth
                                        )
                                        drawLine(
                                            color = reticleColor,
                                            start = androidx.compose.ui.geometry.Offset(cursor.x - crosshairLength * 0.6f, cursor.y),
                                            end = androidx.compose.ui.geometry.Offset(cursor.x + crosshairLength * 0.6f, cursor.y),
                                            strokeWidth = crosshairWidth
                                        )
                                        
                                        // Vertical
                                        drawLine(
                                            color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.8f),
                                            start = androidx.compose.ui.geometry.Offset(cursor.x, cursor.y - crosshairLength),
                                            end = androidx.compose.ui.geometry.Offset(cursor.x, cursor.y + crosshairLength),
                                            strokeWidth = crosshairWidth
                                        )
                                        drawLine(
                                            color = reticleColor,
                                            start = androidx.compose.ui.geometry.Offset(cursor.x, cursor.y - crosshairLength * 0.6f),
                                            end = androidx.compose.ui.geometry.Offset(cursor.x, cursor.y + crosshairLength * 0.6f),
                                            strokeWidth = crosshairWidth
                                        )

                                        // 2. High contrast outer circle
                                        drawCircle(
                                            color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.7f),
                                            radius = 16f / ts,
                                            center = cursor,
                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 3f / ts)
                                        )
                                        drawCircle(
                                            color = reticleColor,
                                            radius = 16f / ts,
                                            center = cursor,
                                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f / ts)
                                        )

                                        // 3. Center indicator point
                                        drawCircle(
                                            color = androidx.compose.ui.graphics.Color.White,
                                            radius = 4f / ts,
                                            center = cursor
                                        )
                                        drawCircle(
                                            color = androidx.compose.ui.graphics.Color(0xFFFF1744), // Vibrant Red center dot
                                            radius = 2f / ts,
                                            center = cursor
                                        )
                                    }
                                }
                                } // End of isSelected check
                                    } // End of inner artboard withTransform
                                } // End of artboards.forEachIndexed loop
                            } // End of viewport withTransform

                            if (coordinateRulersSetting) {
                                val pointer = lastPointerPosition
                                if (pointer != null) {
                                    // Draw horizontal coordinate line across viewport
                                    drawLine(
                                        color = Color(0x6000FF66), // Subtle translucent neon green
                                        start = androidx.compose.ui.geometry.Offset(0f, pointer.y),
                                        end = androidx.compose.ui.geometry.Offset(size.width, pointer.y),
                                        strokeWidth = 1.dp.toPx()
                                    )
                                    // Draw vertical coordinate line down viewport
                                    drawLine(
                                        color = Color(0x6000FF66),
                                        start = androidx.compose.ui.geometry.Offset(pointer.x, 0f),
                                        end = androidx.compose.ui.geometry.Offset(pointer.x, size.height),
                                        strokeWidth = 1.dp.toPx()
                                    )
                                    
                                    // Calculate active artboard-relative coordinate
                                    val localOffset = screenToCanvas(
                                        screenPos = pointer,
                                        viewportWidth = currentViewportWidthState.value,
                                        viewportHeight = currentViewportHeightState.value,
                                        canvasPanX = canvasPanX,
                                        canvasPanY = canvasPanY,
                                        canvasRotation = canvasRotation,
                                        totalScale = ts,
                                        centerX = currentWorkspaceCenterXState.value,
                                        centerY = currentWorkspaceCenterYState.value,
                                        viewportCenterY = visibleViewportCenterY
                                    )
                                    
                                    // Draw coordinate label near crosshair intersection
                                    val textX = (pointer.x + 12f).coerceAtMost(size.width - 150f)
                                    val textY = (pointer.y - 12f).coerceAtLeast(30f)
                                    
                                    drawIntoCanvas { composeCanvas ->
                                        val paintText = labelPaint.apply {
                                            color = android.graphics.Color.parseColor("#00FF66")
                                            textSize = 10.dp.toPx()
                                            typeface = android.graphics.Typeface.create(android.graphics.Typeface.MONOSPACE, android.graphics.Typeface.BOLD)
                                        }
                                        composeCanvas.nativeCanvas.drawText(
                                            "X: ${localOffset.x.toInt()} Y: ${localOffset.y.toInt()}",
                                            textX,
                                            textY,
                                            paintText
                                        )
                                    }
                                }
                            }
                        } catch (e: Exception) {
                            // Fail-safe compilation error handler
                        }
                    }

                    // Live, independent high-performance guides rendering overlay
                    val currentRulersVal = rulers
                    val currentSelectedRulerIdVal = selectedRulerId
                    val currentRulerEnabledVal = activeTool == "Ruler" || activeFullScreenSheet == "Ruler" || rulers.any { it.enabled }

                    if (currentRulerEnabledVal) {
                        Canvas(
                            modifier = Modifier
                                .fillMaxSize()
                        ) {
                            val w = canvasWidth
                            val h = canvasHeight
                            val totalScale = fitScale * scaleFactor; val ts = totalScale

                            val activeArtboard = artboards.find { it.id == selectedArtboardId }
                            val artboardOffsetX = activeArtboard?.offsetX ?: 0f
                            val artboardOffsetY = activeArtboard?.offsetY ?: 0f
                            val activeW = activeArtboard?.width ?: w
                            val activeH = activeArtboard?.height ?: h

                            withTransform({
                                translate(left = currentViewportWidthState.value / 2f + canvasPanX, top = visibleViewportCenterY + canvasPanY)
                                rotate(degrees = canvasRotation, pivot = Offset.Zero)
                                scale(scaleX = ts, scaleY = ts, pivot = Offset.Zero)
                                translate(left = -currentWorkspaceCenterXState.value, top = -currentWorkspaceCenterYState.value)
                            }) {
                                currentRulersVal.forEach { ruler ->
                                    if (!ruler.enabled && !((activeTool == "Ruler" || activeFullScreenSheet == "Ruler") && ruler.id == currentSelectedRulerIdVal)) return@forEach

                                    val isSelected = ruler.id == currentSelectedRulerIdVal

                                    // Check if this particular ruler is snapped right now
                                    val isSnappedX = snapVerticalLine != null && ruler.orientation == "Vertical" && Math.abs(ruler.position - (snapVerticalLine ?: -999f)) < 1f
                                    val isSnappedY = snapHorizontalLine != null && ruler.orientation == "Horizontal" && Math.abs(ruler.position - (snapHorizontalLine ?: -999f)) < 1f

                                    val baseRulerColor = Color(ruler.color)
                                    val rulerColor = when {
                                        isSnappedX || isSnappedY -> Color(0xFFFF1744) // Snapped highlight
                                        isSelected -> baseRulerColor
                                        else -> baseRulerColor.copy(alpha = 0.75f)
                                    }

                                    val strokeW = (if (isSelected || isSnappedX || isSnappedY) 3.2f else 2.0f) / ts.coerceAtLeast(0.5f)

                                    withTransform({
                                        translate(left = artboardOffsetX, top = artboardOffsetY)
                                    }) {
                                        if (ruler.orientation == "Horizontal") {
                                            withTransform({
                                                rotate(degrees = ruler.angle, pivot = Offset(activeW / 2f, ruler.position))
                                            }) {
                                                drawLine(
                                                    color = rulerColor,
                                                    start = Offset(-1000000f, ruler.position),
                                                    end = Offset(1000000f, ruler.position),
                                                    strokeWidth = strokeW
                                                )
                                            }
                                        } else {
                                            withTransform({
                                                rotate(degrees = ruler.angle, pivot = Offset(ruler.position, activeH / 2f))
                                            }) {
                                                drawLine(
                                                    color = rulerColor,
                                                    start = Offset(ruler.position, -1000000f),
                                                    end = Offset(ruler.position, 1000000f),
                                                    strokeWidth = strokeW
                                                )
                                            }
                                        }

                                        // Render Symmetrical Axis Guidelines when symmetry is enabled
                                        if (ruler.isSymmetrical) {
                                            val symColor = Color(0xFF00E5FF).copy(alpha = 0.85f)
                                            val symDashW = 1.8f / ts.coerceAtLeast(0.5f)
                                            val pivotPt = if (ruler.orientation == "Horizontal") Offset(activeW / 2f, ruler.position) else Offset(ruler.position, activeH / 2f)
                                            
                                            withTransform({
                                                rotate(degrees = ruler.angle, pivot = pivotPt)
                                            }) {
                                                // Perpendicular Symmetry Axis
                                                drawLine(
                                                    color = symColor,
                                                    start = if (ruler.orientation == "Horizontal") Offset(pivotPt.x, -1000000f) else Offset(-1000000f, pivotPt.y),
                                                    end = if (ruler.orientation == "Horizontal") Offset(pivotPt.x, 1000000f) else Offset(1000000f, pivotPt.y),
                                                    strokeWidth = symDashW,
                                                    pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f / ts, 6f / ts))
                                                )

                                                if (ruler.symmetryMode == "4-Way" || ruler.symmetryMode == "8-Way") {
                                                    // 4-Way Secondary Diagonal Axis
                                                    drawLine(
                                                        color = Color(0xFFFFD700).copy(alpha = 0.85f),
                                                        start = Offset(pivotPt.x - 1000000f, pivotPt.y - 1000000f),
                                                        end = Offset(pivotPt.x + 1000000f, pivotPt.y + 1000000f),
                                                        strokeWidth = symDashW,
                                                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(8f / ts, 4f / ts))
                                                    )
                                                    drawLine(
                                                        color = Color(0xFFFFD700).copy(alpha = 0.85f),
                                                        start = Offset(pivotPt.x - 1000000f, pivotPt.y + 1000000f),
                                                        end = Offset(pivotPt.x + 1000000f, pivotPt.y - 1000000f),
                                                        strokeWidth = symDashW,
                                                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(8f / ts, 4f / ts))
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

