                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Button(
                                onClick = { isBottomPanelVisible = true },
                                colors = ButtonDefaults.buttonColors(containerColor = MidSlate),
                                shape = RoundedCornerShape(24.dp),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp),
                                modifier = Modifier.height(38.dp)
                            ) {
                                Icon(Icons.Default.Tune, "Show parameters", tint = TextPrimary, modifier = Modifier.size(16.dp))
                                Spacer(Modifier.width(4.dp))
                                Text("PARAMETERS", style = Typography.labelSmall.copy(fontSize = 10.sp), color = TextPrimary, fontWeight = FontWeight.Bold)
                            }
                        }
                    }

                    // Elegant Snapping Indicator Badge Overlay
                    snapIndicatorMsg?.let { msg ->
                        Box(
                            modifier = Modifier
                                .align(Alignment.TopCenter)
                                .padding(top = 76.dp, start = 12.dp, end = 12.dp, bottom = 12.dp)
                                .background(Color(0xFFCC0000).copy(alpha = 0.9f), RoundedCornerShape(8.dp))
                                .border(1.2.dp, Color.Red, RoundedCornerShape(8.dp))
                                .padding(horizontal = 14.dp, vertical = 8.dp)
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.GridOn,
                                    contentDescription = "Snapping Indicator",
                                    tint = Color.White,
                                    modifier = Modifier.size(16.dp)
                                )
                                Text(
                                    text = msg,
                                    style = Typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                                    color = Color.White
                                )
                            }
                        }
                    }

                    // Compact Floating Layer Manager Panel
                    val layerDrawerAlignment = if (toolPanelSide == "Right") Alignment.TopStart else Alignment.TopEnd
                    val layerDrawerStartPadding = if (toolPanelSide == "Right") 8.dp else 0.dp
                    val layerDrawerEndPadding = if (toolPanelSide == "Right") 0.dp else layersEndPadding

                    androidx.compose.animation.AnimatedVisibility(
                        visible = isLayersPanelVisible,
                        enter = if (toolPanelSide == "Right") slideInHorizontally(initialOffsetX = { -it }) + fadeIn() else slideInHorizontally(initialOffsetX = { it }) + fadeIn(),
                        exit = if (toolPanelSide == "Right") slideOutHorizontally(targetOffsetX = { -it }) + fadeOut() else slideOutHorizontally(targetOffsetX = { it }) + fadeOut(),
                        modifier = Modifier
                            .align(layerDrawerAlignment)
                            .padding(top = if (controlBarPosition == "Top") 54.dp else 12.dp, start = layerDrawerStartPadding, end = layerDrawerEndPadding)
                            .zIndex(12f)
                    ) {
                        RightsideLayerDrawer(
                            layers = layers,
                            selectedLayerId = selectedLayerId,
                            onSelectLayer = { selectedLayerId = it },
                            onChangeVisibility = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(isVisible = !it.isVisible) else it }
                            },
                            onChangeAlphaLock = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(isAlphaLocked = !it.isAlphaLocked) else it }
                            },
                            onChangeClippingMask = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(isClippingMask = !it.isClippingMask) else it }
                            },
                            onLayerMove = { fromIndex, toIndex ->
                                val targetLayer = layers.getOrNull(fromIndex)
                                val isEmptyLayer = targetLayer != null && targetLayer.type == com.example.studio.model.LayerType.FREEHAND_DRAWING && targetLayer.brushPoints.isEmpty()
                                if (fromIndex in layers.indices && toIndex in layers.indices && fromIndex != toIndex && !isEmptyLayer) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val list = layers.toMutableList()
                                    val removed = list.removeAt(fromIndex)
                                    list.add(toIndex, removed)
                                    layers = list
                                }
                            },
                            onLayerReorderUp = { index ->
                                val targetLayer = layers.getOrNull(index)
                                val isEmptyLayer = targetLayer != null && targetLayer.type == com.example.studio.model.LayerType.FREEHAND_DRAWING && targetLayer.brushPoints.isEmpty()
                                if (index > 0 && !isEmptyLayer) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val list = layers.toMutableList()
                                    val removed = list.removeAt(index)
                                    list.add(index - 1, removed)
                                    layers = list
                                }
                            },
                            onLayerReorderDown = { index ->
                                val targetLayer = layers.getOrNull(index)
                                val isEmptyLayer = targetLayer != null && targetLayer.type == com.example.studio.model.LayerType.FREEHAND_DRAWING && targetLayer.brushPoints.isEmpty()
                                if (index < layers.size - 1 && !isEmptyLayer) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val list = layers.toMutableList()
                                    val removed = list.removeAt(index)
                                    list.add(index + 1, removed)
                                    layers = list
                                }
                            },
                            onAddLayer = {
                                undoStack.add(layers)
                                redoStack.clear()
                                val newL = StudioLayer(
                                    name = "Empty Layer ${layers.size + 1}",
                                    type = LayerType.FREEHAND_DRAWING,
                                    positionX = 0f,
                                    positionY = 0f,
                                    width = canvasWidth,
                                    height = canvasHeight,
                                    baseColor = Color.Transparent,
                                    effects = listOf(
                                        PhotoshopEffectTemplates.create(effectType = "BrushConfig").let { eff ->
                                            var updated = eff.updateParameter("Size", brushSize)
                                            updated = updated.updateParameter("Opacity", brushOpacity)
                                            updated = updated.updateParameter("Smoothing", if (brushSmoothing) 1.0f else 0.0f)
                                            updated = updated.updateParameter("Preset", brushPresetIndex.toFloat())
                                            updated
                                        }
                                    ),
                                    brushPoints = emptyList()
                                )
                                val updated = listOf(newL) + layers
                                layers = updated
                                selectedLayerId = newL.id
                                artboards = artboards.map { if (it.id == selectedArtboardId) it.copy(layers = updated) else it }
                            },
                            onRasterizeLayer = { id ->
                                val orig = layers.find { it.id == id }
                                if (orig != null) {
                                    scope.launch {
                                        try {
                                            fun getDescendants(parentId: String): List<com.example.studio.model.StudioLayer> {
                                                val direct = layers.filter { it.parentGroupId == parentId }
                                                return direct + direct.flatMap { if (it.type == com.example.studio.model.LayerType.GROUP) getDescendants(it.id) else emptyList() }
                                            }
                                            
                                            val isGroup = orig.type == com.example.studio.model.LayerType.GROUP
                                            val descendants = if (isGroup) getDescendants(orig.id) else emptyList()
                                            
                                            val layersToRasterize = if (isGroup) {
                                                val descendantIds = descendants.map { it.id }.toSet()
                                                layers.filter { it.id in descendantIds }.reversed()
                                            } else {
                                                listOf(orig)
                                            }
                                            
                                            if (layersToRasterize.isEmpty() && isGroup) return@launch
                                            
                                            var minX = Float.MAX_VALUE
                                            var minY = Float.MAX_VALUE
                                            var maxX = -Float.MAX_VALUE
                                            var maxY = -Float.MAX_VALUE
                                            var maxPadding = 0f
                                            
                                            if (isGroup) {
                                                layersToRasterize.forEach { l ->
                                                    minX = kotlin.math.min(minX, l.positionX)
                                                    minY = kotlin.math.min(minY, l.positionY)
                                                    maxX = kotlin.math.max(maxX, l.positionX + l.width)
                                                    maxY = kotlin.math.max(maxY, l.positionY + l.height)
                                                }
                                                if (minX == Float.MAX_VALUE) {
                                                    minX = orig.positionX; minY = orig.positionY; maxX = orig.positionX + orig.width; maxY = orig.positionY + orig.height
                                                }
                                            } else {
                                                minX = orig.positionX
                                                minY = orig.positionY
                                                maxX = orig.positionX + orig.width
                                                maxY = orig.positionY + orig.height
                                            }
                                            
                                            layersToRasterize.forEach { l ->
                                                val paddingPx = if (l.effects.any { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType in listOf("DropShadow", "OuterGlow", "BordersAndShadows") }) {
                                                    kotlin.math.max(l.width, l.height) * 0.5f
                                                } else if (l.strokeThickness > 0f) {
                                                    l.strokeThickness + 8f
                                                } else {
                                                    0f
                                                }
                                                maxPadding = kotlin.math.max(maxPadding, paddingPx)
                                            }
                                            
                                            val boundsLeft = minX - maxPadding
                                            val boundsTop = minY - maxPadding
                                            val boundsRight = maxX + maxPadding
                                            val boundsBottom = maxY + maxPadding
                                            
                                            val layW = kotlin.math.max(1f, boundsRight - boundsLeft)
                                            val layH = kotlin.math.max(1f, boundsBottom - boundsTop)
                                            
                                            // Get zoom safely
                                            val zoom = try { currentFitScaleState.value * currentScaleFactorState.value } catch (e: Exception) { 1.0f }
                                            val pxPerUnit = kotlin.math.min(zoom * 2f, 4096f / kotlin.math.max(layW, layH))
                                            
                                            val sizePx = androidx.compose.ui.unit.IntSize(
                                                kotlin.math.ceil(layW * pxPerUnit).toInt().coerceAtLeast(1),
                                                kotlin.math.ceil(layH * pxPerUnit).toInt().coerceAtLeast(1)
                                            )
                                            
                                            val oldCenterX = orig.positionX + orig.width * orig.pivotX
                                            val oldCenterY = orig.positionY + orig.height * orig.pivotY
                                            val newPivotX = if (layW > 0f) (oldCenterX - boundsLeft) / layW else 0.5f
                                            val newPivotY = if (layH > 0f) (oldCenterY - boundsTop) / layH else 0.5f
                                            
                                            val untransformedOrig = orig.copy(
                                                rotation = 0f, scaleX = 1f, scaleY = 1f, skewX = 0f, skewY = 0f, perspX = 0f, perspY = 0f
                                            )
                                            val tempAllLayers = layers.map { if (it.id == orig.id) untransformedOrig else it }
                                            
                                            rasterGraphicsLayer.record(
                                                density = androidx.compose.ui.unit.Density(1f, 1f),
                                                layoutDirection = androidx.compose.ui.unit.LayoutDirection.Ltr,
                                                size = sizePx
                                            ) {
                                                withTransform({
                                                    scale(pxPerUnit, pxPerUnit, pivot = androidx.compose.ui.geometry.Offset.Zero)
                                                    translate(-boundsLeft, -boundsTop)
                                                }) {
                                                    layersToRasterize.forEach { layerToDraw ->
                                                        if (layerToDraw.isClippingMask) return@forEach
                                                        
                                                        val targetLayer = tempAllLayers.find { it.id == layerToDraw.id } ?: layerToDraw
                                                        
                                                        drawLayerWithFullPipeline(
                                                            layer = targetLayer,
                                                            allLayers = tempAllLayers,
                                                            layerOpacity = targetLayer.opacity,
                                                            selectedLayerId = null,
                                                            pathCache = pathCache,
                                                            pathPointsCountCache = pathPointsCountCache,
                                                            totalScale = 1.0f,
                                                            dashEffect = dashEffect8,
                                                            imageBitmapCache = imageBitmapCache,
                                                            composeBlendMode = targetLayer.blendMode.toComposeBlendMode(),
                                                            sharedTransformMatrix = androidx.compose.ui.graphics.Matrix(),
                                                            activeTool = activeTool,
                                                            liveDragScaleX = 1.0f,
                                                            liveDragScaleY = 1.0f,
                                                            viewportWidth = currentViewportWidthState.value,
                                                            viewportHeight = currentViewportHeightState.value,
                                                            panX = canvasPanX,
                                                            panY = canvasPanY,
                                                            canvasWidth = canvasWidth,
                                                            canvasHeight = canvasHeight,
                                                            isRasterizing = true
                                                        )
                                                    }
                                                }
                                            }
                                            
                                            val imageBitmap = rasterGraphicsLayer.toImageBitmap()
                                            val hardwareBitmap = imageBitmap.asAndroidBitmap()
                                            
                                            val file = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                                                val dir = java.io.File(context.filesDir, "rasterized").apply { mkdirs() }
                                                val f = java.io.File(dir, "${java.util.UUID.randomUUID()}.png")
                                                java.io.FileOutputStream(f).use { out ->
                                                    try {
                                                        hardwareBitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, out)
                                                    } catch (e: Exception) {
                                                        val swBitmap = hardwareBitmap.copy(android.graphics.Bitmap.Config.ARGB_8888, false)
                                                        swBitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, out)
                                                        swBitmap.recycle()
                                                    }
                                                }
                                                f
                                            }
                                            
                                            val cachedImg = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                                                val bmp = android.graphics.BitmapFactory.decodeFile(file.absolutePath)
                                                bmp?.asImageBitmap()
                                            }
                                            
                                            undoStack.add(layers)
                                            redoStack.clear()
                                            
                                            val rasterized = orig.copy(
                                                type = com.example.studio.model.LayerType.IMAGE_CARD,
                                                imageUri = file.absolutePath,
                                                width = layW,
                                                height = layH,
                                                positionX = boundsLeft,
                                                positionY = boundsTop,
                                                pivotX = newPivotX,
                                                pivotY = newPivotY,
                                                rotation = orig.rotation,
                                                scaleX = orig.scaleX,
                                                scaleY = orig.scaleY,
                                                skewX = orig.skewX,
                                                skewY = orig.skewY,
                                                perspX = orig.perspX,
                                                perspY = orig.perspY,
                                                textContent = "",
                                                richTextSpansJson = "",
                                                brushPoints = emptyList(),
                                                meshWarpPointsStr = "",
                                                perspWarpPointsStr = "",
                                                effects = emptyList()
                                            )
                                            
                                            val descendantIds = descendants.map { it.id }.toSet()
                                            var updated = layers.filter { it.id !in descendantIds }.map { if (it.id == id) rasterized else it }
                                            
                                            com.aistudio.zenithstudio.rpxwtq.EffectStackManager.saveUndoState()
                                            com.aistudio.zenithstudio.rpxwtq.EffectStackManager.filtersByLayer[id]?.clear()
                                            com.aistudio.zenithstudio.rpxwtq.EffectStackManager.filtersByLayer.remove(id)
                                            com.aistudio.zenithstudio.rpxwtq.EffectStackManager.changeCounter.value++
                                            
                                            if (cachedImg != null) {
                                                imageBitmapCache[file.absolutePath] = cachedImg
                                            }
                                            layers = updated
                                            artboards = artboards.map { if (it.id == selectedArtboardId) it.copy(layers = updated) else it }
                                            
                                        } catch (e: Exception) {
                                            e.printStackTrace()
                                        }
                                    }
                                }
                            },
                            onDuplicateLayer = { id ->
                                val orig = layers.find { it.id == id }
                                if (orig != null) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val copy = orig.copy(
                                        id = UUID.randomUUID().toString(),
                                        name = "${orig.name} (Copy)",
                                        positionX = orig.positionX + 40f,
                                        positionY = orig.positionY + 40f,
                                        effects = orig.effects.map { eff -> eff.duplicate() }
                                    )
                                    com.aistudio.zenithstudio.rpxwtq.EffectStackManager.duplicateFiltersForLayer(id, copy.id)
                                    com.example.studio.ui.ParametricLayerCache.duplicateNode(id, copy.id)
                                    val updated = listOf(copy) + layers
                                    layers = updated
                                    selectedLayerId = copy.id
                                    artboards = artboards.map { if (it.id == selectedArtboardId) it.copy(layers = updated) else it }
                                }
                            },
                            onDeleteLayer = { id ->
                                val targetLayer = layers.find { it.id == id }
                                val isEmptyLayer = targetLayer != null && targetLayer.type == com.example.studio.model.LayerType.FREEHAND_DRAWING && targetLayer.brushPoints.isEmpty()
                                if (layers.size > 1 && !isEmptyLayer) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val updated = layers.filter { it.id != id }
                                    layers = updated
                                    selectedLayerId = updated.firstOrNull()?.id ?: ""
                                    artboards = artboards.map { if (it.id == selectedArtboardId) it.copy(layers = updated) else it }
                                }
                            },
                            onBlendModeChange = { id, mode ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(blendMode = mode) else it }
                            },
                            onOpacityChange = { id, op ->
                                layers = layers.map { if (it.id == id) it.copy(opacity = op) else it }
                            },
                            onTriggerRename = { id, currentName ->
                                renamingLayerId = id
                                renamingLayerName = currentName
                            },
                            onCloseDrawer = { isLayersPanelVisible = false },
                            isMultiSelectMode = isMultiSelectMode,
                            onToggleMultiSelect = {
                                isMultiSelectMode = !isMultiSelectMode
                                if (!isMultiSelectMode) {
                                    selectedLayersSet = emptySet()
                                }
                            },
                            selectedLayersSet = selectedLayersSet,
                            onToggleSelectLayerMulti = { id ->
                                selectedLayersSet = if (selectedLayersSet.contains(id)) {
                                    selectedLayersSet - id
                                } else {
                                    selectedLayersSet + id
                                }
                            },
                            onSelectAllLayers = { selectAll ->
                                selectedLayersSet = if (selectAll) {
                                    layers.map { it.id }.toSet()
                                } else {
                                    emptySet()
                                }
                            },
                            onGroupSelected = {
                                if (selectedLayersSet.size >= 2) {
                                    val newGroupId = UUID.randomUUID().toString()
                                    val selectedIndices = layers.indices.filter { layers[it].id in selectedLayersSet }
                                    val topIndex = selectedIndices.minOrNull() ?: 0
                                    
                                    val newGroupLayer = com.example.studio.model.StudioLayer(
                                        id = newGroupId,
                                        name = "Group ${layers.filter { it.type == com.example.studio.model.LayerType.GROUP }.size + 1}",
                                        type = com.example.studio.model.LayerType.GROUP,
                                        positionX = 0f,
                                        positionY = 0f,
                                        width = canvasWidth,
                                        height = canvasHeight,
                                        isVisible = true,
                                        opacity = 1.0f
                                    )
                                    
                                    val updatedLayers = layers.map { 
                                        if (it.id in selectedLayersSet) {
                                            it.copy(parentGroupId = newGroupId)
                                        } else {
                                            it
                                        }
                                    }.toMutableList()
                                    
                                    updatedLayers.add(topIndex, newGroupLayer)
                                    
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    
                                    layers = updatedLayers
                                    selectedLayerId = newGroupId
                                    
                                    selectedLayersSet = emptySet()
                                    isMultiSelectMode = false
                                }
                            },
                            onMergeDown = { id ->
                                val activeIndex = layers.indexOfFirst { it.id == id }
                                if (activeIndex != -1 && activeIndex < layers.size - 1) {
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    mergeDownLayer(
                                        activeLayerIndex = activeIndex,
                                        layers = layers,
                                        canvasWidth = canvasWidth,
                                        canvasHeight = canvasHeight,
                                        context = context,
                                        imageBitmapCache = imageBitmapCache,
                                        pathCache = pathCache,
                                        pathPointsCountCache = pathPointsCountCache,
                                        dashEffect8 = dashEffect8,
                                        onLayersChanged = { 
                                            layers = it
                                        }
                                    )
                                }
                            },
                            collapsedGroupIds = collapsedGroupIds,
                            onToggleGroupCollapse = { id ->
                                collapsedGroupIds = if (collapsedGroupIds.contains(id)) {
                                    collapsedGroupIds - id
                                } else {
                                    collapsedGroupIds + id
                                }
                            },
                            activeClipboard = activeClipboard,
                            onCopyLayer = { layerToCopy ->
                                activeClipboard = layerToCopy.deepCloneForClipboard()
                            },
                            onPasteLayer = {
                                activeClipboard?.let { copied ->
                                    undoStack.add(layers)
                                    redoStack.clear()
                                    val targetArtboard = artboards.find { it.id == selectedArtboardId }
                                    val targetW = targetArtboard?.width ?: 1080f
                                    val targetH = targetArtboard?.height ?: 1350f
                                    
                                    val newPosRefX = (targetW - copied.width * copied.scaleX) / 2f
                                    val newPosRefY = (targetH - copied.height * copied.scaleY) / 2f
                                    
                                    val newPastedId = UUID.randomUUID().toString()
                                    val pastedLayer = copied.deepCloneForClipboard().copy(
                                        id = newPastedId,
                                        name = "${copied.name} (Pasted)",
                                        positionX = newPosRefX,
                                        positionY = newPosRefY
                                    )
                                    com.aistudio.zenithstudio.rpxwtq.EffectStackManager.duplicateFiltersForLayer(copied.id, newPastedId)
                                    com.example.studio.ui.ParametricLayerCache.duplicateNode(copied.id, newPastedId)
                                    layers = listOf(pastedLayer) + layers
                                    selectedLayerId = pastedLayer.id
                                }
                            },
                            onFlipHorizontal = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(scaleX = -it.scaleX) else it }
                            },
                            onFlipVertical = { id ->
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == id) it.copy(scaleY = -it.scaleY) else it }
                            },
                            modifier = Modifier
                        )
                    }

                    // Floating Shape Transform HUD (Quick Dimensions, Symmetric scaling & Aspect Lock)
                    val isShapeOrVectorLayer = selectedLayer != null && (
                        selectedLayer.type != LayerType.FREEHAND_DRAWING || selectedLayer.brushPoints.isNotEmpty()
                    ) && selectedLayer.type != LayerType.GROUP && selectedLayer.type != LayerType.ADJUSTMENT_LAYER

                    androidx.compose.animation.AnimatedVisibility(
                        visible = isShapeOrVectorLayer && selectedLayer != null && !isResizingActive && activeFullScreenSheet == null,
                        enter = androidx.compose.animation.fadeIn() + androidx.compose.animation.slideInVertically { it / 2 },
                        exit = androidx.compose.animation.fadeOut() + androidx.compose.animation.slideOutVertically { it / 2 },
                        modifier = Modifier
                            .align(Alignment.BottomCenter)
                            .padding(bottom = if (workspaceLayoutMode == "Mobile" && isMobileBottomDockVisible) 88.dp else 20.dp)
                            .zIndex(16f)
                    ) {
                        selectedLayer?.let { activeShapeLayer ->
                            Surface(
                                shape = RoundedCornerShape(20.dp),
                                color = DarkOnyx.copy(alpha = 0.94f),
                                border = androidx.compose.foundation.BorderStroke(1.dp, EnergeticYellow.copy(alpha = 0.4f)),
                                shadowElevation = 8.dp,
                                modifier = Modifier
                                    .padding(horizontal = 8.dp)
                                    .testTag("shape_transform_hud")
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    // Shape Type Icon & Dimensions Readout
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                                        modifier = Modifier
                                            .background(MidSlate.copy(alpha = 0.6f), RoundedCornerShape(8.dp))
                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Category,
                                            contentDescription = "Shape Icon",
                                            tint = EnergeticYellow,
                                            modifier = Modifier.size(14.dp)
                                        )
                                        Text(
                                            text = "${activeShapeLayer.width.toInt()} × ${activeShapeLayer.height.toInt()} px",
                                            style = Typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                                            color = TextPrimary
                                        )
                                    }

                                    // Proportional lock toggle
                                    IconButton(
                                        onClick = {
                                            undoStack.add(layers)
                                            redoStack.clear()
                                            layers = layers.map {
                                                if (it.id == activeShapeLayer.id) it.copy(isAspectLocked = !it.isAspectLocked) else it
                                            }
                                        },
                                        modifier = Modifier.size(36.dp)
                                    ) {
                                        Icon(
                                            imageVector = if (activeShapeLayer.isAspectLocked) Icons.Default.Lock else Icons.Default.LockOpen,
                                            contentDescription = "Aspect Ratio Lock",
                                            tint = if (activeShapeLayer.isAspectLocked) IndustrialAmber else TextSecondary,
                                            modifier = Modifier.size(18.dp)
                                        )
                                    }

                                    // Symmetrical Center / Anchor Mode Dropdown Badge
                                    Box {
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(6.dp))
                                                .background(Color(0xFF0F766E).copy(alpha = 0.45f))
                                                .border(0.8.dp, Color(0xFF14B8A6), RoundedCornerShape(6.dp))
                                                .clickable { showShapeAnchorMenu = true }
                                                .padding(horizontal = 7.dp, vertical = 3.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(3.dp)
                                            ) {
                                                Icon(
                                                    imageVector = when (shapeAnchorMode) {
                                                        "OPPOSITE" -> Icons.Default.CropFree
                                                        "ORIGIN" -> Icons.Default.VerticalAlignTop
                                                        else -> Icons.Default.FilterCenterFocus
                                                    },
                                                    contentDescription = null,
                                                    tint = Color(0xFF2DD4BF),
                                                    modifier = Modifier.size(11.dp)
                                                )
                                                Text(
                                                    text = when (shapeAnchorMode) {
                                                        "OPPOSITE" -> "Anchor: Opposite"
                                                        "ORIGIN" -> "Anchor: Origin"
                                                        else -> "Anchor: Center"
                                                    },
                                                    style = Typography.labelSmall.copy(fontSize = 9.sp, fontWeight = FontWeight.SemiBold),
                                                    color = Color(0xFF2DD4BF)
                                                )
                                                Icon(
                                                    imageVector = Icons.Default.ArrowDropDown,
                                                    contentDescription = "Anchor Mode Menu",
                                                    tint = Color(0xFF2DD4BF),
                                                    modifier = Modifier.size(13.dp)
                                                )
                                            }
                                        }

                                        DropdownMenu(
                                            expanded = showShapeAnchorMenu,
                                            onDismissRequest = { showShapeAnchorMenu = false },
                                            modifier = Modifier
                                                .background(Color(0xFF1E293B))
                                                .border(1.dp, Color(0xFF334155), RoundedCornerShape(8.dp))
                                        ) {
                                            DropdownMenuItem(
                                                text = {
                                                    Column {
                                                        Text("Center Symmetrical", style = Typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold), color = Color.White)
                                                        Text("Scale equally outward from shape center", style = Typography.labelSmall, color = TextSecondary)
                                                    }
                                                },
                                                leadingIcon = {
                                                    Icon(Icons.Default.FilterCenterFocus, contentDescription = null, tint = if (shapeAnchorMode == "CENTER") Color(0xFF2DD4BF) else TextSecondary)
                                                },
                                                trailingIcon = if (shapeAnchorMode == "CENTER") {
                                                    { Icon(Icons.Default.Check, contentDescription = null, tint = Color(0xFF2DD4BF), modifier = Modifier.size(18.dp)) }
                                                } else null,
                                                onClick = {
                                                    shapeAnchorMode = "CENTER"
                                                    showShapeAnchorMenu = false
                                                }
                                            )
                                            DropdownMenuItem(
                                                text = {
                                                    Column {
                                                        Text("Opposite Corner", style = Typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold), color = Color.White)
                                                        Text("Opposite corner stays anchored in place", style = Typography.labelSmall, color = TextSecondary)
                                                    }
                                                },
                                                leadingIcon = {
                                                    Icon(Icons.Default.CropFree, contentDescription = null, tint = if (shapeAnchorMode == "OPPOSITE") Color(0xFF2DD4BF) else TextSecondary)
                                                },
                                                trailingIcon = if (shapeAnchorMode == "OPPOSITE") {
                                                    { Icon(Icons.Default.Check, contentDescription = null, tint = Color(0xFF2DD4BF), modifier = Modifier.size(18.dp)) }
                                                } else null,
                                                onClick = {
                                                    shapeAnchorMode = "OPPOSITE"
                                                    showShapeAnchorMenu = false
                                                }
                                            )
                                            DropdownMenuItem(
                                                text = {
                                                    Column {
                                                        Text("Fixed Origin (Top-Left)", style = Typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold), color = Color.White)
                                                        Text("Top-left origin remains stationary", style = Typography.labelSmall, color = TextSecondary)
                                                    }
                                                },
                                                leadingIcon = {
                                                    Icon(Icons.Default.VerticalAlignTop, contentDescription = null, tint = if (shapeAnchorMode == "ORIGIN") Color(0xFF2DD4BF) else TextSecondary)
                                                },
                                                trailingIcon = if (shapeAnchorMode == "ORIGIN") {
                                                    { Icon(Icons.Default.Check, contentDescription = null, tint = Color(0xFF2DD4BF), modifier = Modifier.size(18.dp)) }
                                                } else null,
                                                onClick = {
                                                    shapeAnchorMode = "ORIGIN"
                                                    showShapeAnchorMenu = false
                                                }
                                            )
                                            HorizontalDivider(color = Color.White.copy(alpha = 0.12f), modifier = Modifier.padding(vertical = 4.dp))
                                            DropdownMenuItem(
                                                text = {
                                                    Text(
                                                        text = if (activeShapeLayer.isAspectLocked) "Aspect Ratio: Locked" else "Aspect Ratio: Free",
                                                        style = Typography.bodyMedium,
                                                        color = if (activeShapeLayer.isAspectLocked) IndustrialAmber else TextSecondary
                                                    )
                                                },
                                                leadingIcon = {
                                                    Icon(
                                                        if (activeShapeLayer.isAspectLocked) Icons.Default.Lock else Icons.Default.LockOpen,
                                                        contentDescription = null,
                                                        tint = if (activeShapeLayer.isAspectLocked) IndustrialAmber else TextSecondary
                                                    )
                                                },
                                                onClick = {
                                                    layers = layers.map {
                                                        if (it.id == activeShapeLayer.id) it.copy(isAspectLocked = !it.isAspectLocked) else it
                                                    }
                                                    showShapeAnchorMenu = false
                                                }
                                            )
                                        }
                                    }

                                    // Quick Nudge Buttons (-20, +20)
                                    val onResizeDelta = { delta: Float ->
                                        undoStack.add(layers)
                                        redoStack.clear()
                                        layers = layers.map { lyr ->
                                            if (lyr.id == activeShapeLayer.id) {
                                                val ratio = if (lyr.isAspectLocked && lyr.height > 0f) lyr.width / lyr.height else 1f
                                                val newW = (lyr.width + delta).coerceIn(20f, 4000f)
                                                val newH = if (lyr.isAspectLocked) (newW / ratio).coerceIn(20f, 4000f) else (lyr.height + delta).coerceIn(20f, 4000f)
                                                val newX = lyr.positionX + (lyr.width - newW) / 2f
                                                val newY = lyr.positionY + (lyr.height - newH) / 2f
                                                lyr.copy(width = newW, height = newH, positionX = newX, positionY = newY)
                                            } else lyr
                                        }
                                    }

                                    Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(6.dp))
                                                .background(SlatePanel)
                                                .clickable { onResizeDelta(-20f) }
                                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                        ) {
                                            Text("-20", style = Typography.labelSmall.copy(fontWeight = FontWeight.Bold), color = TextPrimary)
                                        }
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(6.dp))
                                                .background(SlatePanel)
                                                .clickable { onResizeDelta(20f) }
                                                .padding(horizontal = 8.dp, vertical = 4.dp)
                                        ) {
                                            Text("+20", style = Typography.labelSmall.copy(fontWeight = FontWeight.Bold), color = TextPrimary)
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // -- BOTTOM EFFECTS & PARAMETERS PANEL / SPLIT-SHEET OVERLAY (with smooth animated transition) --
            androidx.compose.animation.AnimatedVisibility(
                visible = activeFullScreenSheet != null && !isLandscape,
                enter = androidx.compose.animation.slideInVertically(
                    initialOffsetY = { it },
                    animationSpec = androidx.compose.animation.core.tween(durationMillis = 350, easing = androidx.compose.animation.core.FastOutSlowInEasing)
                ) + androidx.compose.animation.fadeIn(animationSpec = androidx.compose.animation.core.tween(durationMillis = 200)),
                exit = androidx.compose.animation.slideOutVertically(
                    targetOffsetY = { it },
                    animationSpec = androidx.compose.animation.core.tween(durationMillis = 300, easing = androidx.compose.animation.core.FastOutSlowInEasing)
                ) + androidx.compose.animation.fadeOut(animationSpec = androidx.compose.animation.core.tween(durationMillis = 200)),
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .zIndex(14f)
            ) {
                Box(
                    modifier = Modifier
                        .navigationBarsPadding()
                        .fillMaxWidth()
                        .fillMaxHeight(if (activeFullScreenSheet == "Ruler" || activeFullScreenSheet == "Grid") 0.28f else 0.48f)
                        .background(SlatePanel.copy(alpha = 0.9f))
                        .border(BorderStroke(1.2.dp, HighslateOutline), RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp))
                        .padding(horizontal = 16.dp, vertical = 8.dp)
                        .clickable(interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() }, indication = null) { }
                ) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        // Header Area
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(52.dp)
                                .padding(horizontal = 16.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                Column {
                                    val headerText = when (activeFullScreenSheet) {
                                        "Color" -> "Color & Fill Designer"
                                        "Border" -> "Border & Shadows Studio"
                                        "Transform" -> "Geometrical Canvas Transforms"
                                        "Shape" -> when (selectedLayer?.type) {
                                            com.example.studio.model.LayerType.IMAGE_CARD -> "Edit Image"
                                            com.example.studio.model.LayerType.TEXT -> "Edit Text & Typography"
                                            else -> "Edit Shape & Typography"
                                        }
                                        "Effects" -> "Filters & FX Config Stack"
                                        "Brush" -> if (activeTool == "Pen") "Bezier Pen Studio" else "Paint Brush Studio Settings"
                                        "Grid" -> "Grid Alignment Calibration"
                                        "Ruler" -> "Ruler Guideline Calibration"
                                        else -> "Border & Shadows Studio"
                                    }
                                    Text(headerText, style = Typography.titleMedium, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold)
                                    if (activeFullScreenSheet == "Ruler") {
                                        Text(
                                            text = "Magnet Snap: ${if (snapToRuler) "ON" else "OFF"}  •  Angle Lock: ${if (allRulersLocked) "LOCKED" else "FREE"}",
                                            style = Typography.labelSmall,
                                            color = if (snapToRuler) Color(0xFF00FF66) else TextSecondary,
                                            fontSize = 11.sp
                                        )
                                    } else {
                                        selectedLayer?.let {
                                            Text("Active Item: ${it.name}", style = Typography.labelSmall, color = TextSecondary, fontSize = 11.sp)
                                        }
                                    }
                                }
                            }
                            
                            IconButton(
                                onClick = { activeFullScreenSheet = null },
                                modifier = Modifier.size(48.dp)
                            ) {
                                Icon(Icons.Default.Close, "Close Panel", tint = TextSecondary, modifier = Modifier.size(20.dp))
                            }
                        }
                        
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(0.5.dp)
                                .background(HighslateOutline)
                        )
                        Spacer(Modifier.height(8.dp))

                        // Render lightweight property panel inside the lower 40% bounds
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .weight(1f)
                        ) {
                            when (activeFullScreenSheet) {
                                "Color" -> {
                                    if (selectedLayer != null) {
                                        HsvColorPickerPanel(
                                            currentColor = selectedLayer.baseColor,
                                            currentOpacity = selectedLayer.opacity,
                                            onColorChanged = { newColor ->
                                                layers = layers.map { if (it.id == selectedLayer.id) it.copy(baseColor = newColor) else it }
                                            },
                                            selectedLayer = selectedLayer,
                                            onUpdateLayer = { updatedLayer ->
                                                layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                                            },
                                            onOpenColorPickerDialog = { idx ->
                                                activeGradientStopIndex = idx
                                                showGradientColorPickerDialog = true
                                            },
                                            projectColorProfile = projectColorProfile,
                                            selectedCmykProfile = selectedCmykProfile,
                                            modifier = Modifier.fillMaxSize()
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Border" -> {
                                    if (selectedLayer != null) {
                                        BordersAndShadowsTabPanel(
                                            selectedLayer = selectedLayer,
                                            onRemoveEffect = { effectId ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        layer.copy(effects = layer.effects.filter { it.id != effectId })
                                                    } else layer
                                                }
                                            },
                                            onToggleEffectEnabled = { effectId ->
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        layer.copy(effects = layer.effects.map { eff ->
                                                            if (eff.id == effectId) {
                                                                eff.toggleEnabled()
                                                            } else eff
                                                        })
                                                     } else layer
                                                 }
                                             },
                                            onAddEffect = { effect ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        layer.copy(effects = layer.effects + effect)
                                                    } else layer
                                                }
                                                selectedEffectIndex = selectedLayer.effects.size
                                            },
                                            onUpdateEffectParam = { effectId, paramName, newValue ->
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        val updatedEffects = layer.effects.map { eff ->
                                                            if (eff.id == effectId) {
                                                                eff.updateParameter(paramName, newValue)
                                                            } else eff
                                                        }
                                                        layer.copy(effects = updatedEffects)
                                                    } else layer
                                                }
                                            }
                                        )
                                    } else {
                                        Text("No selected shape/vector layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Transform" -> {
                                    if (selectedLayer != null) {
                                        val activeArtboard = artboards.find { it.id == selectedArtboardId } ?: artboards.firstOrNull()
                                        val artW = activeArtboard?.width ?: 1080f
                                        val artH = activeArtboard?.height ?: 1080f
                                        TransformDetailView(
                                            selectedLayer = selectedLayer,
                                            onUpdateLayer = { updatedLayer ->
                                                layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                                            },
                                            artboardWidth = artW,
                                            artboardHeight = artH
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Shape" -> {
                                    if (selectedLayer != null) {
                                        val activeArtboard = artboards.find { it.id == selectedArtboardId } ?: artboards.firstOrNull()
                                        val artW = activeArtboard?.width ?: 1080f
                                        val artH = activeArtboard?.height ?: 1080f
                                        TypographyOrShapeDetailView(
                                            selectedLayer = selectedLayer,
                                            onUpdateLayer = { updatedLayer ->
                                                layers = layers.map { if (it.id == updatedLayer.id) updatedLayer else it }
                                            },
                                            fontSearchQuery = fontSearchQuery,
                                            onFontSearchQueryChange = { fontSearchQuery = it },
                                            selectedCategoryFilter = selectedCategoryFilter,
                                            onSelectedCategoryFilterChange = { selectedCategoryFilter = it },
                                            onImportFontClick = { showFontScannerDialog = true },
                                            customFonts = customFonts,
                                            canvasWidth = artW,
                                            canvasHeight = artH
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }
                                "Effects" -> {
                                    if (selectedLayer != null) {
                                        FiltersAndFxDetailView(
                                            selectedLayer = selectedLayer,
                                            selectedEffectIndex = selectedEffectIndex,
                                            onSelectEffectIndex = { selectedEffectIndex = it },
                                            onRemoveEffect = { effectId ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        layer.copy(effects = layer.effects.filter { it.id != effectId })
                                                    } else layer
                                                }
                                            },
                                            onDuplicateEffect = { effectId ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        val effectToDuplicate = layer.effects.find { it.id == effectId }
                                                        if (effectToDuplicate != null) {
                                                            val duplicated = effectToDuplicate.duplicate()
                                                            val idx = layer.effects.indexOf(effectToDuplicate)
                                                            val newList = layer.effects.toMutableList()
                                                            newList.add(idx + 1, duplicated)
                                                            layer.copy(effects = newList)
                                                        } else layer
                                                    } else layer
                                                }
                                            },
                                            onToggleEffectEnabled = { effectId ->
                                                undoStack.add(layers)
                                                redoStack.clear()
                                                layers = layers.map { layer ->
                                                    if (layer.id == selectedLayer.id) {
                                                        val updatedEffects = layer.effects.map { eff ->
                                                            if (eff.id == effectId) {
                                                                eff.toggleEnabled()
                                                            } else eff
                                                        }
                                                        layer.copy(effects = updatedEffects)
                                                    } else layer
                                                }
                                            },
                                            onUpdateEffectParam = { effectId, paramName, newValue ->
                                                com.example.studio.ui.CanvasEventLoop.emit(
                                                    com.example.studio.ui.CanvasEvent.UpdateSlider(
                                                        layerId = selectedLayer.id,
                                                        effectId = effectId,
                                                        paramName = paramName,
                                                        value = newValue
                                                    )
                                                )
                                            },
                                            onOpenEffectsGallery = { showEffectsGallery = true }
                                        )
                                    } else {
                                        Text("No selected shape layer.", color = TextSecondary, style = Typography.bodyMedium)
                                    }
                                }

                                "Brush" -> {
                                    if (activeTool == "Pen") {
                                        val activeArtboard = artboards.find { it.id == selectedArtboardId } ?: artboards.firstOrNull()
                                        val artW = activeArtboard?.width ?: 1080f
                                        val artH = activeArtboard?.height ?: 1080f
                                        val totalScale = fitScale * scaleFactor
                                        BezierVectorControlPane(
                                            layer = selectedLayer,
                                            activeBezierPointIndex = activeBezierPointIndex,
                                            keepBezierSymmetrical = keepBezierSymmetrical,
                                            onKeepBezierSymmetricalChange = { keepBezierSymmetrical = it },
                                            onActiveBezierPointIndexChange = { idx -> activeBezierPointIndex = idx },
                                            penCursorOffset = penCursorOffset,
                                            onPenCursorOffsetChange = { offset -> penCursorOffset = offset },
                                            penSubTool = penSubTool,
                                            onPenSubToolChange = { sub -> penSubTool = sub },
                                            onUpdateLayerProperties = { thickness, color ->
                                                if (selectedLayer != null) {
                                                     undoStack.add(layers)
                                                     redoStack.clear()
                                                     layers = layers.map {
                                                         if (it.id == selectedLayer.id) {
                                                             it.copy(strokeThickness = thickness, baseColor = color)
                                                         } else it
                                                     }
                                                     com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                }
                                            },
                                            onUpdatePoints = { newPoints ->
                                                if (selectedLayer != null) {
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    layers = layers.map {
                                                        if (it.id == selectedLayer.id) {
                                                            it.copy(brushPoints = newPoints)
                                                        } else it
                                                    }
                                                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                }
                                            },
                                            onAddPoint = {
                                                val cursor = penCursorOffset ?: androidx.compose.ui.geometry.Offset(artW / 2f, artH / 2f)
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER) {
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    val updatedPoints = selectedLayer.brushPoints + cursor + cursor + cursor
                                                    layers = layers.map {
                                                        if (it.id == selectedLayer.id) {
                                                            it.copy(brushPoints = updatedPoints)
                                                        } else it
                                                    }
                                                    activeBezierPointIndex = updatedPoints.size - 3
                                                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                } else {
                                                    val newL = com.example.studio.model.StudioLayer(
                                                        name = "Pen Vector Path ${layers.filter { it.type == com.example.studio.model.LayerType.VECTOR_BEZIER }.size + 1}",
                                                        type = com.example.studio.model.LayerType.VECTOR_BEZIER,
                                                        positionX = 0f,
                                                        positionY = 0f,
                                                        width = artW,
                                                        height = artH,
                                                        baseColor = brushColor,
                                                        brushPoints = listOf(cursor, cursor, cursor)
                                                    )
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    layers = listOf(newL) + layers
                                                    selectedLayerId = newL.id
                                                    activeBezierPointIndex = 0
                                                }
                                            },
                                            onDeletePoint = {
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && activeBezierPointIndex != -1) {
                                                    val k = activeBezierPointIndex / 3
                                                    val updatedPoints = selectedLayer.brushPoints.toMutableList()
                                                    if (k * 3 in updatedPoints.indices) {
                                                        updatedPoints.removeAt(k * 3)
                                                        if (k * 3 in updatedPoints.indices) updatedPoints.removeAt(k * 3)
                                                        if (k * 3 in updatedPoints.indices) updatedPoints.removeAt(k * 3)
                                                        
                                                        undoStack.add(layers)
                                                        redoStack.clear()
                                                        layers = layers.map {
                                                            if (it.id == selectedLayer.id) {
                                                                it.copy(brushPoints = updatedPoints)
                                                            } else it
                                                        }
                                                        activeBezierPointIndex = if (updatedPoints.isNotEmpty()) {
                                                            (k * 3).coerceAtMost(updatedPoints.size - 3)
                                                        } else -1
                                                        com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                    }
                                                }
                                            },
                                            onToggleClosePath = {
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER) {
                                                    val newVal = if (selectedLayer.polygonEdges == 1) 0 else 1
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    layers = layers.map {
                                                        if (it.id == selectedLayer.id) {
                                                            it.copy(polygonEdges = newVal)
                                                        } else it
                                                    }
                                                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                }
                                            },
                                            onToggleNodeType = {
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && activeBezierPointIndex != -1) {
                                                    val k = activeBezierPointIndex / 3
                                                    val currentTypes = selectedLayer.bezierNodeTypes.toMutableList()
                                                    while (currentTypes.size <= k) {
                                                        currentTypes.add("SMOOTH")
                                                    }
                                                    val oldType = currentTypes[k]
                                                    val newType = if (oldType == "CORNER") "SMOOTH" else "CORNER"
                                                    currentTypes[k] = newType
                                                    
                                                    val updatedPoints = selectedLayer.brushPoints.toMutableList()
                                                    if (newType == "SMOOTH" && (k * 3 + 2) < updatedPoints.size) {
                                                        val anchor = updatedPoints[k * 3]
                                                        val handleIn = updatedPoints[k * 3 + 1]
                                                        val handleOut = updatedPoints[k * 3 + 2]
                                                        val distIn = (handleIn - anchor).getDistance()
                                                        val distOut = (handleOut - anchor).getDistance()
                                                        
                                                        if (distOut > 0.001f) {
                                                            val vOut = handleOut - anchor
                                                            val normIn = androidx.compose.ui.geometry.Offset(-vOut.x / distOut, -vOut.y / distOut)
                                                            updatedPoints[k * 3 + 1] = anchor + (normIn * distIn)
                                                        } else if (distIn > 0.001f) {
                                                            val vIn = handleIn - anchor
                                                            val normOut = androidx.compose.ui.geometry.Offset(-vIn.x / distIn, -vIn.y / distIn)
                                                            updatedPoints[k * 3 + 2] = anchor + (normOut * distOut)
                                                        }
                                                    }
                                                    
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    layers = layers.map {
                                                        if (it.id == selectedLayer.id) {
                                                            it.copy(bezierNodeTypes = currentTypes, brushPoints = updatedPoints)
                                                        } else it
                                                    }
                                                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                }
                                            },
                                            onToggleFillStyle = {
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER) {
                                                    val newVal = if (selectedLayer.strokeThickness > 0f) -1f else 8f
                                                    undoStack.add(layers)
                                                    redoStack.clear()
                                                    layers = layers.map {
                                                        if (it.id == selectedLayer.id) {
                                                            it.copy(strokeThickness = newVal)
                                                        } else it
                                                    }
                                                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                }
                                            },
                                            onRetractHandle = { isHandleIn ->
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && activeBezierPointIndex != -1) {
                                                    val k = activeBezierPointIndex / 3
                                                    val updatedPoints = selectedLayer.brushPoints.toMutableList()
                                                    if (k * 3 + 2 < updatedPoints.size) {
                                                        val anchor = updatedPoints[k * 3]
                                                        if (isHandleIn) {
                                                            updatedPoints[k * 3 + 1] = anchor
                                                        } else {
                                                            updatedPoints[k * 3 + 2] = anchor
                                                        }
                                                        undoStack.add(layers)
                                                        redoStack.clear()
                                                        layers = layers.map {
                                                            if (it.id == selectedLayer.id) {
                                                                it.copy(brushPoints = updatedPoints)
                                                            } else it
                                                        }
                                                        com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                    }
                                                }
                                            },
                                            onRestoreHandles = {
                                                if (selectedLayer != null && selectedLayer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && activeBezierPointIndex != -1) {
                                                    val k = activeBezierPointIndex / 3
                                                    val updatedPoints = selectedLayer.brushPoints.toMutableList()
                                                    if (k * 3 + 2 < updatedPoints.size) {
                                                        val anchor = updatedPoints[k * 3]
                                                        val handleIn = updatedPoints[k * 3 + 1]
                                                        val handleOut = updatedPoints[k * 3 + 2]
                                                        
                                                        val distIn = (handleIn - anchor).getDistance()
                                                        val distOut = (handleOut - anchor).getDistance()
                                                        
                                                        val numNodes = updatedPoints.size / 3
                                                        val prev = if (k > 0) updatedPoints[(k - 1) * 3] else anchor
                                                        val next = if (k < numNodes - 1) updatedPoints[(k + 1) * 3] else anchor
                                                        
                                                        var tangent = next - prev
                                                        var tangentLen = tangent.getDistance()
                                                        if (tangentLen < 0.001f) {
                                                            tangent = androidx.compose.ui.geometry.Offset(100f, 0f)
                                                            tangentLen = 100f
                                                        }
                                                        
                                                        val unitTangent = tangent / tangentLen
                                                        val defaultLength = (tangentLen * 0.25f).coerceIn(20f, 100f)
                                                        
                                                        if (distIn < 0.001f) {
                                                            updatedPoints[k * 3 + 1] = anchor - (unitTangent * defaultLength)
                                                        }
                                                        if (distOut < 0.001f) {
                                                            updatedPoints[k * 3 + 2] = anchor + (unitTangent * defaultLength)
                                                        }
                                                        
                                                        undoStack.add(layers)
                                                        redoStack.clear()
                                                        layers = layers.map {
                                                            if (it.id == selectedLayer.id) {
                                                                it.copy(brushPoints = updatedPoints)
                                                            } else it
                                                        }
                                                        com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayer.id)
                                                    }
                                                }
                                            },
                                            artboardWidth = artW,
                                            artboardHeight = artH,
                                            totalScale = totalScale,
                                            onClose = {
                                                activeTool = "Move"
                                                activeBezierPointIndex = -1
                                                penCursorOffset = null
                                            },
                                            modifier = Modifier.fillMaxSize()
                                        )
                                    } else {
                                        val currentSmoothing = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        val valSmooth = (selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Smoothing")?.value ?: 0.0f
                                        valSmooth > 0.5f
                                    } else {
                                        brushSmoothing
                                    }
                                    val currentPreset = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        val config = selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                        config?.parameters?.get("Preset")?.value?.toInt() ?: brushPresetIndex
                                    } else {
                                        brushPresetIndex
                                    }
                                    val currentSize = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        (selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Size")?.value ?: brushSize
                                    } else {
                                        brushSize
                                    }
                                    val currentOpacity = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                        (selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Opacity")?.value ?: brushOpacity
                                    } else {
                                        brushOpacity
                                     }
                                     val updateBrushParamsLocal = { newSize: Float?, newOpacity: Float?, newSmooth: Boolean?, newPreset: Int?, newColor: Color?, newHardness: Float? ->
                                        if (newSize != null) brushSize = newSize
                                        if (newOpacity != null) brushOpacity = newOpacity
                                        if (newSmooth != null) brushSmoothing = newSmooth
                                        if (newPreset != null) brushPresetIndex = newPreset
                                        if (newColor != null) brushColor = newColor
                                        if (newHardness != null) brushHardness = newHardness

                                        if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                            val config = selectedLayer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
                                            if (config != null) {
                                                var updatedConfig = config
                                                if (newSize != null) updatedConfig = updatedConfig.updateParameter("Size", newSize) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newOpacity != null) updatedConfig = updatedConfig.updateParameter("Opacity", newOpacity) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newSmooth != null) updatedConfig = updatedConfig.updateParameter("Smoothing", if (newSmooth) 1.0f else 0.0f) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newPreset != null) updatedConfig = updatedConfig.updateParameter("Preset", newPreset.toFloat()) as com.example.studio.model.StudioEffect.PhotoshopEffect
                                                if (newHardness != null) updatedConfig = updatedConfig.updateParameter("Hardness", newHardness) as com.example.studio.model.StudioEffect.PhotoshopEffect

                                                val updatedEffects = selectedLayer.effects.map { if (it.id == config.id) updatedConfig else it }
                                                layers = layers.map {
                                                    if (it.id == selectedLayer.id) {
                                                        it.copy(
                                                            baseColor = newColor ?: selectedLayer.baseColor,
                                                            effects = updatedEffects
                                                        )
                                                    } else it
                                                }
                                            } else {
                                                layers = layers.map {
                                                    if (it.id == selectedLayer.id) {
                                                        it.copy(baseColor = newColor ?: selectedLayer.baseColor)
                                                    } else it
                                                }
                                            }
                                        }
                                    }
                                    
                                    BrushStudioControlPane(
                                        currentPreset = currentPreset,
                                        currentSize = currentSize,
                                        currentOpacity = currentOpacity,
                                        currentColor = if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) selectedLayer.baseColor else brushColor,
                                        currentSmoothing = currentSmoothing,
                                        updateBrushParams = updateBrushParamsLocal,
                                        onOpenBrushesLibrary = { showBrushesLibrary = true },
                                        gridEnabled = gridEnabled,
                                        onGridEnabledChange = { gridEnabled = it },
                                        rulerEnabled = rulerEnabled,
                                        onRulerEnabledChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(enabled = value) else it } },
                                        rulerOrientation = rulerOrientation,
                                        onRulerOrientationChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(orientation = value) else it } },
                                        rulerPosition = rulerPosition,
                                        onRulerPositionChange = { value -> rulers = rulers.map { if (it.id == selectedRulerId) it.copy(position = value) else it } },
                                        activeTool = activeTool,
                                        eraserSize = eraserSize,
                                        onEraserSizeChange = { eraserSize = it },
                                        eraserHardness = eraserHardness,
                                        onEraserHardnessChange = { eraserHardness = it },
                                        brushHardness = brushHardness,
                                        projectColorProfile = projectColorProfile,
                                        selectedCmykProfile = selectedCmykProfile,
                                        modifier = Modifier.fillMaxSize()
                                    )
                                    }
                                }
                                "Grid" -> {
                                    GridControlPane(
                                        gridEnabled = gridEnabled,
                                        onGridEnabledChange = { gridEnabled = it },
                                        gridColumns = gridColumns,
                                        onGridColumnsChange = { gridColumns = it },
                                        gridRows = gridRows,
