                                        warpMeshDivisionY = newRows
                                        val selId = selectedLayerId
                                        val currentSelected = layers.find { l -> l.id == selId }
                                        if (currentSelected != null) {
                                            val newNodes = getInitialMeshNodesWithHandles(
                                                currentSelected.width, currentSelected.height,
                                                warpMeshDivisionX, newRows,
                                                warpTarget, currentSelected
                                            )
                                            val newStr = formatMeshWarpPointsStr(newNodes)
                                            layers = layers.map { l ->
                                                if (l.id == selId) {
                                                    l.copy(warpMeshDivisionY = newRows, meshWarpPointsStr = newStr)
                                                } else l
                                            }
                                            activeWarpNodeIndex = -1
                                            com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                                            /* pathCache.clear() */
                                        }
