                            }

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Button(
                                    onClick = {
                                        activeTool = "Move"
                                        activeWarpNodeIndex = -1
                                    },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = EnergeticYellow,
                                        contentColor = DarkOnyx
                                    ),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Icon(Icons.Default.Check, contentDescription = "Done", modifier = Modifier.size(16.dp))
                                    Spacer(Modifier.width(6.dp))
                                    Text("Done Editing", fontWeight = FontWeight.Bold)
                                }

                                Button(
                                    onClick = {
                                        warpMeshDivisionX = 3
                                        warpMeshDivisionY = 3
                                        warpTarget = "Layer"
                                        // Reset layer mesh warp nodes
                                        layers = layers.map { l ->
                                            if (l.id == selectedLayerId) {
                                                l.copy(meshWarpPointsStr = "")
                                            } else l
                                        }
                                        com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                                        /* pathCache.clear() */
                                    },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = Color(0xFFD32F2F),
                                        contentColor = Color.White
                                    ),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    Icon(Icons.Default.Refresh, contentDescription = "Reset Nodes", modifier = Modifier.size(16.dp))
                                    Spacer(Modifier.width(6.dp))
                                    Text("Reset Nodes", fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }
                }
            }
                                  // -- LANDSCAPE COLLAPSIBLE RIGHT SIDEBAR PARAMETERS PANEL --
            val activeArtboardForLandscape = artboards.find { it.id == selectedArtboardId } ?: artboards.firstOrNull()
            val artWForLandscape = activeArtboardForLandscape?.width ?: 1080f
            val artHForLandscape = activeArtboardForLandscape?.height ?: 1080f
            val totalScaleForLandscape = fitScale * scaleFactor

            LandscapeSidebarPanel(
                isLandscape = isLandscape,
                activeTool = activeTool,
                onActiveToolChange = { activeTool = it },
                isRightSidebarExpanded = isRightSidebarExpanded,
                onRightSidebarExpandedChange = { isRightSidebarExpanded = it },
                modifier = Modifier.align(Alignment.CenterEnd),
                activeFullScreenSheet = activeFullScreenSheet,
                onActiveFullScreenSheetChange = { activeFullScreenSheet = it },
                layers = layers,
                onLayersChange = { layers = it },
                selectedLayer = selectedLayer,
                activeGradientStopIndex = activeGradientStopIndex,
                onActiveGradientStopIndexChange = { activeGradientStopIndex = it },
                showGradientColorPickerDialog = showGradientColorPickerDialog,
                onShowGradientColorPickerDialogChange = { showGradientColorPickerDialog = it },
                undoStack = undoStack,
                redoStack = redoStack,
                selectedEffectIndex = selectedEffectIndex,
                onSelectedEffectIndexChange = { selectedEffectIndex = it },
                fontSearchQuery = fontSearchQuery,
                onFontSearchQueryChange = { fontSearchQuery = it },
                selectedCategoryFilter = selectedCategoryFilter,
                onSelectedCategoryFilterChange = { selectedCategoryFilter = it },
                showFontScannerDialog = showFontScannerDialog,
                onShowFontScannerDialogChange = { showFontScannerDialog = it },
                customFonts = customFonts,
                showZenithEffectsOverlay = showZenithEffectsOverlay,
                onShowZenithEffectsOverlayChange = { showZenithEffectsOverlay = it },
                showEffectsGallery = showEffectsGallery,
                onShowEffectsGalleryChange = { showEffectsGallery = it },
                brushSmoothing = brushSmoothing,
                onBrushSmoothingChange = { brushSmoothing = it },
                brushPresetIndex = brushPresetIndex,
                onBrushPresetIndexChange = { brushPresetIndex = it },
                brushSize = brushSize,
                onBrushSizeChange = { brushSize = it },
                brushOpacity = brushOpacity,
                onBrushOpacityChange = { brushOpacity = it },
                brushColor = brushColor,
                onBrushColorChange = { brushColor = it },
                brushHardness = brushHardness,
                onBrushHardnessChange = { brushHardness = it },
                showBrushesLibrary = showBrushesLibrary,
                onShowBrushesLibraryChange = { showBrushesLibrary = it },
                gridEnabled = gridEnabled,
                onGridEnabledChange = { gridEnabled = it },
                activeGridType = activeGridType,
                onGridTypeChange = { activeGridType = it },
                polarGridCenterX = polarGridCenterX,
                onPolarGridCenterXChange = { polarGridCenterX = it },
                polarGridCenterY = polarGridCenterY,
                onPolarGridCenterYChange = { polarGridCenterY = it },
                rulers = rulers,
                onRulersChange = { rulers = it },
                selectedRulerId = selectedRulerId,
                onSelectedRulerIdChange = { selectedRulerId = it },
                rulerOrientation = rulerOrientation,
                rulerPosition = rulerPosition,
                eraserSize = eraserSize,
                onEraserSizeChange = { eraserSize = it },
                eraserHardness = eraserHardness,
                onEraserHardnessChange = { eraserHardness = it },
                gridColumns = gridColumns,
                onGridColumnsChange = { gridColumns = it },
                gridRows = gridRows,
                onGridRowsChange = { gridRows = it },
                snapToRuler = snapToRuler,
                onSnapToRulerChange = { snapToRuler = it },
                allRulersLocked = allRulersLocked,
                onAllRulersLockedChange = { allRulersLocked = it },
                activeBezierPointIndex = activeBezierPointIndex,
                onActiveBezierPointIndexChange = { activeBezierPointIndex = it },
                penCursorOffset = penCursorOffset,
                onPenCursorOffsetChange = { penCursorOffset = it },
                penSubTool = penSubTool,
                onPenSubToolChange = { penSubTool = it },
                artboardWidth = artWForLandscape,
                artboardHeight = artHForLandscape,
                totalScale = totalScaleForLandscape,
                keepBezierSymmetrical = keepBezierSymmetrical,
                onKeepBezierSymmetricalChange = { keepBezierSymmetrical = it },
                onSelectedLayerIdChange = { selectedLayerId = it },
                warpRepeatMode = warpRepeatMode,
                onWarpRepeatModeChange = {
                    warpRepeatMode = it
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(warpRepeatMode = it)
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                },
                warpRepeatX = warpRepeatX,
                onWarpRepeatXChange = {
                    val newVal = Math.round(it).toFloat()
                    warpRepeatX = newVal
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(warpRepeatX = newVal)
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                },
                warpRepeatY = warpRepeatY,
                onWarpRepeatYChange = {
                    val newVal = Math.round(it).toFloat()
                    warpRepeatY = newVal
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(warpRepeatY = newVal)
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                },
                warpPhaseX = warpPhaseX,
                onWarpPhaseXChange = {
                    warpPhaseX = it
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(warpPhaseX = it)
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                },
                warpPhaseY = warpPhaseY,
                onWarpPhaseYChange = {
                    warpPhaseY = it
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(warpPhaseY = it)
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                },
                warpInterpolation = warpInterpolation,
                onWarpInterpolationChange = {
                    warpInterpolation = it
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(warpInterpolation = it)
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                },
                warpTarget = warpTarget,
                onWarpTargetChange = { mode ->
                    if (warpTarget != mode) {
                        val selId = selectedLayerId
                        val currentSelected = layers.find { it.id == selId }
                        if (currentSelected != null) {
                            val cols = warpMeshDivisionX
                            val rows = warpMeshDivisionY
                            val oldNodes = parseMeshWarpPointsStr(
                                currentSelected.meshWarpPointsStr, cols, rows,
                                currentSelected.width, currentSelected.height,
                                warpTarget, currentSelected
                            )
                            val convertedNodes = oldNodes.map { node ->
                                if (mode == "Canvas" && warpTarget == "Layer") {
                                    val mainCanvas = layerLocalToCanvas(node.main, currentSelected)
                                    val hAbs = layerLocalToCanvas(node.main + node.hHandle, currentSelected)
                                    val vAbs = layerLocalToCanvas(node.main + node.vHandle, currentSelected)
                                    MeshNode(mainCanvas, hAbs - mainCanvas, vAbs - mainCanvas)
                                } else if (mode == "Layer" && warpTarget == "Canvas") {
                                    val mainLocal = canvasToLayerLocal(node.main, currentSelected)
                                    val hAbs = canvasToLayerLocal(node.main + node.hHandle, currentSelected)
                                    val vAbs = canvasToLayerLocal(node.main + node.vHandle, currentSelected)
                                    MeshNode(mainLocal, hAbs - mainLocal, vAbs - mainLocal)
                                } else {
                                    node
                                }
                            }
                            val newStr = formatMeshWarpPointsStr(convertedNodes)
                            layers = layers.map { l ->
                                if (l.id == selId) {
                                    l.copy(warpTarget = mode, meshWarpPointsStr = newStr)
                                } else l
                            }
                            com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                            /* pathCache.clear() */
                        }
                        warpTarget = mode
                    }
                },
                warpMeshDivisionX = warpMeshDivisionX,
                onWarpMeshDivisionXChange = { newCols ->
                    warpMeshDivisionX = newCols
                    val selId = selectedLayerId
                    val currentSelected = layers.find { l -> l.id == selId }
                    if (currentSelected != null) {
                        val newNodes = getInitialMeshNodesWithHandles(
                            currentSelected.width, currentSelected.height,
                            newCols, warpMeshDivisionY,
                            warpTarget, currentSelected
                        )
                        val newStr = formatMeshWarpPointsStr(newNodes)
                        layers = layers.map { l ->
                            if (l.id == selId) {
                                l.copy(warpMeshDivisionX = newCols, meshWarpPointsStr = newStr)
                            } else l
                        }
                        activeWarpNodeIndex = -1
                        com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                        /* pathCache.clear() */
                    }
                },
                warpMeshDivisionY = warpMeshDivisionY,
                onWarpMeshDivisionYChange = { newRows ->
                    warpMeshDivisionY = newRows
                    val selId = selectedLayerId
                    val currentSelected = layers.find { l -> l.id == selId }
                    if (currentSelected != null) {
                        val newNodes = getInitialMeshNodesWithHandles(
                            currentSelected.width, currentSelected.height,
                            warpMeshDivisionX, newRows,
                            warpTarget, currentSelected
                        )
                        val newStr = formatMeshWarpPointsStr(newNodes)
                        layers = layers.map { l ->
                            if (l.id == selId) {
                                l.copy(warpMeshDivisionY = newRows, meshWarpPointsStr = newStr)
                            } else l
                        }
                        activeWarpNodeIndex = -1
                        com.example.studio.ui.ParametricLayerCache.invalidate(selId)
                        /* pathCache.clear() */
                    }
                },
                onResetWarp = {
                    warpRepeatMode = "Off"
                    warpRepeatX = 1f
                    warpRepeatY = 1f
                    warpPhaseX = 0f
                    warpPhaseY = 0f
                    warpInterpolation = true
                    warpTarget = "Layer"
                    warpMeshDivisionX = 3
                    warpMeshDivisionY = 3
                    layers = layers.map { l ->
                        if (l.id == selectedLayerId) {
                            l.copy(
                                warpRepeatMode = "Off",
                                warpRepeatX = 1f,
                                warpRepeatY = 1f,
                                warpPhaseX = 0f,
                                warpPhaseY = 0f,
                                warpInterpolation = true,
                                warpTarget = "Layer",
                                warpMeshDivisionX = 3,
                                warpMeshDivisionY = 3
                            )
                        } else l
                    }
                    com.example.studio.ui.ParametricLayerCache.invalidate(selectedLayerId)
                }
            )

            if (showEffectsGallery && selectedLayer != null) {
                Box(
                    modifier = Modifier.fillMaxSize().zIndex(15f),
                    contentAlignment = Alignment.Center
                ) {
                    EffectsGalleryOverlay(
                        onClose = { showEffectsGallery = false },
                        onAddEffect = { effect ->
                            undoStack.add(layers)
                            redoStack.clear()
                            layers = layers.map { layer ->
                                if (layer.id == selectedLayer.id) {
                                    layer.copy(effects = layer.effects + effect)
                                } else layer
                            }
                            selectedEffectIndex = selectedLayer.effects.size
                        }
                    )
                }
            }

            if (showZenithEffectsOverlay && selectedLayer != null) {
                Box(
                    modifier = Modifier.fillMaxSize().zIndex(15f),
                    contentAlignment = Alignment.Center
                ) {
                    com.aistudio.zenithstudio.rpxwtq.EffectsWindowShell(
                        layerId = selectedLayer.id,
                        onClose = {
                            GradientEyedropperState.isActive = false
                            GradientEyedropperState.onColorSampled = null
                            showZenithEffectsOverlay = false
                        },
                        baseBitmap = selectedLayer.imageUri?.let { imageBitmapCache[it]?.asAndroidBitmap() },
                        modifier = Modifier.fillMaxSize()
                    )
                }
            }

            if (showBrushesLibrary) {
                Box(
                    modifier = Modifier.fillMaxSize().zIndex(15f),
                    contentAlignment = Alignment.Center
                ) {
                    BrushesLibraryOverlay(
                        currentPreset = brushPresetIndex,
                        onPresetChange = { 
                            brushPresetIndex = it
                            if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                layers = layers.map { layer ->
                                    if (layer.id == selectedLayer.id) {
                                        val updatedEffects = layer.effects.map { eff ->
                                            if (eff.name == "BrushConfig") {
                                                eff.updateParameter("Preset", it.toFloat())
                                            } else eff
                                        }
                                        layer.copy(effects = updatedEffects)
                                    } else layer
                                }
                            }
                        },
                        currentSize = brushSize,
                        onSizeChange = {
                            brushSize = it
                            if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                layers = layers.map { layer ->
                                    if (layer.id == selectedLayer.id) {
                                        val updatedEffects = layer.effects.map { eff ->
                                            if (eff.name == "BrushConfig") {
                                                eff.updateParameter("Size", it)
                                            } else eff
                                        }
                                        layer.copy(effects = updatedEffects)
                                    } else layer
                                }
                            }
                        },
                        currentOpacity = brushOpacity,
                        onOpacityChange = {
                            brushOpacity = it
                            if (selectedLayer?.type == LayerType.FREEHAND_DRAWING) {
                                layers = layers.map { layer ->
                                    if (layer.id == selectedLayer.id) {
                                        val updatedEffects = layer.effects.map { eff ->
                                            if (eff.name == "BrushConfig") {
                                                eff.updateParameter("Opacity", it)
                                            } else eff
                                        }
                                        layer.copy(effects = updatedEffects)
                                    } else layer
                                }
                            }
                        },
                        currentColor = brushColor,
                        currentSmoothing = brushSmoothing,
                        onClose = { showBrushesLibrary = false }
                    )
                }
            }
        }

        // Layer renaming Dialog Box overlay to make the Layers stack completely editable
        if (renamingLayerId != null) {
            AlertDialog(
                onDismissRequest = { renamingLayerId = null },
                title = { Text("Rename Layer Source", style = Typography.titleLarge, color = TextPrimary) },
                text = {
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Text("Provide a descriptive tag name inside the compositing list.", style = Typography.bodyMedium, color = TextSecondary)
                        OutlinedTextField(
                            value = renamingLayerName,
                            onValueChange = { renamingLayerName = it },
                            modifier = Modifier.fillMaxWidth(),
                            textStyle = Typography.bodyMedium.copy(color = TextPrimary),
                            singleLine = true,
                            colors = OutlinedTextFieldDefaults.colors(
                                focusedBorderColor = IndustrialAmber,
                                unfocusedBorderColor = HighslateOutline,
                                cursorColor = IndustrialAmber
                            )
                        )
                    }
                },
                confirmButton = {
                    Button(
                        onClick = {
                            undoStack.add(layers)
                            redoStack.clear()
                            layers = layers.map {
                                if (it.id == renamingLayerId) it.copy(name = renamingLayerName) else it
                            }
                            renamingLayerId = null
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber)
                    ) {
                        Text("Rename", color = DarkOnyx, fontWeight = FontWeight.Bold)
                    }
                },
                dismissButton = {
                    TextButton(onClick = { renamingLayerId = null }) {
                        Text("Cancel", color = TextSecondary)
                    }
                },
                containerColor = SlatePanel
            )
        }

        // Advanced high-density and color-space export popup Settings Dialog (Categorized Window)
        if (showExportSettingsDialog) {
            AlertDialog(
                onDismissRequest = { showExportSettingsDialog = false },
                title = {
                    Column {
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            Icon(Icons.Default.Download, contentDescription = null, tint = EnergeticYellow)
                            Text("Export Studio Studio", style = Typography.titleLarge, color = TextPrimary)
                        }
                        Spacer(Modifier.height(4.dp))
                        Text("Select an export category below to configure quality, DPI, and format parameters.", style = Typography.labelSmall, color = TextSecondary)
                    }
                },
                text = {
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        // --- CATEGORY TABS HEADER ---
                        val categories = listOf("JPEG", "PNG", "SVG", "PDF", "ALIGHT XML")
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .horizontalScroll(rememberScrollState()),
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            categories.forEach { cat ->
                                val isSelected = selectedExportFormatCategory == cat
                                val catBg = if (isSelected) Color(0xFF00FF66) else Color(0xFF1B1B22)
                                val catText = if (isSelected) DarkOnyx else TextPrimary
                                Surface(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(8.dp))
                                        .border(BorderStroke(1.dp, if (isSelected) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(8.dp))
                                        .clickable { selectedExportFormatCategory = cat }
                                        .testTag("export_cat_$cat"),
                                    color = catBg
                                ) {
                                    Text(
                                        text = cat,
                                        style = Typography.labelSmall.copy(fontWeight = FontWeight.Bold),
                                        fontSize = 11.sp,
                                        color = catText,
                                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
                                    )
                                }
                            }
                        }

                        // --- ARTBOARD TARGET SELECTOR ---
                        var selectedExportArtboardIds by remember(artboards) { mutableStateOf(artboards.map { it.id }.toSet()) }

                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFF1B1B22)),
                            border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.5f)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(
                                modifier = Modifier.padding(10.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(Icons.Default.Layers, contentDescription = null, tint = EnergeticYellow, modifier = Modifier.size(16.dp))
                                        Spacer(Modifier.width(6.dp))
                                        Text("ARTBOARD SELECTION (${selectedExportArtboardIds.size}/${artboards.size})", style = Typography.labelSmall, color = TextPrimary, fontWeight = FontWeight.Bold)
                                    }
                                    Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                        TextButton(
                                            onClick = {
                                                selectedExportArtboardIds = artboards.map { it.id }.toSet()
                                            },
                                            contentPadding = PaddingValues(horizontal = 6.dp, vertical = 0.dp)
                                        ) {
                                            Text(
                                                text = "Select All",
                                                style = Typography.labelSmall,
                                                color = if (selectedExportArtboardIds.size == artboards.size) EnergeticYellow else TextSecondary,
                                                fontSize = 11.sp,
                                                fontWeight = if (selectedExportArtboardIds.size == artboards.size) FontWeight.Bold else FontWeight.Normal
                                            )
                                        }
                                        TextButton(
                                            onClick = {
                                                selectedExportArtboardIds = setOf(selectedArtboardId)
                                            },
                                            contentPadding = PaddingValues(horizontal = 6.dp, vertical = 0.dp)
                                        ) {
                                            Text(
                                                text = "Active Only",
                                                style = Typography.labelSmall,
                                                color = if (selectedExportArtboardIds.size == 1 && selectedExportArtboardIds.contains(selectedArtboardId)) EnergeticYellow else TextSecondary,
                                                fontSize = 11.sp,
                                                fontWeight = if (selectedExportArtboardIds.size == 1 && selectedExportArtboardIds.contains(selectedArtboardId)) FontWeight.Bold else FontWeight.Normal
                                            )
                                        }
                                    }
                                }

                                androidx.compose.foundation.lazy.LazyRow(
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    items(artboards.size) { index ->
                                        val art = artboards[index]
                                        val isSelected = selectedExportArtboardIds.contains(art.id)
                                        Surface(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(6.dp))
                                                .border(BorderStroke(1.dp, if (isSelected) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(6.dp))
                                                .clickable {
                                                    val newSet = selectedExportArtboardIds.toMutableSet()
                                                    if (isSelected) {
                                                        if (newSet.size > 1) newSet.remove(art.id)
                                                    } else {
                                                        newSet.add(art.id)
                                                    }
                                                    selectedExportArtboardIds = newSet
                                                },
                                            color = if (isSelected) Color(0xFF00FF66).copy(alpha = 0.15f) else Color(0xFF131317)
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Icon(
                                                    imageVector = if (isSelected) Icons.Default.CheckCircle else Icons.Default.RadioButtonUnchecked,
                                                    contentDescription = null,
                                                    tint = if (isSelected) Color(0xFF00FF66) else TextSecondary,
                                                    modifier = Modifier.size(14.dp)
                                                )
                                                Spacer(Modifier.width(6.dp))
                                                Text(
                                                    text = art.name,
                                                    style = Typography.labelSmall,
                                                    color = if (isSelected) TextPrimary else TextSecondary,
                                                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        // --- ACTIVE CATEGORY PARAMETERS WINDOW ---
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFF131317)),
                            border = BorderStroke(1.dp, HighslateOutline.copy(alpha = 0.5f)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(
                                modifier = Modifier.padding(14.dp),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                val originalW = canvasWidth.toInt()
                                val originalH = canvasHeight.toInt()

                                when (selectedExportFormatCategory) {
                                    "JPEG" -> {
                                        // JPEG Category Controls (TOP CATEGORY)
                                        Text("JPEG Format Parameters (Compressed Image)", style = Typography.labelSmall, color = EnergeticYellow, fontWeight = FontWeight.Bold)

                                        // Quality Slider
                                        Column {
                                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                                Text("JPEG Compression Quality", style = Typography.labelSmall, color = TextPrimary)
                                                Text("${exportJpegQuality.toInt()}% Quality", style = Typography.labelSmall, color = Color(0xFF00FF66), fontWeight = FontWeight.Bold)
                                            }
                                            Slider(
                                                value = exportJpegQuality,
                                                onValueChange = { exportJpegQuality = it },
                                                valueRange = 10f..100f,
                                                colors = SliderDefaults.colors(thumbColor = Color(0xFF00FF66), activeTrackColor = Color(0xFF00FF66))
                                            )
                                        }

                                        // DPI Preset Selection
                                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                            Text("Target DPI (Dots Per Inch)", style = Typography.labelSmall, color = TextSecondary)
                                            Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                                listOf("72 DPI (Web)", "150 DPI (Draft)", "300 DPI (Print)", "600 DPI (Ultra)").forEach { dpi ->
                                                    val isDpiSel = exportDpiPreset == dpi
                                                    Surface(
                                                        modifier = Modifier
                                                            .weight(1f)
                                                            .clip(RoundedCornerShape(6.dp))
                                                            .border(BorderStroke(1.dp, if (isDpiSel) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(6.dp))
                                                            .clickable { exportDpiPreset = dpi },
                                                        color = if (isDpiSel) Color(0xFF1B3B2B) else Color(0xFF1B1B22)
                                                    ) {
                                                        Text(dpi.split(" ")[0], style = Typography.labelSmall, fontSize = 9.sp, color = if (isDpiSel) Color(0xFF00FF66) else TextPrimary, textAlign = TextAlign.Center, modifier = Modifier.padding(vertical = 6.dp))
                                                    }
                                                }
                                            }
                                        }

                                        // Resolution Multipliers
                                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                            Text("Export Resolution Preset", style = Typography.labelSmall, color = TextSecondary)
                                            listOf(
                                                Triple(1.0f, "Standard (1x)", "${originalW}x${originalH}"),
                                                Triple(2.0f, "Quad HD (2x)", "${originalW * 2}x${originalH * 2}"),
                                                Triple(4.0f, "4K / 8K Poster (4x)", "${originalW * 4}x${originalH * 4}")
                                            ).forEach { (mult, label, resStr) ->
                                                val isSelected = exportMultiplier == mult
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .clip(RoundedCornerShape(6.dp))
                                                        .background(if (isSelected) Color(0xFF1B3B2B) else Color(0xFF1B1B22))
                                                        .border(BorderStroke(if (isSelected) 1.5.dp else 1.dp, if (isSelected) Color(0xFF00FF66) else HighslateOutline), RoundedCornerShape(6.dp))
                                                        .clickable { exportMultiplier = mult }
                                                        .padding(horizontal = 10.dp, vertical = 8.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(label, style = Typography.labelSmall, color = if (isSelected) Color(0xFF00FF66) else TextPrimary, fontWeight = FontWeight.Bold)
                                                    Text(resStr, style = Typography.labelSmall, color = TextSecondary, fontSize = 9.sp)
                                                }
                                            }
                                        }

                                        // Color Profile
                                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                            Button(
                                                onClick = { exportIsCmyk = false },
                                                colors = ButtonDefaults.buttonColors(containerColor = if (!exportIsCmyk) Color(0xFF1B3B2B) else Color(0xFF1B1B22)),
                                                border = BorderStroke(1.dp, if (!exportIsCmyk) Color(0xFF00FF66) else HighslateOutline),
                                                modifier = Modifier.weight(1f)
                                            ) {
                                                Text("RGB Screen Profile", style = Typography.labelSmall, fontSize = 9.sp, color = if (!exportIsCmyk) Color(0xFF00FF66) else TextPrimary)
                                            }
                                            Button(
                                                onClick = { exportIsCmyk = true },
                                                colors = ButtonDefaults.buttonColors(containerColor = if (exportIsCmyk) Color(0xFF1B3B2B) else Color(0xFF1B1B22)),
                                                border = BorderStroke(1.dp, if (exportIsCmyk) Color(0xFF00FF66) else HighslateOutline),
                                                modifier = Modifier.weight(1f)
                                            ) {
                                                Text("CMYK Print Ink", style = Typography.labelSmall, fontSize = 9.sp, color = if (exportIsCmyk) Color(0xFF00FF66) else TextPrimary)
                                            }
                                        }

                                        // Export Action Button
                                        Button(
                                            onClick = {
                                                showExportSettingsDialog = false
                                                val targetArts = artboards.filter { selectedExportArtboardIds.contains(it.id) }
                                                executeArtworkExport(targetArts, exportMultiplier, exportIsCmyk, "JPEG")
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF00FF66)),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.fillMaxWidth().height(40.dp).testTag("jpeg_export_button")
                                        ) {
                                            Icon(Icons.Default.Download, contentDescription = null, tint = DarkOnyx, modifier = Modifier.size(16.dp))
                                            Spacer(Modifier.width(6.dp))
                                            Text("EXPORT JPEG IMAGE (${(originalW * exportMultiplier).toInt()}x${(originalH * exportMultiplier).toInt()})", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "PNG" -> {
                                        // PNG Category Controls
                                        Text("PNG Format Parameters (Lossless & Alpha)", style = Typography.labelSmall, color = Color(0xFF29B6F6), fontWeight = FontWeight.Bold)

                                        // Background Transparency Toggle
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clip(RoundedCornerShape(6.dp))
                                                .background(Color(0xFF1B1B22))
                                                .border(BorderStroke(1.dp, HighslateOutline), RoundedCornerShape(6.dp))
                                                .clickable { isBackgroundTransparent = !isBackgroundTransparent }
                                                .padding(horizontal = 10.dp, vertical = 6.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Column {
                                                Text("Alpha Transparency", style = Typography.labelSmall, color = TextPrimary, fontWeight = FontWeight.Bold)
                                                Text("Export transparent PNG canvas", style = Typography.labelSmall, color = TextSecondary, fontSize = 9.sp)
                                            }
                                            androidx.compose.material3.Switch(
                                                checked = isBackgroundTransparent,
                                                onCheckedChange = { isBackgroundTransparent = it },
                                                colors = androidx.compose.material3.SwitchDefaults.colors(checkedThumbColor = Color(0xFF29B6F6), checkedTrackColor = Color(0xFF0D47A1))
                                            )
                                        }

                                        // Resolution Multipliers
                                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                                            Text("Export Resolution Preset", style = Typography.labelSmall, color = TextSecondary)
                                            listOf(
                                                Triple(1.0f, "Standard (1x)", "${originalW}x${originalH}"),
                                                Triple(2.0f, "Quad HD (2x)", "${originalW * 2}x${originalH * 2}"),
                                                Triple(4.0f, "4K / 8K Poster (4x)", "${originalW * 4}x${originalH * 4}")
                                            ).forEach { (mult, label, resStr) ->
                                                val isSelected = exportMultiplier == mult
                                                Row(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .clip(RoundedCornerShape(6.dp))
                                                        .background(if (isSelected) Color(0xFF0D47A1).copy(alpha = 0.4f) else Color(0xFF1B1B22))
                                                        .border(BorderStroke(if (isSelected) 1.5.dp else 1.dp, if (isSelected) Color(0xFF29B6F6) else HighslateOutline), RoundedCornerShape(6.dp))
                                                        .clickable { exportMultiplier = mult }
                                                        .padding(horizontal = 10.dp, vertical = 8.dp),
                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                    verticalAlignment = Alignment.CenterVertically
                                                ) {
                                                    Text(label, style = Typography.labelSmall, color = if (isSelected) Color(0xFF29B6F6) else TextPrimary, fontWeight = FontWeight.Bold)
                                                    Text(resStr, style = Typography.labelSmall, color = TextSecondary, fontSize = 9.sp)
                                                }
                                            }
                                        }

                                        // Export Action Button
                                        Button(
                                            onClick = {
                                                showExportSettingsDialog = false
                                                val targetArts = artboards.filter { selectedExportArtboardIds.contains(it.id) }
                                                executeArtworkExport(targetArts, exportMultiplier, exportIsCmyk, "PNG")
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF29B6F6)),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.fillMaxWidth().height(40.dp).testTag("png_export_button")
                                        ) {
                                            Icon(Icons.Default.Download, contentDescription = null, tint = DarkOnyx, modifier = Modifier.size(16.dp))
                                            Spacer(Modifier.width(6.dp))
                                            Text("EXPORT PNG IMAGE (${(originalW * exportMultiplier).toInt()}x${(originalH * exportMultiplier).toInt()})", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "SVG" -> {
                                        // SVG Category Controls
                                        Text("SVG Vector Format Parameters", style = Typography.labelSmall, color = Color(0xFFE040FB), fontWeight = FontWeight.Bold)

                                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                            Text("Scalable Vector Graphics (SVG 1.1) preserves vector Bézier curves, path nodes, text typography, and SVG shapes perfectly at any resolution.", style = Typography.labelSmall, color = TextSecondary, fontSize = 9.5.sp)

                                            Row(
                                                modifier = Modifier.fillMaxWidth().background(Color(0xFF1B1B22), RoundedCornerShape(6.dp)).padding(10.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text("Vector Precision:", style = Typography.labelSmall, color = TextPrimary)
                                                Text("High (Sub-pixel 0.5px)", style = Typography.labelSmall, color = Color(0xFFE040FB), fontWeight = FontWeight.Bold)
                                            }

                                            Row(
                                                modifier = Modifier.fillMaxWidth().background(Color(0xFF1B1B22), RoundedCornerShape(6.dp)).padding(10.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text("Canvas Bounds:", style = Typography.labelSmall, color = TextPrimary)
                                                Text("${originalW} x ${originalH} px", style = Typography.labelSmall, color = TextSecondary)
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                showExportSettingsDialog = false
                                                val targetArts = artboards.filter { selectedExportArtboardIds.contains(it.id) }
                                                executeSvgExport(targetArts)
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFE040FB)),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.fillMaxWidth().height(40.dp).testTag("svg_export_button")
                                        ) {
                                            Icon(Icons.Default.Download, contentDescription = null, tint = Color.White, modifier = Modifier.size(16.dp))
                                            Spacer(Modifier.width(6.dp))
                                            Text("EXPORT VECTOR SVG", style = Typography.labelSmall, color = Color.White, fontWeight = FontWeight.Bold)
                                        }
                                    }

                                    "PDF" -> {
                                        // PDF Category Controls
                                        Text("PDF Document Format Parameters", style = Typography.labelSmall, color = Color(0xFFFF5722), fontWeight = FontWeight.Bold)

                                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                            Text("Print-ready PDF document format with embedded high-resolution graphics, target DPI metadata, and color profile tags.", style = Typography.labelSmall, color = TextSecondary, fontSize = 9.5.sp)

                                            Row(
                                                modifier = Modifier.fillMaxWidth().background(Color(0xFF1B1B22), RoundedCornerShape(6.dp)).padding(10.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text("Document Page Size:", style = Typography.labelSmall, color = TextPrimary)
                                                Text("Fit Canvas (${originalW}x${originalH})", style = Typography.labelSmall, color = Color(0xFFFF5722), fontWeight = FontWeight.Bold)
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                showExportSettingsDialog = false
                                                val targetArts = artboards.filter { selectedExportArtboardIds.contains(it.id) }
                                                executePdfExport(targetArts)
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFFF5722)),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.fillMaxWidth().height(40.dp).testTag("pdf_export_button")
                                        ) {
                                            Icon(Icons.Default.Download, contentDescription = null, tint = Color.White, modifier = Modifier.size(16.dp))
                                            Spacer(Modifier.width(6.dp))
                                            Text("EXPORT PRINT PDF DOCUMENT", style = Typography.labelSmall, color = Color.White, fontWeight = FontWeight.Bold)
                                        }
                                    }


                                    else -> {
                                        // ALIGHT XML Category Controls
                                        Text("Alight Motion XML Layout Parameters", style = Typography.labelSmall, color = Color(0xFF78909C), fontWeight = FontWeight.Bold)

                                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                            Text("Exports project scene geometry, keyframes, layers, and visual FX directly into Alight Motion compatible XML template format.", style = Typography.labelSmall, color = TextSecondary, fontSize = 9.5.sp)

                                            Row(
                                                modifier = Modifier.fillMaxWidth().background(Color(0xFF1B1B22), RoundedCornerShape(6.dp)).padding(10.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text("Target Frame Rate:", style = Typography.labelSmall, color = TextPrimary)
                                                Text("30 FPS / 60 FPS Dynamic", style = Typography.labelSmall, color = Color(0xFF78909C), fontWeight = FontWeight.Bold)
                                            }
                                        }

                                        Button(
                                            onClick = {
                                                showExportSettingsDialog = false
                                                val targetArts = artboards.filter { selectedExportArtboardIds.contains(it.id) }
                                                executeAlightXmlExport(targetArts)
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF78909C)),
                                            shape = RoundedCornerShape(8.dp),
                                            modifier = Modifier.fillMaxWidth().height(40.dp).testTag("alight_export_button")
                                        ) {
                                            Icon(Icons.Default.Download, contentDescription = null, tint = Color.White, modifier = Modifier.size(16.dp))
                                            Spacer(Modifier.width(6.dp))
                                            Text("EXPORT ALIGHT MOTION XML", style = Typography.labelSmall, color = Color.White, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
                confirmButton = {},
                dismissButton = {
                    TextButton(onClick = { showExportSettingsDialog = false }) {
                        Text("Close", style = Typography.labelSmall, color = TextSecondary)
                    }
                },
                containerColor = SlatePanel
            )
        }

        // --- HOVER ACTIVE GRADIENT STOP COLOR PICKER OVERLAY ---
        if (showGradientColorPickerDialog && selectedLayer != null && activeGradientStopIndex != -1) {
            val idx = activeGradientStopIndex
            val gradOverlay = selectedLayer.effects.find { it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? StudioEffect.PhotoshopEffect
            if (gradOverlay != null) {
                val rKey = "CustomStop_${idx}_R"
                val gKey = "CustomStop_${idx}_G"
                val bKey = "CustomStop_${idx}_B"
                val aKey = "CustomStop_${idx}_A"
                val posKey = "CustomStop_${idx}_Pos"

                val rVal = gradOverlay.parameters[rKey]?.value ?: when(idx) {
                    0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                    1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                    else -> 0.5f
                }
                val gVal = gradOverlay.parameters[gKey]?.value ?: when(idx) {
                    0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                    else -> 0.5f
                }
                val bVal = gradOverlay.parameters[bKey]?.value ?: when(idx) {
                    0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                    else -> 0.5f
                }
                val aVal = gradOverlay.parameters[aKey]?.value ?: 1.0f
                val posVal = gradOverlay.parameters[posKey]?.value ?: (idx.toFloat() / ((gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt() - 1).coerceAtLeast(1))

                var r by remember(idx, selectedLayerId) { mutableStateOf(rVal) }
                var g by remember(idx, selectedLayerId) { mutableStateOf(gVal) }
                var b by remember(idx, selectedLayerId) { mutableStateOf(bVal) }
                var alpha by remember(idx, selectedLayerId) { mutableStateOf(aVal) }
                var stopPos by remember(idx, selectedLayerId) { mutableStateOf(posVal) }

                var hsv by remember(r, g, b) {
                    val hsvArr = FloatArray(3)
                    android.graphics.Color.RGBToHSV((r * 255).toInt(), (g * 255).toInt(), (b * 255).toInt(), hsvArr)
                    mutableStateOf(Triple(hsvArr[0], hsvArr[1], hsvArr[2]))
                }

                AlertDialog(
                    onDismissRequest = { showGradientColorPickerDialog = false },
                    title = {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(imageVector = Icons.Default.Palette, contentDescription = null, tint = IndustrialAmber, modifier = Modifier.size(24.dp))
                            Spacer(Modifier.width(8.dp))
                            Text("Edit Stop Node #${idx + 1}", style = Typography.titleMedium, color = TextPrimary)
                        }
                    },
                    text = {
                        Column(
                            verticalArrangement = Arrangement.spacedBy(14.dp),
                            horizontalAlignment = Alignment.CenterHorizontally,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(12.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(60.dp)
                                        .clip(RoundedCornerShape(8.dp))
                                        .drawBehind {
                                            val cellSize = 8.dp.toPx()
                                            for (x in 0 until (size.width / cellSize).toInt() + 1) {
                                                for (y in 0 until (size.height / cellSize).toInt() + 1) {
                                                    val color = if ((x + y) % 2 == 0) Color(0xFFD0D0D4) else Color(0xFFFFFFFF)
                                                    drawRect(
                                                        color = color,
                                                        topLeft = Offset(x * cellSize, y * cellSize),
                                                        size = Size(cellSize, cellSize)
                                                    )
                                                }
                                            }
                                        }
                                        .background(Color(r, g, b, alpha))
                                        .border(1.dp, Color(0x33FFFFFF), RoundedCornerShape(8.dp))
                                )
                                Column(
                                    verticalArrangement = Arrangement.spacedBy(4.dp),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    val hexCode = String.format("#%02X%02X%02X%02X", (alpha * 255).toInt(), (r * 255).toInt(), (g * 255).toInt(), (b * 255).toInt())
                                    var hexInputState by remember(hexCode) { mutableStateOf(hexCode) }
                                    val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current
                                    val context = androidx.compose.ui.platform.LocalContext.current

                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        androidx.compose.foundation.text.BasicTextField(
                                            value = hexInputState,
                                            onValueChange = { newVal ->
                                                hexInputState = newVal
                                                val parsed = parseHexColor(newVal)
                                                if (parsed != null) {
                                                    r = parsed.red
                                                    g = parsed.green
                                                    b = parsed.blue
                                                    if (newVal.trim().replace("#", "").length == 8) {
                                                        alpha = parsed.alpha
                                                    }
                                                }
                                            },
                                            textStyle = Typography.labelSmall.copy(
                                                fontSize = 10.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = Color.White
                                            ),
                                            singleLine = true,
                                            modifier = Modifier
                                                .weight(1f)
                                                .background(Color(0xFF1E1E24), RoundedCornerShape(4.dp))
                                                .padding(vertical = 4.dp, horizontal = 6.dp)
                                        )

                                        IconButton(
                                            onClick = {
                                                clipboardManager.setText(androidx.compose.ui.text.AnnotatedString(hexCode))
                                                android.widget.Toast.makeText(context, "Copied: $hexCode", android.widget.Toast.LENGTH_SHORT).show()
                                            },
                                            modifier = Modifier.size(20.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.ContentCopy,
                                                contentDescription = "Copy Hex",
                                                tint = Color.LightGray,
                                                modifier = Modifier.size(11.dp)
                                            )
                                        }

                                        IconButton(
                                            onClick = {
                                                val pasted = clipboardManager.getText()?.text
                                                if (pasted != null) {
                                                    val parsed = parseHexColor(pasted)
                                                    if (parsed != null) {
                                                        r = parsed.red
                                                        g = parsed.green
                                                        b = parsed.blue
                                                        if (pasted.trim().replace("#", "").length == 8) {
                                                            alpha = parsed.alpha
                                                        }
                                                        hexInputState = pasted
                                                        android.widget.Toast.makeText(context, "Hex pasted!", android.widget.Toast.LENGTH_SHORT).show()
                                                    } else {
                                                        android.widget.Toast.makeText(context, "Invalid Hex format", android.widget.Toast.LENGTH_SHORT).show()
                                                    }
                                                }
                                            },
                                            modifier = Modifier.size(20.dp)
                                        ) {
                                            Icon(
                                                imageVector = Icons.Default.ContentPaste,
                                                contentDescription = "Paste Hex",
                                                tint = Color.LightGray,
                                                modifier = Modifier.size(11.dp)
                                            )
                                        }
                                    }
                                    Text("Position: ${(stopPos * 100).toInt()}%", style = Typography.labelSmall, color = TextSecondary)
                                }
                                
                                Button(
                                    onClick = {
                                        GradientEyedropperState.isActive = true
                                        showGradientColorPickerDialog = false
                                    },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (GradientEyedropperState.isActive) IndustrialAmber else Color(0xFF161622)
                                    ),
                                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 6.dp),
                                    modifier = Modifier.height(32.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Colorize,
                                        contentDescription = "Canvas Eyedropper",
                                        tint = if (GradientEyedropperState.isActive) Color.Black else Color.White,
                                        modifier = Modifier.size(13.dp)
                                    )
                                    Spacer(Modifier.width(4.dp))
                                    Text("Sample Canvas", style = Typography.labelSmall.copy(fontSize = 10.sp), color = if (GradientEyedropperState.isActive) Color.Black else Color.White)
                                }
                            }

                            Box(
                                modifier = Modifier
                                    .size(150.dp)
                                    .clip(CircleShape)
                                    .border(1.dp, HighslateOutline, CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Canvas(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .pointerInput(idx) {
                                            detectTapGestures { offset ->
                                                val centerX = size.width / 2f
                                                val centerY = size.height / 2f
                                                val dx = offset.x - centerX
                                                val dy = offset.y - centerY
                                                val dist = kotlin.math.sqrt(dx * dx + dy * dy)
                                                val maxRadius = size.width / 2f
                                                if (dist <= maxRadius) {
                                                    val angleRad = kotlin.math.atan2(dy, dx)
                                                    val angleDeg = (Math.toDegrees(angleRad.toDouble()).toFloat() + 360f) % 360f
                                                    val sat = (dist / maxRadius).coerceIn(0f, 1f)
                                                    hsv = Triple(angleDeg, sat, hsv.third)
                                                    
                                                    val rgbInt = android.graphics.Color.HSVToColor(floatArrayOf(hsv.first, hsv.second, hsv.third))
                                                    r = android.graphics.Color.red(rgbInt) / 255f
                                                    g = android.graphics.Color.green(rgbInt) / 255f
                                                    b = android.graphics.Color.blue(rgbInt) / 255f
                                                }
                                            }
                                        }
                                        .pointerInput(idx) {
                                            detectDragGestures { change, _ ->
                                                val centerX = size.width / 2f
                                                val centerY = size.height / 2f
                                                val dx = change.position.x - centerX
                                                val dy = change.position.y - centerY
                                                val dist = kotlin.math.sqrt(dx * dx + dy * dy)
                                                val maxRadius = size.width / 2f
                                                val angleRad = kotlin.math.atan2(dy, dx)
                                                val angleDeg = (Math.toDegrees(angleRad.toDouble()).toFloat() + 360f) % 360f
                                                val sat = (dist / maxRadius).coerceIn(0f, 1f)
                                                hsv = Triple(angleDeg, sat, hsv.third)

                                                val rgbInt = android.graphics.Color.HSVToColor(floatArrayOf(hsv.first, hsv.second, hsv.third))
                                                r = android.graphics.Color.red(rgbInt) / 255f
                                                g = android.graphics.Color.green(rgbInt) / 255f
                                                b = android.graphics.Color.blue(rgbInt) / 255f
                                            }
                                        }
                                ) {
                                    val centerX = size.width / 2f
                                    val centerY = size.height / 2f
                                    val radius = size.width / 2f
                                    
                                    val sweepBrush = androidx.compose.ui.graphics.Brush.sweepGradient(
                                        colors = listOf(
                                            Color.Red, Color.Yellow, Color.Green, Color.Cyan, Color.Blue, Color.Magenta, Color.Red
                                        ),
                                        center = Offset(centerX, centerY)
                                    )
                                    drawCircle(brush = sweepBrush, radius = radius)
                                    
                                    val radialBrush = androidx.compose.ui.graphics.Brush.radialGradient(
                                        colors = listOf(Color.White, Color.Transparent),
                                        center = Offset(centerX, centerY),
                                        radius = radius
                                    )
                                    drawCircle(brush = radialBrush, radius = radius)

                                    val handleAngleRad = Math.toRadians(hsv.first.toDouble())
                                    val handleDist = hsv.second * radius
                                    val handleX = centerX + handleDist * kotlin.math.cos(handleAngleRad).toFloat()
                                    val handleY = centerY + handleDist * kotlin.math.sin(handleAngleRad).toFloat()
                                    
                                    drawCircle(
                                        color = Color.Black,
                                        radius = 7.dp.toPx(),
                                        center = Offset(handleX, handleY)
                                    )
                                    drawCircle(
                                        color = Color.White,
                                        radius = 5.dp.toPx(),
                                        center = Offset(handleX, handleY)
                                    )
                                }
                            }

                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Brightness (Value)", style = Typography.labelSmall, color = TextSecondary)
                                    Text("${(hsv.third * 100).toInt()}%", style = Typography.labelSmall, color = TextPrimary)
                                }
                                Slider(
                                    value = hsv.third,
                                    onValueChange = { newVal ->
                                        hsv = Triple(hsv.first, hsv.second, newVal)
                                        val rgbInt = android.graphics.Color.HSVToColor(floatArrayOf(hsv.first, hsv.second, hsv.third))
                                        r = android.graphics.Color.red(rgbInt) / 255f
                                        g = android.graphics.Color.green(rgbInt) / 255f
                                        b = android.graphics.Color.blue(rgbInt) / 255f
                                    },
                                    valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(
                                        activeTrackColor = IndustrialAmber,
                                        thumbColor = Color.White
                                    )
                                )
                            }

                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Opacity (Stop Alpha)", style = Typography.labelSmall, color = TextSecondary)
                                    Text("${(alpha * 100).toInt()}%", style = Typography.labelSmall, color = TextPrimary)
                                }
                                Slider(
                                    value = alpha,
                                    onValueChange = { alpha = it },
                                    valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(
                                        activeTrackColor = IndustrialAmber,
                                        thumbColor = Color.White
                                    )
                                )
                            }

                            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Stop Position along line", style = Typography.labelSmall, color = TextSecondary)
                                    Text("${(stopPos * 100).toInt()}%", style = Typography.labelSmall, color = TextPrimary)
                                }
                                Slider(
                                    value = stopPos,
                                    onValueChange = { stopPos = it },
                                    valueRange = 0f..1f,
                                    colors = SliderDefaults.colors(
                                        activeTrackColor = EnergeticYellow,
                                        thumbColor = Color.White
                                    )
                                )
                            }
                        }
                    },
                    confirmButton = {
                        TextButton(
                            onClick = {
                                val updatedGo = gradOverlay.updateParameter("CustomStop_${idx}_R", r)
                                    .updateParameter("CustomStop_${idx}_G", g)
                                    .updateParameter("CustomStop_${idx}_B", b)
                                    .updateParameter("CustomStop_${idx}_A", alpha)
                                    .updateParameter("CustomStop_${idx}_Pos", stopPos)
                                
                                val nextEffects = selectedLayer.effects.map { if (it.id == gradOverlay.id) updatedGo else it }
                                val updatedLayer = selectedLayer.copy(effects = nextEffects)
                                
                                undoStack.add(layers)
                                redoStack.clear()
                                layers = layers.map { if (it.id == selectedLayer.id) updatedLayer else it }
                                showGradientColorPickerDialog = false
                            }
                        ) {
                            Text("Apply Aesthetics", color = EnergeticYellow, style = Typography.labelSmall)
                        }
                    },
                    dismissButton = {
                        TextButton(onClick = { showGradientColorPickerDialog = false }) {
                            Text("Cancel", color = TextSecondary, style = Typography.labelSmall)
                        }
                    },
                    containerColor = SlatePanel
                )
            }
        }

        // --- CENTRAL IMPORT OPTIONS MENU ---
        if (showElementsImportDialog) {
        var elementsList by remember { mutableStateOf<List<com.example.studio.model.StudioLayer>>(emptyList()) }
        LaunchedEffect(Unit) {
            elementsList = com.example.studio.model.ElementsManager.loadElements(context)
        }
        AlertDialog(
            onDismissRequest = { showElementsImportDialog = false },
            containerColor = Color(0xFF1E1E24),
            title = { Text("Import Element", color = TextPrimary, style = Typography.titleMedium) },
            text = {
                if (elementsList.isEmpty()) {
                    Text("No saved elements found.", color = TextSecondary)
                } else {
                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        elementsList.forEach { element ->
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        undoStack.add(layers)
                                        redoStack.clear()
                                        val newElement = element.copy(id = java.util.UUID.randomUUID().toString())
                                        layers = layers + newElement
                                        showElementsImportDialog = false
                                    },
                                colors = CardDefaults.cardColors(containerColor = SlatePanel.copy(alpha = 0.85f)),
                                shape = RoundedCornerShape(8.dp)
                            ) {
                                Row(
                                    modifier = Modifier.padding(12.dp).fillMaxWidth(),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(Icons.Default.Extension, contentDescription = null, tint = IndustrialAmber)
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Column {
                                        Text(element.name, color = TextPrimary, style = Typography.bodyMedium)
                                        Text(element.type.name, color = TextSecondary, style = Typography.labelSmall)
                                    }
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                TextButton(onClick = { showElementsImportDialog = false }) {
                    Text("Cancel", color = TextSecondary)
                }
            }
        )
    }

    if (showImportOptionMenu) {
            AlertDialog(
                onDismissRequest = { showImportOptionMenu = false },
                title = {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Icon(Icons.Default.CloudDownload, contentDescription = null, tint = EnergeticYellow)
                        Text("Dynamic Asset Import Hub", style = Typography.titleMedium, color = TextPrimary)
                    }
                },
                text = {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Text(
                            "Select an import protocol to enrich your canvas workspace:",
                            style = Typography.bodyMedium,
                            color = TextSecondary,
                            modifier = Modifier.padding(bottom = 6.dp)
                        )

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    imagePickerLauncher.launch("image/*")
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Icon(Icons.Default.Image, contentDescription = null, tint = Color(0xFF29B6F6), modifier = Modifier.size(24.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Device Photos & Gallery", style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text("Import PNG, JPEG, or WEBP layers from your device's image gallery.", style = Typography.labelSmall, color = TextSecondary)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    showElementsImportDialog = true
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Icon(Icons.Default.Extension, contentDescription = null, tint = IndustrialAmber, modifier = Modifier.size(24.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Import from Elements", style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text("Import saved vector elements into your current project.", style = Typography.labelSmall, color = TextSecondary)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    showPngSearchOverlay = true
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Icon(Icons.Default.CloudSync, contentDescription = null, tint = EnergeticYellow, modifier = Modifier.size(24.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Import PNGs from the web", style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text("Search & download transparent PNG elements from across the web.", style = Typography.labelSmall, color = TextSecondary)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    showWebBrowserOverlay = true
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Icon(Icons.Default.Language, contentDescription = null, tint = EnergeticYellow, modifier = Modifier.size(24.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Import from Web / Stock Assets", style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text("Search & Download Stock Photos, Google Fonts, or type asset URLs.", style = Typography.labelSmall, color = TextSecondary)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    pdfLauncher.launch("application/pdf")
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Icon(Icons.Default.PictureAsPdf, contentDescription = null, tint = Color(0xFFFF5722), modifier = Modifier.size(24.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("📄 High-Fidelity PDF Artboards", style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text("Convert PDF pages into active individual project artboards.", style = Typography.labelSmall, color = TextSecondary)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    alightXmlPickerLauncher.launch("*/*")
                                }
                                .padding(12.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Icon(Icons.Default.Code, contentDescription = null, tint = Color(0xFF00FF66), modifier = Modifier.size(24.dp))
                            Column(modifier = Modifier.weight(1f)) {
                                Text("Alight Motion XML Layout", style = Typography.bodyMedium, color = TextPrimary, fontWeight = FontWeight.Bold)
                                Text("Import and rebuild dynamic vectors and compositions.", style = Typography.labelSmall, color = TextSecondary)
                            }
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(Color(0xFF1E1E24))
                                .clickable {
                                    showImportOptionMenu = false
                                    svgPickerLauncher.launch("image/svg+xml")
                                }
                                .padding(12.dp)
