val DefaultShapeGrey = Color(0xFFB5B5B5)

@Composable
fun MiniShapePreview(type: LayerType, color: Color = DefaultShapeGrey, modifier: Modifier = Modifier) {
    Canvas(modifier = modifier) {
        val w = size.width
        val h = size.height
        val cx = w / 2f
        val cy = h / 2f

        when (type) {
            LayerType.VECTOR_CIRCLE -> {
                drawCircle(color = color, radius = minOf(w, h) / 2f, center = Offset(cx, cy))
            }
            LayerType.VECTOR_OVAL -> {
                drawOval(color = color, topLeft = Offset.Zero, size = Size(w, h))
            }
            LayerType.VECTOR_RECT -> {
                drawRect(color = color, topLeft = Offset.Zero, size = Size(w, h))
            }
            LayerType.VECTOR_ROUNDED_RECT -> {
                drawRoundRect(
                    color = color,
                    topLeft = Offset.Zero,
                    size = Size(w, h),
                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(minOf(w, h) * 0.15f)
                )
            }
            LayerType.VECTOR_LINE -> {
                drawLine(color = color, start = Offset.Zero, end = Offset(w, h), strokeWidth = minOf(w, h) * 0.15f)
            }
            LayerType.VECTOR_TRIANGLE -> {
                val path = Path().apply {
                    val edges = 3
                    val rx = w / 2f
                    val ry = h / 2f
                    for (i in 0 until edges) {
                        val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                        val x = (cx + rx * Math.cos(angle)).toFloat()
                        val y = (cy + ry * Math.sin(angle)).toFloat()
                        if (i == 0) moveTo(x, y) else lineTo(x, y)
                    }
                    close()
                }
                drawPath(path, color)
            }
            LayerType.VECTOR_PENTAGON -> {
                val path = Path().apply {
                    val edges = 5
                    val rx = w / 2f
                    val ry = h / 2f
                    for (i in 0 until edges) {
                        val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                        val x = (cx + rx * Math.cos(angle)).toFloat()
                        val y = (cy + ry * Math.sin(angle)).toFloat()
                        if (i == 0) moveTo(x, y) else lineTo(x, y)
                    }
                    close()
                }
                drawPath(path, color)
            }
            LayerType.VECTOR_HEXAGON -> {
                val path = Path().apply {
                    val edges = 6
                    val rx = w / 2f
                    val ry = h / 2f
                    for (i in 0 until edges) {
                        val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                        val x = (cx + rx * Math.cos(angle)).toFloat()
                        val y = (cy + ry * Math.sin(angle)).toFloat()
                        if (i == 0) moveTo(x, y) else lineTo(x, y)
                    }
                    close()
                }
                drawPath(path, color)
            }
            LayerType.VECTOR_STAR -> {
                val path = Path().apply {
                    val rOuter = w / 2f
                    val rInner = rOuter * 0.4f
                    val pointsCount = 5
                    var angle = Math.PI / 2.0 * 3.0
                    val step = Math.PI / pointsCount
                    moveTo((cx + Math.cos(angle) * rOuter).toFloat(), (cy + Math.sin(angle) * rOuter).toFloat())
                    for (i in 0..(pointsCount * 2)) {
                        val r = if (i % 2 == 0) rOuter else rInner
                        lineTo((cx + Math.cos(angle) * r).toFloat(), (cy + Math.sin(angle) * r).toFloat())
                        angle += step
                    }
                    close()
                }
                drawPath(path, color)
            }
            else -> {
                val path = createComplexShapePath(type, w, h, polygonEdges = 5, starInnerRadiusRatio = 0.4f)
                drawPath(path, color)
            }
        }
    }
}

        // Vector Shape addition overlay
        if (showAddShapeDialog) {
