// Helpers to compute rendering effects output representation dynamically in canvas
fun getBlurRadius(layer: StudioLayer): Float {
    if (isThermalThrottleActive) return 0f // Temporarily bypass expensive multi-draw blur rendering under hardware thermal strain
    val blurEff = layer.effects.firstOrNull { it is StudioEffect.GaussianBlur } as? StudioEffect.GaussianBlur
    if (blurEff != null) {
        return (blurEff.parameters["Radius"]?.value ?: 0f) * (blurEff.parameters["Intensity"]?.value ?: 1f)
    }
    val psBlur = layer.effects.firstOrNull {
        it is StudioEffect.PhotoshopEffect && (it.effectType == "GaussianBlur" || it.effectType == "MotionBlur" || it.effectType == "LensBlur")
    } as? StudioEffect.PhotoshopEffect
    if (psBlur != null) {
        val radius = psBlur.parameters["Radius"]?.value ?: psBlur.parameters["Distance"]?.value ?: 12f
        val intensity = psBlur.parameters["Intensity"]?.value ?: 0.8f
        return radius * intensity * 0.5f
    }
    return 0f
}

fun getEffectGradientShader(prefix: String, effect: com.example.studio.model.StudioEffect.PhotoshopEffect, width: Float, height: Float): android.graphics.Shader? {
    val gradEnabled = (effect.parameters["${prefix}_Grad_Enabled"]?.value ?: 0f) > 0.5f
    if (!gradEnabled) return null

    val r1 = effect.parameters["${prefix}_Grad_R1"]?.value ?: 1f
    val g1 = effect.parameters["${prefix}_Grad_G1"]?.value ?: 1f
    val b1 = effect.parameters["${prefix}_Grad_B1"]?.value ?: 1f
    val a1 = effect.parameters["${prefix}_Grad_A1"]?.value ?: 1f

    val r2 = effect.parameters["${prefix}_Grad_R2"]?.value ?: 0f
    val g2 = effect.parameters["${prefix}_Grad_G2"]?.value ?: 0f
    val b2 = effect.parameters["${prefix}_Grad_B2"]?.value ?: 0f
    val a2 = effect.parameters["${prefix}_Grad_A2"]?.value ?: 1f

    val angle = effect.parameters["${prefix}_Grad_Angle"]?.value ?: 90f

    val rads = Math.toRadians(angle.toDouble())
    val cos = Math.cos(rads).toFloat()
    val sin = Math.sin(rads).toFloat()

    val startX = width / 2f - (width / 2f * cos)
    val startY = height / 2f - (height / 2f * sin)
    val endX = width / 2f + (width / 2f * cos)
    val endY = height / 2f + (height / 2f * sin)

    val color1 = android.graphics.Color.argb((a1 * 255).toInt().coerceIn(0, 255), (r1 * 255).toInt().coerceIn(0, 255), (g1 * 255).toInt().coerceIn(0, 255), (b1 * 255).toInt().coerceIn(0, 255))
    val color2 = android.graphics.Color.argb((a2 * 255).toInt().coerceIn(0, 255), (r2 * 255).toInt().coerceIn(0, 255), (g2 * 255).toInt().coerceIn(0, 255), (b2 * 255).toInt().coerceIn(0, 255))

    return android.graphics.LinearGradient(
        startX, startY, endX, endY,
        intArrayOf(color1, color2),
        floatArrayOf(0f, 1f),
        android.graphics.Shader.TileMode.CLAMP
    )
}

fun getGlowIntensity(layer: StudioLayer): Float {
    val glowEff = layer.effects.firstOrNull { it is StudioEffect.InnerGlow } as? StudioEffect.InnerGlow
    if (glowEff != null) {
        return (glowEff.parameters["Choke"]?.value ?: 0f) * (glowEff.parameters["Opacity"]?.value ?: 1f)
    }
    val psGlow = layer.effects.firstOrNull {
        it is StudioEffect.PhotoshopEffect && (it.effectType == "InnerGlow" || it.effectType == "OuterGlow" || it.effectType == "DropShadow" || it.effectType == "InnerShadow")
    } as? StudioEffect.PhotoshopEffect
    if (psGlow != null) {
        val chokeOrSize = psGlow.parameters["Choke"]?.value ?: psGlow.parameters["Size"]?.value ?: psGlow.parameters["Spread"]?.value ?: 15f
        val opacity = psGlow.parameters["Opacity"]?.value ?: 0.65f
        return chokeOrSize * opacity * 0.5f
    }
    return 0f
}

fun getHueShiftMultiplier(layer: StudioLayer): Float {
    val hueEff = layer.effects.firstOrNull { it is StudioEffect.ColorBalance } as? StudioEffect.ColorBalance
    if (hueEff != null) {
        return hueEff.parameters["HueShift"]?.value ?: 0f
    }
    val psHue = layer.effects.firstOrNull {
        it is StudioEffect.PhotoshopEffect && (it.effectType == "ColorOverlay" || it.effectType == "CameraRaw")
    } as? StudioEffect.PhotoshopEffect
    if (psHue != null) {
        return psHue.parameters["HueShift"]?.value ?: 0f
    }
    return 0f
}

private val hsvBufferLocal = object : ThreadLocal<FloatArray>() {
    override fun initialValue() = FloatArray(3)
}
private val rgbBufferLocal = object : ThreadLocal<FloatArray>() {
    override fun initialValue() = FloatArray(3)
}

private fun hsvToRgbBuffer(h: Float, s: Float, v: Float, dest: FloatArray) {
    val c = v * s
    val x = c * (1f - Math.abs((h / 60f) % 2f - 1f))
    val m = v - c

    var r1 = 0f
    var g1 = 0f
    var b1 = 0f

    val normH = (h % 360f + 360f) % 360f

    when {
        normH >= 0f && normH < 60f -> { r1 = c; g1 = x; b1 = 0f }
        normH >= 60f && normH < 120f -> { r1 = x; g1 = c; b1 = 0f }
        normH >= 120f && normH < 180f -> { r1 = 0f; g1 = c; b1 = x }
        normH >= 180f && normH < 240f -> { r1 = 0f; g1 = x; b1 = c }
        normH >= 240f && normH < 300f -> { r1 = x; g1 = 0f; b1 = c }
        normH >= 300f && normH <= 360f -> { r1 = c; g1 = 0f; b1 = x }
    }

    dest[0] = (r1 + m).coerceIn(0f, 1f)
    dest[1] = (g1 + m).coerceIn(0f, 1f)
    dest[2] = (b1 + m).coerceIn(0f, 1f)
}

private fun rgbToHsv(r: Float, g: Float, b: Float, hsv: FloatArray) {
    val max = maxOf(r, maxOf(g, b))
    val min = minOf(r, minOf(g, b))
    val delta = max - min

    var h = 0f
    val s = if (max == 0f) 0f else delta / max
    val v = max

    if (delta > 0f) {
        h = when (max) {
            r -> ((g - b) / delta) % 6f
            g -> ((b - r) / delta) + 2f
            else -> ((r - g) / delta) + 4f
        }
        h *= 60f
        if (h < 0f) h += 360f
    }
    hsv[0] = h
    hsv[1] = s
    hsv[2] = v
}

private fun hsvToRgb(h: Float, s: Float, v: Float): FloatArray {
    val c = v * s
    val x = c * (1f - Math.abs((h / 60f) % 2f - 1f))
    val m = v - c

    var r1 = 0f
    var g1 = 0f
    var b1 = 0f

    val normH = (h % 360f + 360f) % 360f

    when {
        normH >= 0f && normH < 60f -> { r1 = c; g1 = x; b1 = 0f }
        normH >= 60f && normH < 120f -> { r1 = x; g1 = c; b1 = 0f }
        normH >= 120f && normH < 180f -> { r1 = 0f; g1 = c; b1 = x }
        normH >= 180f && normH < 240f -> { r1 = 0f; g1 = x; b1 = c }
        normH >= 240f && normH < 300f -> { r1 = x; g1 = 0f; b1 = c }
        normH >= 300f && normH <= 360f -> { r1 = c; g1 = 0f; b1 = x }
    }

    return floatArrayOf(
        (r1 + m).coerceIn(0f, 1f),
        (g1 + m).coerceIn(0f, 1f),
        (b1 + m).coerceIn(0f, 1f)
    )
}

data class GradientStop(val index: Int, val color: Color)

@Composable
fun GradientPickerPanel(
    selectedLayer: StudioLayer?,
    onUpdateLayer: ((StudioLayer) -> Unit)?,
    modifier: Modifier = Modifier,
    onOpenColorPickerDialog: ((Int) -> Unit)? = null
) {
    val isGradientEyedropperActive = GradientEyedropperState.isActive
    val onToggleGradientEyedropper: ((Boolean) -> Unit) = { GradientEyedropperState.isActive = it }

    val gradOverlay = remember(selectedLayer) {
        selectedLayer?.effects?.find { it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? StudioEffect.PhotoshopEffect
    }

    if (selectedLayer == null || onUpdateLayer == null || gradOverlay == null) {
        Box(
            modifier = modifier.fillMaxSize(),
            contentAlignment = Alignment.Center
        ) {
            Text(
                "Select any visual layer to apply gradients!",
                style = Typography.labelSmall,
                color = Color.LightGray,
                textAlign = TextAlign.Center
            )
        }
        return
    }

    val goPreset = gradOverlay.parameters["Preset"]?.value ?: 0f
    val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
    val goScale = gradOverlay.parameters["Scale"]?.value ?: 100f
    val goOpacity = gradOverlay.parameters["Opacity"]?.value ?: 1.0f
    val gradientTypeOrdinal = (gradOverlay.parameters["GradientType"]?.value ?: 0f).toInt().coerceIn(0, 6)

    val updateParam = { key: String, newVal: Float ->
        val updatedGo = gradOverlay.updateParameter(key, newVal)
        val nextEffects = selectedLayer.effects.map { if (it.id == gradOverlay.id) updatedGo else it }
        onUpdateLayer(selectedLayer.copy(effects = nextEffects))
    }

    // Interactive local states for buttery smooth 60fps slider drags (resolves all lagging issues)
    var localAngle by remember(goAngle) { mutableStateOf(goAngle) }
    var localScale by remember(goScale) { mutableStateOf(goScale) }
    var localOpacity by remember(goOpacity) { mutableStateOf(goOpacity) }

    val isCustomMode = true
    val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
    val selectedStopIndex = (gradOverlay.parameters["SelectedStopIndex"]?.value ?: 0f).toInt().coerceAtLeast(0)
    var activeStopIndex by remember(selectedLayer.id, selectedStopIndex) { mutableStateOf(selectedStopIndex.coerceAtMost(stopCount - 1)) }

    // Assemble modern list of custom colors supporting individual stop alpha
    val customColorsList = mutableListOf<androidx.compose.ui.graphics.Color>()
    for (idx in 0 until stopCount) {
        val rKey = "CustomStop_${idx}_R"
        val gKey = "CustomStop_${idx}_G"
        val bKey = "CustomStop_${idx}_B"
        val aKey = "CustomStop_${idx}_A"
        val r = gradOverlay.parameters[rKey]?.value ?: when(idx) {
            0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
            1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
            2 -> 0.0f
            3 -> 1.0f
            4 -> 1.0f
            else -> 0.5f
        }
        val g = gradOverlay.parameters[gKey]?.value ?: when(idx) {
            0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
            1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
            2 -> 1.0f
            3 -> 1.0f
            4 -> 0.5f
            else -> 0.0f
        }
        val b = gradOverlay.parameters[bKey]?.value ?: when(idx) {
            0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
            1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
            2 -> 0.0f
            3 -> 0.0f
            4 -> 0.0f
            else -> 1.0f
        }
        val a = gradOverlay.parameters[aKey]?.value ?: 1.0f
        customColorsList.add(Color(r, g, b, a))
    }

    val gradientStops = remember(gradOverlay, stopCount, customColorsList) {
        customColorsList.mapIndexed { idx, col -> GradientStop(idx, col) }
    }

    val previewColors = if (isCustomMode) {
        customColorsList
    } else {
        gradientPresets[goPreset.toInt().coerceIn(0, gradientPresets.size - 1)]
    }

    Column(
        modifier = modifier
            .fillMaxSize()
            .padding(horizontal = 4.dp)
            .verticalScroll(androidx.compose.foundation.rememberScrollState()),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        // Minimalist active header
        Text(
            text = "Interactive Vector Gradient Controller",
            style = Typography.labelSmall.copy(fontSize = 11.sp, fontWeight = FontWeight.Bold, color = IndustrialAmber)
        )

        // --- 1. Gradient Style selection row ---
        Text(
            text = "Gradient Pattern",
            style = Typography.labelSmall.copy(fontSize = 10.sp, fontWeight = FontWeight.Bold),
            color = Color.LightGray
        )
        androidx.compose.foundation.lazy.LazyRow(
            modifier = Modifier
                .fillMaxWidth()
                .height(36.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            val patterns = listOf(
                "Linear" to 0f,
                "Radial" to 1f,
                "Sweep" to 2f,
                "Reflected" to 3f,
                "Concentric" to 4f,
                "Diamond" to 5f,
                "Reflected Rad" to 6f
            )
            items(patterns.size) { i ->
                val (label, valFloat) = patterns[i]
                val isSelected = gradientTypeOrdinal == valFloat.toInt()
                Box(
                    modifier = Modifier
                        .height(28.dp)
                        .clip(RoundedCornerShape(8.dp))
                        .background(if (isSelected) IndustrialAmber else Color(0x15FFFFFF))
                        .border(
                            1.dp,
                            if (isSelected) IndustrialAmber else Color(0x22FFFFFF),
                            RoundedCornerShape(8.dp)
                        )
                        .clickable { updateParam("GradientType", valFloat) }
                        .padding(horizontal = 10.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = label,
                        style = Typography.labelSmall.copy(
                            fontWeight = FontWeight.Bold,
                            fontSize = 10.sp,
                            color = if (isSelected) Color(0xFF131317) else Color.White
                        )
                    )
                }
            }
        }

        // --- 2. Interactive Multi-Stop Slider Track ---
        Text(
            text = if (isCustomMode) "Click on any color block to select & edit its color!" else "Click any end node to edit this preset color!",
            style = Typography.labelSmall.copy(fontSize = 9.sp, fontWeight = FontWeight.SemiBold),
            color = IndustrialAmber
        )

        BoxWithConstraints(
            modifier = Modifier
                .fillMaxWidth()
                .height(56.dp)
                .background(Color(0xFF0F0F14), RoundedCornerShape(10.dp))
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.CenterStart
        ) {
            val totalWidth = maxWidth
            
            // Background Live Gradient bar representation of selected pattern
            Canvas(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(16.dp)
                    .clip(RoundedCornerShape(4.dp))
                    .border(0.5.dp, Color(0x33FFFFFF), RoundedCornerShape(4.dp))
            ) {
                val brush = when (gradientTypeOrdinal) {
                    1, 6 -> androidx.compose.ui.graphics.Brush.radialGradient(
                        colors = previewColors,
                        center = androidx.compose.ui.geometry.Offset(size.width / 2f, size.height / 2f),
                        radius = (size.width / 2f).coerceAtLeast(1f)
                    )
                    2 -> androidx.compose.ui.graphics.Brush.sweepGradient(
                        colors = previewColors,
                        center = androidx.compose.ui.geometry.Offset(size.width / 2f, size.height / 2f)
                    )
                    3 -> {
                        val reflectedColors = previewColors.reversed() + previewColors.drop(1)
                        androidx.compose.ui.graphics.Brush.horizontalGradient(colors = reflectedColors)
                    }
                    else -> androidx.compose.ui.graphics.Brush.horizontalGradient(colors = previewColors)
                }
                drawRect(brush = brush)
            }

            // Distribute handles along the track based on their real Stop positions (creates a fluid, aligned layout representation)
            val handlesCount = if (isCustomMode) stopCount else previewColors.size
            for (idx in 0 until handlesCount) {
                val fraction = if (isCustomMode) {
                    gradOverlay.parameters["CustomStop_${idx}_Pos"]?.value ?: (idx.toFloat() / (handlesCount - 1).coerceAtLeast(1))
                } else {
                    idx.toFloat() / (handlesCount - 1).coerceAtLeast(1)
                }
                val stopCol = if (isCustomMode) {
                    customColorsList[idx]
                } else {
                    previewColors[idx.coerceIn(0, previewColors.size - 1)]
                }
                val isEditingThisStop = isCustomMode && idx == activeStopIndex
                val offsetDp = (totalWidth - 28.dp) * fraction

                val totalWidthPx = with(androidx.compose.ui.platform.LocalDensity.current) { (totalWidth - 28.dp).toPx() }

                Box(
                    modifier = Modifier
                        .offset(x = offsetDp)
                        .size(28.dp)
                        .clip(RoundedCornerShape(6.dp))
                        .background(Color(0xFF161622))
                        .border(
                            1.dp,
                            if (isEditingThisStop) IndustrialAmber else Color(0x33FFFFFF),
                            RoundedCornerShape(6.dp)
                        )
                        .padding(2.dp)
                        .pointerInput(idx, totalWidthPx) {
                            detectDragGestures(
                                onDragStart = {
                                    updateParam("SelectedStopIndex", idx.toFloat())
                                    activeStopIndex = idx
                                },
                                onDrag = { change, dragAmount ->
                                    change.consume()
                                    val currentPos = gradOverlay.parameters["CustomStop_${idx}_Pos"]?.value ?: (idx.toFloat() / (handlesCount - 1).coerceAtLeast(1))
                                    val currentPosPx = currentPos * totalWidthPx
                                    val nextPosPx = currentPosPx + dragAmount.x
                                    val nextFraction = (nextPosPx / totalWidthPx).coerceIn(0f, 1f)
                                    updateParam("CustomStop_${idx}_Pos", nextFraction)
                                }
                            )
                        }
                        .clickable {
                            updateParam("SelectedStopIndex", idx.toFloat())
                            activeStopIndex = idx
                            onOpenColorPickerDialog?.invoke(idx)
                        }
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .clip(RoundedCornerShape(4.dp))
                            .background(stopCol)
                            .border(
                                BorderStroke(
                                    if (isEditingThisStop) 2.dp else 0.5.dp,
                                    if (isEditingThisStop) IndustrialAmber else Color.White
                                ),
                                RoundedCornerShape(4.dp)
                            )
                    ) {
                        Text(
                            text = (idx + 1).toString(),
                            style = Typography.labelSmall.copy(
                                fontWeight = FontWeight.ExtraBold,
                                fontSize = 9.sp,
                                color = if (stopCol.red * 0.299 + stopCol.green * 0.587 + stopCol.blue * 0.114 > 0.5) Color.Black else Color.White
                            ),
                            modifier = Modifier.align(Alignment.Center)
                        )
                    }
                }
            }
        }

        // --- CUSTOM STOPS DESIGNER ---
        if (isCustomMode) {
            // Number of Stops Selection Row
            Row(
                modifier = Modifier.fillMaxWidth().height(30.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text("Stops:", style = Typography.labelSmall.copy(fontSize = 9.sp), color = Color.LightGray, modifier = Modifier.width(36.dp))
                for (sc in 2..6) {
                    val isCurrentCount = sc == stopCount
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .height(24.dp)
                            .clip(RoundedCornerShape(4.dp))
                            .background(if (isCurrentCount) IndustrialAmber else Color(0x1FFFFFFF))
                            .border(0.5.dp, if (isCurrentCount) IndustrialAmber else Color(0x33FFFFFF), RoundedCornerShape(4.dp))
                            .clickable { updateParam("CustomStopCount", sc.toFloat()) },
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "$sc Way",
                            style = Typography.labelSmall.copy(
                                fontWeight = FontWeight.Bold,
                                fontSize = 9.sp,
                                color = if (isCurrentCount) Color(0xFF131317) else Color.White
                            )
                        )
                    }
                }
            }

            val rKey = "CustomStop_${activeStopIndex}_R"
            val gKey = "CustomStop_${activeStopIndex}_G"
            val bKey = "CustomStop_${activeStopIndex}_B"
            
            val activeColor = gradientStops[activeStopIndex.coerceIn(0, gradientStops.size - 1)].color

            val activeHsv = remember(activeColor) {
                val hsvArr = FloatArray(3)
                android.graphics.Color.RGBToHSV(
                    (activeColor.red * 255f).toInt(),
                    (activeColor.green * 255f).toInt(),
                    (activeColor.blue * 255f).toInt(),
                    hsvArr
                )
                hsvArr
            }

            val activeHue = activeHsv[0]
            val activeSat = activeHsv[1]
            val activeVal = activeHsv[2]

            val updateStopColorRGB = { rVal: Float, gVal: Float, bVal: Float ->
                var nextOverlay = gradOverlay.updateParameter("CustomStop_${activeStopIndex}_R", rVal) as StudioEffect.PhotoshopEffect
                nextOverlay = nextOverlay.updateParameter("CustomStop_${activeStopIndex}_G", gVal) as StudioEffect.PhotoshopEffect
                nextOverlay = nextOverlay.updateParameter("CustomStop_${activeStopIndex}_B", bVal) as StudioEffect.PhotoshopEffect
                
                if (activeStopIndex == 0) {
                    nextOverlay = nextOverlay.updateParameter("CustomStart_R", rVal) as StudioEffect.PhotoshopEffect
                    nextOverlay = nextOverlay.updateParameter("CustomStart_G", gVal) as StudioEffect.PhotoshopEffect
                    nextOverlay = nextOverlay.updateParameter("CustomStart_B", bVal) as StudioEffect.PhotoshopEffect
                } else if (activeStopIndex == 1) {
                    nextOverlay = nextOverlay.updateParameter("CustomEnd_R", rVal) as StudioEffect.PhotoshopEffect
                    nextOverlay = nextOverlay.updateParameter("CustomEnd_G", gVal) as StudioEffect.PhotoshopEffect
                    nextOverlay = nextOverlay.updateParameter("CustomEnd_B", bVal) as StudioEffect.PhotoshopEffect
                }
                
                val nextEffects = selectedLayer.effects.map { if (it.id == gradOverlay.id) nextOverlay else it }
                onUpdateLayer(selectedLayer.copy(effects = nextEffects))
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                var wheelSize by remember { mutableStateOf(androidx.compose.ui.unit.IntSize.Zero) }
                
                val updateColorFromOffset = { offset: androidx.compose.ui.geometry.Offset ->
                    val w = wheelSize.width.toFloat()
                    val h = wheelSize.height.toFloat()
                    if (w > 0f && h > 0f) {
                        val cx = w / 2f
                        val cy = h / 2f
                        val dx = offset.x - cx
                        val dy = offset.y - cy
                        val distance = Math.sqrt((dx * dx + dy * dy).toDouble()).toFloat()
                        val maxRadius = w / 2f
                        
                        var hue = Math.toDegrees(Math.atan2(dy.toDouble(), dx.toDouble())).toFloat()
                        if (hue < 0f) hue += 360f
                        
                        val sat = (distance / maxRadius).coerceIn(0f, 1f)
                        
                        val rgb = android.graphics.Color.HSVToColor(floatArrayOf(hue, sat, activeVal))
                        updateStopColorRGB(
                            android.graphics.Color.red(rgb) / 255f,
                            android.graphics.Color.green(rgb) / 255f,
                            android.graphics.Color.blue(rgb) / 255f
                        )
                    }
                }

                Box(
                    modifier = Modifier
                        .size(126.dp)
                        .background(Color(0xFF0F0F14), CircleShape)
                        .clip(CircleShape)
                        .border(1.dp, Color(0x22FFFFFF), CircleShape)
                        .onSizeChanged { wheelSize = it }
                        .pointerInput(activeStopIndex, activeVal) {
                            detectTapGestures { offset ->
                                updateColorFromOffset(offset)
                            }
                        }
                        .pointerInput(activeStopIndex, activeVal) {
                            detectDragGestures { change, _ ->
                                change.consume()
                                updateColorFromOffset(change.position)
                            }
                        }
                ) {
                    Canvas(modifier = Modifier.fillMaxSize()) {
                        drawCircle(
                            brush = androidx.compose.ui.graphics.Brush.sweepGradient(
                                colors = listOf(
                                    Color.Red, Color.Magenta, Color.Blue, Color.Cyan, Color.Green, Color.Yellow, Color.Red
                                )
                            )
                        )
                        drawCircle(
                            brush = androidx.compose.ui.graphics.Brush.radialGradient(
                                colors = listOf(Color.White, Color.Transparent),
                                radius = size.width / 2f
                            )
                        )
                    }

                    if (wheelSize.width > 0 && wheelSize.height > 0) {
                        val w = wheelSize.width.toFloat()
                        val h = wheelSize.height.toFloat()
                        val cx = w / 2f
                        val cy = h / 2f
                        val angleScale = Math.toRadians(activeHue.toDouble())
                        val radiusPct = activeSat * (w / 2f)
                        val rxPx = cx + (radiusPct * Math.cos(angleScale)).toFloat()
                        val ryPx = cy + (radiusPct * Math.sin(angleScale)).toFloat()
                        
                        val density = androidx.compose.ui.platform.LocalDensity.current
                        val rxDp = with(density) { rxPx.toDp() }
                        val ryDp = with(density) { ryPx.toDp() }

                        Box(
                            modifier = Modifier
                                .absoluteOffset(x = rxDp - 8.dp, y = ryDp - 8.dp)
                                .size(16.dp)
                                .background(Color.White, CircleShape)
                                .border(2.dp, Color.Black, CircleShape)
                        )
                    }
                }

                Column(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    Text(
                        text = "Quick Swatches",
                        style = Typography.labelSmall.copy(fontSize = 10.sp, fontWeight = FontWeight.Bold),
                        color = Color.LightGray
                    )

                    val swatches = listOf(
                        Color(0xFFE53935), Color(0xFFFB8C00), Color(0xFFFFB300), 
                        Color(0xFF7CB342), Color(0xFF00ACC1), Color(0xFF1E88E5), 
                        Color(0xFF8E24AA), Color(0xFFFFFFFF), Color(0xFF888888), 
                        Color(0xFF000000)
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        swatches.take(5).forEach { color ->
                            Box(
                                modifier = Modifier
                                    .size(24.dp)
                                    .clip(RoundedCornerShape(6.dp))
                                    .background(color)
                                    .border(1.dp, Color(0x33FFFFFF), RoundedCornerShape(6.dp))
                                    .clickable {
                                        updateStopColorRGB(color.red, color.green, color.blue)
                                    }
                            )
                        }
                    }

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        swatches.drop(5).forEach { color ->
                            Box(
                                modifier = Modifier
                                    .size(24.dp)
                                    .clip(RoundedCornerShape(6.dp))
                                    .background(color)
                                    .border(1.dp, Color(0x33FFFFFF), RoundedCornerShape(6.dp))
                                    .clickable {
                                        updateStopColorRGB(color.red, color.green, color.blue)
                                    }
                            )
                        }
                    }

                    Text(
                        text = "Lightness / Shade",
                        style = Typography.labelSmall.copy(fontSize = 9.sp, fontWeight = FontWeight.Medium),
                        color = Color.LightGray
                    )
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        var bLocal by remember(activeVal) { mutableStateOf(activeVal) }
                        Slider(
                            value = bLocal,
                            onValueChange = {
                                bLocal = it
                                val rgb = android.graphics.Color.HSVToColor(floatArrayOf(activeHue, activeSat, it))
                                updateStopColorRGB(
                                    android.graphics.Color.red(rgb) / 255f,
                                    android.graphics.Color.green(rgb) / 255f,
                                    android.graphics.Color.blue(rgb) / 255f
                                )
                            },
                            valueRange = 0f..1f,
                            colors = SliderDefaults.colors(
                                activeTrackColor = IndustrialAmber,
                                thumbColor = IndustrialAmber
                            ),
                            modifier = Modifier.weight(1f).height(16.dp)
                        )
                        Text(
                            text = "${(bLocal * 100).toInt()}%",
                            style = Typography.labelSmall.copy(fontSize = 8.sp, fontWeight = FontWeight.Bold),
                            color = Color.White
                        )
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    Text(
                        text = "Stop Opacity / Alpha",
                        style = Typography.labelSmall.copy(fontSize = 9.sp, fontWeight = FontWeight.Medium),
                        color = Color.LightGray
                    )
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        val activeAlpha = gradOverlay.parameters["CustomStop_${activeStopIndex}_A"]?.value ?: 1.0f
                        var alphaLocal by remember(activeAlpha) { mutableStateOf(activeAlpha) }
                        Slider(
                            value = alphaLocal,
                            onValueChange = {
                                alphaLocal = it
                                val nextOverlay = gradOverlay.updateParameter("CustomStop_${activeStopIndex}_A", it) as StudioEffect.PhotoshopEffect
                                val nextEffects = selectedLayer.effects.map { if (it.id == gradOverlay.id) nextOverlay else it }
                                onUpdateLayer(selectedLayer.copy(effects = nextEffects))
                            },
                            valueRange = 0f..1f,
                            colors = SliderDefaults.colors(
                                activeTrackColor = IndustrialAmber,
                                thumbColor = IndustrialAmber
                            ),
                            modifier = Modifier.weight(1f).height(16.dp)
                        )
                        Text(
                            text = "${(alphaLocal * 100).toInt()}%",
                            style = Typography.labelSmall.copy(fontSize = 8.sp, fontWeight = FontWeight.Bold),
                            color = Color.White,
                            modifier = Modifier.width(24.dp)
                        )
                        
                        // Small premium Eyedropper button
                        Box(
                            modifier = Modifier
                                .size(28.dp)
                                .clip(RoundedCornerShape(6.dp))
                                .background(if (isGradientEyedropperActive) IndustrialAmber.copy(alpha = 0.2f) else Color(0xFF161622))
                                .border(1.dp, if (isGradientEyedropperActive) IndustrialAmber else Color(0x33FFFFFF), RoundedCornerShape(6.dp))
                                .clickable {
                                    onToggleGradientEyedropper?.invoke(!isGradientEyedropperActive)
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Default.Colorize,
                                contentDescription = "Canvas Eyedropper",
                                tint = if (isGradientEyedropperActive) IndustrialAmber else Color.White,
                                modifier = Modifier.size(13.dp)
                            )
                        }
                    }
                }
            }
        }

        // Sliders section for Angle, Scale and Opacity Blend
        Column(
            modifier = Modifier.fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(1.dp)
        ) {
            // Angle Slider
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Angle",
                    style = Typography.labelSmall.copy(fontSize = 9.sp),
                    color = Color.LightGray,
                    modifier = Modifier.width(36.dp)
                )
                Slider(
                    value = localAngle,
                    onValueChange = { 
                        localAngle = it
                        updateParam("Angle", it) 
                    },
                    valueRange = -180f..180f,
                    colors = SliderDefaults.colors(
                        activeTrackColor = IndustrialAmber,
                        thumbColor = IndustrialAmber
                    ),
                    modifier = Modifier.weight(1f).height(18.dp)
                )
                Text(
                    text = "${localAngle.toInt()}°",
                    style = Typography.labelSmall.copy(fontSize = 8.sp),
                    color = Color.White,
                    modifier = Modifier.width(28.dp),
                    textAlign = TextAlign.End
                )
            }

            // Scale Slider
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Scale",
                    style = Typography.labelSmall.copy(fontSize = 9.sp),
                    color = Color.LightGray,
                    modifier = Modifier.width(36.dp)
                )
                Slider(
                    value = localScale,
                    onValueChange = { 
                        localScale = it
                        updateParam("Scale", it) 
                    },
                    valueRange = 10f..150f,
                    colors = SliderDefaults.colors(
                        activeTrackColor = IndustrialAmber,
                        thumbColor = IndustrialAmber
                    ),
                    modifier = Modifier.weight(1f).height(18.dp)
                )
                Text(
                    text = "${localScale.toInt()}%",
                    style = Typography.labelSmall.copy(fontSize = 8.sp),
                    color = Color.White,
                    modifier = Modifier.width(28.dp),
                    textAlign = TextAlign.End
                )
            }

            // Opacity Slider
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Blend",
                    style = Typography.labelSmall.copy(fontSize = 9.sp),
                    color = Color.LightGray,
                    modifier = Modifier.width(36.dp)
                )
                Slider(
                    value = localOpacity,
                    onValueChange = { 
                        localOpacity = it
                        updateParam("Opacity", it) 
                    },
                    valueRange = 0f..1f,
                    colors = SliderDefaults.colors(
                        activeTrackColor = IndustrialAmber,
                        thumbColor = IndustrialAmber
                    ),
                    modifier = Modifier.weight(1f).height(18.dp)
                )
                Text(
                    text = "${(localOpacity * 100).toInt()}%",
                    style = Typography.labelSmall.copy(fontSize = 8.sp),
                    color = Color.White,
                    modifier = Modifier.width(28.dp),
                    textAlign = TextAlign.End
                )
            }
        }
    }
}

@Composable
fun IntegratedColorWheel(
    hue: Float,
    saturation: Float,
    value: Float,
    opacity: Float,
    onColorChanged: (Color) -> Unit,
    modifier: Modifier = Modifier
) {
    val currentHue by rememberUpdatedState(hue)
    val currentSaturation by rememberUpdatedState(saturation)
    val currentValue by rememberUpdatedState(value)
    val currentOpacity by rememberUpdatedState(opacity)
    val currentOnColorChanged by rememberUpdatedState(onColorChanged)

    BoxWithConstraints(
        modifier = modifier,
        contentAlignment = Alignment.Center
    ) {
        val cMaxW = if (constraints.maxWidth == androidx.compose.ui.unit.Constraints.Infinity) 300 else constraints.maxWidth
        val cMaxH = if (constraints.maxHeight == androidx.compose.ui.unit.Constraints.Infinity) 300 else constraints.maxHeight
        val sizePx = minOf(cMaxW, cMaxH).toFloat().coerceAtLeast(100f)
        
        val center = Offset(sizePx / 2f, sizePx / 2f)
        val outerRadius = sizePx / 2f - 4f
        val hueRingWidth = sizePx * 0.12f // 12% of total size for Hue ring
        val innerRadius = outerRadius - hueRingWidth
        val squareHalfSize = innerRadius * 0.707f
        
        Canvas(
            modifier = Modifier
                .size((sizePx / androidx.compose.ui.platform.LocalDensity.current.density).dp)
                .pointerInput(sizePx, innerRadius, outerRadius, squareHalfSize) {
                    awaitEachGesture {
                        val down = awaitFirstDown(requireUnconsumed = false)
                        val touchOffset = down.position
                        val dx = touchOffset.x - center.x
                        val dy = touchOffset.y - center.y
                        val distance = kotlin.math.sqrt(dx * dx + dy * dy)
                        
                        var isRing = distance in innerRadius..outerRadius + 15f
                        var isSquare = touchOffset.x >= center.x - squareHalfSize && touchOffset.x <= center.x + squareHalfSize &&
                                touchOffset.y >= center.y - squareHalfSize && touchOffset.y <= center.y + squareHalfSize
                        
                        if (!isRing && !isSquare) {
                            if (distance > innerRadius) {
                                isRing = true
                            } else {
                                isSquare = true
                            }
                        }

                        val handleTouchUpdate = { pos: Offset ->
                            if (isRing) {
                                val curDx = pos.x - center.x
                                val curDy = pos.y - center.y
                                val angleRad = Math.atan2(curDy.toDouble(), curDx.toDouble())
                                var angleDeg = Math.toDegrees(angleRad).toFloat()
                                if (angleDeg.isNaN()) angleDeg = 0f
                                if (angleDeg < 0f) angleDeg += 360f
                                currentOnColorChanged(Color.hsv(angleDeg.coerceIn(0f, 360f), currentSaturation, currentValue, currentOpacity))
                            } else if (isSquare) {
                                val relativeX = (pos.x - (center.x - squareHalfSize)) / (squareHalfSize * 2f)
                                val relativeY = (pos.y - (center.y - squareHalfSize)) / (squareHalfSize * 2f)
                                val nextS = relativeX.coerceIn(0f, 1f)
                                val nextV = (1f - relativeY).coerceIn(0f, 1f)
                                currentOnColorChanged(Color.hsv(currentHue, nextS, nextV, currentOpacity))
                            }
                        }

                        handleTouchUpdate(touchOffset)

                        while (true) {
                            val event = awaitPointerEvent()
                            val anyPressed = event.changes.any { it.pressed }
                            if (!anyPressed) break
                            val pointer = event.changes.firstOrNull()
                            if (pointer != null) {
                                pointer.consume()
                                handleTouchUpdate(pointer.position)
                            }
                        }
                    }
                }
        ) {
            val hueColors = listOf(
                Color.Red, Color.Yellow, Color.Green, Color.Cyan, Color.Blue, Color.Magenta, Color.Red
            )
            drawCircle(
                brush = androidx.compose.ui.graphics.Brush.sweepGradient(colors = hueColors),
                radius = outerRadius - hueRingWidth / 2f,
                style = Stroke(width = hueRingWidth)
            )
            
            val angleRad = Math.toRadians(hue.toDouble()).toFloat()
            val indicatorRadius = outerRadius - hueRingWidth / 2f
            val indX = center.x + indicatorRadius * kotlin.math.cos(angleRad)
            val indY = center.y + indicatorRadius * kotlin.math.sin(angleRad)
            
            drawCircle(
                color = Color.Black,
                radius = 8f,
                center = Offset(indX, indY)
            )
            drawCircle(
                color = Color.White,
                radius = 6f,
                center = Offset(indX, indY)
            )
            
            val baseHueColor = Color.hsv(hue, 1f, 1f)
            val squareLeft = center.x - squareHalfSize
            val squareTop = center.y - squareHalfSize
            val squareWidth = squareHalfSize * 2f
            
            drawRect(
                brush = androidx.compose.ui.graphics.Brush.horizontalGradient(
                    colors = listOf(Color.White, baseHueColor),
                    startX = squareLeft,
                    endX = squareLeft + squareWidth
                ),
                topLeft = Offset(squareLeft, squareTop),
                size = androidx.compose.ui.geometry.Size(squareWidth, squareWidth)
            )
            drawRect(
                brush = androidx.compose.ui.graphics.Brush.verticalGradient(
                    colors = listOf(Color.Transparent, Color.Black),
                    startY = squareTop,
                    endY = squareTop + squareWidth
                ),
                topLeft = Offset(squareLeft, squareTop),
                size = androidx.compose.ui.geometry.Size(squareWidth, squareWidth),
                blendMode = androidx.compose.ui.graphics.BlendMode.Multiply
            )
            
            drawRect(
                color = Color(0x66FFFFFF),
                topLeft = Offset(squareLeft, squareTop),
                size = androidx.compose.ui.geometry.Size(squareWidth, squareWidth),
                style = Stroke(width = 2f)
            )
            
            val handleX = squareLeft + saturation * squareWidth
            val handleY = squareTop + (1f - value) * squareWidth
            
            drawCircle(
                color = Color.Black,
                radius = 8f,
                center = Offset(handleX, handleY),
                style = Stroke(width = 3f)
            )
            drawCircle(
                color = Color.White,
                radius = 8f,
                center = Offset(handleX, handleY),
                style = Stroke(width = 1.5f)
            )
        }
    }
}

fun parseHexColor(hex: String): Color? {
    val clean = hex.trim().replace("#", "")
    if (clean.length == 6) {
        return try {
            val r = clean.substring(0, 2).toInt(16)
            val g = clean.substring(2, 4).toInt(16)
            val b = clean.substring(4, 6).toInt(16)
            Color(r / 255f, g / 255f, b / 255f)
        } catch (e: Exception) {
            null
        }
    } else if (clean.length == 8) {
        return try {
            val a = clean.substring(0, 2).toInt(16)
            val r = clean.substring(2, 4).toInt(16)
            val g = clean.substring(4, 6).toInt(16)
            val b = clean.substring(6, 8).toInt(16)
            Color(r / 255f, g / 255f, b / 255f, a / 255f)
        } catch (e: Exception) {
            null
        }
    }
    return null
}

fun rgbToCmyk(r: Float, g: Float, b: Float, profile: String): FloatArray {
    val cRaw = 1f - r
    val mRaw = 1f - g
    val yRaw = 1f - b
    var k = minOf(cRaw, minOf(mRaw, yRaw))
    
    var c = 0f
    var m = 0f
    var y = 0f
    
    if (k < 1f) {
        c = (cRaw - k) / (1f - k)
        m = (mRaw - k) / (1f - k)
        y = (yRaw - k) / (1f - k)
    } else {
        k = 1f
    }
    
    // Profile-specific corrections and soft-proofing
    when {
        profile.contains("FOGRA39", ignoreCase = true) -> {
            // FOGRA39 supports vibrant gamut. Ink limit: 330%
            val total = c + m + y + k
            if (total > 3.3f) {
                val excess = total - 3.3f
                val reduction = excess / 3f
                c = (c - reduction).coerceAtLeast(0f)
                m = (m - reduction).coerceAtLeast(0f)
                y = (y - reduction).coerceAtLeast(0f)
                k = (k + reduction * 0.5f).coerceIn(0f, 1f)
            }
        }
        profile.contains("SWOP", ignoreCase = true) -> {
            // SWOP v2. Ink limit: 300%. Slightly open up midtones due to high dot gain.
            c = java.lang.Math.pow(c.toDouble(), 1.05).toFloat()
            m = java.lang.Math.pow(m.toDouble(), 1.05).toFloat()
            y = java.lang.Math.pow(y.toDouble(), 1.05).toFloat()
            
            val total = c + m + y + k
            if (total > 3.0f) {
                val excess = total - 3.0f
                val reduction = excess / 3f
                c = (c - reduction).coerceAtLeast(0f)
                m = (m - reduction).coerceAtLeast(0f)
                y = (y - reduction).coerceAtLeast(0f)
                k = (k + reduction * 0.4f).coerceIn(0f, 1f)
            }
        }
        profile.contains("FOGRA29", ignoreCase = true) -> {
            // Uncoated paper has high absorption, muted gamut. Ink limit: 280%.
            val avg = (c + m + y) / 3f
            c = (c * 0.85f + avg * 0.15f).coerceIn(0f, 1f)
            m = (m * 0.85f + avg * 0.15f).coerceIn(0f, 1f)
            y = (y * 0.85f + avg * 0.15f).coerceIn(0f, 1f)
            
            val total = c + m + y + k
            if (total > 2.8f) {
                val excess = total - 2.8f
                val reduction = excess / 3f
                c = (c - reduction).coerceAtLeast(0f)
                m = (m - reduction).coerceAtLeast(0f)
                y = (y - reduction).coerceAtLeast(0f)
                k = (k + reduction * 0.6f).coerceIn(0f, 1f)
            }
        }
        profile.contains("Japan", ignoreCase = true) -> {
            // Warmer yellows, ink limit: 350%
            y = (y * 1.05f).coerceIn(0f, 1f)
            val total = c + m + y + k
            if (total > 3.5f) {
                val excess = total - 3.5f
                val reduction = excess / 3f
                c = (c - reduction).coerceAtLeast(0f)
                m = (m - reduction).coerceAtLeast(0f)
                y = (y - reduction).coerceAtLeast(0f)
                k = (k + reduction * 0.3f).coerceIn(0f, 1f)
            }
        }
    }
    
    return floatArrayOf(
        c.coerceIn(0f, 1f),
        m.coerceIn(0f, 1f),
        y.coerceIn(0f, 1f),
        k.coerceIn(0f, 1f)
    )
}

fun cmykToRgb(c: Float, m: Float, y: Float, k: Float, profile: String): Color {
    var adjC = c.coerceIn(0f, 1f)
    var adjM = m.coerceIn(0f, 1f)
    var adjY = y.coerceIn(0f, 1f)
    var adjK = k.coerceIn(0f, 1f)
    
    when {
        profile.contains("SWOP", ignoreCase = true) -> {
            adjC = java.lang.Math.pow(adjC.toDouble(), 1.0 / 1.05).toFloat()
            adjM = java.lang.Math.pow(adjM.toDouble(), 1.0 / 1.05).toFloat()
            adjY = java.lang.Math.pow(adjY.toDouble(), 1.0 / 1.05).toFloat()
        }
        profile.contains("FOGRA29", ignoreCase = true) -> {
            val avg = (adjC + adjM + adjY) / 3f
            adjC = (adjC * 0.9f + avg * 0.1f).coerceIn(0f, 1f)
            adjM = (adjM * 0.9f + avg * 0.1f).coerceIn(0f, 1f)
            adjY = (adjY * 0.9f + avg * 0.1f).coerceIn(0f, 1f)
        }
        profile.contains("Japan", ignoreCase = true) -> {
            adjY = (adjY / 1.05f).coerceIn(0f, 1f)
        }
    }
    
    val r = (1f - adjC) * (1f - adjK)
    val g = (1f - adjM) * (1f - adjK)
    val b = (1f - adjY) * (1f - adjK)
    
    return Color(r.coerceIn(0f, 1f), g.coerceIn(0f, 1f), b.coerceIn(0f, 1f))
}

@Composable
fun EffectColorPicker(
    red: Float,
    green: Float,
    blue: Float,
    opacity: Float,
    onColorChanged: (Color) -> Unit,
    modifier: Modifier = Modifier
) {
    val hsv = remember(red, green, blue) {
        val arr = FloatArray(3)
        android.graphics.Color.RGBToHSV(
            (red * 255f).toInt().coerceIn(0, 255),
            (green * 255f).toInt().coerceIn(0, 255),
            (blue * 255f).toInt().coerceIn(0, 255),
            arr
        )
        arr
    }
    val hue = hsv[0]
    val saturation = hsv[1]
    val value = hsv[2]

    val hexCode = remember(red, green, blue) {
        val r = (red * 255f).toInt().coerceIn(0, 255)
        val g = (green * 255f).toInt().coerceIn(0, 255)
        val b = (blue * 255f).toInt().coerceIn(0, 255)
        String.format("#%02X%02X%02X", r, g, b)
    }

    Column(
        modifier = modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Box(
            modifier = Modifier.fillMaxWidth(),
            contentAlignment = Alignment.Center
        ) {
            IntegratedColorWheel(
                hue = hue,
                saturation = saturation,
                value = value,
                opacity = opacity,
                onColorChanged = onColorChanged,
                modifier = Modifier.size(150.dp)
            )
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            var hexInputState by remember(hexCode) { mutableStateOf(hexCode) }
            val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current
            val context = androidx.compose.ui.platform.LocalContext.current

            Box(
                modifier = Modifier
                    .size(20.dp)
                    .clip(RoundedCornerShape(3.dp))
                    .background(Color(red, green, blue, opacity))
                    .border(BorderStroke(0.5.dp, Color.White), RoundedCornerShape(3.dp))
            )

            androidx.compose.foundation.text.BasicTextField(
                value = hexInputState,
                onValueChange = { newVal ->
                    hexInputState = newVal
                    val parsed = parseHexColor(newVal)
                    if (parsed != null) {
                        onColorChanged(parsed)
                    }
                },
                textStyle = Typography.labelSmall.copy(
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Bold,
                    color = Color.White
                ),
                singleLine = true,
                modifier = Modifier
                    .weight(1f)
                    .background(Color(0xFF1E1E24), RoundedCornerShape(4.dp))
                    .padding(vertical = 4.dp, horizontal = 6.dp)
            )

            IconButton(
                onClick = {
                    clipboardManager.setText(androidx.compose.ui.text.AnnotatedString(hexCode))
                    android.widget.Toast.makeText(context, "Copied: $hexCode", android.widget.Toast.LENGTH_SHORT).show()
                },
                modifier = Modifier.size(20.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.ContentCopy,
                    contentDescription = "Copy Hex",
                    tint = Color.LightGray,
                    modifier = Modifier.size(11.dp)
                )
            }

            IconButton(
                onClick = {
                    val pasted = clipboardManager.getText()?.text
                    if (pasted != null) {
                        val parsed = parseHexColor(pasted)
                        if (parsed != null) {
                            onColorChanged(parsed)
                            hexInputState = pasted
                            android.widget.Toast.makeText(context, "Hex pasted!", android.widget.Toast.LENGTH_SHORT).show()
                        } else {
                            android.widget.Toast.makeText(context, "Invalid Hex format", android.widget.Toast.LENGTH_SHORT).show()
                        }
                    }
                },
                modifier = Modifier.size(20.dp)
            ) {
                Icon(
                    imageVector = Icons.Default.ContentPaste,
                    contentDescription = "Paste Hex",
                    tint = Color.LightGray,
                    modifier = Modifier.size(11.dp)
                )
            }
        }
    }
}

@Composable
fun HsvColorPickerPanel(
    currentColor: Color,
    currentOpacity: Float,
    onColorChanged: (Color) -> Unit,
    modifier: Modifier = Modifier,
    selectedLayer: StudioLayer? = null,
    onUpdateLayer: ((StudioLayer) -> Unit)? = null,
    onOpenColorPickerDialog: ((Int) -> Unit)? = null,
    projectColorProfile: String = "RGB",
    selectedCmykProfile: String = "Coated FOGRA39 (Premium Glossy)"
) {
    val isGradientEyedropperActive = GradientEyedropperState.isActive
    val onToggleGradientEyedropper: ((Boolean) -> Unit) = { GradientEyedropperState.isActive = it }

    var fillMode by remember { mutableStateOf("Solid") } // "Transparent", "Solid", "Gradient", "Media"
    var sliderMode by remember { mutableStateOf("HSV") }

    LaunchedEffect(selectedLayer) {
        if (selectedLayer != null) {
            val hasGrid = selectedLayer.effects.any { it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" }
            if (hasGrid) {
                fillMode = "Gradient"
            } else if (selectedLayer.baseColor == Color.Transparent) {
                fillMode = "Transparent"
            } else {
                fillMode = "Solid"
            }
        }
    }
    
    // Safely convert current RGB color to HSV components on changes to avoid crashes on non-sRGB colorspaces
    val hsv = remember(currentColor) {
        val arr = FloatArray(3)
        try {
            val srgbColor = try {
                currentColor.convert(androidx.compose.ui.graphics.colorspace.ColorSpaces.Srgb)
            } catch (e: Exception) {
                currentColor
            }
            val r = (srgbColor.red * 255f).toInt().coerceIn(0, 255)
            val g = (srgbColor.green * 255f).toInt().coerceIn(0, 255)
            val b = (srgbColor.blue * 255f).toInt().coerceIn(0, 255)
            android.graphics.Color.RGBToHSV(r, g, b, arr)
        } catch (e: Exception) {
            arr[0] = 0f
            arr[1] = 0f
            arr[2] = 0f
        }
        arr
    }
    val hue = hsv[0].coerceIn(0f, 360f)
    val saturation = hsv[1].coerceIn(0f, 1f)
    val value = hsv[2].coerceIn(0f, 1f)
    val opacity = currentOpacity.coerceIn(0f, 1f)

    var localHue by remember { mutableStateOf(hue) }
    var localSaturation by remember { mutableStateOf(saturation) }
    var localValue by remember { mutableStateOf(value) }
    var localOpacity by remember { mutableStateOf(opacity) }

    LaunchedEffect(currentColor, opacity) {
        val currentLocal = Color.hsv(localHue, localSaturation, localValue, localOpacity)
        val diffR = Math.abs(currentColor.red - currentLocal.red)
        val diffG = Math.abs(currentColor.green - currentLocal.green)
        val diffB = Math.abs(currentColor.blue - currentLocal.blue)
        val diffA = Math.abs(opacity - localOpacity)
        if (diffR > 0.005f || diffG > 0.005f || diffB > 0.005f || diffA > 0.005f) {
            localHue = hue
            localSaturation = saturation
            localValue = value
            localOpacity = opacity
        }
    }

    // Save custom swatches locally
    val customSwatches = remember {
        mutableStateListOf(
            Color(0xFFFFB300), Color(0xFF29B6F6), Color(0xFF4CAF50), Color(0xFFE91E63),
            Color.White, Color.Black, Color(0xFFE53935), Color(0xFF9C27B0)
        )
    }
    
    var showPaletteDropdown by remember { mutableStateOf(false) }

    // Hex expression builder and opacity percent representation wrapped safely
    val hexCode = remember(currentColor) {
        try {
            val srgbColor = try {
                currentColor.convert(androidx.compose.ui.graphics.colorspace.ColorSpaces.Srgb)
            } catch (e: Exception) {
                currentColor
            }
            val r = (srgbColor.red * 255f).toInt().coerceIn(0, 255)
            val g = (srgbColor.green * 255f).toInt().coerceIn(0, 255)
            val b = (srgbColor.blue * 255f).toInt().coerceIn(0, 255)
            String.format("#%02X%02X%02X", r, g, b)
        } catch (e: Exception) {
            "#000000"
        }
    }
    val opacityPercent = (opacity * 100).toInt()

    Column(
        modifier = modifier
            .fillMaxHeight()
            .background(Color(0xFF131317), RoundedCornerShape(8.dp))
            .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
            .padding(6.dp)
    ) {
        // 1. Top 4-tab fill mode bar (Transparent, Solid, Gradient, Media)
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(30.dp)
                .background(Color(0xFF0F0F14), RoundedCornerShape(6.dp))
                .padding(2.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            val tabs = listOf(
                "Transparent" to Icons.Default.Block,
                "Solid" to Icons.Default.FormatColorFill,
                "Gradient" to Icons.Default.Gradient,
                "Media" to Icons.Default.Image
            )
            tabs.forEach { (mode, icon) ->
                val isSelected = fillMode == mode
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight()
                        .clip(RoundedCornerShape(4.dp))
                        .background(if (isSelected) MidSlate else Color.Transparent)
                        .clickable {
                            fillMode = mode
                            if (mode == "Transparent") {
                                onColorChanged(Color.Transparent)
                                if (selectedLayer != null && onUpdateLayer != null) {
                                    val nextEffects = selectedLayer.effects.filter { !(it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay") }
                                    onUpdateLayer(selectedLayer.copy(effects = nextEffects, baseColor = Color.Transparent))
                                }
                            } else if (mode == "Solid") {
                                val sCol = Color.hsv(hue.coerceIn(0f, 360f), saturation.coerceIn(0f, 1f), value.coerceIn(0f, 1f), 1.0f)
                                onColorChanged(sCol)
                                if (selectedLayer != null && onUpdateLayer != null) {
                                    val nextEffects = selectedLayer.effects.filter { !(it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay") }
                                    onUpdateLayer(selectedLayer.copy(effects = nextEffects, baseColor = sCol))
                                }
                            } else if (mode == "Gradient") {
                                if (selectedLayer != null && onUpdateLayer != null) {
                                    val hasGrid = selectedLayer.effects.any { it is StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" }
                                    if (!hasGrid) {
                                        val newGrad = PhotoshopEffectTemplates.create(effectType = "GradientOverlay")
                                        onUpdateLayer(selectedLayer.copy(effects = selectedLayer.effects + newGrad))
                                    }
                                }
                            }
                        },
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = icon,
                        contentDescription = mode,
                        tint = if (isSelected) IndustrialAmber else Color(0x99FFFFFF),
                        modifier = Modifier.size(15.dp)
                    )
                }
            }
        }

        Spacer(Modifier.height(4.dp))

        // Split center area container
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            if (showPaletteDropdown) {
                // Swatches dropdown grid
                Column(
                    modifier = Modifier
                        .weight(1.5f)
                        .fillMaxHeight()
                        .background(Color(0xFF060608), RoundedCornerShape(6.dp))
                        .padding(4.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Custom Swatches", style = MaterialTheme.typography.labelSmall, color = IndustrialAmber, fontSize = 10.sp)
                        Icon(
                            imageVector = Icons.Default.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White,
                            modifier = Modifier.size(12.dp).clickable { showPaletteDropdown = false }
                        )
                    }
                    Spacer(Modifier.height(4.dp))
                    androidx.compose.foundation.lazy.grid.LazyVerticalGrid(
                        columns = androidx.compose.foundation.lazy.grid.GridCells.Fixed(4),
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                        verticalArrangement = Arrangement.spacedBy(4.dp),
                        modifier = Modifier.fillMaxWidth().weight(1f)
                    ) {
                        items(customSwatches.size) { idx ->
                            val sCol = customSwatches[idx]
                            Box(
                                modifier = Modifier
                                    .aspectRatio(1f)
                                    .clip(RoundedCornerShape(4.dp))
                                    .background(sCol)
                                    .border(
                                        BorderStroke(
                                            if (currentColor == sCol) 2.dp else 0.5.dp,
                                            if (currentColor == sCol) IndustrialAmber else Color(0x33FFFFFF)
                                        ),
                                        RoundedCornerShape(4.dp)
                                    )
                                    .clickable { onColorChanged(sCol) }
                            )
                        }
                    }
                }
            } else if (fillMode == "Gradient") {
                GradientPickerPanel(
                    selectedLayer = selectedLayer,
                    onUpdateLayer = onUpdateLayer,
                    modifier = Modifier.weight(1.5f).fillMaxHeight(),
                    onOpenColorPickerDialog = onOpenColorPickerDialog
                )
            } else {
                // Integrated color wheel and slider deck
                Row(
                    modifier = Modifier
                        .weight(1.5f)
                        .fillMaxHeight(),
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    // 1. Integrated Color Wheel
                    Box(
                        modifier = Modifier
                            .weight(1.1f)
                            .fillMaxHeight(),
                        contentAlignment = Alignment.Center
                    ) {
                        IntegratedColorWheel(
                            hue = localHue,
                            saturation = localSaturation,
                            value = localValue,
                            opacity = localOpacity,
                            onColorChanged = { nextColor ->
                                val arr = FloatArray(3)
                                android.graphics.Color.RGBToHSV(
                                    (nextColor.red * 255f).toInt().coerceIn(0, 255),
                                    (nextColor.green * 255f).toInt().coerceIn(0, 255),
                                    (nextColor.blue * 255f).toInt().coerceIn(0, 255),
                                    arr
                                )
                                localHue = arr[0]
                                localSaturation = arr[1]
                                localValue = arr[2]
                                localOpacity = nextColor.alpha
                                onColorChanged(nextColor)
                            },
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                    
                    // 2. Vertical sliders for granular numerical input
                    Column(
                        modifier = Modifier
                            .weight(1.1f)
                            .fillMaxHeight()
                            .verticalScroll(androidx.compose.foundation.rememberScrollState()),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        // Color Preview Block with Hex Input and Copy/Paste
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(24.dp)
                                    .clip(RoundedCornerShape(4.dp))
                                    .background(currentColor)
                                    .border(BorderStroke(0.5.dp, Color.White), RoundedCornerShape(4.dp))
                            )
                            
                            var hexInputState by remember(hexCode) { mutableStateOf(hexCode) }
                            val clipboardManager = androidx.compose.ui.platform.LocalClipboardManager.current
                            val context = androidx.compose.ui.platform.LocalContext.current

                            androidx.compose.foundation.text.BasicTextField(
                                value = hexInputState,
                                onValueChange = { newVal ->
                                    hexInputState = newVal
                                    val parsed = parseHexColor(newVal)
                                    if (parsed != null) {
                                        onColorChanged(parsed)
                                    }
                                },
                                textStyle = Typography.labelSmall.copy(
                                    fontSize = 11.sp, 
                                    fontWeight = FontWeight.Bold,
                                    color = Color.White
                                ),
                                singleLine = true,
                                modifier = Modifier
                                    .weight(1f)
                                    .background(Color(0xFF1E1E24), RoundedCornerShape(4.dp))
                                    .padding(vertical = 4.dp, horizontal = 6.dp)
                            )

                            // Copy button
                            IconButton(
                                onClick = {
                                    clipboardManager.setText(androidx.compose.ui.text.AnnotatedString(hexCode))
                                    android.widget.Toast.makeText(context, "Hex copied: $hexCode", android.widget.Toast.LENGTH_SHORT).show()
                                },
                                modifier = Modifier.size(22.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.ContentCopy,
                                    contentDescription = "Copy Hex",
                                    tint = Color.LightGray,
                                    modifier = Modifier.size(12.dp)
                                )
                            }

                            // Paste button
                            IconButton(
                                onClick = {
                                    val pasted = clipboardManager.getText()?.text
                                    if (pasted != null) {
                                        val parsed = parseHexColor(pasted)
                                        if (parsed != null) {
                                            onColorChanged(parsed)
                                            hexInputState = pasted
                                            android.widget.Toast.makeText(context, "Hex pasted!", android.widget.Toast.LENGTH_SHORT).show()
                                        } else {
                                            android.widget.Toast.makeText(context, "Invalid Hex format", android.widget.Toast.LENGTH_SHORT).show()
                                        }
                                    }
                                },
                                modifier = Modifier.size(22.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.ContentPaste,
                                    contentDescription = "Paste Hex",
                                    tint = Color.LightGray,
                                    modifier = Modifier.size(12.dp)
                                )
                            }
                        }
                        
                        Box(modifier = Modifier.fillMaxWidth().height(0.5.dp).background(Color(0xFF2C313C)))
                        
                        if (projectColorProfile == "CMYK") {
                            val cmykVals = remember(currentColor, selectedCmykProfile) {
                                rgbToCmyk(currentColor.red, currentColor.green, currentColor.blue, selectedCmykProfile)
                            }
                            val cVal = cmykVals[0] * 100f
                            val mVal = cmykVals[1] * 100f
                            val yVal = cmykVals[2] * 100f
                            val kVal = cmykVals[3] * 100f

                            // Cyan Slider
                            Column {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Cyan (C)", color = Color(0xFF00B0FF), fontSize = 9.sp, fontWeight = FontWeight.Bold)
                                    Text("${cVal.toInt()}%", color = Color.White, fontSize = 9.sp)
                                }
                                Slider(
                                    value = cVal,
                                    onValueChange = { nextC ->
                                        val nextColor = cmykToRgb(nextC / 100f, cmykVals[1], cmykVals[2], cmykVals[3], selectedCmykProfile)
                                        val finalColor = Color(nextColor.red, nextColor.green, nextColor.blue, opacity)
                                        onColorChanged(finalColor)
                                    },
                                    valueRange = 0f..100f,
                                    modifier = Modifier.height(18.dp),
                                    colors = SliderDefaults.colors(
                                        thumbColor = Color(0xFF00B0FF),
                                        activeTrackColor = Color(0xFF00B0FF),
                                        inactiveTrackColor = Color(0xFF2C313C)
                                    )
                                )
                            }

                            // Magenta Slider
                            Column {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Magenta (M)", color = Color(0xFFFF4081), fontSize = 9.sp, fontWeight = FontWeight.Bold)
                                    Text("${mVal.toInt()}%", color = Color.White, fontSize = 9.sp)
                                }
                                Slider(
                                    value = mVal,
                                    onValueChange = { nextM ->
                                        val nextColor = cmykToRgb(cmykVals[0], nextM / 100f, cmykVals[2], cmykVals[3], selectedCmykProfile)
                                        val finalColor = Color(nextColor.red, nextColor.green, nextColor.blue, opacity)
                                        onColorChanged(finalColor)
                                    },
                                    valueRange = 0f..100f,
                                    modifier = Modifier.height(18.dp),
                                    colors = SliderDefaults.colors(
                                        thumbColor = Color(0xFFFF4081),
                                        activeTrackColor = Color(0xFFFF4081),
                                        inactiveTrackColor = Color(0xFF2C313C)
                                    )
                                )
                            }

                            // Yellow Slider
                            Column {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("Yellow (Y)", color = Color(0xFFFFEB3B), fontSize = 9.sp, fontWeight = FontWeight.Bold)
                                    Text("${yVal.toInt()}%", color = Color.White, fontSize = 9.sp)
                                }
                                Slider(
                                    value = yVal,
                                    onValueChange = { nextY ->
                                        val nextColor = cmykToRgb(cmykVals[0], cmykVals[1], nextY / 100f, cmykVals[3], selectedCmykProfile)
                                        val finalColor = Color(nextColor.red, nextColor.green, nextColor.blue, opacity)
                                        onColorChanged(finalColor)
                                    },
                                    valueRange = 0f..100f,
                                    modifier = Modifier.height(18.dp),
                                    colors = SliderDefaults.colors(
