                    val effR = layer.cornerRadius.coerceIn(0f, maxR)
                    if (effR > 0f) {
                        shapePaint.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                }
                drawContext.canvas.drawPath(path, shapePaint)
            }
            com.example.studio.model.LayerType.TEXT -> {
                drawTextLayerInternal(
                    layer = layer,
                    opacityMultiplier = finalOpacity,
                    composeBlendMode = blendModeOverride ?: composeBlendMode,
                    overrideColor = finalColor,
                    drawStyle = styleToUse,
                    blurRadius = 0f,
                    gradientShader = gradientShader
                )
            }
            com.example.studio.model.LayerType.FREEHAND_DRAWING -> {
                val canvas = drawContext.canvas
                val paint = androidx.compose.ui.graphics.Paint().apply {
                    blendMode = composeBlendMode
                }
                val widthToUse = if (layer.width.isFinite() && layer.width > 0f) layer.width else 1000f
                val heightToUse = if (layer.height.isFinite() && layer.height > 0f) layer.height else 1000f
                val bounds = androidx.compose.ui.geometry.Rect(-4000f, -4000f, widthToUse + 4000f, heightToUse + 4000f)

                var savedSuccessfully = false
                try {
                    canvas.saveLayer(bounds, paint)
                    savedSuccessfully = true
                } catch (t: Throwable) {
                    try {
                        canvas.save()
                        savedSuccessfully = true
                    } catch (t2: Throwable) {}
                }

                if (savedSuccessfully) {
                    try {
                        val activeFilters = layer.effects.filter { it.isEnabled && it.name != "BrushConfig" }
                        val bSize = brushConfig?.parameters?.get("Size")?.value ?: 12f
                        val bOpacity = brushConfig?.parameters?.get("Opacity")?.value ?: 1.0f
                        val bSmoothing = (brushConfig?.parameters?.get("Smoothing")?.value ?: 1.0f) > 0.5f
                        val bPreset = brushConfig?.parameters?.get("Preset")?.value?.toInt() ?: 0

                        if (activeFilters.isEmpty()) {
                            // FAST PATH: Draw directly onto the canvas (inside the saveLayer block) to avoid GC thrashing/O(N) layout lag
                            if (layer.brushPoints.isNotEmpty()) {
                                val strokesKey = "${layer.id}_${layer.brushPoints.hashCode()}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}"
                                var strokes = parsedStrokesCache.get(strokesKey)
                                if (strokes == null) {
                                    strokes = parseFreehandStrokes(
                                        brushPoints = layer.brushPoints,
                                        defaultColor = finalComposeColor,
                                        defaultSize = bSize,
                                        defaultOpacity = bOpacity * layerOpacity,
                                        defaultPreset = bPreset,
                                        defaultSmoothing = bSmoothing
                                    )
                                    parsedStrokesCache.put(strokesKey, strokes)
                                }

                                for (stroke in strokes) {
                                    if (stroke.points.isNotEmpty()) {
                                        val strokeBlend = if (stroke.isEraser) androidx.compose.ui.graphics.BlendMode.DstOut else androidx.compose.ui.graphics.BlendMode.SrcOver
                                        drawBrushStroke(
                                            points = stroke.points,
                                            color = stroke.color,
                                            size = stroke.size,
                                            opacity = stroke.opacity,
                                            presetIndex = stroke.presetIndex,
                                            smoothing = stroke.smoothing,
                                            originX = 0f,
                                            originY = 0f,
                                            composeBlendMode = strokeBlend,
                                            pathCache = pathCache,
                                            pathPointsCountCache = pathPointsCountCache,
                                            cacheKey = layer.id.hashCode() + stroke.hashCode(),
                                            backdropBitmap = backdropBitmap
                                        )
                                    }
                                }
                            }
                        } else {
                            // SLOW PATH: Use offscreen Bitmap caching to support GPU image filters (Blur, Color Balance, etc.)
                            val effectsHash = activeFilters.sumOf { it.hashCode() }
                            val w = widthToUse.toInt().coerceIn(1, 2048)
                            val h = heightToUse.toInt().coerceIn(1, 2048)

                            val cacheKey = "drawing_${layer.id}_${layer.brushPoints.hashCode()}_${effectsHash}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}_${w}_${h}"
                            var cachedProcessed = processedImageBitmapCache[cacheKey]

                            if (cachedProcessed == null) {
                                val offscreenBmp = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
                                val nativeCanvas = android.graphics.Canvas(offscreenBmp)
                                val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                                val originalCanvas = drawContext.canvas

                                drawContext.canvas = tempCanvas
                                nativeCanvas.drawColor(android.graphics.Color.TRANSPARENT, android.graphics.PorterDuff.Mode.CLEAR)

                                try {
                                    if (layer.brushPoints.isNotEmpty()) {
                                        val strokesKey = "${layer.id}_${layer.brushPoints.hashCode()}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}"
                                        var strokes = parsedStrokesCache.get(strokesKey)
                                        if (strokes == null) {
                                            strokes = parseFreehandStrokes(
                                                brushPoints = layer.brushPoints,
                                                defaultColor = finalComposeColor,
                                                defaultSize = bSize,
                                                defaultOpacity = bOpacity * layerOpacity,
                                                defaultPreset = bPreset,
                                                defaultSmoothing = bSmoothing
                                            )
                                            parsedStrokesCache.put(strokesKey, strokes)
                                        }

                                        for (stroke in strokes) {
                                            if (stroke.points.isNotEmpty()) {
                                                val strokeBlend = if (stroke.isEraser) androidx.compose.ui.graphics.BlendMode.DstOut else androidx.compose.ui.graphics.BlendMode.SrcOver
                                                drawBrushStroke(
                                                    points = stroke.points,
                                                    color = stroke.color,
                                                    size = stroke.size,
                                                    opacity = stroke.opacity,
                                                    presetIndex = stroke.presetIndex,
                                                    smoothing = stroke.smoothing,
                                                    originX = 0f,
                                                    originY = 0f,
                                                    composeBlendMode = strokeBlend,
                                                    pathCache = pathCache,
                                                    pathPointsCountCache = pathPointsCountCache,
                                                    cacheKey = layer.id.hashCode() + stroke.hashCode(),
                                                    backdropBitmap = backdropBitmap
                                                )
                                            }
                                        }
                                    }
                                } finally {
                                    drawContext.canvas = originalCanvas
                                }

                                val filteredBmp = if (globalAppContext != null) {
                                    applyGPUImageFilters(globalAppContext!!, offscreenBmp, layer.id, activeFilters)
                                } else {
                                    offscreenBmp
                                }
                                cachedProcessed = filteredBmp.asImageBitmap()
                                processedImageBitmapCache[cacheKey] = cachedProcessed
                            }

                            cachedProcessed?.let { img ->
                                drawImage(
                                    image = img,
                                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                    blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
                                )
                            }
                        }

                        // Render active real-time Wet Ink stroke on top separately; guarantees fluid 60 FPS feedback and zero filter freezes
                        if (layer.id == selectedLayerId && OpenGLBrushRenderer.WetInkRenderer.isInitialized()) {
                            OpenGLBrushRenderer.WetInkRenderer.getWetInkBitmap()?.let { b ->
                                drawImage(
                                    image = b.asImageBitmap(),
                                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                    blendMode = if (activeTool == "Eraser") androidx.compose.ui.graphics.BlendMode.DstOut else androidx.compose.ui.graphics.BlendMode.SrcOver
                                )
                            }
                        }
                    } catch (t: Throwable) {
                        t.printStackTrace()
                    } finally {
                        try {
                            canvas.restore()
                        } catch (t: Throwable) {}
                    }
                }
            }
            com.example.studio.model.LayerType.GROUP -> {}
            com.example.studio.model.LayerType.ADJUSTMENT_LAYER -> {}
            com.example.studio.model.LayerType.IMAGE_CARD -> {
                if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                    if (layer.cornerRadius > 0f) {
                        drawRoundRect(
                            color = finalComposeColor,
                            topLeft = androidx.compose.ui.geometry.Offset.Zero,
                            size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                            cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    } else {
                        drawRect(
                            color = finalComposeColor,
                            topLeft = androidx.compose.ui.geometry.Offset.Zero,
                            size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                            style = styleToUse,
                            blendMode = composeBlendMode
                        )
                    }
                } else {
                    val uriStr = layer.imageUri
                    val loadedBitmap = if (!uriStr.isNullOrEmpty()) imageBitmapCache[uriStr] else null
                    if (loadedBitmap != null) {
                        val activeEffects = layer.effects.filter { it.isEnabled }
                        val _drawTrigger = rawFilterRedrawTrigger.value
                        val drawImage = if (activeEffects.isNotEmpty()) {
                            val effectHash = activeEffects.map { it.id + "_" + it.parameters.values.joinToString { p -> p.value.toString() } }.hashCode()
                            val processedKey = "${layer.id}_${uriStr}_${effectHash}"
                            var cachedProcessed = processedImageBitmapCache[processedKey]
                            if (cachedProcessed == null) {
                                CameraRAWFilterEngine.triggerBackgroundFilterRender(
                                    processedKey = processedKey,
                                    layerId = layer.id,
                                    loadedBitmap = loadedBitmap,
                                    activeEffects = activeEffects,
                                    context = globalAppContext
                                )
                                loadedBitmap
                            } else {
                                cachedProcessed
                            }
                        } else {
                            loadedBitmap
                        }

                        val cropParams = com.example.studio.model.calculateImageCropDrawParams(
                            bitmapWidth = drawImage.width,
                            bitmapHeight = drawImage.height,
                            cropLeft = layer.cropLeft,
                            cropTop = layer.cropTop,
                            cropRight = layer.cropRight,
                            cropBottom = layer.cropBottom,
                            layerWidth = layer.width,
                            layerHeight = layer.height
                        )
                        val srcOffset = androidx.compose.ui.unit.IntOffset(cropParams.srcX, cropParams.srcY)
                        val srcSize = androidx.compose.ui.unit.IntSize(cropParams.srcW, cropParams.srcH)
                        val dstSize = androidx.compose.ui.unit.IntSize(cropParams.drawW.toInt().coerceAtLeast(1), cropParams.drawH.toInt().coerceAtLeast(1))

                        withTransform({
                            translate(left = cropParams.offsetX, top = cropParams.offsetY)
                        }) {
                            if (isShadowOrEffect) {
                                val imgPaint = ComposePaintCache.getCleanPaint().apply {
                                    this.blendMode = blendModeOverride ?: composeBlendMode
                                    this.alpha = finalOpacity * layerOpacity
                                    this.color = finalColor
                                    this.colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(finalColor, androidx.compose.ui.graphics.BlendMode.SrcIn)
                                    val fwSelf = this.asFrameworkPaint()
                                    fwSelf.isFilterBitmap = true
                                    fwSelf.isAntiAlias = true
                                    fwSelf.isDither = true
                                }
                                try {
                                    drawContext.canvas.drawImageRect(
                                        image = drawImage,
                                        srcOffset = srcOffset,
                                        srcSize = srcSize,
                                        dstSize = dstSize,
                                        paint = imgPaint
                                    )
                                } catch (e: Exception) {
                                    android.util.Log.e("StudioImageLoader", "Failed to draw image shadow", e)
                                }
                            } else {
                                if (layer.cornerRadius > 0f) {
                                    val maxR = minOf(layer.width, layer.height) / 2f
                                    val effectiveR = (cornerRadiusOverride ?: layer.cornerRadius).coerceIn(0f, maxR)
                                    val rRect = androidx.compose.ui.geometry.RoundRect(
                                        rect = androidx.compose.ui.geometry.Rect(-cropParams.offsetX, -cropParams.offsetY, layer.width - cropParams.offsetX, layer.height - cropParams.offsetY),
                                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(effectiveR, effectiveR)
                                    )
                                    val clipP = androidx.compose.ui.graphics.Path().apply { addRoundRect(rRect) }
                                    clipPath(clipP) {
                                        drawImage(
                                            image = drawImage,
                                            srcOffset = srcOffset,
                                            srcSize = srcSize,
                                            dstSize = dstSize,
                                            alpha = finalOpacity * layerOpacity,
                                            blendMode = composeBlendMode,
                                            filterQuality = androidx.compose.ui.graphics.FilterQuality.High
                                        )
                                    }
                                } else {
                                    drawImage(
                                        image = drawImage,
                                        srcOffset = srcOffset,
                                        srcSize = srcSize,
                                        dstSize = dstSize,
                                        alpha = finalOpacity * layerOpacity,
                                        blendMode = composeBlendMode,
                                        filterQuality = androidx.compose.ui.graphics.FilterQuality.High
                                    )
                                }
                            }
                        }
                    } else {
                        if (!uriStr.isNullOrEmpty()) {
                            // Draw a modern pulsing background panel matching the image dimensions and corner radius
                            val basePulseColor = androidx.compose.ui.graphics.Color(0xFF2C2C35)
                            if (layer.cornerRadius > 0f) {
                                drawRoundRect(
                                    color = basePulseColor.copy(alpha = pulseAlpha),
                                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                    size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                                    blendMode = composeBlendMode
                                )
                                // Pulsing inner border outline
                                drawRoundRect(
                                    color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.15f * pulseAlpha),
                                    topLeft = androidx.compose.ui.geometry.Offset(1f, 1f),
                                    size = androidx.compose.ui.geometry.Size(layer.width - 2f, layer.height - 2f),
                                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f),
                                    blendMode = composeBlendMode
                                )
                            } else {
                                drawRect(
                                    color = basePulseColor.copy(alpha = pulseAlpha),
                                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                    size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                                    blendMode = composeBlendMode
                                )
                                // Pulsing inner border outline
                                drawRect(
                                    color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.15f * pulseAlpha),
                                    topLeft = androidx.compose.ui.geometry.Offset(1f, 1f),
                                    size = androidx.compose.ui.geometry.Size(layer.width - 2f, layer.height - 2f),
                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f),
                                    blendMode = composeBlendMode
                                )
                            }

                            // Centered progress spinner loading indicator
                            val minDim = minOf(layer.width, layer.height)
                            if (minDim > 20f) {
                                val spinnerRadius = minOf(minDim * 0.25f, 40f)
                                val centerOffset = androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height / 2f)
                                
                                // Background track
                                drawCircle(
                                    color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.1f),
                                    radius = spinnerRadius,
                                    center = centerOffset,
                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 3.5f),
                                    blendMode = composeBlendMode
                                )
                                
                                // Spinning loader arc
                                val rectSize = spinnerRadius * 2f
                                drawArc(
                                    color = androidx.compose.ui.graphics.Color(0xFF2196F3).copy(alpha = 0.85f),
                                    startAngle = spinAngle,
                                    sweepAngle = 90f,
                                    useCenter = false,
                                    topLeft = androidx.compose.ui.geometry.Offset(centerOffset.x - spinnerRadius, centerOffset.y - spinnerRadius),
                                    size = androidx.compose.ui.geometry.Size(rectSize, rectSize),
                                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 3.5f, cap = androidx.compose.ui.graphics.StrokeCap.Round),
                                    blendMode = composeBlendMode
                                )
                            }
                        } else {
                            if (isOverlay && paintToUse != null) {
                                if (layer.cornerRadius > 0f) {
                                    drawContext.canvas.drawRoundRect(
                                        left = 0f,
                                        top = 0f,
                                        right = layer.width,
                                        bottom = layer.height,
                                        radiusX = layer.cornerRadius,
                                        radiusY = layer.cornerRadius,
                                        paint = paintToUse
                                    )
                                } else {
                                    drawContext.canvas.drawRect(
                                        left = 0f,
                                        top = 0f,
                                        right = layer.width,
                                        bottom = layer.height,
                                        paint = paintToUse
                                    )
                                }
                            } else {
                                if (layer.cornerRadius > 0f) {
                                    drawRoundRect(
                                        color = finalComposeColor,
                                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius),
                                        style = styleToUse,
                                        blendMode = composeBlendMode
                                    )
                                } else {
                                    drawRect(
                                        color = finalComposeColor,
                                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                                        style = styleToUse,
                                        blendMode = composeBlendMode
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }

        if (hasEraserOrBrush) {
            if (canvasSaved) {
                try {
                    val bSize = brushConfig?.parameters?.get("Size")?.value ?: 12f
                    val bOpacity = brushConfig?.parameters?.get("Opacity")?.value ?: 1.0f
                    val bSmoothing = (brushConfig?.parameters?.get("Smoothing")?.value ?: 1.0f) > 0.5f
                    val bPreset = brushConfig?.parameters?.get("Preset")?.value?.toInt() ?: 3

                    val cacheKey = "${layer.id}_${layer.brushPoints.hashCode()}_${bSize}_${bOpacity}_${bSmoothing}_${bPreset}_${layerOpacity}_${finalComposeColor.hashCode()}"
                    var strokes = parsedStrokesCache.get(cacheKey)
                    if (strokes == null) {
                        strokes = parseFreehandStrokes(
                            brushPoints = layer.brushPoints,
                            defaultColor = finalComposeColor,
                            defaultSize = bSize,
                            defaultOpacity = bOpacity * layerOpacity,
                            defaultPreset = bPreset,
                            defaultSmoothing = bSmoothing
                        )
                        parsedStrokesCache.put(cacheKey, strokes)
                    }

                    for (stroke in strokes) {
                        if (stroke.points.isNotEmpty()) {
                            val strokeBlend = if (stroke.isEraser) androidx.compose.ui.graphics.BlendMode.DstOut else composeBlendMode
                            drawBrushStroke(
                                points = stroke.points,
                                color = stroke.color,
                                size = stroke.size,
                                opacity = stroke.opacity,
                                presetIndex = stroke.presetIndex,
                                smoothing = stroke.smoothing,
                                originX = 0f,
                                originY = 0f,
                                composeBlendMode = strokeBlend,
                                pathCache = pathCache,
                                pathPointsCountCache = pathPointsCountCache,
                                cacheKey = layer.id.hashCode() + stroke.hashCode(),
                                backdropBitmap = backdropBitmap,
                                customHardness = stroke.hardness
                            )
                        }
                    }

                    // Render active real-time Wet Ink stroke on top separately if this layer is currently being erased
                    if (layer.id == selectedLayerId && OpenGLBrushRenderer.WetInkRenderer.isInitialized() && activeTool == "Eraser") {
                        OpenGLBrushRenderer.WetInkRenderer.getWetInkBitmap()?.let { b ->
                            drawImage(
                                image = b.asImageBitmap(),
                                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                                blendMode = androidx.compose.ui.graphics.BlendMode.DstOut
                            )
                        }
                    }
                } catch (e: Exception) {
                    e.printStackTrace()
                } finally {
                    try {
                        drawContext.canvas.restore()
                    } catch (t: Throwable) {}
                }
            }
        }
    }

    fun drawGeometryWithBlurAndOffset(finalColor: androidx.compose.ui.graphics.Color, finalOpacity: Float, fillStyle: androidx.compose.ui.graphics.drawscope.DrawStyle, blurRadius: Float, blurMode: android.graphics.BlurMaskFilter.Blur, offsetX: Float, offsetY: Float, isOverlay: Boolean = true, blendModeOverride: androidx.compose.ui.graphics.BlendMode? = null, isShadowOrEffect: Boolean = false, gradientShader: android.graphics.Shader? = null, cornerRadiusOverride: Float? = null) {
        val originalCanvas = drawContext.canvas
        val isHardware = originalCanvas.nativeCanvas.isHardwareAccelerated
        
        if (isHardware && blurRadius > 0.1f && layer.width in 1f..3000f && layer.height in 1f..3000f) {
            val strokePad = if (layer.strokeThickness > 0f) layer.strokeThickness * 2f else 0f
            val pad = ((blurRadius * 3) + strokePad).toInt().coerceIn(1, 400)
            val bmpW = (layer.width + pad * 2).toInt().coerceAtLeast(1)
            val bmpH = (layer.height + pad * 2).toInt().coerceAtLeast(1)
            
            try {
                val tempBmp = android.graphics.Bitmap.createBitmap(bmpW, bmpH, android.graphics.Bitmap.Config.ARGB_8888)
                val nativeCanvas = android.graphics.Canvas(tempBmp)
                val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                
                drawContext.canvas = tempCanvas
                nativeCanvas.drawColor(android.graphics.Color.TRANSPARENT, android.graphics.PorterDuff.Mode.CLEAR)
                
                try {
                    tempCanvas.save()
                    tempCanvas.translate(pad.toFloat(), pad.toFloat())
                    
                    // Recursive call in software canvas mode
                    drawGeometryWithBlurAndOffset(finalColor, finalOpacity, fillStyle, blurRadius, blurMode, 0f, 0f, isOverlay, androidx.compose.ui.graphics.BlendMode.SrcOver, isShadowOrEffect, gradientShader, cornerRadiusOverride)
                    
                    tempCanvas.restore()
                } finally {
                    drawContext.canvas = originalCanvas
                }
                
                originalCanvas.drawImage(tempBmp.asImageBitmap(), androidx.compose.ui.geometry.Offset(-pad.toFloat() + offsetX, -pad.toFloat() + offsetY), androidx.compose.ui.graphics.Paint().apply {
                    blendMode = blendModeOverride ?: composeBlendMode
                })
                tempBmp.recycle()
                return
            } catch (e: Exception) {
                // Fallback to hardware mask filter on OOM
            }
        }

        val finalComposeColor = finalColor.copy(alpha = finalOpacity * layerOpacity)
        val styleToUse = if (layer.strokeThickness > 0f && fillStyle is androidx.compose.ui.graphics.drawscope.Fill && layer.type !in listOf(com.example.studio.model.LayerType.FREEHAND_DRAWING, com.example.studio.model.LayerType.IMAGE_CARD)) {
            androidx.compose.ui.graphics.drawscope.Stroke(width = layer.strokeThickness)
        } else {
            fillStyle
        }
        
        val paint = androidx.compose.ui.graphics.Paint().apply {
            color = finalComposeColor
            this.style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                androidx.compose.ui.graphics.PaintingStyle.Stroke
            } else {
                androidx.compose.ui.graphics.PaintingStyle.Fill
            }
            if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                this.strokeWidth = styleToUse.width
                this.strokeCap = styleToUse.cap
                this.strokeMiterLimit = styleToUse.miter
                this.strokeJoin = styleToUse.join
                asFrameworkPaint().isAntiAlias = true
            }
            this.blendMode = blendModeOverride ?: composeBlendMode
            if (isShadowOrEffect && layer.type == com.example.studio.model.LayerType.IMAGE_CARD) {
                this.colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(finalColor, androidx.compose.ui.graphics.BlendMode.SrcIn)
            }
            
            if (blurRadius > 0.1f) {
                asFrameworkPaint().maskFilter = android.graphics.BlurMaskFilter(blurRadius, blurMode)
            }
            if (gradientShader != null) {
                asFrameworkPaint().shader = gradientShader
            }
        }

        if (offsetX != 0f || offsetY != 0f) {
            originalCanvas.save()
            originalCanvas.translate(offsetX, offsetY)
        }

        when (layer.type) {
            com.example.studio.model.LayerType.VECTOR_RECT -> {
                val maxR = minOf(layer.width, layer.height) / 2f
                val effectiveR = (cornerRadiusOverride ?: layer.cornerRadius).coerceIn(0f, maxR)
                if (effectiveR > 0f) {
                    drawContext.canvas.drawRoundRect(0f, 0f, layer.width, layer.height, effectiveR, effectiveR, paint)
                } else {
                    drawContext.canvas.drawRect(0f, 0f, layer.width, layer.height, paint)
                }
            }
            com.example.studio.model.LayerType.VECTOR_TRIANGLE -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 3
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val r = minOf(layer.width, layer.height) / 2f
                        for (i in 0 until edges) {
                            val angle = -Math.PI / 2.0 + i * 2.0 * Math.PI / edges
                            val x = (cx + r * Math.cos(angle)).toFloat()
                            val y = (cy + r * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                if (layer.cornerRadius > 0f) {
                    val maxR = minOf(layer.width, layer.height) / 4f
                    val effR = layer.cornerRadius.coerceIn(0f, maxR)
                    if (effR > 0f) {
                        paint.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                }
                drawContext.canvas.drawPath(path, paint)
            }
            com.example.studio.model.LayerType.VECTOR_OVAL -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        addOval(androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height))
                    }
                    pathCache.put(cacheKey, path)
                }
                drawContext.canvas.drawPath(path, paint)
            }
            com.example.studio.model.LayerType.VECTOR_LINE -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    val px = layer.width
                    val py = layer.height
                    path = androidx.compose.ui.graphics.Path().apply {
                        moveTo(0f, 0f)
                        lineTo(px, py)
                    }
                    pathCache.put(cacheKey, path)
                }
                drawContext.canvas.drawPath(path, paint)
            }
            com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                if (layer.brushPoints.isNotEmpty()) {
                    val cacheKey = getLayerGeometryHash(layer)
                    var path = pathCache.get(cacheKey)
                    if (path == null) {
                        path = androidx.compose.ui.graphics.Path().apply {
                            val anchors = layer.brushPoints.toAnchorPoints()
                            buildComposeBezierPath(this, layer, anchors)
                        }
                        pathCache.put(cacheKey, path)
                    }
                    drawContext.canvas.drawPath(path, paint)
                }
            }
            com.example.studio.model.LayerType.FREEHAND_DRAWING -> {
                if (layer.brushPoints.isNotEmpty()) {
                    val cacheKey = layer.id.hashCode()
                    var path = pathCache.get(cacheKey)
                    if (path == null) {
                        path = androidx.compose.ui.graphics.Path().apply {
                            var isFirst = true
                            for (pt in layer.brushPoints) {
                                if (pt == androidx.compose.ui.geometry.Offset.Unspecified || pt.x.isNaN() || pt.y.isNaN()) {
                                    isFirst = true
                                } else {
                                    if (isFirst) {
                                        moveTo(pt.x - layer.positionX, pt.y - layer.positionY)
                                        isFirst = false
                                    } else {
                                        lineTo(pt.x - layer.positionX, pt.y - layer.positionY)
                                    }
                                }
                            }
                        }
                        pathCache.put(cacheKey, path)
                    }
                    val strokeW = if (fillStyle is androidx.compose.ui.graphics.drawscope.Stroke) fillStyle.width else {
                        (layer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Size")?.value ?: (if (layer.strokeThickness > 0f) layer.strokeThickness else 8f)
                    }
                    paint.style = androidx.compose.ui.graphics.PaintingStyle.Stroke
                    paint.strokeWidth = strokeW
                    paint.strokeCap = androidx.compose.ui.graphics.StrokeCap.Round
                    paint.strokeJoin = androidx.compose.ui.graphics.StrokeJoin.Round
                    drawContext.canvas.drawPath(path, paint)
                }
            }
            com.example.studio.model.LayerType.IMAGE_CARD -> {
                if (layer.cornerRadius > 0f) {
                    val effR = layer.cornerRadius
                    drawContext.canvas.drawRoundRect(0f, 0f, layer.width, layer.height, effR, effR, paint)
                } else {
                    drawContext.canvas.drawRect(0f, 0f, layer.width, layer.height, paint)
                }
            }
            else -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = createComplexShapePath(layer.type, layer.width, layer.height, layer.polygonEdges, layer.starInnerRadiusRatio, layer.skewX, layer.skewY, cornerRadiusOverride ?: layer.cornerRadius)
                    pathCache.put(cacheKey, path)
                }
                if (layer.cornerRadius > 0f) {
                    val maxR = minOf(layer.width, layer.height) / 4f
                    val effR = layer.cornerRadius.coerceIn(0f, maxR)
                    if (effR > 0f) {
                        paint.asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                }
                drawContext.canvas.drawPath(path, paint)
            }
        }

        if (offsetX != 0f || offsetY != 0f) {
            originalCanvas.restore()
        }
        paint.asFrameworkPaint().maskFilter = null
        paint.asFrameworkPaint().shader = null
        paint.asFrameworkPaint().pathEffect = null
    }

    fun drawGeometryWithBlur(finalColor: androidx.compose.ui.graphics.Color, finalOpacity: Float, fillStyle: androidx.compose.ui.graphics.drawscope.DrawStyle, blurRadius: Float, blurMode: android.graphics.BlurMaskFilter.Blur, isOverlay: Boolean = true, blendModeOverride: androidx.compose.ui.graphics.BlendMode? = null, isShadowOrEffect: Boolean = false, gradientShader: android.graphics.Shader? = null, cornerRadiusOverride: Float? = null) {
        drawGeometryWithBlurAndOffset(finalColor, finalOpacity, fillStyle, blurRadius, blurMode, 0f, 0f, isOverlay, blendModeOverride, isShadowOrEffect = isShadowOrEffect, gradientShader = gradientShader)
    }

    // Brush/Gradient drawing helper
    val drawGeometryWithBrush: (androidx.compose.ui.graphics.Brush, Float, androidx.compose.ui.graphics.drawscope.DrawStyle) -> Unit = { finalBrush, finalOpacity, fillStyle ->
        val brushAlpha = finalOpacity * layerOpacity
        val styleToUse = if (layer.strokeThickness > 0f && fillStyle is androidx.compose.ui.graphics.drawscope.Fill && layer.type !in listOf(com.example.studio.model.LayerType.FREEHAND_DRAWING, com.example.studio.model.LayerType.IMAGE_CARD)) {
            androidx.compose.ui.graphics.drawscope.Stroke(width = layer.strokeThickness)
        } else {
            fillStyle
        }
        when (layer.type) {
            com.example.studio.model.LayerType.VECTOR_RECT -> {
                val maxR = minOf(layer.width, layer.height) / 2f
                val effectiveR = layer.cornerRadius.coerceIn(0f, maxR)
                if (effectiveR > 0f) {
                    drawRoundRect(
                        brush = finalBrush,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(effectiveR, effectiveR),
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                } else {
                    drawRect(
                        brush = finalBrush,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_TRIANGLE -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 3
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                val maxR = minOf(layer.width, layer.height) / 4f
                val effR = layer.cornerRadius.coerceIn(0f, maxR)
                if (effR > 0f) {
                    val paint = ComposePaintCache.getCleanPaint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_PENTAGON -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 5
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                val maxR = minOf(layer.width, layer.height) / 4f
                val effR = layer.cornerRadius.coerceIn(0f, maxR)
                if (effR > 0f) {
                    val paint = ComposePaintCache.getCleanPaint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_HEXAGON -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val edges = if (layer.polygonEdges in 3..25) layer.polygonEdges else 6
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rx = layer.width / 2f
                        val ry = layer.height / 2f
                        for (i in 0 until edges) {
                            val angle = Math.toRadians((i * (360.0 / edges) - 90).toDouble())
                            val x = (cx + rx * Math.cos(angle)).toFloat()
                            val y = (cy + ry * Math.sin(angle)).toFloat()
                            if (i == 0) moveTo(x, y) else lineTo(x, y)
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                val maxR = minOf(layer.width, layer.height) / 4f
                val effR = layer.cornerRadius.coerceIn(0f, maxR)
                if (effR > 0f) {
                    val paint = ComposePaintCache.getCleanPaint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_OVAL -> {
                drawOval(
                    brush = finalBrush,
                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                    size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                    style = styleToUse,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_LINE -> {
                val strokeW = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) styleToUse.width else (if (layer.strokeThickness > 0f) layer.strokeThickness else 6f)
                drawLine(
                    brush = finalBrush,
                    start = androidx.compose.ui.geometry.Offset.Zero,
                    end = androidx.compose.ui.geometry.Offset(layer.width, layer.height),
                    strokeWidth = strokeW,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_BEZIER -> {
                val start = androidx.compose.ui.geometry.Offset(0f, layer.height)
                val end = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
                val controlLocal = layer.brushPoints.getOrNull(0) ?: androidx.compose.ui.geometry.Offset(layer.width / 2f, 0f)

                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val anchors = layer.brushPoints.toAnchorPoints()
                        buildComposeBezierPath(this, layer, anchors)
                    }
                    pathCache.put(cacheKey, path)
                }
                val shapeStyle = if (layer.strokeThickness <= 0f) {
                    androidx.compose.ui.graphics.drawscope.Fill
                } else {
                    val strokeW = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) styleToUse.width else (if (layer.strokeThickness > 0f) layer.strokeThickness else 8f)
                    androidx.compose.ui.graphics.drawscope.Stroke(width = strokeW)
                }
                drawPath(
                    path = path,
                    brush = finalBrush,
                    style = shapeStyle,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_CIRCLE -> {
                val radius = layer.width / 2f
                val center = androidx.compose.ui.geometry.Offset(radius, layer.height / 2f)
                drawCircle(
                    brush = finalBrush,
                    radius = radius,
                    center = center,
                    style = styleToUse,
                    alpha = brushAlpha,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.VECTOR_STAR -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = androidx.compose.ui.graphics.Path().apply {
                        val cx = layer.width / 2f
                        val cy = layer.height / 2f
                        val rOuter = layer.width / 2f
                        val rInner = rOuter * layer.starInnerRadiusRatio.coerceIn(0.01f, 0.99f)
                        val pointsCount = if (layer.polygonEdges >= 3) layer.polygonEdges else 5
                        var angle = Math.PI / 2.0 * 3.0
                        val step = Math.PI / pointsCount

                        moveTo(
                            (cx + Math.cos(angle) * rOuter).toFloat(),
                            (cy + Math.sin(angle) * rOuter).toFloat()
                        )

                        for (i in 0..(pointsCount * 2)) {
                            val r = if (i % 2 == 0) rOuter else rInner
                            lineTo(
                                (cx + Math.cos(angle) * r).toFloat(),
                                (cy + Math.sin(angle) * r).toFloat()
                            )
                            angle += step
                        }
                        close()
                    }
                    pathCache.put(cacheKey, path)
                }
                val maxR = minOf(layer.width, layer.height) / 4f
                val effR = layer.cornerRadius.coerceIn(0f, maxR)
                if (effR > 0f) {
                    val paint = ComposePaintCache.getCleanPaint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.VECTOR_HEART,
            com.example.studio.model.LayerType.VECTOR_CROSS,
            com.example.studio.model.LayerType.VECTOR_SHIELD,
            com.example.studio.model.LayerType.VECTOR_RING,
            com.example.studio.model.LayerType.VECTOR_CRESCENT,
            com.example.studio.model.LayerType.VECTOR_CLOVER,
            com.example.studio.model.LayerType.VECTOR_GEAR,
            com.example.studio.model.LayerType.VECTOR_DIAMOND,
            com.example.studio.model.LayerType.VECTOR_TILTED_RECT,
            com.example.studio.model.LayerType.VECTOR_TRAPEZOID,
            com.example.studio.model.LayerType.VECTOR_ROUNDED_RECT,
            com.example.studio.model.LayerType.VECTOR_PIE_SLICE,
            com.example.studio.model.LayerType.VECTOR_ARROW,
            com.example.studio.model.LayerType.VECTOR_SPEECH_BUBBLE,
            com.example.studio.model.LayerType.VECTOR_CHAT_BUBBLE,
            com.example.studio.model.LayerType.VECTOR_BRACKETS,
            com.example.studio.model.LayerType.VECTOR_DOUBLE_ARROW,
            com.example.studio.model.LayerType.VECTOR_CROSSHAIR,
            com.example.studio.model.LayerType.VECTOR_SPIRAL,
            com.example.studio.model.LayerType.VECTOR_WAVE,
            com.example.studio.model.LayerType.VECTOR_POLYGON,
            com.example.studio.model.LayerType.VECTOR_BLOB,
            com.example.studio.model.LayerType.VECTOR_CONTAINER,
            com.example.studio.model.LayerType.VECTOR_FLOW_CONNECTOR,
            com.example.studio.model.LayerType.VECTOR_NODE,
            com.example.studio.model.LayerType.VECTOR_TIMELINE_MARKER,
            com.example.studio.model.LayerType.VECTOR_ROUNDED_TRIANGLE,
            com.example.studio.model.LayerType.VECTOR_CUT_CORNER_SQUARE,
            com.example.studio.model.LayerType.VECTOR_RING_SEGMENT,
            com.example.studio.model.LayerType.VECTOR_HUD_FRAME_1,
            com.example.studio.model.LayerType.VECTOR_HUD_FRAME_2,
            com.example.studio.model.LayerType.VECTOR_HUD_FRAME_3,
            com.example.studio.model.LayerType.VECTOR_HUD_FRAME_4,
            com.example.studio.model.LayerType.VECTOR_HUD_FRAME_5,
            com.example.studio.model.LayerType.VECTOR_HUD_FRAME_6 -> {
                val cacheKey = getLayerGeometryHash(layer)
                var path = pathCache.get(cacheKey)
                if (path == null) {
                    path = createComplexShapePath(layer.type, layer.width, layer.height, layer.polygonEdges, layer.starInnerRadiusRatio, layer.skewX, layer.skewY, layer.cornerRadius)
                    pathCache.put(cacheKey, path)
                }
                val maxR = minOf(layer.width, layer.height) / 4f
                val effR = layer.cornerRadius.coerceIn(0f, maxR)
                if (effR > 0f && layer.type !in listOf(
                    com.example.studio.model.LayerType.VECTOR_ROUNDED_RECT,
                    com.example.studio.model.LayerType.VECTOR_CUT_CORNER_SQUARE,
                    com.example.studio.model.LayerType.VECTOR_CONTAINER,
                    com.example.studio.model.LayerType.VECTOR_CHAT_BUBBLE,
                    com.example.studio.model.LayerType.VECTOR_SPEECH_BUBBLE,
                    com.example.studio.model.LayerType.VECTOR_ROUNDED_TRIANGLE
                )) {
                    val paint = ComposePaintCache.getCleanPaint().apply {
                        style = if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            androidx.compose.ui.graphics.PaintingStyle.Stroke
                        } else {
                            androidx.compose.ui.graphics.PaintingStyle.Fill
                        }
                        if (styleToUse is androidx.compose.ui.graphics.drawscope.Stroke) {
                            strokeWidth = styleToUse.width
                        }
                        blendMode = composeBlendMode
                        asFrameworkPaint().pathEffect = android.graphics.CornerPathEffect(effR)
                    }
                    finalBrush.applyTo(androidx.compose.ui.geometry.Size(layer.width, layer.height), paint, brushAlpha)
                    drawContext.canvas.drawPath(path, paint)
                } else {
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = styleToUse,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.TEXT -> {
                drawRect(
                    brush = finalBrush,
                    alpha = brushAlpha,
                    style = styleToUse,
                    blendMode = composeBlendMode
                )
            }
            com.example.studio.model.LayerType.FREEHAND_DRAWING -> {
                if (layer.brushPoints.isNotEmpty()) {
                    val cacheKey = layer.id.hashCode()
                    val cachedPath = pathCache.get(cacheKey)
                    val px = layer.positionX
                    val py = layer.positionY

                    val path = if (cachedPath != null) {
                        cachedPath
                    } else {
                        val newPath = androidx.compose.ui.graphics.Path().apply {
                            var isFirst = true
                            for (pt in layer.brushPoints) {
                                if (pt == androidx.compose.ui.geometry.Offset.Unspecified || pt.x.isNaN() || pt.y.isNaN()) {
                                    isFirst = true
                                } else {
                                    if (isFirst) {
                                        moveTo(pt.x - px, pt.y - py)
                                        isFirst = false
                                    } else {
                                        lineTo(pt.x - px, pt.y - py)
                                    }
                                }
                            }
                        }
                        pathCache.put(cacheKey, newPath)
                        newPath
                    }
                    val strokeW = if (fillStyle is androidx.compose.ui.graphics.drawscope.Stroke) fillStyle.width else {
                        (layer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BrushConfig" } as? com.example.studio.model.StudioEffect.PhotoshopEffect)?.parameters?.get("Size")?.value ?: (if (layer.strokeThickness > 0f) layer.strokeThickness else 8f)
                    }
                    drawPath(
                        path = path,
                        brush = finalBrush,
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = strokeW,
                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                        ),
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
            com.example.studio.model.LayerType.GROUP -> {}
            com.example.studio.model.LayerType.ADJUSTMENT_LAYER -> {}
            com.example.studio.model.LayerType.IMAGE_CARD -> {
                if (layer.cornerRadius > 0f) {
                    val effR = layer.cornerRadius
                    drawRoundRect(
                        brush = finalBrush,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(effR, effR),
                        style = fillStyle,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                } else {
                    drawRect(
                        brush = finalBrush,
                        topLeft = androidx.compose.ui.geometry.Offset.Zero,
                        size = androidx.compose.ui.geometry.Size(layer.width, layer.height),
                        style = fillStyle,
                        alpha = brushAlpha,
                        blendMode = composeBlendMode
                    )
                }
            }
        }
    }

    // 1. Drop Shadow Pass
    if (bordersShadowsList.isNotEmpty()) {
        for (bordersShadowsItem in bordersShadowsList) {
            if ((bordersShadowsItem.parameters["DropShadow_Enabled"]?.value ?: 0f) > 0.5f) {
                val dsDistance = bordersShadowsItem.parameters["DropShadow_Distance"]?.value ?: 10f
                val dsSize = bordersShadowsItem.parameters["DropShadow_Size"]?.value ?: 15f
                val dsAngle = bordersShadowsItem.parameters["DropShadow_Angle"]?.value ?: 120f
                val dsOpacity = bordersShadowsItem.parameters["DropShadow_Opacity"]?.value ?: 0.5f
                val dsGlow = bordersShadowsItem.parameters["DropShadow_Glow"]?.value ?: 0f
                val dsSharpen = (bordersShadowsItem.parameters["DropShadow_Sharpen"]?.value ?: 0f) > 0.5f
                val dsZoom = bordersShadowsItem.parameters["DropShadow_Zoom"]?.value ?: 1.0f
                val dsHardness = bordersShadowsItem.parameters["DropShadow_Hardness"]?.value ?: 0f
                val dsAlpha = bordersShadowsItem.parameters["DropShadow_Alpha"]?.value ?: 1.0f
                
                val r = bordersShadowsItem.parameters["DropShadow_Color_R"]?.value ?: 0f
                val g = bordersShadowsItem.parameters["DropShadow_Color_G"]?.value ?: 0f
                val b = bordersShadowsItem.parameters["DropShadow_Color_B"]?.value ?: 0f
                val col = androidx.compose.ui.graphics.Color(r, g, b).copy(alpha = dsAlpha)
                val rads = Math.toRadians(dsAngle.toDouble())
                val dx = (dsDistance * Math.cos(rads)).toFloat()
                val dy = (dsDistance * Math.sin(rads)).toFloat()
                
                drawContext.canvas.save()
                withTransform({
                    translate(left = dx, top = dy)
                    scale(scaleX = dsZoom, scaleY = dsZoom, pivot = androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height / 2f))
                }) {
                    val gradShader = getEffectGradientShader("DropShadow", bordersShadowsItem, layer.width, layer.height)
                    val effectiveBlur = (dsSize * (1f - dsHardness)).coerceAtLeast(0.1f)
                    val useBlur = dsSize > 0.1f && !dsSharpen && effectiveBlur > 0.15f
                    if (useBlur) {
                        drawGeometryWithBlur(col, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill, effectiveBlur, android.graphics.BlurMaskFilter.Blur.NORMAL, isOverlay = false, isShadowOrEffect = true, gradientShader = gradShader)
                    } else {
                        drawGeometry(col, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill, isOverlay = false, isShadowOrEffect = true, gradientShader = gradShader)
                    }
                }
                drawContext.canvas.restore()
            }
        }
    } else if (dropShadow != null) {
        val dsDistance = dropShadow.parameters["Distance"]?.value ?: 10f
        val dsSize = dropShadow.parameters["Size"]?.value ?: 15f
        val dsAngle = dropShadow.parameters["Angle"]?.value ?: 120f
        val dsOpacity = dropShadow.parameters["Opacity"]?.value ?: 0.5f
        val dsHardness = dropShadow.parameters["Hardness"]?.value ?: 0f
        val rads = Math.toRadians(dsAngle.toDouble())
        val dx = (dsDistance * Math.cos(rads)).toFloat()
        val dy = (dsDistance * Math.sin(rads)).toFloat()
        withTransform({
            translate(left = dx, top = dy)
        }) {
            val effectiveBlur = (dsSize * (1f - dsHardness)).coerceAtLeast(0.1f)
            val useBlur = dsSize > 0.1f && effectiveBlur > 0.15f
            if (useBlur) {
                drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill, effectiveBlur, android.graphics.BlurMaskFilter.Blur.NORMAL, isOverlay = false, isShadowOrEffect = true)
            } else {
                drawGeometry(androidx.compose.ui.graphics.Color.Black, dsOpacity, androidx.compose.ui.graphics.drawscope.Fill, isOverlay = false, isShadowOrEffect = true)
            }
        }
    }

    // --- Glass Morphism & Reeded Glass Shader Injection ---
    if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
        val compiledEffect = if (glassMorphism != null && glassMorphism.isEnabled) {
            com.example.studio.ui.GlassShaders.compileGlassMorphismEffect(
                effect = glassMorphism,
                width = layer.width,
                height = layer.height,
                backdrop = backdropBitmap,
                globalX = globalX,
                globalY = globalY,
                zoomScale = totalScale
            )
        } else if (reededGlass != null && reededGlass.isEnabled) {
            com.example.studio.ui.GlassShaders.compileReededGlassEffect(
                effect = reededGlass,
                width = layer.width,
                height = layer.height,
                backdrop = backdropBitmap,
                globalX = globalX,
                globalY = globalY,
                zoomScale = totalScale
            )
        } else if (bevelStyle != null && bevelStyle.isEnabled) {
            com.example.studio.ui.GlassShaders.compileBevelEmbossEffect(
                effect = bevelStyle,
                width = layer.width,
                height = layer.height
            )
        } else {
            null
        }

        if (compiledEffect != null && android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
            val nativeCanvas = drawContext.canvas.nativeCanvas
            val paint = android.graphics.Paint()
            try {
                val setRenderEffectMethod = android.graphics.Paint::class.java.getMethod(
                    "setRenderEffect",
                    android.graphics.RenderEffect::class.java
                )
                setRenderEffectMethod.invoke(paint, compiledEffect as android.graphics.RenderEffect)
            } catch (e: Exception) {
                e.printStackTrace()
            }
            nativeCanvas.saveLayer(null, paint)
            didSaveLayer = true
        }
    }

    // 2. Outer Glow Pass
    if (outerGlow != null) {
        val ogSize = outerGlow.parameters["Size"]?.value ?: 20f
        val ogOpacity = outerGlow.parameters["Opacity"]?.value ?: 0.75f
        val ogR = outerGlow.parameters["Color_R"]?.value ?: outerGlow.parameters["Red"]?.value ?: 1.0f
        val ogG = outerGlow.parameters["Color_G"]?.value ?: outerGlow.parameters["Green"]?.value ?: 1.0f
        val ogB = outerGlow.parameters["Color_B"]?.value ?: outerGlow.parameters["Blue"]?.value ?: 1.0f
        val ogColor = androidx.compose.ui.graphics.Color(ogR, ogG, ogB)
        val blendModeVal = outerGlow.parameters["BlendMode"]?.value ?: 2.0f
        val blendModeOverride = when (blendModeVal.toInt()) {
            0 -> androidx.compose.ui.graphics.BlendMode.SrcOver  // Normal
            1 -> androidx.compose.ui.graphics.BlendMode.Multiply  // Multiply
            2 -> androidx.compose.ui.graphics.BlendMode.Screen    // Screen
            3 -> androidx.compose.ui.graphics.BlendMode.Plus      // Add
            4 -> androidx.compose.ui.graphics.BlendMode.Overlay   // Overlay
            5 -> androidx.compose.ui.graphics.BlendMode.Lighten   // Lighten
            6 -> androidx.compose.ui.graphics.BlendMode.Darken    // Darken
            else -> androidx.compose.ui.graphics.BlendMode.Screen
        }
        if (ogSize > 0.1f) {
            drawGeometryWithBlur(
                finalColor = ogColor, 
                finalOpacity = ogOpacity, 
                fillStyle = androidx.compose.ui.graphics.drawscope.Fill, 
                blurRadius = ogSize, 
                blurMode = android.graphics.BlurMaskFilter.Blur.OUTER, 
                isOverlay = false, 
                blendModeOverride = blendModeOverride,
                isShadowOrEffect = true
            )
        }
    }

    // 3. Main Base Shape Pass with Blurs precomputed
    val bRadius = getBlurRadius(layer) +
            (raBlur?.let { (it.parameters["Amount"]?.value ?: 10f) * 0.15f } ?: 0f) +
            (moBlur?.let { (it.parameters["Distance"]?.value ?: 15f) * 0.1f } ?: 0f) +
            (leBlur?.let { (it.parameters["Radius"]?.value ?: 15f) * 0.1f } ?: 0f)

    // Draw Custom Outer Stroke & Outer Border BEFORE drawing main solid layer so the fill occludes the inner half!
    for (bordersShadowsItem in bordersShadowsList) {
        // 1. Outer Border
        if ((bordersShadowsItem.parameters["OuterBorder_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadowsItem.parameters["OuterBorder_Size"]?.value ?: 0f
            val cRad = bordersShadowsItem.parameters["OuterBorder_CornerRadius"]?.value
            val opacity = bordersShadowsItem.parameters["OuterBorder_Opacity"]?.value ?: 1f
            val r = bordersShadowsItem.parameters["OuterBorder_Color_R"]?.value ?: 1f
            val g = bordersShadowsItem.parameters["OuterBorder_Color_G"]?.value ?: 1f
            val b = bordersShadowsItem.parameters["OuterBorder_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val gradShader = getEffectGradientShader("OuterBorder", bordersShadowsItem, layer.width, layer.height)
                val finalCRad = cRad
                drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f), isOverlay = false, gradientShader = gradShader, cornerRadiusOverride = finalCRad)
            }
        }
        // 2. Outer Stroke
        if ((bordersShadowsItem.parameters["OuterStroke_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadowsItem.parameters["OuterStroke_Size"]?.value ?: 0f
            val cRad = bordersShadowsItem.parameters["OuterStroke_CornerRadius"]?.value
            val opacity = bordersShadowsItem.parameters["OuterStroke_Opacity"]?.value ?: 1f
            val r = bordersShadowsItem.parameters["OuterStroke_Color_R"]?.value ?: 1f
            val g = bordersShadowsItem.parameters["OuterStroke_Color_G"]?.value ?: 1f
            val b = bordersShadowsItem.parameters["OuterStroke_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val gradShader = getEffectGradientShader("OuterStroke", bordersShadowsItem, layer.width, layer.height)
                val finalCRad = cRad
                drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f), isOverlay = false, gradientShader = gradShader, cornerRadiusOverride = finalCRad)
            }
        }
    }

    // Main solid layer drawing
    val hideBaseForPattern = patOverlay != null && ((patOverlay.parameters["Hide Base Shape"]?.value ?: 1f) > 0.5f)
    if (gradOverlay == null && !hideBaseForPattern) {
        if (bRadius > 0.1f) {
            drawGeometryWithBlur(effectiveColor, 1.0f, androidx.compose.ui.graphics.drawscope.Fill, bRadius, android.graphics.BlurMaskFilter.Blur.NORMAL, isOverlay = true)
        } else {
            drawGeometry(effectiveColor, 1.0f, androidx.compose.ui.graphics.drawscope.Fill, isOverlay = true)
        }
    }

    // 4. Gradient Overlay Pass
    if (gradOverlay != null) {
        val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
        val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
        val goOpacity = gradOverlay.parameters["Opacity"]?.value ?: 1.0f
        val gradientTypeOrdinal = (gradOverlay.parameters["GradientType"]?.value ?: 0f).toInt().coerceIn(0, 6)

        val rads = Math.toRadians(goAngle.toDouble())
        val cos = Math.cos(rads).toFloat()
        val sin = Math.sin(rads).toFloat()
        val hasCustomHandles = gradOverlay.parameters["StartX"] != null
        val startX: Float
        val startY: Float
        val endX: Float
        val endY: Float
        if (hasCustomHandles) {
            startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * layer.width
            startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * layer.height
            endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * layer.width
            endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * layer.height
        } else {
            startX = layer.width / 2f - (layer.width / 2f * cos * goScale)
            startY = layer.height / 2f - (layer.height / 2f * sin * goScale)
            endX = layer.width / 2f + (layer.width / 2f * cos * goScale)
            endY = layer.height / 2f + (layer.height / 2f * sin * goScale)
        }

        val goPresetIdx = (gradOverlay.parameters["Preset"]?.value ?: 0f).toInt().coerceIn(0, 7)
        val stopPositions = if (goPresetIdx == 7) {
            val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
            val list = mutableListOf<Float>()
            for (i in 0 until stopCount) {
                val posVal = gradOverlay.parameters["CustomStop_${i}_Pos"]?.value ?: (i.toFloat() / (stopCount - 1).coerceAtLeast(1))
                list.add(posVal)
            }
            list
        } else {
            null
        }

        val originalColors = if (goPresetIdx == 7) {
            val stopCount = (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
            val list = mutableListOf<androidx.compose.ui.graphics.Color>()
            for (i in 0 until stopCount) {
                val rKey = "CustomStop_${i}_R"
                val gKey = "CustomStop_${i}_G"
                val bKey = "CustomStop_${i}_B"
                val aKey = "CustomStop_${i}_A"
                
                val r = gradOverlay.parameters[rKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                    1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                    2 -> 0.0f
                    3 -> 1.0f
                    4 -> 1.0f
                    else -> 0.5f
                }
                val g = gradOverlay.parameters[gKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                    2 -> 1.0f
                    3 -> 1.0f
                    4 -> 0.5f
                    else -> 0.0f
                }
                val b = gradOverlay.parameters[bKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                    1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                    2 -> 0.0f
                    3 -> 0.0f
                    4 -> 0.0f
                    else -> 1.0f
                }
                val a = gradOverlay.parameters[aKey]?.value ?: when(i) {
                    0 -> gradOverlay.parameters["CustomStart_A"]?.value ?: 1.0f
                    1 -> gradOverlay.parameters["CustomEnd_A"]?.value ?: 1.0f
                    else -> 1.0f
                }
                list.add(androidx.compose.ui.graphics.Color(red = r, green = g, blue = b, alpha = a))
            }
            list
        } else {
            gradientPresets[goPresetIdx.coerceIn(0, gradientPresets.size - 1)]
        }

        val colorStops = if (stopPositions != null) {
            stopPositions.zip(originalColors).map { Pair(it.first, it.second) }.sortedBy { it.first }.toTypedArray()
        } else {
            null
        }

        val finalColorStops = if (colorStops != null) {
            colorStops
        } else {
            val sz = originalColors.size
            if (sz > 1) {
                originalColors.mapIndexed { idx, col ->
                    Pair(idx.toFloat() / (sz - 1).coerceAtLeast(1), col)
                }.toTypedArray()
            } else if (sz == 1) {
                arrayOf(Pair(0f, originalColors[0]), Pair(1f, originalColors[0]))
            } else {
                null
            }
        }

        val getColorAtRatio = { ratio: Float ->
            val stops = finalColorStops
            if (stops != null && stops.isNotEmpty()) {
                val sortedStops = stops.sortedBy { it.first }
                if (ratio <= sortedStops.first().first) {
                    sortedStops.first().second
                } else if (ratio >= sortedStops.last().first) {
                    sortedStops.last().second
                } else {
                    var match: androidx.compose.ui.graphics.Color? = null
                    for (i in 0 until sortedStops.size - 1) {
                        val s1 = sortedStops[i]
                        val s2 = sortedStops[i + 1]
                        if (ratio >= s1.first && ratio <= s2.first) {
                            val t = (ratio - s1.first) / (s2.first - s1.first).coerceAtLeast(0.001f)
                            match = androidx.compose.ui.graphics.Color(
                                red = s1.second.red + (s2.second.red - s1.second.red) * t,
                                green = s1.second.green + (s2.second.green - s1.second.green) * t,
                                blue = s1.second.blue + (s2.second.blue - s1.second.blue) * t,
                                alpha = s1.second.alpha + (s2.second.alpha - s1.second.alpha) * t
                            )
                            break
                        }
                    }
                    match ?: interpolateMultiColor(originalColors, ratio)
                }
            } else {
                interpolateMultiColor(originalColors, ratio)
            }
        }

        val pathCachedObj = layerPath
        clipPath(pathCachedObj) {
            when (gradientTypeOrdinal) {
                0 -> { // Linear Gradient
                    val gradBrush = if (finalColorStops != null) {
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colorStops = finalColorStops,
                            start = androidx.compose.ui.geometry.Offset(startX, startY),
                            end = androidx.compose.ui.geometry.Offset(endX, endY)
                        )
                    } else {
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colors = originalColors,
                            start = androidx.compose.ui.geometry.Offset(startX, startY),
                            end = androidx.compose.ui.geometry.Offset(endX, endY)
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
                1 -> { // Radial Gradient
                    val dist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val radius = if (dist > 1f) dist else ((Math.min(layer.width, layer.height) / 2f) * goScale)
                    val gradBrush = if (finalColorStops != null) {
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colorStops = finalColorStops,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    } else {
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colors = originalColors,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
                2 -> { // Sweep / Angular Gradient
                    val dx = endX - startX
                    val dy = endY - startY
                    val lineAngle = if (Math.abs(dx) > 0.1f || Math.abs(dy) > 0.1f) {
                        Math.toDegrees(Math.atan2(dy.toDouble(), dx.toDouble())).toFloat()
                    } else {
                        goAngle
                    }
                    val gradBrush = if (finalColorStops != null) {
                        androidx.compose.ui.graphics.Brush.sweepGradient(
                            colorStops = finalColorStops,
                            center = androidx.compose.ui.geometry.Offset(startX, startY)
                        )
                    } else {
                        androidx.compose.ui.graphics.Brush.sweepGradient(
                            colors = originalColors,
                            center = androidx.compose.ui.geometry.Offset(startX, startY)
                        )
                    }
                    withTransform({
                        rotate(degrees = lineAngle, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                    }) {
                        drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                    }
                }
                3 -> { // Reflected Gradient
                    val reflectedColorStops = if (finalColorStops != null) {
                        val stopsList = mutableListOf<Pair<Float, androidx.compose.ui.graphics.Color>>()
                        finalColorStops.forEach { (fraction, color) ->
                            stopsList.add(Pair(0.5f - 0.5f * fraction, color))
                            stopsList.add(Pair(0.5f + 0.5f * fraction, color))
                        }
                        stopsList.sortBy { it.first }
                        stopsList.toTypedArray()
                    } else {
                        null
                    }
                    val brushStart = androidx.compose.ui.geometry.Offset(startX - (endX - startX), startY - (endY - startY))
                    val brushEnd = androidx.compose.ui.geometry.Offset(endX, endY)
                    val gradBrush = if (reflectedColorStops != null) {
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colorStops = reflectedColorStops,
                            start = brushStart,
                            end = brushEnd
                        )
                    } else {
                        val reflectedColors = originalColors.reversed() + originalColors.drop(1)
                        androidx.compose.ui.graphics.Brush.linearGradient(
                            colors = reflectedColors,
                            start = brushStart,
                            end = brushEnd
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
                4 -> { // Shape-Conforming Concentric Gradient
                    val steps = 30
                    val refDist = Math.hypot((layer.width / 2f).toDouble(), (layer.height / 2f).toDouble()).toFloat().coerceAtLeast(1f)
                    val curDist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val finalScale = if (hasCustomHandles) (curDist / refDist) else goScale

                    for (step in steps downTo 1) {
                        val ratio = step.toFloat() / steps
                        val color = getColorAtRatio(ratio)
                        withTransform({
                            scale(scaleX = ratio * finalScale, scaleY = ratio * finalScale, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                        }) {
                            drawGeometry(color, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                        }
                    }
                }
                5 -> { // Diamond / Starburst Gradient
                    val steps = 30
                    val refDist = Math.hypot((layer.width / 2f).toDouble(), (layer.height / 2f).toDouble()).toFloat().coerceAtLeast(1f)
                    val curDist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val finalScale = if (hasCustomHandles) (curDist / refDist) else goScale
                    val dx = endX - startX
                    val dy = endY - startY
                    val lineAngle = if (Math.abs(dx) > 0.1f || Math.abs(dy) > 0.1f) {
                        Math.toDegrees(Math.atan2(dy.toDouble(), dx.toDouble())).toFloat()
                    } else {
                        45f
                    }

                    for (step in steps downTo 1) {
                        val ratio = step.toFloat() / steps
                        val color = getColorAtRatio(ratio)
                        withTransform({
                            scale(scaleX = ratio * finalScale, scaleY = ratio * finalScale, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                            rotate(degrees = lineAngle, pivot = androidx.compose.ui.geometry.Offset(startX, startY))
                        }) {
                            drawGeometry(color, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                        }
                    }
                }
                6 -> { // Reflected Radial Gradient
                    val reflectedColorStops = if (finalColorStops != null) {
                        val stopsList = mutableListOf<Pair<Float, androidx.compose.ui.graphics.Color>>()
                        finalColorStops.forEach { (fraction, color) ->
                            stopsList.add(Pair(0.5f - 0.5f * fraction, color))
                            stopsList.add(Pair(0.5f + 0.5f * fraction, color))
                        }
                        stopsList.sortBy { it.first }
                        stopsList.toTypedArray()
                    } else {
                        null
                    }
                    val dist = Math.hypot((endX - startX).toDouble(), (endY - startY).toDouble()).toFloat()
                    val radius = if (dist > 1f) dist else ((Math.min(layer.width, layer.height) / 2f) * goScale)
                    val gradBrush = if (reflectedColorStops != null) {
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colorStops = reflectedColorStops,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    } else {
                        val reflectedColors = originalColors.reversed() + originalColors.drop(1)
                        androidx.compose.ui.graphics.Brush.radialGradient(
                            colors = reflectedColors,
                            center = androidx.compose.ui.geometry.Offset(startX, startY),
                            radius = radius.coerceAtLeast(1f)
                        )
                    }
                    drawGeometryWithBrush(gradBrush, goOpacity, androidx.compose.ui.graphics.drawscope.Fill)
                }
            }
        }
    }

    // 5. Pattern Overlay Pass
    if (patOverlay != null) {
        val poScale = (patOverlay.parameters["Scale"]?.value ?: 100f) / 100f
        val poAngle = patOverlay.parameters["Angle"]?.value ?: 0f
        val poOpacity = (patOverlay.parameters["Opacity"]?.value ?: 1.0f).coerceIn(0f, 1f)
        val poOffX = patOverlay.parameters["X Offset"]?.value ?: 0f
        val poOffY = patOverlay.parameters["Y Offset"]?.value ?: 0f
        val poStyle = (patOverlay.parameters["Pattern Style"]?.value ?: 0f).toInt().coerceIn(0, 6)
        val hideBaseShape = (patOverlay.parameters["Hide Base Shape"]?.value ?: 1f) > 0.5f
        
        val pR = patOverlay.parameters["ColorRed"]?.value ?: 1.0f
        val pG = patOverlay.parameters["ColorGreen"]?.value ?: 1.0f
        val pB = patOverlay.parameters["ColorBlue"]?.value ?: 1.0f
        val patColor = androidx.compose.ui.graphics.Color(pR, pG, pB, poOpacity * layerOpacity)

        if (hideBaseShape) {
            // Base shape is hidden, leaving behind only the pattern
        }

        val step = (24f * poScale).coerceAtLeast(6f)
        val rad = Math.toRadians(poAngle.toDouble())
        val cosA = Math.cos(rad).toFloat()
        val sinA = Math.sin(rad).toFloat()

        when (poStyle) {
            0 -> {
                // Diagonal Hatch
                var d = -layer.height - layer.width
                while (d < (layer.width + layer.height) * 2f) {
                    val startX = d + poOffX
                    val startY = poOffY
                    val endX = d - layer.height + poOffX
                    val endY = layer.height + poOffY
                    
                    // Apply rotation around center
                    val cx = layer.width / 2f
                    val cy = layer.height / 2f
                    val rStartX = cx + (startX - cx) * cosA - (startY - cy) * sinA
                    val rStartY = cy + (startX - cx) * sinA + (startY - cy) * cosA
                    val rEndX = cx + (endX - cx) * cosA - (endY - cy) * sinA
                    val rEndY = cy + (endX - cx) * sinA + (endY - cy) * cosA

                    drawLine(
                        color = patColor,
                        start = androidx.compose.ui.geometry.Offset(rStartX, rStartY),
                        end = androidx.compose.ui.geometry.Offset(rEndX, rEndY),
                        strokeWidth = maxOf(1f, 2f * poScale),
                        blendMode = composeBlendMode
                    )
                    d += step
                }
            }
            1 -> {
                // Polka Dots
                val cx = layer.width / 2f
                val cy = layer.height / 2f
                val dotRadius = maxOf(1.5f, 4f * poScale)
                var x = -step * 2 + poOffX
                while (x < layer.width + step * 2) {
                    var y = -step * 2 + poOffY
                    while (y < layer.height + step * 2) {
                        val rx = cx + (x - cx) * cosA - (y - cy) * sinA
                        val ry = cy + (x - cx) * sinA + (y - cy) * cosA
                        drawCircle(
                            color = patColor,
                            radius = dotRadius,
                            center = androidx.compose.ui.geometry.Offset(rx, ry),
                            blendMode = composeBlendMode
                        )
                        y += step
                    }
                    x += step
                }
            }
            2 -> {
                // Checkerboard
                val cx = layer.width / 2f
                val cy = layer.height / 2f
                var col = 0
                var x = -step * 2 + poOffX
                while (x < layer.width + step * 2) {
                    var row = 0
                    var y = -step * 2 + poOffY
                    while (y < layer.height + step * 2) {
                        if ((col + row) % 2 == 0) {
                            val rx = cx + (x - cx) * cosA - (y - cy) * sinA
                            val ry = cy + (x - cx) * sinA + (y - cy) * cosA
                            drawRect(
                                color = patColor,
                                topLeft = androidx.compose.ui.geometry.Offset(rx, ry),
                                size = androidx.compose.ui.geometry.Size(step, step),
                                blendMode = composeBlendMode
                            )
                        }
                        row++
                        y += step
                    }
                    col++
                    x += step
                }
            }
            3 -> {
                // Grid Cross
                var x = poOffX % step
                while (x < layer.width) {
                    drawLine(color = patColor, start = androidx.compose.ui.geometry.Offset(x, 0f), end = androidx.compose.ui.geometry.Offset(x, layer.height), strokeWidth = 1.5f * poScale, blendMode = composeBlendMode)
                    x += step
                }
                var y = poOffY % step
                while (y < layer.height) {
                    drawLine(color = patColor, start = androidx.compose.ui.geometry.Offset(0f, y), end = androidx.compose.ui.geometry.Offset(layer.width, y), strokeWidth = 1.5f * poScale, blendMode = composeBlendMode)
                    y += step
                }
            }
            4 -> {
                // Crosshatch
                var d = -layer.height - layer.width
                while (d < (layer.width + layer.height) * 2f) {
                    drawLine(color = patColor, start = androidx.compose.ui.geometry.Offset(d + poOffX, 0f), end = androidx.compose.ui.geometry.Offset(d - layer.height + poOffX, layer.height), strokeWidth = 1.5f * poScale, blendMode = composeBlendMode)
                    drawLine(color = patColor, start = androidx.compose.ui.geometry.Offset(d + poOffX, layer.height), end = androidx.compose.ui.geometry.Offset(d - layer.height + poOffX, 0f), strokeWidth = 1.5f * poScale, blendMode = composeBlendMode)
                    d += step
                }
            }
            5 -> {
                // Horizontal Stripes
                var y = poOffY % step
                while (y < layer.height) {
                    drawLine(color = patColor, start = androidx.compose.ui.geometry.Offset(0f, y), end = androidx.compose.ui.geometry.Offset(layer.width, y), strokeWidth = maxOf(1f, step / 2f), blendMode = composeBlendMode)
                    y += step
                }
            }
            else -> {
                // Waves
                var y = poOffY % step
                while (y < layer.height) {
                    val path = androidx.compose.ui.graphics.Path()
                    path.moveTo(0f, y)
                    var x = 0f
                    while (x < layer.width) {
                        path.quadraticTo(x + step / 2f, y + 10f * sinA, x + step, y)
                        x += step
                    }
                    drawPath(path = path, color = patColor, style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2f * poScale), blendMode = composeBlendMode)
                    y += step
                }
            }
        }
    }

    // 5b. Grids Overlay Pass
    if (gridsOverlay != null) {
        val numCols = (gridsOverlay.parameters["Columns"]?.value ?: 8f).toInt().coerceIn(1, 1000)
        val numRows = (gridsOverlay.parameters["Rows"]?.value ?: 8f).toInt().coerceIn(1, 1000)
        val lineWidth = gridsOverlay.parameters["Width"]?.value ?: 1.5f
        val r = gridsOverlay.parameters["ColorRed"]?.value ?: 1.0f
        val g = gridsOverlay.parameters["ColorGreen"]?.value ?: 1.0f
        val b = gridsOverlay.parameters["ColorBlue"]?.value ?: 1.0f
        val a = gridsOverlay.parameters["ColorAlpha"]?.value ?: 1.0f
        val gridColor = androidx.compose.ui.graphics.Color(r, g, b, a * layerOpacity)

        val offsetX = gridsOverlay.parameters["OffsetX"]?.value ?: 0f
        val offsetY = gridsOverlay.parameters["OffsetY"]?.value ?: 0f
        val dashed = (gridsOverlay.parameters["Dashed"]?.value ?: 0f) > 0.5f
        val dashLength = gridsOverlay.parameters["Dash Length"]?.value ?: 15f
        val dashGap = gridsOverlay.parameters["Dash Gap"]?.value ?: 10f

        val effect = if (dashed && dashLength > 0f && dashGap > 0f) {
            androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(dashLength, dashGap), 0f)
        } else {
            null
        }

        // Draw vertical column lines
        val colStep = layer.width / numCols
        for (i in 0..numCols) {
            val x = i * colStep + offsetX
            if (x in 0f..layer.width) {
                drawLine(
                    color = gridColor,
                    start = androidx.compose.ui.geometry.Offset(x, 0f),
                    end = androidx.compose.ui.geometry.Offset(x, layer.height),
                    strokeWidth = lineWidth,
                    blendMode = composeBlendMode,
                    pathEffect = effect
                )
            }
        }

        // Draw horizontal row lines
        val rowStep = layer.height / numRows
        for (j in 0..numRows) {
            val y = j * rowStep + offsetY
            if (y in 0f..layer.height) {
                drawLine(
                    color = gridColor,
                    start = androidx.compose.ui.geometry.Offset(0f, y),
                    end = androidx.compose.ui.geometry.Offset(layer.width, y),
                    strokeWidth = lineWidth,
                    blendMode = composeBlendMode,
                    pathEffect = effect
                )
            }
        }
    }

    // 6. Satin Metallic Waves Pass
    if (satinStyle != null) {
        val satSize = satinStyle.parameters["Size"]?.value ?: 14f
        val satOpacity = satinStyle.parameters["Opacity"]?.value ?: 0.5f
        val satPath = androidx.compose.ui.graphics.Path().apply {
            moveTo(0f, layer.height * 0.25f)
            quadraticTo(layer.width / 2f, layer.height * 0.7f, layer.width, layer.height * 0.3f)
        }
        val composePaint = ComposePaintCache.getCleanPaint().apply {
            color = androidx.compose.ui.graphics.Color.White.copy(alpha = satOpacity * 0.40f * layerOpacity)
            style = androidx.compose.ui.graphics.PaintingStyle.Stroke
            strokeWidth = satSize
            blendMode = composeBlendMode
            if (satSize > 1f) {
                val isSoftwareCanvas = !drawContext.canvas.nativeCanvas.isHardwareAccelerated
                if (!isSoftwareCanvas && android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {
                    try {
                        val fwPaint = asFrameworkPaint()
                        val mSet = fwPaint.javaClass.getMethod("setRenderEffect", android.graphics.RenderEffect::class.java)
                        val blurEffect = android.graphics.RenderEffect.createBlurEffect(satSize * 0.5f, satSize * 0.5f, android.graphics.Shader.TileMode.DECAL)
                        mSet.invoke(fwPaint, blurEffect)
                    } catch (t: Throwable) {
                        asFrameworkPaint().maskFilter = android.graphics.BlurMaskFilter(satSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
                    }
                } else {
                    asFrameworkPaint().maskFilter = android.graphics.BlurMaskFilter(satSize * 0.5f, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        }
        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                drawContext.canvas.drawPath(satPath, composePaint)
            }
        } else {
            drawContext.canvas.drawPath(satPath, composePaint)
        }
    }

    // 7. Inner Shadow Pass
    if (bordersShadowsList.isNotEmpty()) {
        for (bordersShadowsItem in bordersShadowsList) {
            if ((bordersShadowsItem.parameters["InnerShadow_Enabled"]?.value ?: 0f) > 0.5f) {
                val isDistance = bordersShadowsItem.parameters["InnerShadow_Distance"]?.value ?: 5f
                val isSize = bordersShadowsItem.parameters["InnerShadow_Size"]?.value ?: 10f
                val isAngle = bordersShadowsItem.parameters["InnerShadow_Angle"]?.value ?: 120f
                val isOpacity = bordersShadowsItem.parameters["InnerShadow_Opacity"]?.value ?: 0.5f
                val isHardness = bordersShadowsItem.parameters["InnerShadow_Hardness"]?.value ?: 0f
                val isChoke = bordersShadowsItem.parameters["InnerShadow_Choke"]?.value ?: 0f

                val r = bordersShadowsItem.parameters["InnerShadow_Color_R"]?.value ?: 0f
                val g = bordersShadowsItem.parameters["InnerShadow_Color_G"]?.value ?: 0f
                val b = bordersShadowsItem.parameters["InnerShadow_Color_B"]?.value ?: 0f
                val col = androidx.compose.ui.graphics.Color(r, g, b)

                val rads = Math.toRadians(isAngle.toDouble())
                val dx = (isDistance * Math.cos(rads)).toFloat()
                val dy = (isDistance * Math.sin(rads)).toFloat()

                val effectiveBlur = (isSize * (1f - isHardness)).coerceAtLeast(0.1f)
                val effectiveStrokeWidth = isSize * 2f + (isChoke / 100f) * isSize * 4f

                val gradShader = getEffectGradientShader("InnerShadow", bordersShadowsItem, layer.width, layer.height)
                val pathCachedObj = layerPath
                if (!pathCachedObj.asAndroidPath().isEmpty) {
                    clipPath(pathCachedObj) {
                        withTransform({ translate(left = dx, top = dy) }) {
                            drawGeometryWithBlur(col, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = effectiveStrokeWidth), effectiveBlur, android.graphics.BlurMaskFilter.Blur.NORMAL, gradientShader = gradShader)
                        }
                    }
                } else {
                    withTransform({ translate(left = dx, top = dy) }) {
                        drawGeometryWithBlur(col, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = effectiveStrokeWidth), effectiveBlur, android.graphics.BlurMaskFilter.Blur.NORMAL, gradientShader = gradShader)
                    }
                }
            }
        }
    } else if (innerShadow != null) {
        val isDistance = innerShadow.parameters["Distance"]?.value ?: 5f
        val isSize = innerShadow.parameters["Size"]?.value ?: 10f
        val isAngle = innerShadow.parameters["Angle"]?.value ?: 120f
        val isOpacity = innerShadow.parameters["Opacity"]?.value ?: 0.5f
        val isHardness = innerShadow.parameters["Hardness"]?.value ?: 0f
        val isChoke = innerShadow.parameters["Choke"]?.value ?: 0f

        val rads = Math.toRadians(isAngle.toDouble())
        val dx = (isDistance * Math.cos(rads)).toFloat()
        val dy = (isDistance * Math.sin(rads)).toFloat()

        val effectiveBlur = (isSize * (1f - isHardness)).coerceAtLeast(0.1f)
        val effectiveStrokeWidth = isSize * 2f + (isChoke / 100f) * isSize * 4f

        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                withTransform({ translate(left = dx, top = dy) }) {
                    drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = effectiveStrokeWidth), effectiveBlur, android.graphics.BlurMaskFilter.Blur.NORMAL)
                }
            }
        } else {
            withTransform({ translate(left = dx, top = dy) }) {
                drawGeometryWithBlur(androidx.compose.ui.graphics.Color.Black, isOpacity, androidx.compose.ui.graphics.drawscope.Stroke(width = effectiveStrokeWidth), effectiveBlur, android.graphics.BlurMaskFilter.Blur.NORMAL)
            }
        }
    }

    // 8. Inner Glow Pass
    if (innerGlow != null) {
        val igDistance = innerGlow.parameters["Distance"]?.value ?: innerGlow.parameters["Radius"]?.value ?: 0f
        val igSize = innerGlow.parameters["Size"]?.value ?: innerGlow.parameters["Radius"]?.value ?: 15f
        val igAngle = innerGlow.parameters["Angle"]?.value ?: 120f
        val igOpacity = innerGlow.parameters["Opacity"]?.value ?: 0.65f
        val igHardness = innerGlow.parameters["Hardness"]?.value ?: 0f
        val igChoke = innerGlow.parameters["Choke"]?.value ?: 0f

        val igR = innerGlow.parameters["Color_R"]?.value ?: innerGlow.parameters["Red"]?.value ?: 1.0f
        val igG = innerGlow.parameters["Color_G"]?.value ?: innerGlow.parameters["Green"]?.value ?: 1.0f
        val igB = innerGlow.parameters["Color_B"]?.value ?: innerGlow.parameters["Blue"]?.value ?: 1.0f
        val igColor = androidx.compose.ui.graphics.Color(igR, igG, igB)

        val blendModeVal = innerGlow.parameters["BlendMode"]?.value ?: 2.0f
        val blendModeOverride = when (blendModeVal.toInt()) {
            0 -> androidx.compose.ui.graphics.BlendMode.SrcOver  // Normal
            1 -> androidx.compose.ui.graphics.BlendMode.Multiply  // Multiply
            2 -> androidx.compose.ui.graphics.BlendMode.Screen    // Screen
            3 -> androidx.compose.ui.graphics.BlendMode.Plus      // Add
            4 -> androidx.compose.ui.graphics.BlendMode.Overlay   // Overlay
            5 -> androidx.compose.ui.graphics.BlendMode.Lighten   // Lighten
            6 -> androidx.compose.ui.graphics.BlendMode.Darken    // Darken
            else -> androidx.compose.ui.graphics.BlendMode.Screen
        }

        val rads = Math.toRadians(igAngle.toDouble())
        val dx = (igDistance * Math.cos(rads)).toFloat()
        val dy = (igDistance * Math.sin(rads)).toFloat()

        val effectiveBlur = (igSize * (1f - igHardness)).coerceAtLeast(0.1f)
        val effectiveStrokeWidth = igSize * 2f + (igChoke / 100f) * igSize * 4f

        val pathCachedObj = layerPath
        if (!pathCachedObj.asAndroidPath().isEmpty) {
            clipPath(pathCachedObj) {
                withTransform({ translate(left = dx, top = dy) }) {
                    drawGeometryWithBlur(
                        finalColor = igColor,
                        finalOpacity = igOpacity,
                        fillStyle = androidx.compose.ui.graphics.drawscope.Stroke(width = effectiveStrokeWidth),
                        blurRadius = effectiveBlur,
                        blurMode = android.graphics.BlurMaskFilter.Blur.NORMAL,
                        blendModeOverride = blendModeOverride
                    )
                }
            }
        } else {
            withTransform({ translate(left = dx, top = dy) }) {
                drawGeometryWithBlur(
                    finalColor = igColor,
                    finalOpacity = igOpacity,
                    fillStyle = androidx.compose.ui.graphics.drawscope.Stroke(width = effectiveStrokeWidth),
                    blurRadius = effectiveBlur,
                    blurMode = android.graphics.BlurMaskFilter.Blur.NORMAL,
                    blendModeOverride = blendModeOverride
                )
            }
        }
    }

    // 9. Stroke Pass
    for (bordersShadowsItem in bordersShadowsList) {
        // 1. Center Stroke
        if ((bordersShadowsItem.parameters["CenterStroke_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadowsItem.parameters["CenterStroke_Size"]?.value ?: 0f
            val opacity = bordersShadowsItem.parameters["CenterStroke_Opacity"]?.value ?: 1f
            val r = bordersShadowsItem.parameters["CenterStroke_Color_R"]?.value ?: 1f
            val g = bordersShadowsItem.parameters["CenterStroke_Color_G"]?.value ?: 1f
            val b = bordersShadowsItem.parameters["CenterStroke_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val gradShader = getEffectGradientShader("CenterStroke", bordersShadowsItem, layer.width, layer.height)
                drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size), gradientShader = gradShader)
            }
        }
        // 2. Inner stroke (clipped to layer path!)
        if ((bordersShadowsItem.parameters["InnerStroke_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadowsItem.parameters["InnerStroke_Size"]?.value ?: 0f
            val cRad = bordersShadowsItem.parameters["InnerStroke_CornerRadius"]?.value
            val opacity = bordersShadowsItem.parameters["InnerStroke_Opacity"]?.value ?: 1f
            val r = bordersShadowsItem.parameters["InnerStroke_Color_R"]?.value ?: 1f
            val g = bordersShadowsItem.parameters["InnerStroke_Color_G"]?.value ?: 1f
            val b = bordersShadowsItem.parameters["InnerStroke_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val gradShader = getEffectGradientShader("InnerStroke", bordersShadowsItem, layer.width, layer.height)
                val finalCRad = cRad
                val pathCachedObj = layerPath
                if (pathCachedObj.asAndroidPath().isEmpty) {
                    drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size), gradientShader = gradShader, cornerRadiusOverride = finalCRad)
                } else {
                    clipPath(pathCachedObj) {
                        drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f), gradientShader = gradShader, cornerRadiusOverride = finalCRad)
                    }
                }
            }
        }
        // 3. Inner Border (clipped to layer path!)
        if ((bordersShadowsItem.parameters["InnerBorder_Enabled"]?.value ?: 0f) > 0.5f) {
            val size = bordersShadowsItem.parameters["InnerBorder_Size"]?.value ?: 0f
            val cRad = bordersShadowsItem.parameters["InnerBorder_CornerRadius"]?.value
            val opacity = bordersShadowsItem.parameters["InnerBorder_Opacity"]?.value ?: 1f
            val r = bordersShadowsItem.parameters["InnerBorder_Color_R"]?.value ?: 1f
            val g = bordersShadowsItem.parameters["InnerBorder_Color_G"]?.value ?: 1f
            val b = bordersShadowsItem.parameters["InnerBorder_Color_B"]?.value ?: 1f
            val col = androidx.compose.ui.graphics.Color(r, g, b)
            if (size > 0f) {
                val gradShader = getEffectGradientShader("InnerBorder", bordersShadowsItem, layer.width, layer.height)
                val finalCRad = cRad
                val pathCachedObj = layerPath
                if (pathCachedObj.asAndroidPath().isEmpty) {
                    drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size), gradientShader = gradShader, cornerRadiusOverride = finalCRad)
                } else {
                    clipPath(pathCachedObj) {
                        drawGeometry(col, opacity, androidx.compose.ui.graphics.drawscope.Stroke(width = size * 2f), gradientShader = gradShader, cornerRadiusOverride = finalCRad)
                    }
                }
            }
        }
    }
    if (strokeStyle != null) {
        val sSize = strokeStyle.parameters["Size"]?.value ?: 3f
        val sOpacity = strokeStyle.parameters["Opacity"]?.value ?: 1.0f
        drawGeometry(androidx.compose.ui.graphics.Color.White, sOpacity * 0.9f, androidx.compose.ui.graphics.drawscope.Stroke(width = sSize))
    }

    // 10. Bevel & Emboss Pass
    if (bevelStyle != null && bevelStyle.isEnabled) {
        val bevTechVal = (bevelStyle.parameters["Technique"]?.value ?: 0f).toInt().coerceIn(0, 2)
        val bevDirVal = (bevelStyle.parameters["Direction"]?.value ?: 0f).toInt().coerceIn(0, 1) // 0 = Up, 1 = Down
        val bevSize = (bevelStyle.parameters["Size"]?.value ?: 8f).coerceAtLeast(1f)
        val bevDepth = bevelStyle.parameters["Depth"]?.value ?: 100f
        val bevSoften = bevelStyle.parameters["Soften"]?.value ?: 0f
        val bevAngle = bevelStyle.parameters["Angle"]?.value ?: 120f
        val bevAltitude = bevelStyle.parameters["Altitude"]?.value ?: 30f
        val hlOpacity = bevelStyle.parameters["Highlight Opacity"]?.value ?: 0.75f
        val shOpacity = bevelStyle.parameters["Shadow Opacity"]?.value ?: 0.75f

        val bMult = (bevDepth / 100f).coerceIn(0.1f, 3.0f)
        val radAngle = java.lang.Math.toRadians(bevAngle.toDouble())
        val radAltitude = java.lang.Math.toRadians(bevAltitude.toDouble())
        val cosAlt = java.lang.Math.cos(radAltitude).toFloat()

        val dirSign = if (bevDirVal == 1) -1f else 1f
        val offsetProj = (bevSize * 0.35f * cosAlt).coerceAtLeast(1f)

        val dxHl = (-offsetProj * java.lang.Math.cos(radAngle)).toFloat() * dirSign
        val dyHl = (-offsetProj * java.lang.Math.sin(radAngle)).toFloat() * dirSign
        val dxSh = (offsetProj * java.lang.Math.cos(radAngle)).toFloat() * dirSign
        val dySh = (offsetProj * java.lang.Math.sin(radAngle)).toFloat() * dirSign

        val blurRad = when (bevTechVal) {
            1 -> bevSoften.coerceAtLeast(0.1f) // Chisel Hard
            2 -> (bevSize * 0.2f + bevSoften).coerceAtLeast(0.5f) // Chisel Soft
            else -> (bevSize * 0.5f + bevSoften).coerceAtLeast(0.5f) // Smooth
        }

        val shapePath = if (!layerPath.asAndroidPath().isEmpty) {
            layerPath
        } else {
            androidx.compose.ui.graphics.Path().apply {
                addRoundRect(
                    androidx.compose.ui.geometry.RoundRect(
                        rect = androidx.compose.ui.geometry.Rect(0f, 0f, layer.width, layer.height),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(layer.cornerRadius, layer.cornerRadius)
                    )
                )
            }
        }

        clipPath(shapePath) {
            // Highlight (White) facing light with Screen blend mode
            withTransform({ translate(left = dxHl, top = dyHl) }) {
                drawGeometryWithBlur(
                    finalColor = androidx.compose.ui.graphics.Color.White,
                    finalOpacity = (hlOpacity * 0.65f * bMult).coerceIn(0.01f, 1.0f),
                    fillStyle = androidx.compose.ui.graphics.drawscope.Stroke(width = bevSize * 1.2f),
                    blurRadius = blurRad,
                    blurMode = android.graphics.BlurMaskFilter.Blur.NORMAL,
                    blendModeOverride = androidx.compose.ui.graphics.BlendMode.Screen
                )
            }
            // Shadow (Black) away from light with Multiply blend mode
            withTransform({ translate(left = dxSh, top = dySh) }) {
                drawGeometryWithBlur(
                    finalColor = androidx.compose.ui.graphics.Color.Black,
                    finalOpacity = (shOpacity * 0.7f * bMult).coerceIn(0.01f, 1.0f),
                    fillStyle = androidx.compose.ui.graphics.drawscope.Stroke(width = bevSize * 1.2f),
                    blurRadius = blurRad,
                    blurMode = android.graphics.BlurMaskFilter.Blur.NORMAL,
                    blendModeOverride = androidx.compose.ui.graphics.BlendMode.Multiply
                )
            }
        }
    }

    // 11. Custom Noise Grain Pass
    if (noiseFil != null) {
        val amount = noiseFil.parameters["Amount"]?.value ?: 10f
        val rSeed = java.util.Random(layer.id.hashCode().toLong())
        val dotCount = (amount * 3.5f).toInt().coerceIn(10, 250)
        for (i in 0 until dotCount) {
            val nx = rSeed.nextFloat() * layer.width
            val ny = rSeed.nextFloat() * layer.height
            val colVal = if (rSeed.nextBoolean()) androidx.compose.ui.graphics.Color.White else androidx.compose.ui.graphics.Color.Black
            drawCircle(
                color = colVal.copy(alpha = 0.3f * layerOpacity),
                radius = 1f,
                center = androidx.compose.ui.geometry.Offset(nx, ny)
            )
        }
    }

    // 12. Dust & Scratches Pass
    if (dustScratch != null) {
        val dRadius = dustScratch.parameters["Radius"]?.value ?: 2f
        val rSeed = java.util.Random(layer.id.hashCode().toLong() + 199)
        val count = (dRadius * 0.12f + 4f).toInt()
        for (i in 0 until count) {
            val sx = rSeed.nextFloat() * layer.width
            val sy = rSeed.nextFloat() * layer.height
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.5f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(sx, sy),
                end = androidx.compose.ui.geometry.Offset(sx + rSeed.nextFloat() * 10f - 5f, sy + rSeed.nextFloat() * 10f - 5f),
                strokeWidth = 1f
            )
            drawCircle(
                color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.45f * layerOpacity),
                radius = 1.2f,
                center = androidx.compose.ui.geometry.Offset(rSeed.nextFloat() * layer.width, rSeed.nextFloat() * layer.height)
            )
        }
    }

    // 13. Edge Shaders (Median/Unsharp/Smart/High Filters)
    if (medFil != null || unsharpFil != null || smartFil != null || highFil != null) {
        val intense = if (highFil != null) 0.7f else 0.35f
        drawGeometry(androidx.compose.ui.graphics.Color.White, intense, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5f))
    }

    // 14. Color Halftone Pass
    if (halftoneFil != null) {
        val maxR = halftoneFil.parameters["MaxRadius"]?.value ?: 8f
        val spacing = (maxR * 2.8f).coerceAtLeast(8f)
        val stepX = spacing.coerceAtLeast(layer.width / 50f)
        val stepY = spacing.coerceAtLeast(layer.height / 50f)
        var hx = stepX / 2
        while (hx < layer.width) {
            var hy = stepY / 2
            while (hy < layer.height) {
                drawCircle(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.35f * layerOpacity), maxR * 0.25f, androidx.compose.ui.geometry.Offset(hx - 2f, hy - 2f))
                drawCircle(androidx.compose.ui.graphics.Color.Magenta.copy(alpha = 0.35f * layerOpacity), maxR * 0.25f, androidx.compose.ui.geometry.Offset(hx + 2f, hy - hx % 3f))
                drawCircle(androidx.compose.ui.graphics.Color.Yellow.copy(alpha = 0.35f * layerOpacity), maxR * 0.25f, androidx.compose.ui.geometry.Offset(hx, hy + 2f))
                hy += stepY
            }
            hx += stepX
        }
    }

    // 15. Crystallize / Mosaic / Pointillize Pass
    if (crysFil != null || mosFil != null || pointFil != null) {
        val cSize = crysFil?.parameters["CellSize"]?.value ?: mosFil?.parameters["CellSize"]?.value ?: pointFil?.parameters["CellSize"]?.value ?: 10f
        val spacing = cSize.coerceIn(8f, 95f)
        val stepX = spacing.coerceAtLeast(layer.width / 50f)
        val stepY = spacing.coerceAtLeast(layer.height / 50f)
        var mx = stepX / 2
        while (mx < layer.width) {
            var my = stepY / 2
            while (my < layer.height) {
                if (pointFil != null) {
                    drawCircle(effectiveColor.copy(alpha = 0.55f * layerOpacity), spacing * 0.32f, androidx.compose.ui.geometry.Offset(mx, my))
                } else if (mosFil != null) {
                    drawRect(
                        color = effectiveColor.copy(alpha = 0.40f * layerOpacity),
                        topLeft = androidx.compose.ui.geometry.Offset(mx - spacing/2 + 1f, my - spacing/2 + 1f),
                        size = androidx.compose.ui.geometry.Size(spacing - 2f, spacing - 2f)
                    )
                } else {
                    drawLine(
                        color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.2f * layerOpacity),
                        start = androidx.compose.ui.geometry.Offset(mx - spacing/2, my - spacing/2),
                        end = androidx.compose.ui.geometry.Offset(mx + spacing/2, my + spacing/2),
                        strokeWidth = 1f
                    )
                }
                my += stepY
            }
            mx += stepX
        }
    }

    // 16. Clouds Gaseous Smoke Pass
    if (cloudFil != null) {
        val details = cloudFil.parameters["DetailLevel"]?.value ?: 2f
        val rSeed = java.util.Random(layer.id.hashCode().toLong() * 3)
        for (i in 0 until (details * 2).toInt().coerceAtLeast(3)) {
            val cx = rSeed.nextFloat() * layer.width
            val cy = rSeed.nextFloat() * layer.height
            val cr = (layer.width + layer.height) * 0.22f * (0.8f + rSeed.nextFloat() * 0.5f)
            val col = when (i % 3) {
                0 -> androidx.compose.ui.graphics.Color(0xFF1E88E5)
                1 -> androidx.compose.ui.graphics.Color(0xFFAB47BC)
                else -> androidx.compose.ui.graphics.Color(0xFFEF5350)
            }
            drawCircle(col.copy(alpha = 0.12f * layerOpacity), cr, androidx.compose.ui.geometry.Offset(cx, cy))
        }
    }

    // 17. Cinematic Lens Flare Pass
    if (flareFil != null) {
        val bright = (flareFil.parameters["Brightness"]?.value ?: 100f) / 100f
        val lightColor = androidx.compose.ui.graphics.Color(0xFFFFF9C4)
        drawCircle(androidx.compose.ui.graphics.Color.White.copy(alpha = 0.9f * layerOpacity * bright), 20f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f, layer.height/2f))
        drawCircle(lightColor.copy(alpha = 0.45f * layerOpacity * bright), 50f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f, layer.height/2f))
        drawCircle(
            color = com.example.ui.theme.AdjustmentNodeColor.copy(alpha = 0.22f * layerOpacity * bright),
            radius = 100f * bright,
            center = androidx.compose.ui.geometry.Offset(layer.width/2f, layer.height/2f),
            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.5f * bright)
        )
        val offsetUnitX = 35f * bright
        val offsetUnitY = -22f * bright
        drawCircle(androidx.compose.ui.graphics.Color(0xFFFFEA00).copy(alpha = 0.32f * layerOpacity * bright), 10f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f + offsetUnitX, layer.height/2f + offsetUnitY))
        drawCircle(androidx.compose.ui.graphics.Color(0xFFE040FB).copy(alpha = 0.22f * layerOpacity * bright), 16f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f - offsetUnitX * 1.8f, layer.height/2f - offsetUnitY * 1.8f))
        drawCircle(androidx.compose.ui.graphics.Color(0xFF00E676).copy(alpha = 0.18f * layerOpacity * bright), 7f * bright, androidx.compose.ui.geometry.Offset(layer.width/2f + offsetUnitX * 2.5f, layer.height/2f + offsetUnitY * 2.5f))
    }

    // 18. Spotlight Lighting pass
    if (lightFil != null) {
        val intensity = (lightFil.parameters["Intensity"]?.value ?: 50f) / 100f
        val conePath = androidx.compose.ui.graphics.Path().apply {
            moveTo(0f, 0f)
            lineTo(layer.width * 0.85f, layer.height * 0.22f)
            lineTo(layer.width * 0.22f, layer.height * 0.85f)
            close()
        }
        drawPath(
            path = conePath,
            color = androidx.compose.ui.graphics.Color.White.copy(alpha = intensity * 0.2f * layerOpacity),
            blendMode = composeBlendMode
        )
    }

    // 19. Find Edges pass
    if (findFil != null) {
        drawGeometry(com.example.ui.theme.AdjustmentNodeColor, 0.85f, androidx.compose.ui.graphics.drawscope.Stroke(width = 2.2f))
    }

    // 20. Emboss Contour Pass
    if (embFil != null) {
        withTransform({ translate(left = -1.5f, top = -1.5f) }) {
            drawGeometry(androidx.compose.ui.graphics.Color.White, 0.4f, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.2f))
        }
        withTransform({ translate(left = 1.5f, top = 1.5f) }) {
            drawGeometry(androidx.compose.ui.graphics.Color.Black, 0.5f, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.2f))
        }
    }

    // 21. Hand-penciled Sketch / Texture Burlap shaders
    if (sketchFil != null) {
        var sy = 0f
        val step = (layer.height / 150f).coerceAtLeast(10f)
        while (sy < layer.height) {
            drawLine(
                color = androidx.compose.ui.graphics.Color(0xFF616161).copy(alpha = 0.4f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(0f, sy),
                end = androidx.compose.ui.geometry.Offset(layer.width * 0.85f, sy + 12f),
                strokeWidth = 1f
            )
            sy += step
        }
    }
    if (texFil != null) {
        var gx = 0f
        val stepX = (layer.width / 150f).coerceAtLeast(8f)
        while (gx < layer.width) {
            drawLine(color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.12f * layerOpacity), start = androidx.compose.ui.geometry.Offset(gx, 0f), end = androidx.compose.ui.geometry.Offset(gx, layer.height), strokeWidth = 1f)
            gx += stepX
        }
        var gy = 0f
        val stepY = (layer.height / 150f).coerceAtLeast(8f)
        while (gy < layer.height) {
            drawLine(color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.12f * layerOpacity), start = androidx.compose.ui.geometry.Offset(0f, gy), end = androidx.compose.ui.geometry.Offset(layer.width, gy), strokeWidth = 1f)
            gy += stepY
        }
    }
    if (artFil != null || brushFil != null) {
        drawGeometry(androidx.compose.ui.graphics.Color.White.copy(alpha = 0.25f), 0.25f, androidx.compose.ui.graphics.drawscope.Stroke(width = 1.8f))
    }

    // 22. AI Face Mesh neural overlay
    if (neuralFil != null) {
        val nx1 = layer.width * 0.35f
        val nx2 = layer.width * 0.65f
        val ny = layer.height * 0.4f
        drawCircle(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.3f * layerOpacity), 7f, androidx.compose.ui.geometry.Offset(nx1, ny))
        drawCircle(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.3f * layerOpacity), 7f, androidx.compose.ui.geometry.Offset(nx2, ny))
        drawLine(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.25f * layerOpacity), androidx.compose.ui.geometry.Offset(nx1, ny), androidx.compose.ui.geometry.Offset(nx2, ny), strokeWidth = 1.2f)
        drawLine(androidx.compose.ui.graphics.Color.Cyan.copy(alpha = 0.25f * layerOpacity), androidx.compose.ui.geometry.Offset(layer.width / 2f, ny), androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height * 0.65f), strokeWidth = 1.2f)
    }

    // 23. Wind streak trails
    if (windFil != null) {
        val rSeed = java.util.Random(layer.id.hashCode().toLong() * 4)
        for (i in 0 until 10) {
            val wy = rSeed.nextFloat() * layer.height
            val length = rSeed.nextFloat() * 30f + 8f
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.5f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(layer.width, wy),
                end = androidx.compose.ui.geometry.Offset(layer.width + length, wy),
                strokeWidth = 1.2f
            )
        }
    }

    // 24. Oil Paint strokes overlay
    if (oilFil != null) {
        val styliz = oilFil.parameters["Stylization"]?.value ?: 5f
        val rSeed = java.util.Random(layer.id.hashCode().toLong() * 11)
        for (i in 0 until (styliz * 1.3f).toInt().coerceAtLeast(3)) {
            val sy = layer.height * rSeed.nextFloat()
            drawLine(
                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.25f * layerOpacity),
                start = androidx.compose.ui.geometry.Offset(0f, sy),
                end = androidx.compose.ui.geometry.Offset(layer.width, sy + rSeed.nextFloat() * 10f - 5f),
                strokeWidth = 2.5f + rSeed.nextFloat() * 3f,
                blendMode = composeBlendMode
            )
        }
    }

    // Paint Bezier control lines overlay if active and selected
    if (layer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && layer.id == selectedLayerId && activeTool == "Pen") {
        val anchors = layer.brushPoints.toAnchorPoints()
        if (anchors.isNotEmpty()) {
            for (apIdx in anchors.indices) {
                val ap = anchors[apIdx]
                if (ap.position.x.isNaN() || ap.position.y.isNaN()) {
                    continue
                }
                val isInSelected = activeBezierPointIndex == apIdx * 3 + 1
                val isOutSelected = activeBezierPointIndex == apIdx * 3 + 2
                val isAnchorSelected = activeBezierPointIndex == apIdx * 3
                
                // If handleIn is active, draw line and handle circle
                if (ap.handleIn != ap.position) {
                    drawLine(
                        color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.65f),
                        start = ap.position,
                        end = ap.handleIn,
                        strokeWidth = 3f / totalScale.coerceAtLeast(0.3f),
                        pathEffect = dashEffect
                    )
                    drawCircle(
                        color = if (isInSelected) androidx.compose.ui.graphics.Color(0xFFFFD54F) else IndustrialAmber,
                        radius = (if (isInSelected) 24f else 18f) / totalScale.coerceAtLeast(0.3f),
                        center = ap.handleIn
                    )
                    drawCircle(
                        color = if (isInSelected) androidx.compose.ui.graphics.Color(0xFFFF1744) else androidx.compose.ui.graphics.Color.White,
                        radius = (if (isInSelected) 11f else 8f) / totalScale.coerceAtLeast(0.3f),
                        center = ap.handleIn
                    )
                }

                // If handleOut is active, draw line and handle circle
                if (ap.handleOut != ap.position) {
                    drawLine(
                        color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.65f),
                        start = ap.position,
                        end = ap.handleOut,
                        strokeWidth = 3f / totalScale.coerceAtLeast(0.3f),
                        pathEffect = dashEffect
                    )
                    drawCircle(
                        color = if (isOutSelected) androidx.compose.ui.graphics.Color(0xFFFFD54F) else IndustrialAmber,
                        radius = (if (isOutSelected) 24f else 18f) / totalScale.coerceAtLeast(0.3f),
                        center = ap.handleOut
                    )
                    drawCircle(
                        color = if (isOutSelected) androidx.compose.ui.graphics.Color(0xFFFF1744) else androidx.compose.ui.graphics.Color.White,
                        radius = (if (isOutSelected) 11f else 8f) / totalScale.coerceAtLeast(0.3f),
                        center = ap.handleOut
                    )
                }

                // Main anchor center point
                drawCircle(
                    color = if (isAnchorSelected) androidx.compose.ui.graphics.Color(0xFFFF1744) else androidx.compose.ui.graphics.Color(0xFF00E5FF),
                    radius = (if (isAnchorSelected) 26f else 20f) / totalScale.coerceAtLeast(0.3f),
                    center = ap.position
                )
                drawCircle(
                    color = androidx.compose.ui.graphics.Color.White,
                    radius = (if (isAnchorSelected) 12f else 9f) / totalScale.coerceAtLeast(0.3f),
                    center = ap.position
                )
            }
        } else {
            val start = androidx.compose.ui.geometry.Offset(0f, layer.height)
            val end = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
            val controlLocal = layer.brushPoints.getOrNull(0) ?: androidx.compose.ui.geometry.Offset(layer.width / 2f, 0f)
            drawLine(
                color = androidx.compose.ui.graphics.Color.LightGray.copy(alpha = 0.5f),
                start = start,
                end = controlLocal,
                strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                pathEffect = dashEffect
            )
            drawLine(
                color = androidx.compose.ui.graphics.Color.LightGray.copy(alpha = 0.5f),
                start = end,
                end = controlLocal,
                strokeWidth = 2f / totalScale.coerceAtLeast(0.5f),
                pathEffect = dashEffect
            )
            drawCircle(
                color = IndustrialAmber,
                radius = 10f / totalScale.coerceAtLeast(0.5f),
                center = controlLocal
            )
            drawCircle(
                color = androidx.compose.ui.graphics.Color.White,
                radius = 5f / totalScale.coerceAtLeast(0.5f),
                center = controlLocal
            )
        }
    }

    // Sizing frames and anchors drawn locally
    if (layer.id == selectedLayerId && (activeTool != "Pen" || layer.type != com.example.studio.model.LayerType.VECTOR_BEZIER)) {
        drawRect(
            color = IndustrialAmber.copy(0.8f),
            topLeft = androidx.compose.ui.geometry.Offset(-6f, -6f),
            size = androidx.compose.ui.geometry.Size(layer.width + 12f, layer.height + 12f),
            style = androidx.compose.ui.graphics.drawscope.Stroke(
                width = 1.5f / totalScale.coerceAtLeast(0.5f),
                pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f / totalScale.coerceAtLeast(0.5f), 8f / totalScale.coerceAtLeast(0.5f)))
            )
        )
        drawCircle(
            color = EnergeticYellow,
            radius = 8f / totalScale.coerceAtLeast(0.5f),
            center = androidx.compose.ui.geometry.Offset.Zero
        )
        drawCircle(
            color = EnergeticYellow,
            radius = 11f / totalScale.coerceAtLeast(0.5f),
            center = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
        )
        drawCircle(
            color = androidx.compose.ui.graphics.Color(0xFFFF5722),
            radius = 5.5f / totalScale.coerceAtLeast(0.5f),
            center = androidx.compose.ui.geometry.Offset(layer.width, layer.height)
        )

        // On-Canvas Gradient Overlay Guideline rendering moved to drawSingleConnectedLayer to float live and dynamically above cache layers
    }
    if (didSaveLayer) {
        drawContext.canvas.nativeCanvas.restore()
    }
}

private object CanvasMatrixHolder {
    private val matrixLocal = object : ThreadLocal<android.graphics.Matrix>() {
        override fun initialValue() = android.graphics.Matrix()
    }
    private val valuesLocal = object : ThreadLocal<FloatArray>() {
        override fun initialValue() = FloatArray(9)
    }

    val transformMatrix: android.graphics.Matrix
        get() {
            val m = matrixLocal.get() ?: android.graphics.Matrix()
            m.reset()
            return m
        }

    val matrixValues: FloatArray
        get() = valuesLocal.get() ?: FloatArray(9)
}

private fun parseWarpPointsStr(s: String): List<Offset> {
    if (s.isEmpty()) return emptyList()
    return try {
        s.split(";").map {
            val parts = it.split(",")
            Offset(parts[0].toFloat(), parts[1].toFloat())
        }
    } catch (e: Exception) {
        emptyList()
    }
}

private fun formatWarpPointsStr(points: List<Offset>): String {
    return points.joinToString(";") { "${it.x},${it.y}" }
}

private fun getInitialMeshNodes(width: Float, height: Float, cols: Int, rows: Int): List<Offset> {
    val list = mutableListOf<Offset>()
    for (r in 0..rows) {
        val y = r.toFloat() / rows * height
        for (c in 0..cols) {
            val x = c.toFloat() / cols * width
            list.add(Offset(x, y))
        }
    }
    return list
}

data class MeshNode(
    val main: androidx.compose.ui.geometry.Offset,
    val hHandle: androidx.compose.ui.geometry.Offset,
    val vHandle: androidx.compose.ui.geometry.Offset
)

private fun parseMeshWarpPointsStr(
    s: String,
    cols: Int,
    rows: Int,
    layerW: Float,
    layerH: Float,
    target: String = "Layer",
    layer: com.example.studio.model.StudioLayer? = null
): List<MeshNode> {
    val cellW = layerW / cols.coerceAtLeast(1)
    val cellH = layerH / rows.coerceAtLeast(1)
    val expectedCount = (cols + 1) * (rows + 1)
    
    if (s.isEmpty()) {
        return getInitialMeshNodesWithHandles(layerW, layerH, cols, rows, target, layer)
    }
    
    val parts = s.split(";")
    if (parts.size != expectedCount) {
        return getInitialMeshNodesWithHandles(layerW, layerH, cols, rows, target, layer)
    }
    
    val list = ArrayList<MeshNode>()
    for (i in 0 until expectedCount) {
        val subParts = parts[i].split(",")
        val mainX = subParts.getOrNull(0)?.toFloatOrNull() ?: 0f
        val mainY = subParts.getOrNull(1)?.toFloatOrNull() ?: 0f
        
        val hx = subParts.getOrNull(2)?.toFloatOrNull() ?: (cellW / 3f)
        val hy = subParts.getOrNull(3)?.toFloatOrNull() ?: 0f
        val vx = subParts.getOrNull(4)?.toFloatOrNull() ?: 0f
        val vy = subParts.getOrNull(5)?.toFloatOrNull() ?: (cellH / 3f)
        
        list.add(
            MeshNode(
                androidx.compose.ui.geometry.Offset(mainX, mainY),
                androidx.compose.ui.geometry.Offset(hx, hy),
                androidx.compose.ui.geometry.Offset(vx, vy)
            )
        )
    }
    return list
}

private fun formatMeshWarpPointsStr(nodes: List<MeshNode>): String {
    return nodes.joinToString(";") { 
        "${it.main.x},${it.main.y},${it.hHandle.x},${it.hHandle.y},${it.vHandle.x},${it.vHandle.y}"
    }
}

private fun getInitialMeshNodesWithHandles(
    width: Float,
    height: Float,
    cols: Int,
    rows: Int,
    target: String = "Layer",
    layer: com.example.studio.model.StudioLayer? = null
): List<MeshNode> {
    val cellW = width / cols.coerceAtLeast(1)
    val cellH = height / rows.coerceAtLeast(1)
    val list = ArrayList<MeshNode>()
    for (r in 0..rows) {
        val y = r * cellH
        for (c in 0..cols) {
            val x = c * cellW
            val localPt = androidx.compose.ui.geometry.Offset(x, y)
            val mainPt = if (target == "Canvas" && layer != null) layerLocalToCanvas(localPt, layer) else localPt
            
            val hx = cellW / 3f
            val hy = 0f
            val vx = 0f
            val vy = cellH / 3f
            val localH = androidx.compose.ui.geometry.Offset(hx, hy)
            val localV = androidx.compose.ui.geometry.Offset(vx, vy)
            
            val hVec = if (target == "Canvas" && layer != null) {
                layerLocalToCanvas(localPt + localH, layer) - mainPt
            } else localH
            
            val vVec = if (target == "Canvas" && layer != null) {
                layerLocalToCanvas(localPt + localV, layer) - mainPt
            } else localV
            
            list.add(MeshNode(mainPt, hVec, vVec))
        }
    }
    return list
}

private fun evaluateBezierPatch(
    u: Float, v: Float,
    p00: androidx.compose.ui.geometry.Offset, p10: androidx.compose.ui.geometry.Offset, p20: androidx.compose.ui.geometry.Offset, p30: androidx.compose.ui.geometry.Offset,
    p01: androidx.compose.ui.geometry.Offset, p11: androidx.compose.ui.geometry.Offset, p21: androidx.compose.ui.geometry.Offset, p31: androidx.compose.ui.geometry.Offset,
    p02: androidx.compose.ui.geometry.Offset, p12: androidx.compose.ui.geometry.Offset, p22: androidx.compose.ui.geometry.Offset, p32: androidx.compose.ui.geometry.Offset,
    p03: androidx.compose.ui.geometry.Offset, p13: androidx.compose.ui.geometry.Offset, p23: androidx.compose.ui.geometry.Offset, p33: androidx.compose.ui.geometry.Offset
): androidx.compose.ui.geometry.Offset {
    val t1 = 1f - u
    val bu0 = t1 * t1 * t1
    val bu1 = 3f * u * t1 * t1
    val bu2 = 3f * u * u * t1
    val bu3 = u * u * u
    
    val s1 = 1f - v
    val bv0 = s1 * s1 * s1
    val bv1 = 3f * v * s1 * s1
    val bv2 = 3f * v * v * s1
    val bv3 = v * v * v
    
    val pts = arrayOf(
        arrayOf(p00, p01, p02, p03),
        arrayOf(p10, p11, p12, p13),
        arrayOf(p20, p21, p22, p23),
        arrayOf(p30, p31, p32, p33)
    )
    
    var rx = 0f
    var ry = 0f
    
    for (m in 0..3) {
        val bu = when (m) {
            0 -> bu0
            1 -> bu1
            2 -> bu2
            else -> bu3
        }
        for (n in 0..3) {
            val bv = when (n) {
                0 -> bv0
                1 -> bv1
                2 -> bv2
                else -> bv3
            }
            val weight = bu * bv
            rx += weight * pts[m][n].x
            ry += weight * pts[m][n].y
        }
    }
    return androidx.compose.ui.geometry.Offset(rx, ry)
}


private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawLayerWithFullPipeline(
    layer: com.example.studio.model.StudioLayer,
    allLayers: List<com.example.studio.model.StudioLayer>,
    layerOpacity: Float,
    selectedLayerId: String?,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>,
    pathPointsCountCache: android.util.SparseIntArray,
    totalScale: Float,
    dashEffect: androidx.compose.ui.graphics.PathEffect,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode,
    sharedTransformMatrix: androidx.compose.ui.graphics.Matrix,
    activeTool: String,
    liveDragScaleX: Float,
    liveDragScaleY: Float,
    liveDragPivotX: Float = -1f,
    liveDragPivotY: Float = -1f,
    viewportWidth: Float,
    viewportHeight: Float,
    panX: Float,
    panY: Float,
    canvasWidth: Float,
    canvasHeight: Float,
    pulseAlpha: Float = 1f,
    spinAngle: Float = 0f,
    activeBezierPointIndex: Int = -1,
    activeWarpNodeIndex: Int = -1,
    warpRepeatMode: String = "Off",
    warpRepeatX: Float = 1f,
    warpRepeatY: Float = 1f,
    warpPhaseX: Float = 0f,
    warpPhaseY: Float = 0f,
    warpInterpolation: Boolean = true,
    warpTarget: String = "Mesh",
    warpMeshDivisionX: Int = 2,
    warpMeshDivisionY: Int = 2,
    isDraggingBezierNode: Boolean = false,
    showGradientControls: Boolean = false,
    isRasterizing: Boolean = false,
    backdropProvider: (() -> android.graphics.Bitmap?)? = null
) {
    val index = allLayers.indexOfFirst { it.id == layer.id }
    if (index == -1) return
    
    val clippedLayers = mutableListOf<com.example.studio.model.StudioLayer>()
    for (i in (index - 1) downTo 0) {
        val prospect = allLayers[i]
        if (!prospect.isVisible) continue
        if (prospect.isClippingMask) {
            clippedLayers.add(prospect)
        } else {
            break
        }
    }
    
    val hasAdjustmentEffect = layer.effects.any { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && 
        it.effectType in listOf("CameraRaw", "ColorGrading", "Fast Adjusting", "color_fast_adjusting", "FastAdjusting", "fast_adj", "Solarize", "Emboss", "FindEdges", "ColorHalftone", "Sketch", "Mosaic", "Twirl", "Spherize", "SmartSharpen", "UnsharpMask", "AddNoise") }
    val hasGlassEffect = layer.effects.any { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && (it.effectType == "GlassMorphism" || it.effectType == "ReededGlass") }
    val needsBackdrop = hasGlassEffect || hasAdjustmentEffect || layer.blendMode != com.example.studio.model.ZenithBlendMode.NORMAL || layer.effects.any { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType !in listOf("BrushConfig", "DropShadow", "InnerShadow", "BordersAndShadows", "OuterGlow", "InnerGlow", "BevelEmboss", "Satin", "GradientOverlay", "PatternOverlay", "Stroke", "GlassMorphism", "ReededGlass") }
    
    val currentBackdrop = if (needsBackdrop && !isRasterizing) {
        backdropProvider?.invoke()
    } else { null }
    
    if (clippedLayers.isNotEmpty()) {
        try {
            drawSingleConnectedLayer(
                layer = layer, layerOpacity = layerOpacity, selectedLayerId = selectedLayerId,
                pathCache = pathCache, pathPointsCountCache = pathPointsCountCache,
                totalScale = totalScale, dashEffect = dashEffect, imageBitmapCache = imageBitmapCache,
                composeBlendMode = composeBlendMode, sharedTransformMatrix = sharedTransformMatrix,
                backdropBitmap = currentBackdrop, globalX = layer.positionX, globalY = layer.positionY,
                activeTool = activeTool, allLayers = allLayers, liveDragScaleX = liveDragScaleX, liveDragScaleY = liveDragScaleY,
                liveDragPivotX = liveDragPivotX, liveDragPivotY = liveDragPivotY,
                viewportWidth = viewportWidth, viewportHeight = viewportHeight, panX = panX, panY = panY,
                canvasWidth = canvasWidth, canvasHeight = canvasHeight, pulseAlpha = pulseAlpha, spinAngle = spinAngle,
                activeBezierPointIndex = activeBezierPointIndex, activeWarpNodeIndex = activeWarpNodeIndex,
                warpRepeatMode = warpRepeatMode, warpRepeatX = warpRepeatX, warpRepeatY = warpRepeatY,
                warpPhaseX = warpPhaseX, warpPhaseY = warpPhaseY, warpInterpolation = warpInterpolation,
                warpTarget = warpTarget, warpMeshDivisionX = warpMeshDivisionX, warpMeshDivisionY = warpMeshDivisionY, isExporting = isRasterizing,
                isDraggingBezierNode = isDraggingBezierNode, showGradientControls = showGradientControls
            )
            val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, canvasWidth, canvasHeight)
            drawContext.canvas.saveLayer(bounds, androidx.compose.ui.graphics.Paint())
            drawSingleConnectedLayer(
                layer = layer, layerOpacity = layerOpacity, selectedLayerId = selectedLayerId,
                pathCache = pathCache, pathPointsCountCache = pathPointsCountCache,
                totalScale = totalScale, dashEffect = dashEffect, imageBitmapCache = imageBitmapCache,
                composeBlendMode = composeBlendMode, sharedTransformMatrix = sharedTransformMatrix,
                backdropBitmap = currentBackdrop, globalX = layer.positionX, globalY = layer.positionY,
                activeTool = activeTool, allLayers = allLayers, liveDragScaleX = liveDragScaleX, liveDragScaleY = liveDragScaleY,
                liveDragPivotX = liveDragPivotX, liveDragPivotY = liveDragPivotY,
                viewportWidth = viewportWidth, viewportHeight = viewportHeight, panX = panX, panY = panY,
                canvasWidth = canvasWidth, canvasHeight = canvasHeight, pulseAlpha = pulseAlpha, spinAngle = spinAngle,
                activeBezierPointIndex = activeBezierPointIndex, activeWarpNodeIndex = activeWarpNodeIndex,
                warpRepeatMode = warpRepeatMode, warpRepeatX = warpRepeatX, warpRepeatY = warpRepeatY,
                warpPhaseX = warpPhaseX, warpPhaseY = warpPhaseY, warpInterpolation = warpInterpolation,
                warpTarget = warpTarget, warpMeshDivisionX = warpMeshDivisionX, warpMeshDivisionY = warpMeshDivisionY, isExporting = isRasterizing,
                isDraggingBezierNode = isDraggingBezierNode, showGradientControls = showGradientControls
            )
            val groupPaint = androidx.compose.ui.graphics.Paint().apply { blendMode = androidx.compose.ui.graphics.BlendMode.SrcIn }
            drawContext.canvas.saveLayer(bounds, groupPaint)
            for (clipped in clippedLayers) {
                drawSingleConnectedLayer(
                    layer = clipped, layerOpacity = clipped.opacity, selectedLayerId = selectedLayerId,
                    pathCache = pathCache, pathPointsCountCache = pathPointsCountCache,
                    totalScale = totalScale, dashEffect = dashEffect, imageBitmapCache = imageBitmapCache,
                    composeBlendMode = clipped.blendMode.toComposeBlendMode(), sharedTransformMatrix = sharedTransformMatrix,
                    backdropBitmap = null, globalX = clipped.positionX, globalY = clipped.positionY,
                    activeTool = activeTool, allLayers = allLayers, liveDragScaleX = liveDragScaleX, liveDragScaleY = liveDragScaleY,
                    liveDragPivotX = liveDragPivotX, liveDragPivotY = liveDragPivotY,
                    viewportWidth = viewportWidth, viewportHeight = viewportHeight, panX = panX, panY = panY,
                    canvasWidth = canvasWidth, canvasHeight = canvasHeight, pulseAlpha = pulseAlpha, spinAngle = spinAngle,
                    activeBezierPointIndex = activeBezierPointIndex, activeWarpNodeIndex = activeWarpNodeIndex,
                    warpRepeatMode = warpRepeatMode, warpRepeatX = warpRepeatX, warpRepeatY = warpRepeatY,
                    warpPhaseX = warpPhaseX, warpPhaseY = warpPhaseY, warpInterpolation = warpInterpolation,
                    warpTarget = warpTarget, warpMeshDivisionX = warpMeshDivisionX, warpMeshDivisionY = warpMeshDivisionY, isExporting = isRasterizing,
                    isDraggingBezierNode = isDraggingBezierNode, showGradientControls = showGradientControls
                )
            }
            drawContext.canvas.restore()
            drawContext.canvas.restore()
        } catch (e: Exception) { e.printStackTrace() }
    } else {
        drawSingleConnectedLayer(
            layer = layer, layerOpacity = layerOpacity, selectedLayerId = selectedLayerId,
            pathCache = pathCache, pathPointsCountCache = pathPointsCountCache,
            totalScale = totalScale, dashEffect = dashEffect, imageBitmapCache = imageBitmapCache,
            composeBlendMode = composeBlendMode, sharedTransformMatrix = sharedTransformMatrix,
            backdropBitmap = currentBackdrop, globalX = layer.positionX, globalY = layer.positionY,
            activeTool = activeTool, allLayers = allLayers, liveDragScaleX = liveDragScaleX, liveDragScaleY = liveDragScaleY,
            liveDragPivotX = liveDragPivotX, liveDragPivotY = liveDragPivotY,
            viewportWidth = viewportWidth, viewportHeight = viewportHeight, panX = panX, panY = panY,
            canvasWidth = canvasWidth, canvasHeight = canvasHeight, pulseAlpha = pulseAlpha, spinAngle = spinAngle,
            activeBezierPointIndex = activeBezierPointIndex, activeWarpNodeIndex = activeWarpNodeIndex,
            warpRepeatMode = warpRepeatMode, warpRepeatX = warpRepeatX, warpRepeatY = warpRepeatY,
            warpPhaseX = warpPhaseX, warpPhaseY = warpPhaseY, warpInterpolation = warpInterpolation,
            warpTarget = warpTarget, warpMeshDivisionX = warpMeshDivisionX, warpMeshDivisionY = warpMeshDivisionY, isExporting = isRasterizing,
            isDraggingBezierNode = isDraggingBezierNode, showGradientControls = showGradientControls
        )
    }
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawSingleConnectedLayer(
    layer: com.example.studio.model.StudioLayer,
    layerOpacity: Float,
    selectedLayerId: String?,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>,
    pathPointsCountCache: android.util.SparseIntArray,
    totalScale: Float,
    dashEffect: androidx.compose.ui.graphics.PathEffect,
    composeBlendMode: androidx.compose.ui.graphics.BlendMode,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>,
    sharedTransformMatrix: androidx.compose.ui.graphics.Matrix,
    backdropBitmap: android.graphics.Bitmap? = null,
    globalX: Float = 0f,
    globalY: Float = 0f,
    activeTool: String = "Brush",
    allLayers: List<com.example.studio.model.StudioLayer> = emptyList(),
    liveDragScaleX: Float = 1.0f,
    liveDragScaleY: Float = 1.0f,
    liveDragPivotX: Float = -1f,
    liveDragPivotY: Float = -1f,
    viewportWidth: Float = 0f,
    viewportHeight: Float = 0f,
    panX: Float = 0f,
    panY: Float = 0f,
    canvasWidth: Float = 0f,
    canvasHeight: Float = 0f,
    pulseAlpha: Float = 1f,
    spinAngle: Float = 0f,
    activeBezierPointIndex: Int = -1,
    showGradientControls: Boolean = false,
    isDraggingBezierNode: Boolean = false,
    warpMeshDivisionX: Int = 3,
    warpMeshDivisionY: Int = 3,
    warpRepeatMode: String = "Off",
    warpRepeatX: Float = 1.0f,
    warpRepeatY: Float = 1.0f,
    warpPhaseX: Float = 0.0f,
    warpPhaseY: Float = 0.0f,
    warpInterpolation: Boolean = true,
    warpTarget: String = "Layer",
    activeWarpNodeIndex: Int = -1,
    isExporting: Boolean = false
) {
    val warpRepeatMode = layer.warpRepeatMode
    val warpRepeatX = layer.warpRepeatX
    val warpRepeatY = layer.warpRepeatY
    val warpPhaseX = layer.warpPhaseX
    val warpPhaseY = layer.warpPhaseY
    val warpInterpolation = layer.warpInterpolation
    val warpTarget = layer.warpTarget
    val warpMeshDivisionX = layer.warpMeshDivisionX
    val warpMeshDivisionY = layer.warpMeshDivisionY

    try {
        if (layer.type == com.example.studio.model.LayerType.ADJUSTMENT_LAYER) {
            val currentIndex = allLayers.indexOfFirst { it.id == layer.id }
            if (currentIndex != -1) {
                val computedBackdrop = generateBackdropForLayer(
                    layers = allLayers,
                    currentIndex = currentIndex,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    imageBitmapCache = imageBitmapCache,
                    pathCache = pathCache,
                    pathPointsCountCache = pathPointsCountCache,
                    existingBitmap = null,
                    isExporting = isExporting,
                )
                if (computedBackdrop != null) {
                    val paint = AdrenoAdjustmentCache.getOrCreatePaint(
                        brightness = SlidersHighFreqState.get("${layer.id}_adj_brightness", layer.adjBrightness),
                        contrast = SlidersHighFreqState.get("${layer.id}_adj_contrast", layer.adjContrast),
                        saturation = SlidersHighFreqState.get("${layer.id}_adj_saturation", layer.adjSaturation),
                        tintColor = layer.adjColorTint ?: androidx.compose.ui.graphics.Color.Transparent,
                        tintIntensity = SlidersHighFreqState.get("${layer.id}_adj_tintIntensity", layer.adjTintColorIntensity)
                    )
                    drawContext.canvas.nativeCanvas.drawBitmap(
                        computedBackdrop,
                        0f,
                        0f,
                        paint.asFrameworkPaint()
                    )
                }
            }
            if (layer.id == selectedLayerId && activeTool != "Pen") {
                val outlineColor = com.example.ui.theme.AdjustmentNodeColor
                val strokeW = 2.0f / totalScale.coerceAtLeast(0.5f)
                drawRect(
                    color = outlineColor,
                    topLeft = androidx.compose.ui.geometry.Offset.Zero,
                    size = androidx.compose.ui.geometry.Size(canvasWidth, canvasHeight),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = strokeW,
                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f, 8f))
                    )
                )
            }
            return
        }

        // Recursively resolve all ancestor parent groups, from top-most ancestor down to immediate parent
    val parentGroups = mutableListOf<com.example.studio.model.StudioLayer>()
    var currentParentId = layer.parentGroupId
    val visitedGroupIds = mutableSetOf<String>()
    while (currentParentId != null && !visitedGroupIds.contains(currentParentId)) {
        visitedGroupIds.add(currentParentId)
        val p = allLayers.find { it.id == currentParentId }
        if (p != null) {
            parentGroups.add(0, p)
            currentParentId = p.parentGroupId
        } else {
            break
        }
    }

    var computedOpacity = layerOpacity
    for (p in parentGroups) {
        computedOpacity *= p.opacity
    }

    // Disable CPU-based BlendPipeline for standard blend modes to utilize 60 FPS GPU hardware acceleration.
    // Standard blend modes (ADD, SCREEN, MULTIPLY, DARKEN, LIGHTEN, OVERLAY, DIFFERENCE, EXCLUSION, etc.)
    // are natively composited directly on the canvas with hardware shaders, giving perfect glowing effects and zero lag.
    val isHSLBlendMode = layer.blendMode in listOf(
        com.example.studio.model.ZenithBlendMode.HUE,
        com.example.studio.model.ZenithBlendMode.SATURATION,
        com.example.studio.model.ZenithBlendMode.COLOR,
        com.example.studio.model.ZenithBlendMode.LUMINOSITY
    )
    if (isHSLBlendMode && backdropBitmap != null && canvasWidth > 0f && canvasHeight > 0f) {
        try {
            val w = canvasWidth.toInt().coerceIn(2, 2048)
            val h = canvasHeight.toInt().coerceIn(2, 2048)
            
            val srcBmp = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
            val nativeCanvas = android.graphics.Canvas(srcBmp)
            val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
            
            val originalCanvas = drawContext.canvas
            drawContext.canvas = tempCanvas
            
            try {
                tempCanvas.save()
                for (parentGroup in parentGroups) {
                    tempCanvas.translate(parentGroup.positionX, parentGroup.positionY)
                    val parentMatrix = androidx.compose.ui.graphics.Matrix().apply {
                        reset()
                        val centerX = parentGroup.width * parentGroup.pivotX
                        val centerY = parentGroup.height * parentGroup.pivotY
                        translate(centerX, centerY)
                        rotateZ(parentGroup.rotation)
                        scale(parentGroup.scaleX, parentGroup.scaleY, 1f)
                        translate(-centerX, -centerY)
                    }
                    tempCanvas.concat(parentMatrix)
                }
                tempCanvas.translate(layer.positionX, layer.positionY)
                if (liveDragScaleX != 1.0f || liveDragScaleY != 1.0f) {
                    val pivotX = if (liveDragPivotX >= 0f) liveDragPivotX else layer.width / 2f
                    val pivotY = if (liveDragPivotY >= 0f) liveDragPivotY else layer.height / 2f
                    tempCanvas.translate(pivotX, pivotY)
                    tempCanvas.scale(liveDragScaleX, liveDragScaleY)
                    tempCanvas.translate(-pivotX, -pivotY)
                }
                
                drawAllEffectsAndLayersLocal(
                    layer = layer,
                    layerOpacity = 1.0f,
                    selectedLayerId = null,
                    pathCache = pathCache,
                    pathPointsCountCache = pathPointsCountCache,
                    totalScale = totalScale,
                    dashEffect = dashEffect,
                    composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                    imageBitmapCache = imageBitmapCache,
                    backdropBitmap = null,
                    globalX = layer.positionX,
                    globalY = layer.positionY,
                    activeTool = activeTool,
                    viewportWidth = viewportWidth,
                    viewportHeight = viewportHeight,
                    panX = panX,
                    panY = panY,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    pulseAlpha = pulseAlpha,
                    spinAngle = spinAngle, isExporting = isExporting
                )
                tempCanvas.restore()
            } finally {
                drawContext.canvas = originalCanvas
            }
            
            val blendedBmp = BlendPipeline.blendBitmaps(
                source = srcBmp,
                destination = backdropBitmap,
                mode = layer.blendMode,
                alpha = computedOpacity
            )
            
            drawImage(
                image = blendedBmp.asImageBitmap(),
                topLeft = androidx.compose.ui.geometry.Offset.Zero,
                alpha = 1.0f,
                blendMode = androidx.compose.ui.graphics.BlendMode.SrcOver
            )
            
            try { srcBmp.recycle() } catch (e: Exception) {}
            try { blendedBmp.recycle() } catch (e: Exception) {}
            
            return
        } catch (t: Throwable) {
            android.util.Log.e("BlendPipeline", "Custom blending failed, falling back to standard draw", t)
        }
    }

    var twirlFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var pinchFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    var sphereFil: com.example.studio.model.StudioEffect.PhotoshopEffect? = null
    for (effect in layer.effects) {
        if (!effect.isEnabled) continue
        if (effect is com.example.studio.model.StudioEffect.PhotoshopEffect) {
            when (effect.effectType) {
                "Twirl" -> twirlFil = effect
                "Pinch" -> pinchFil = effect
                "Spherize" -> sphereFil = effect
            }
        }
    }

    val additionalTwirl = twirlFil?.let { (it.parameters["Angle"]?.value ?: 100f) * 0.12f } ?: 0f
    val additionalScale = (pinchFil?.let { 1f + (it.parameters["Amount"]?.value ?: 50f) / 100f * 0.15f } ?: 1f) *
                          (sphereFil?.let { 1f + (it.parameters["Amount"]?.value ?: 100f) / 100f * 0.20f } ?: 1f)

    drawContext.canvas.save()
    var warpCanvasSaved = false
    // Align all ancestor matrix transformations down the hierarchy
    for (parentGroup in parentGroups) {
        drawContext.canvas.translate(parentGroup.positionX, parentGroup.positionY)
        val parentMatrix = androidx.compose.ui.graphics.Matrix().apply {
            reset()
            val centerX = parentGroup.width * parentGroup.pivotX
            val centerY = parentGroup.height * parentGroup.pivotY
            translate(centerX, centerY)
            rotateZ(parentGroup.rotation)
            scale(parentGroup.scaleX, parentGroup.scaleY, 1f)
            translate(-centerX, -centerY)
        }
        drawContext.canvas.concat(parentMatrix)
    }
    drawContext.canvas.translate(layer.positionX, layer.positionY)
    if (liveDragScaleX != 1.0f || liveDragScaleY != 1.0f) {
        val pivotX = if (liveDragPivotX >= 0f) liveDragPivotX else layer.width / 2f
        val pivotY = if (liveDragPivotY >= 0f) liveDragPivotY else layer.height / 2f
        drawContext.canvas.translate(pivotX, pivotY)
        drawContext.canvas.scale(liveDragScaleX, liveDragScaleY)
        drawContext.canvas.translate(-pivotX, -pivotY)
    }

    val centerX = layer.width * layer.pivotX
    val centerY = layer.height * layer.pivotY

    // Apply safe mathematical clamp (Vector Matrix Protection Loop) to prevent perspective collapse
    val cx = layer.width * layer.pivotX
    val cy = layer.height * layer.pivotY
    val corners = listOf(
        -cx to -cy,
        (layer.width - cx) to -cy,
        -cx to (layer.height - cy),
        (layer.width - cx) to (layer.height - cy)
    )
    var safeScale = 1.0f
    for ((x, y) in corners) {
        val dot = layer.perspX * x + layer.perspY * y
        if (dot < -0.85f) {
            val req = -0.85f / dot
            if (req < safeScale) safeScale = req
        }
    }
    val safePerspX = layer.perspX * safeScale
    val safePerspY = layer.perspY * safeScale

    val nativeMatrix = CanvasMatrixHolder.transformMatrix.apply {
        reset()
        // 1. Move pivot center to local origin (0, 0)
        preTranslate(-centerX, -centerY)

        // 2. Inject true 3D perspective and skew coefficients
        val vals = CanvasMatrixHolder.matrixValues
        getValues(vals)
        val usesSkewXAsParam = layer.type in listOf(
            com.example.studio.model.LayerType.VECTOR_PIE_SLICE,
            com.example.studio.model.LayerType.VECTOR_RING_SEGMENT,
            com.example.studio.model.LayerType.VECTOR_SPEECH_BUBBLE,
            com.example.studio.model.LayerType.VECTOR_CHAT_BUBBLE,
            com.example.studio.model.LayerType.VECTOR_WAVE,
            com.example.studio.model.LayerType.VECTOR_BLOB
        )
        val usesSkewYAsParam = layer.type in listOf(
            com.example.studio.model.LayerType.VECTOR_PIE_SLICE,
            com.example.studio.model.LayerType.VECTOR_RING_SEGMENT,
            com.example.studio.model.LayerType.VECTOR_ARROW,
            com.example.studio.model.LayerType.VECTOR_CHAT_BUBBLE
        )
        vals[android.graphics.Matrix.MSKEW_X] = if (usesSkewXAsParam) 0f else layer.skewX
        vals[android.graphics.Matrix.MSKEW_Y] = if (usesSkewYAsParam) 0f else layer.skewY
        vals[6] = safePerspX // MPERSP_0 control point
        vals[7] = safePerspY // MPERSP_1 control point
        setValues(vals)

        // 3. Move coordinate framework back to position
        postTranslate(centerX, centerY)

        // 4. Apply scale and rotation around center pivot
        postScale(layer.scaleX * additionalScale, layer.scaleY * additionalScale, centerX, centerY)
        postRotate(layer.rotation + additionalTwirl, centerX, centerY)
    }
    drawContext.canvas.nativeCanvas.concat(nativeMatrix)

    if ((layer.perspWarpPointsStr.isNotEmpty() || warpRepeatMode != "Off") && layer.meshWarpPointsStr.isEmpty() && activeTool != "Mesh") {
        val parsedRaw = if (layer.perspWarpPointsStr.isNotEmpty()) {
            parseWarpPointsStr(layer.perspWarpPointsStr)
        } else {
            listOf(
                androidx.compose.ui.geometry.Offset(0f, 0f),
                androidx.compose.ui.geometry.Offset(layer.width, 0f),
                androidx.compose.ui.geometry.Offset(layer.width, layer.height),
                androidx.compose.ui.geometry.Offset(0f, layer.height)
            )
        }
        if (parsedRaw.size == 4) {
            val w = layer.width.toInt().coerceIn(2, 2048)
            val h = layer.height.toInt().coerceIn(2, 2048)
            
            val stateHash = if (layer.type == com.example.studio.model.LayerType.IMAGE_CARD) {
                layer.imageUri.hashCode() * 31 + (imageBitmapCache[layer.imageUri]?.hashCode() ?: 0) + layer.effects.hashCode()
            } else {
                (layer.textContent.hashCode() * 31 + layer.richTextSpansJson.hashCode() * 31 + layer.baseColor.hashCode()) * 31 + layer.brushPoints.size + layer.cornerRadius.hashCode() + layer.polygonEdges + layer.strokeThickness.hashCode() + layer.fontSize.hashCode() + layer.effects.hashCode()
            }
            val cacheKey = "unwarped_${layer.id}_${w}_${h}_${stateHash}"
            var baseBmp = unwarpedLayerBitmapsCache[cacheKey]
            
            if (baseBmp == null || baseBmp.isRecycled) {
                // Evict older cached bitmaps for this specific layer to keep memory footprint low
                val prefix = "unwarped_${layer.id}_"
                val keysToEvict = unwarpedLayerBitmapsCache.keys.asSequence().filter { k ->
                    k.startsWith(prefix) && k != cacheKey
                }.toList()
                for (k in keysToEvict) {
                    val oldBmp = unwarpedLayerBitmapsCache.remove(k)
                    if (oldBmp != null) {
                        try { oldBmp.recycle() } catch (e: Exception) {}
                    }
                }
                
                baseBmp = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
                val nativeCanvas = android.graphics.Canvas(baseBmp)
                val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                val originalCanvas = drawContext.canvas
                
                drawContext.canvas = tempCanvas
                nativeCanvas.drawColor(android.graphics.Color.TRANSPARENT, android.graphics.PorterDuff.Mode.CLEAR)
                try {
                    // Render the layer content unwarped
                    val layerNoWarp = layer.copy(
                        positionX = 0f,
                        positionY = 0f,
                        rotation = 0f,
                        scaleX = 1f,
                        scaleY = 1f,
                        skewX = 0f,
                        skewY = 0f,
                        perspX = 0f,
                        perspY = 0f,
                        perspWarpPointsStr = "",
                        meshWarpPointsStr = ""
                    )
                    drawAllEffectsAndLayersLocal(
                        layer = layerNoWarp,
                        layerOpacity = 1.0f,
                        selectedLayerId = null,
                        pathCache = pathCache,
                        pathPointsCountCache = pathPointsCountCache,
                        totalScale = totalScale,
                        dashEffect = dashEffect,
                        imageBitmapCache = imageBitmapCache,
                        composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                        backdropBitmap = null,
                        globalX = 0f,
                        globalY = 0f,
                        activeTool = activeTool,
                        viewportWidth = viewportWidth,
                        viewportHeight = viewportHeight,
                        panX = panX,
                        panY = panY,
                        canvasWidth = canvasWidth,
                        canvasHeight = canvasHeight,
                        pulseAlpha = pulseAlpha,
                        spinAngle = spinAngle,
                        activeBezierPointIndex = activeBezierPointIndex
                    )
                } finally {
                    drawContext.canvas = originalCanvas
                }
                unwarpedLayerBitmapsCache[cacheKey] = baseBmp!!
            }

            val parsed = if (warpTarget == "Canvas") {
                parsedRaw.map { canvasToLayerLocal(it, layer) }
            } else {
                parsedRaw
            }

            val localWarpMatrix = android.graphics.Matrix()
            val src = floatArrayOf(
                0f, 0f,
                layer.width, 0f,
                layer.width, layer.height,
                0f, layer.height
            )
            val dst = floatArrayOf(
                parsed[0].x, parsed[0].y,
                parsed[1].x, parsed[1].y,
                parsed[2].x, parsed[2].y,
                parsed[3].x, parsed[3].y
            )
            localWarpMatrix.setPolyToPoly(src, 0, dst, 0, 4)

            // Compute shader matrix: S = localWarpMatrix * R
            val shaderMatrix = android.graphics.Matrix()
            shaderMatrix.set(localWarpMatrix)
            
            val rMatrix = android.graphics.Matrix()
            if (warpRepeatMode != "Off") {
                val scaleX = 1.0f / warpRepeatX.coerceAtLeast(0.01f)
                val scaleY = 1.0f / warpRepeatY.coerceAtLeast(0.01f)
                val transX = warpPhaseX * w
                val transY = warpPhaseY * h
                
                // Scale around the center of the bitmap (w / 2, h / 2)
                rMatrix.postTranslate(-w / 2f, -h / 2f)
                rMatrix.postScale(scaleX, scaleY)
                rMatrix.postTranslate(w / 2f, h / 2f)
                rMatrix.postTranslate(transX, transY)
            }
            shaderMatrix.preConcat(rMatrix)

            // Create BitmapShader for repeat modes
            val tileX = if (warpRepeatMode == "Off") android.graphics.Shader.TileMode.CLAMP else android.graphics.Shader.TileMode.REPEAT
            val tileY = if (warpRepeatMode == "Off") android.graphics.Shader.TileMode.CLAMP else android.graphics.Shader.TileMode.REPEAT
            val shader = android.graphics.BitmapShader(baseBmp!!, tileX, tileY)
            shader.setLocalMatrix(shaderMatrix)
            
            val paint = android.graphics.Paint().apply {
                isAntiAlias = warpInterpolation
                isFilterBitmap = warpInterpolation
                setShader(shader)
                alpha = (computedOpacity * 255).toInt().coerceIn(0, 255)
            }

            // Horizon clipping calculations
            val invMatrix = android.graphics.Matrix()
            val hasHorizon = localWarpMatrix.invert(invMatrix)
            
            val hA: Float
            val hB: Float
            val hC: Float
            if (hasHorizon) {
                val invValues = FloatArray(9)
                invMatrix.getValues(invValues)
                hA = invValues[6]
                hB = invValues[7]
                hC = invValues[8]
            } else {
                hA = 0f
                hB = 0f
                hC = 1f
            }
            
            val len = Math.hypot(hA.toDouble(), hB.toDouble()).toFloat()
            val isPerspective = len > 1e-9f && (warpRepeatMode == "Horizon" || warpRepeatMode == "Full")

            if (warpRepeatMode == "Off" || warpRepeatMode == "Inner") {
                // For "Off" and "Inner" repeat modes, we draw restricted to the 4-corner quadrilateral
                val quadPath = android.graphics.Path().apply {
                    moveTo(parsed[0].x, parsed[0].y)
                    lineTo(parsed[1].x, parsed[1].y)
                    lineTo(parsed[2].x, parsed[2].y)
                    lineTo(parsed[3].x, parsed[3].y)
                    close()
                }
                drawContext.canvas.nativeCanvas.save()
                drawContext.canvas.nativeCanvas.clipPath(quadPath)
                drawContext.canvas.nativeCanvas.drawRect(-50000f, -50000f, 50000f, 50000f, paint)
                drawContext.canvas.nativeCanvas.restore()
            } else {
                // For "Horizon" and "Full" repeat modes, we draw infinitely to the horizon
                if (isPerspective) {
                    val nA = hA / len
                    val nB = hB / len
                    val nC = hC / len
                    
                    val x0: Float
                    val y0: Float
                    if (Math.abs(nA) > Math.abs(nB)) {
                        x0 = -nC / nA
                        y0 = 0f
                    } else {
                        x0 = 0f
                        y0 = -nC / nB
                    }
                    
                    val dx = -nB
                    val dy = nA
                    val D = 100000f
                    
                    val sign = hA * parsed[0].x + hB * parsed[0].y + hC
                    val targetSign = if (sign >= 0f) 1f else -1f
                    
                    val eps = 0.5f
                    
                    val pLeftX = x0 - D * dx
                    val pLeftY = y0 - D * dy
                    val pRightX = x0 + D * dx
                    val pRightY = y0 + D * dy
                    
                    // Front Pass
                    val stepX = targetSign * nA * D
                    val stepY = targetSign * nB * D
                    
                    val frontLeftX = pLeftX + targetSign * nA * eps
                    val frontLeftY = pLeftY + targetSign * nB * eps
                    val frontRightX = pRightX + targetSign * nA * eps
                    val frontRightY = pRightY + targetSign * nB * eps
                    
                    val frontPath = android.graphics.Path().apply {
                        moveTo(frontLeftX, frontLeftY)
                        lineTo(frontRightX, frontRightY)
                        lineTo(frontRightX + stepX, frontRightY + stepY)
                        lineTo(frontLeftX + stepX, frontLeftY + stepY)
                        close()
                    }
                    
                    // Draw front pass
                    drawContext.canvas.nativeCanvas.save()
                    drawContext.canvas.nativeCanvas.clipPath(frontPath)
                    drawContext.canvas.nativeCanvas.drawRect(-100000f, -100000f, 100000f, 100000f, paint)
                    drawContext.canvas.nativeCanvas.restore()
                    
                    // Draw back pass if Full
                    if (warpRepeatMode == "Full") {
                        val stepBackX = -targetSign * nA * D
                        val stepBackY = -targetSign * nB * D
                        
                        val backLeftX = pLeftX - targetSign * nA * eps
                        val backLeftY = pLeftY - targetSign * nB * eps
                        val backRightX = pRightX - targetSign * nA * eps
                        val backRightY = pRightY - targetSign * nB * eps
                        
                        val backPath = android.graphics.Path().apply {
                            moveTo(backLeftX, backLeftY)
                            lineTo(backRightX, backRightY)
                            lineTo(backRightX + stepBackX, backRightY + stepBackY)
                            lineTo(backLeftX + stepBackX, backLeftY + stepBackY)
                            close()
                        }
                        
                        drawContext.canvas.nativeCanvas.save()
                        drawContext.canvas.nativeCanvas.clipPath(backPath)
                        drawContext.canvas.nativeCanvas.drawRect(-100000f, -100000f, 100000f, 100000f, paint)
                        drawContext.canvas.nativeCanvas.restore()
                    }
                } else {
                    // Non-perspective fallback
                    drawContext.canvas.nativeCanvas.save()
                    drawContext.canvas.nativeCanvas.drawRect(-50000f, -50000f, 50000f, 50000f, paint)
                    drawContext.canvas.nativeCanvas.restore()
                }
            }
            
            if (layer.id == selectedLayerId && activeTool == "Perspective") {
                val corners = parseWarpPointsStr(layer.perspWarpPointsStr)
                if (corners.size == 4) {
                    val strokeW = 2.5f / totalScale.coerceAtLeast(0.3f)
                    val handleRadius = 14f / totalScale.coerceAtLeast(0.3f)
                    val handleInnerRadius = 6f / totalScale.coerceAtLeast(0.3f)
                    
                    val drawCorners = if (warpTarget == "Canvas") {
                        corners.map { canvasToLayerLocal(it, layer) }
                    } else {
                        corners
                    }
                    
                    drawLine(color = EnergeticYellow, start = drawCorners[0], end = drawCorners[1], strokeWidth = strokeW)
                    drawLine(color = EnergeticYellow, start = drawCorners[1], end = drawCorners[2], strokeWidth = strokeW)
                    drawLine(color = EnergeticYellow, start = drawCorners[2], end = drawCorners[3], strokeWidth = strokeW)
                    drawLine(color = EnergeticYellow, start = drawCorners[3], end = drawCorners[0], strokeWidth = strokeW)
                    
                    val handlesList = drawCorners + listOf(
                        (drawCorners[0] + drawCorners[1]) / 2f,
                        (drawCorners[1] + drawCorners[2]) / 2f,
                        (drawCorners[2] + drawCorners[3]) / 2f,
                        (drawCorners[3] + drawCorners[0]) / 2f
                    )
                    for (i in handlesList.indices) {
                        val isSide = i >= 4
                        val r = if (isSide) handleRadius * 0.85f else handleRadius
                        val ir = if (isSide) handleInnerRadius * 0.85f else handleInnerRadius
                        drawCircle(
                            color = EnergeticYellow,
                            radius = r,
                            center = handlesList[i]
                        )
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color.White,
                            radius = ir,
                            center = handlesList[i]
                        )
                    }
                }
            }
            
            drawContext.canvas.restore()
            // Return early since the layer has been fully drawn warped here
            return
        }
    }

    // Graphite-inspired Parametric Layer Caching via State Hash Tracking
    val isPainting = (activeTool == "Brush" || activeTool == "Eraser" || activeTool == "Sudge" || activeTool == "BlurTool") && layer.id == selectedLayerId
    val isRenderingCache = isRenderingCacheLocal.get() == true
    val isMeshWarp = layer.meshWarpPointsStr.isNotEmpty() || (layer.id == selectedLayerId && activeTool == "Mesh")
    val isVectorEditing = activeTool == "Shape Builder" || activeTool == "Pen" || activeTool == "Direct Select"
    val forceRealtime = isPainting || layer.type == com.example.studio.model.LayerType.FREEHAND_DRAWING || isRenderingCache || (isDraggingBezierNode == true) || isMeshWarp || isVectorEditing || (layer.type == com.example.studio.model.LayerType.VECTOR_BEZIER && totalScale > 1.1f)

    if (forceRealtime) {
        val useOffscreenBuffer = composeBlendMode != androidx.compose.ui.graphics.BlendMode.SrcOver || computedOpacity < 1.0f
        if (useOffscreenBuffer) {
            val bounds = androidx.compose.ui.geometry.Rect(0f, 0f, canvasWidth, canvasHeight)
            val paint = androidx.compose.ui.graphics.Paint().apply {
                this.alpha = computedOpacity
                this.blendMode = composeBlendMode
            }
            drawContext.canvas.saveLayer(bounds, paint)
        }
        val innerOpacity = if (useOffscreenBuffer) 1.0f else computedOpacity
        val innerBlendMode = if (useOffscreenBuffer) androidx.compose.ui.graphics.BlendMode.SrcOver else composeBlendMode

        if (layer.meshWarpPointsStr.isNotEmpty() || (layer.id == selectedLayerId && activeTool == "Mesh")) {
            val cols = warpMeshDivisionX
            val rows = warpMeshDivisionY
            val parsedNodes = parseMeshWarpPointsStr(layer.meshWarpPointsStr, cols, rows, layer.width, layer.height, warpTarget, layer)
            if (parsedNodes.size == (cols + 1) * (rows + 1)) {
                val w = layer.width.toInt().coerceIn(2, 2048)
                val h = layer.height.toInt().coerceIn(2, 2048)
                
                val stateHash = if (layer.type == com.example.studio.model.LayerType.IMAGE_CARD) {
                    (layer.imageUri.hashCode() * 31 + (imageBitmapCache[layer.imageUri]?.hashCode() ?: 0) + layer.effects.hashCode()) * 31 + layer.perspWarpPointsStr.hashCode()
                } else {
                    ((layer.textContent.hashCode() * 31 + layer.richTextSpansJson.hashCode() * 31 + layer.baseColor.hashCode()) * 31 + layer.brushPoints.size + layer.cornerRadius.hashCode() + layer.polygonEdges + layer.strokeThickness.hashCode() + layer.fontSize.hashCode() + layer.letterSpacing.hashCode() + layer.lineSpacing.hashCode() + layer.effects.hashCode()) * 31 + layer.perspWarpPointsStr.hashCode()
                }
                val cacheKey = "unwarped_${layer.id}_${w}_${h}_${stateHash}"
                var baseBmp = unwarpedLayerBitmapsCache[cacheKey]
                
                if (baseBmp == null || baseBmp.isRecycled) {
                    // Evict older cached bitmaps for this specific layer to keep memory footprint low
                    val prefix = "unwarped_${layer.id}_"
                    val keysToEvict = unwarpedLayerBitmapsCache.keys.asSequence().filter { k ->
                        k.startsWith(prefix) && k != cacheKey
                    }.toList()
                    for (k in keysToEvict) {
                        val oldBmp = unwarpedLayerBitmapsCache.remove(k)
                        if (oldBmp != null) {
                            try { oldBmp.recycle() } catch (e: Exception) {}
                        }
                    }
                    
                    baseBmp = android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
                    val nativeCanvas = android.graphics.Canvas(baseBmp)
                    val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                    val originalCanvas = drawContext.canvas
                    
                    drawContext.canvas = tempCanvas
                    nativeCanvas.drawColor(android.graphics.Color.TRANSPARENT, android.graphics.PorterDuff.Mode.CLEAR)
                    try {
                        val layerNoWarp = layer.copy(
                            positionX = 0f,
                            positionY = 0f,
                            rotation = 0f,
                            scaleX = 1f,
                            scaleY = 1f,
                            skewX = 0f,
                            skewY = 0f,
                            perspX = 0f,
                            perspY = 0f,
                            perspWarpPointsStr = layer.perspWarpPointsStr,
                            meshWarpPointsStr = ""
                        )
                        drawAllEffectsAndLayersLocal(
                            layer = layerNoWarp,
                            layerOpacity = 1.0f,
                            selectedLayerId = null,
                            pathCache = pathCache,
                            pathPointsCountCache = pathPointsCountCache,
                            totalScale = totalScale,
                            dashEffect = dashEffect,
                            imageBitmapCache = imageBitmapCache,
                            composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                            backdropBitmap = null,
                            globalX = 0f,
                            globalY = 0f,
                            activeTool = activeTool,
                            viewportWidth = viewportWidth,
                            viewportHeight = viewportHeight,
                            panX = panX,
                            panY = panY,
                            canvasWidth = canvasWidth,
                            canvasHeight = canvasHeight,
                            pulseAlpha = pulseAlpha,
                            spinAngle = spinAngle,
                            activeBezierPointIndex = activeBezierPointIndex
                        )
                    } finally {
                        drawContext.canvas = originalCanvas
                    }
                    unwarpedLayerBitmapsCache[cacheKey] = baseBmp!!
                }
                
                // Highly optimized, super smooth Bicubic Bezier Patch interpolation
                val subdivisions = 16
                val denseCols = cols * subdivisions
                val denseRows = rows * subdivisions
                val verts = FloatArray((denseCols + 1) * (denseRows + 1) * 2)
                
                var vIndex = 0
                for (dr in 0..denseRows) {
                    val patchR = (dr / subdivisions).coerceAtMost(rows - 1)
                    val v = if (dr == denseRows) 1f else (dr % subdivisions).toFloat() / subdivisions
                    
                    for (dc in 0..denseCols) {
                        val patchC = (dc / subdivisions).coerceAtMost(cols - 1)
                        val u = if (dc == denseCols) 1f else (dc % subdivisions).toFloat() / subdivisions
                        
                        val N00 = parsedNodes[patchR * (cols + 1) + patchC]
                        val N10 = parsedNodes[patchR * (cols + 1) + patchC + 1]
                        val N01 = parsedNodes[(patchR + 1) * (cols + 1) + patchC]
                        val N11 = parsedNodes[(patchR + 1) * (cols + 1) + patchC + 1]
                        
                        val p00 = N00.main
                        val p30 = N10.main
                        val p03 = N01.main
                        val p33 = N11.main
                        
                        val p10 = p00 + N00.hHandle
                        val p20 = p30 - N10.hHandle
                        
                        val p13 = p03 + N01.hHandle
                        val p23 = p33 - N11.hHandle
                        
                        val p01 = p00 + N00.vHandle
                        val p02 = p03 - N01.vHandle
                        
                        val p31 = p30 + N10.vHandle
                        val p32 = p33 - N11.vHandle
                        
                        val p11 = p10 + p01 - p00
                        val p21 = p20 + p31 - p30
                        val p12 = p13 + p02 - p03
                        val p22 = p23 + p32 - p33
                        
                        val interp = evaluateBezierPatch(
                            u, v,
                            p00, p10, p20, p30,
                            p01, p11, p21, p31,
                            p02, p12, p22, p32,
                            p03, p13, p23, p33
                        )
                        
                        val localPt = if (warpTarget == "Canvas") canvasToLayerLocal(interp, layer) else interp
                        verts[vIndex++] = localPt.x
                        verts[vIndex++] = localPt.y
                    }
                }
                
                val meshPaint = android.graphics.Paint().apply {
                    isAntiAlias = warpInterpolation
                    isFilterBitmap = warpInterpolation
                    alpha = (innerOpacity * 255).toInt().coerceIn(0, 255)
                }
                drawContext.canvas.nativeCanvas.drawBitmapMesh(
                    baseBmp!!,
                    denseCols,
                    denseRows,
                    verts,
                    0,
                    null,
                    0,
                    meshPaint
                )
                
                // Render active mesh guidelines overlays directly during realtime/dragging interactions
                if (layer.id == selectedLayerId && activeTool == "Mesh") {
                    val strokeW = 1.5f / totalScale.coerceAtLeast(0.3f)
                    val handleRadius = 11f / totalScale.coerceAtLeast(0.3f)
                    
                    val densePoints = Array(denseRows + 1) { Array(denseCols + 1) { Offset.Zero } }
                    var tempVIdx = 0
                    for (dr in 0..denseRows) {
                        for (dc in 0..denseCols) {
                            densePoints[dr][dc] = Offset(verts[tempVIdx], verts[tempVIdx + 1])
                            tempVIdx += 2
                        }
                    }
                    
                    // Draw horizontal lines
                    for (dr in 0..denseRows) {
                        val isMajor = (dr % subdivisions == 0)
                        val lineColor = if (isMajor) EnergeticYellow.copy(alpha = 0.75f) else EnergeticYellow.copy(alpha = 0.22f)
                        val lineStroke = if (isMajor) strokeW else strokeW * 0.7f
                        
                        for (dc in 0 until denseCols) {
                            drawLine(
                                color = lineColor,
                                start = densePoints[dr][dc],
                                end = densePoints[dr][dc + 1],
                                strokeWidth = lineStroke
                            )
                        }
                    }
                    
                    // Draw vertical lines
                    for (dc in 0..denseCols) {
                        val isMajor = (dc % subdivisions == 0)
                        val lineColor = if (isMajor) EnergeticYellow.copy(alpha = 0.75f) else EnergeticYellow.copy(alpha = 0.22f)
                        val lineStroke = if (isMajor) strokeW else strokeW * 0.7f
                        
                        for (dr in 0 until denseRows) {
                            drawLine(
                                color = lineColor,
                                start = densePoints[dr][dc],
                                end = densePoints[dr + 1][dc],
                                strokeWidth = lineStroke
                            )
                        }
                    }
                    
                    // Draw selected node's needles (tangent handles)
                    if (activeWarpNodeIndex != -1 && activeWarpNodeIndex in parsedNodes.indices) {
                        val selNode = parsedNodes[activeWarpNodeIndex]
                        
                        val mainLocal = if (warpTarget == "Canvas") canvasToLayerLocal(selNode.main, layer) else selNode.main
                        val hRelLocal = if (warpTarget == "Canvas") canvasToLayerLocal(selNode.main + selNode.hHandle, layer) - mainLocal else selNode.hHandle
                        val vRelLocal = if (warpTarget == "Canvas") canvasToLayerLocal(selNode.main + selNode.vHandle, layer) - mainLocal else selNode.vHandle
                        
                        val needleStrokeW = 1.8f / totalScale.coerceAtLeast(0.3f)
                        
                        val rightPt = mainLocal + hRelLocal
                        val leftPt = mainLocal - hRelLocal
                        val bottomPt = mainLocal + vRelLocal
                        val topPt = mainLocal - vRelLocal
                        
                        // Draw horizontal needle line
                        drawLine(color = Color(0xFF64FFDA), start = leftPt, end = rightPt, strokeWidth = needleStrokeW)
                        // Draw vertical needle line
                        drawLine(color = Color(0xFFFF4081), start = topPt, end = bottomPt, strokeWidth = needleStrokeW)
                        
                        // Draw needle handles
                        val needleColors = listOf(Color(0xFF64FFDA), Color(0xFF64FFDA), Color(0xFFFF4081), Color(0xFFFF4081))
                        val needlePoints = listOf(rightPt, leftPt, bottomPt, topPt)
                        
                        for (i in 0 until 4) {
                            drawCircle(
                                color = needleColors[i],
                                radius = handleRadius * 0.85f,
                                center = needlePoints[i]
                            )
                            drawCircle(
                                color = Color.White,
                                radius = handleRadius * 0.4f,
                                center = needlePoints[i]
                            )
                        }
                    }
                    
                    // Draw main control nodes
                    for (i in parsedNodes.indices) {
                        val n = parsedNodes[i]
                        val nodeLocal = if (warpTarget == "Canvas") canvasToLayerLocal(n.main, layer) else n.main
                        
                        val isSelected = (i == activeWarpNodeIndex)
                        drawCircle(
                            color = if (isSelected) EnergeticYellow else Color.White,
                            radius = if (isSelected) handleRadius * 1.1f else handleRadius * 0.75f,
                            center = nodeLocal
                        )
                        if (isSelected) {
                            drawCircle(
                                color = Color(0xFF14141A),
                                radius = handleRadius * 0.45f,
                                center = nodeLocal
                            )
                        }
                    }
                }
            } else {
                drawAllEffectsAndLayersLocal(
                    layer = layer.copy(meshWarpPointsStr = ""),
                    layerOpacity = innerOpacity,
                    selectedLayerId = selectedLayerId,
                    pathCache = pathCache,
                    pathPointsCountCache = pathPointsCountCache,
                    totalScale = totalScale,
                    dashEffect = dashEffect,
                    imageBitmapCache = imageBitmapCache,
                    composeBlendMode = innerBlendMode,
                    backdropBitmap = backdropBitmap,
                    globalX = globalX,
                    globalY = globalY,
                    activeTool = activeTool,
                    viewportWidth = viewportWidth,
                    viewportHeight = viewportHeight,
                    panX = panX,
                    panY = panY,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    pulseAlpha = pulseAlpha,
                    parentGroups = parentGroups,
                    isExporting = isExporting,

                    spinAngle = spinAngle,
                    activeBezierPointIndex = activeBezierPointIndex,
                    activeWarpNodeIndex = activeWarpNodeIndex
                )
            }
        } else {
            drawAllEffectsAndLayersLocal(
                layer = layer,
                layerOpacity = innerOpacity,
                selectedLayerId = selectedLayerId,
                pathCache = pathCache,
                pathPointsCountCache = pathPointsCountCache,
                totalScale = totalScale,
                dashEffect = dashEffect,
                imageBitmapCache = imageBitmapCache,
                composeBlendMode = innerBlendMode,
                backdropBitmap = backdropBitmap,
                globalX = globalX,
                globalY = globalY,
                activeTool = activeTool,
                viewportWidth = viewportWidth,
                viewportHeight = viewportHeight,
                panX = panX,
                panY = panY,
                canvasWidth = canvasWidth,
                canvasHeight = canvasHeight,
                pulseAlpha = pulseAlpha,
                parentGroups = parentGroups,
                isExporting = isExporting,

                spinAngle = spinAngle,
                activeBezierPointIndex = activeBezierPointIndex,
                activeWarpNodeIndex = activeWarpNodeIndex
            )
        }
        if (useOffscreenBuffer) {
            drawContext.canvas.restore()
        }
    } else {
        val cacheNode = com.example.studio.ui.ParametricLayerCache.getOrCreateNode(layer.id, isExporting)
        val changeCounterVal = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.changeCounter.value
        val allFilters = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.getFiltersForLayer(layer.id) + parentGroups.flatMap {
            com.aistudio.zenithstudio.rpxwtq.EffectStackManager.getFiltersForLayer(it.id)
        }
        val zenithHash = allFilters.map { f ->
            f.id.hashCode() * 31 + f.parameters.map { p -> p.currentValue.hashCode() }.sum() + (if (f.isEnabled) 1 else 0)
        }.sum() + changeCounterVal
        val currentHash = (com.example.studio.ui.ParametricLayerCache.computeParamHash(layer) + parentGroups.map { com.example.studio.ui.ParametricLayerCache.computeParamHash(it) }.sum()) xor zenithHash

        val dropShadow = layer.effects.find { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "DropShadow" }
        val outerGlow = layer.effects.find { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "OuterGlow" }
        val bordersShadowsList = layer.effects.filter { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BordersAndShadows" }.map { it as com.example.studio.model.StudioEffect.PhotoshopEffect }
        
        val hasBordersShadowsDrop = bordersShadowsList.any { (it.parameters["DropShadow_Enabled"]?.value ?: 0f) > 0.5f }
        val hasBordersShadowsOuterBrd = bordersShadowsList.any { (it.parameters["OuterBorder_Enabled"]?.value ?: 0f) > 0.5f }
        val hasBordersShadowsOuterStk = bordersShadowsList.any { (it.parameters["OuterStroke_Enabled"]?.value ?: 0f) > 0.5f }
        val hasZenithFilters = allFilters.any { it.isEnabled }
        val hasOuterEffect = (dropShadow != null) || (outerGlow != null) || hasBordersShadowsDrop || hasBordersShadowsOuterBrd || hasBordersShadowsOuterStk || hasZenithFilters

        var maxEffectPadding = 0f
        if (dropShadow != null) {
            val dsDistance = dropShadow.parameters["Distance"]?.value ?: 10f
            val dsSize = dropShadow.parameters["Size"]?.value ?: 15f
            maxEffectPadding = maxOf(maxEffectPadding, dsDistance + dsSize + 20f)
        }
        if (outerGlow != null) {
            val ogSize = outerGlow.parameters["Size"]?.value ?: 20f
            maxEffectPadding = maxOf(maxEffectPadding, ogSize + 20f)
        }
        for (bordersShadowsItem in bordersShadowsList) {
            if ((bordersShadowsItem.parameters["DropShadow_Enabled"]?.value ?: 0f) > 0.5f) {
                val dsDistance = bordersShadowsItem.parameters["DropShadow_Distance"]?.value ?: 10f
                val dsSize = bordersShadowsItem.parameters["DropShadow_Size"]?.value ?: 15f
                val dsZoom = bordersShadowsItem.parameters["DropShadow_Zoom"]?.value ?: 1.0f
                val scaleExpansion = if (dsZoom > 1f) (dsZoom - 1f) * maxOf(layer.width, layer.height) / 2f else 0f
                maxEffectPadding = maxOf(maxEffectPadding, dsDistance + dsSize + scaleExpansion + 20f)
            }
            if ((bordersShadowsItem.parameters["OuterBorder_Enabled"]?.value ?: 0f) > 0.5f) {
                val size = bordersShadowsItem.parameters["OuterBorder_Size"]?.value ?: 0f
                maxEffectPadding = maxOf(maxEffectPadding, size + 20f)
            }
            if ((bordersShadowsItem.parameters["OuterStroke_Enabled"]?.value ?: 0f) > 0.5f) {
                val size = bordersShadowsItem.parameters["OuterStroke_Size"]?.value ?: 0f
                maxEffectPadding = maxOf(maxEffectPadding, size + 20f)
            }
        }

        val paddingPx = if (hasOuterEffect) {
            maxOf(150f, maxEffectPadding).coerceAtMost(3500f)
        } else if (layer.strokeThickness > 0f) {
            layer.strokeThickness + 8f
        } else {
            0f
        }

        var drawSuccess = false
        var exceptionOccurred = false
        if (cacheNode.paramHash != currentHash || cacheNode.isDirty || cacheNode.cachedImageBitmap == null) {
            try {
                val isDragging = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.isDraggingSlider
                val isLowRamModeActive = com.example.studio.model.DevicePerformanceManager.statsState.value.isLowRamModeActive
                val isDownscaleEnabled = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.isDownscaleEnabled.value
                val downscaleFactor = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.downscaleFactor.value
                val downscaleOnlyOnDrag = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.downscaleOnlyOnDrag.value
                val useBilinear = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.downscaleBilinear.value && !isLowRamModeActive

                val maxCanvasDim = if (isExporting) 8192 else if (isDragging) (if (isLowRamModeActive) 512 else 1024) else (if (isLowRamModeActive) 1280 else 2560)
                val targetW = layer.width + 2 * paddingPx
                val targetH = layer.height + 2 * paddingPx
                val cacheScale = if (targetW > maxCanvasDim || targetH > maxCanvasDim) {
                    maxCanvasDim.toFloat() / maxOf(targetW, targetH)
                } else {
                    1f
                }
                val w = maxOf(2, (targetW * cacheScale).toInt())
                val h = maxOf(2, (targetH * cacheScale).toInt())
                val existingBmp = cacheNode.cachedBitmap
                val isShared = !com.example.studio.ui.ParametricLayerCache.canRecycleBitmap(existingBmp)
                val bmp = if (existingBmp != null && existingBmp.width == w && existingBmp.height == h && !isShared) {
                    existingBmp.eraseColor(android.graphics.Color.TRANSPARENT)
                    existingBmp
                } else {
                    if (!isShared) existingBmp?.recycle()
                    android.graphics.Bitmap.createBitmap(w, h, android.graphics.Bitmap.Config.ARGB_8888)
                }
                val nativeCanvas = android.graphics.Canvas(bmp)
                val tempCanvas = androidx.compose.ui.graphics.Canvas(nativeCanvas)
                val drawScope = androidx.compose.ui.graphics.drawscope.CanvasDrawScope()
                isRenderingCacheLocal.set(true)
                try {
                    drawScope.draw(
                        density = androidx.compose.ui.unit.Density(1.0f),
                        layoutDirection = androidx.compose.ui.unit.LayoutDirection.Ltr,
                        canvas = tempCanvas,
                        size = androidx.compose.ui.geometry.Size(w.toFloat(), h.toFloat())
                    ) {
                        withTransform({
                            scale(cacheScale, cacheScale, androidx.compose.ui.geometry.Offset.Zero)
                            translate(left = paddingPx, top = paddingPx)
                        }) {
                            val localLayer = layer.copy(
                                positionX = 0f,
                                positionY = 0f,
                                rotation = 0f,
                                scaleX = 1f,
                                scaleY = 1f,
                                skewX = 0f,
                                skewY = 0f,
                                perspX = 0f,
                                perspY = 0f,
                                parentGroupId = null
                            )
                            drawAllEffectsAndLayersLocal(
                                layer = localLayer,
                                layerOpacity = 1.0f,
                                selectedLayerId = null, // don't bake selected design markers in cache
                                pathCache = pathCache,
                                pathPointsCountCache = pathPointsCountCache,
                                totalScale = 1.0f,
                                dashEffect = dashEffect,
                                imageBitmapCache = imageBitmapCache,
                                composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
                                backdropBitmap = backdropBitmap,
                                globalX = 0f,
                                globalY = 0f,
                                activeTool = activeTool,
                                viewportWidth = viewportWidth,
                                viewportHeight = viewportHeight,
                                panX = panX,
                                panY = panY,
                                canvasWidth = canvasWidth,
                                canvasHeight = canvasHeight
                            )
                        }
                    }
                } finally {
                    isRenderingCacheLocal.set(false)
                }

                // Apply active GPU Filters to the padded composited bitmap buffer
                val activeFilters = (layer.effects + parentGroups.flatMap { it.effects }).filter { 
                    it.isEnabled && 
                    it is com.example.studio.model.StudioEffect.PhotoshopEffect && 
                    (layer.type != com.example.studio.model.LayerType.IMAGE_CARD && 
                     layer.type != com.example.studio.model.LayerType.FREEHAND_DRAWING &&
                     it.effectType != "BrushConfig" && 
                     it.effectType != "DropShadow" && 
                     it.effectType != "OuterGlow" && 
                     it.effectType != "BordersAndShadows" && 
                     it.effectType != "InnerShadow" &&
                     it.effectType != "InnerGlow" &&
                     it.effectType != "BevelEmboss" &&
                     it.effectType != "Satin" &&
                     it.effectType != "GradientOverlay" &&
                     it.effectType != "PatternOverlay" &&
                     it.effectType != "Stroke" &&
                     it.effectType != "GlassMorphism" &&
                     it.effectType != "ReededGlass")
                }

                val isLowRamMode = com.example.studio.model.DevicePerformanceManager.statsState.value.isLowRamModeActive
                val activeDownscale = (isDownscaleEnabled && (!downscaleOnlyOnDrag || isDragging)) || isLowRamMode
                val effectiveDownscaleFactor = if (isLowRamMode && downscaleFactor <= 1) 2 else downscaleFactor
                
                val needsDraft = (isDragging && (bmp.width > 384 || bmp.height > 384)) || (activeDownscale && effectiveDownscaleFactor > 1)
                
                val draftBmp = if (needsDraft) {
                    val scale = if (activeDownscale && effectiveDownscaleFactor > 1) {
                        val userScale = 1f / effectiveDownscaleFactor.toFloat()
                        if (isDragging) {
                            minOf(userScale, 384f / maxOf(bmp.width, bmp.height))
                        } else {
                            userScale
                        }
                    } else {
                        384f / maxOf(bmp.width, bmp.height)
                    }
                    val dw = (bmp.width * scale).toInt().coerceAtLeast(1)
                    val dh = (bmp.height * scale).toInt().coerceAtLeast(1)
                    android.graphics.Bitmap.createScaledBitmap(bmp, dw, dh, useBilinear)
                } else {
                    bmp
                }

                val draftGpuFilteredBmp = if (activeFilters.isNotEmpty() && globalAppContext != null) {
                    applyGPUImageFilters(globalAppContext!!, draftBmp, layer.id, activeFilters)
                } else {
                    draftBmp
                }

                val filtersToApply = com.aistudio.zenithstudio.rpxwtq.EffectStackManager.getFiltersForLayer(layer.id) + parentGroups.flatMap {
                    com.aistudio.zenithstudio.rpxwtq.EffectStackManager.getFiltersForLayer(it.id)
                }
                
                val draftFilteredBmp = if (globalAppContext != null && filtersToApply.isNotEmpty()) {
                    var tempBmp = draftGpuFilteredBmp
                    for (zenithFilter in filtersToApply) {
                        if (zenithFilter.isEnabled) {
                            val nextBmp = zenithFilter.computeShaderEffect(tempBmp, globalAppContext!!)
                            if (tempBmp != draftBmp && tempBmp != draftGpuFilteredBmp && tempBmp != nextBmp) {
                                tempBmp.recycle()
                            }
                            tempBmp = nextBmp
                        }
                    }
                    tempBmp
                } else {
                    draftGpuFilteredBmp
                }

                val filteredBmp = if (needsDraft) {
                    val upscaled = android.graphics.Bitmap.createScaledBitmap(draftFilteredBmp, w, h, useBilinear)
                    if (draftFilteredBmp != draftBmp && draftFilteredBmp != draftGpuFilteredBmp) {
                        draftFilteredBmp.recycle()
                    }
                    if (draftGpuFilteredBmp != draftBmp) {
                        draftGpuFilteredBmp.recycle()
                    }
                    if (draftBmp != bmp) {
                        draftBmp.recycle()
                    }
                    upscaled
                } else {
                    draftFilteredBmp
                }

                // Recycle intermediate/unused bitmaps to prevent OOM memory leaks
                if (!needsDraft) {
                    if (draftGpuFilteredBmp != bmp && filteredBmp != draftGpuFilteredBmp) {
                        draftGpuFilteredBmp.recycle()
                    }
                    if (filteredBmp != bmp) {
                        if (com.example.studio.ui.ParametricLayerCache.canRecycleBitmap(bmp)) bmp.recycle()
                    }
                } else {
                    if (com.example.studio.ui.ParametricLayerCache.canRecycleBitmap(bmp)) bmp.recycle()
                }

                cacheNode.cachedBitmap = filteredBmp
                cacheNode.cachedImageBitmap = filteredBmp.asImageBitmap()
                cacheNode.paramHash = currentHash
                cacheNode.isDirty = false
                cacheNode.paddingPx = paddingPx
                drawSuccess = true
            } catch (t: Throwable) {
                android.util.Log.e("ParametricLayerCache", "Exception inside drawing update step.", t)
                exceptionOccurred = true
            }
        } else {
            drawSuccess = true
        }

        if (exceptionOccurred && cacheNode.cachedImageBitmap != null) {
            drawSuccess = true
        }

        if (drawSuccess && cacheNode.cachedImageBitmap != null) {
            val targetW = layer.width + 2 * paddingPx
            val targetH = layer.height + 2 * paddingPx
            drawImage(
                image = cacheNode.cachedImageBitmap!!,
                dstOffset = androidx.compose.ui.unit.IntOffset(-paddingPx.toInt(), -paddingPx.toInt()),
                dstSize = androidx.compose.ui.unit.IntSize(targetW.toInt(), targetH.toInt()),
                alpha = computedOpacity,
                blendMode = composeBlendMode
            )
        } else {
            // Draw raw/vector fallback gracefully under sandboxed crash
            drawAllEffectsAndLayersLocal(
                layer = layer,
                layerOpacity = computedOpacity,
                selectedLayerId = selectedLayerId,
                pathCache = pathCache,
                pathPointsCountCache = pathPointsCountCache,
                totalScale = totalScale,
                dashEffect = dashEffect,
                imageBitmapCache = imageBitmapCache,
                composeBlendMode = composeBlendMode,
                backdropBitmap = backdropBitmap,
                globalX = layer.positionX,
                globalY = layer.positionY,
                activeTool = activeTool,
                viewportWidth = viewportWidth,
                viewportHeight = viewportHeight,
                panX = panX,
                panY = panY,
                canvasWidth = canvasWidth,
                canvasHeight = canvasHeight,
                pulseAlpha = pulseAlpha,
                spinAngle = spinAngle,
                activeBezierPointIndex = activeBezierPointIndex
            )
        }

        if (warpCanvasSaved) {
            drawContext.canvas.nativeCanvas.restore()
        }

        if (layer.id == selectedLayerId) {
            if (activeTool == "Perspective") {
                val corners = if (layer.perspWarpPointsStr.isEmpty()) {
                    listOf(
                        androidx.compose.ui.geometry.Offset(0f, 0f),
                        androidx.compose.ui.geometry.Offset(layer.width, 0f),
                        androidx.compose.ui.geometry.Offset(layer.width, layer.height),
                        androidx.compose.ui.geometry.Offset(0f, layer.height)
                    )
                } else {
                    parseWarpPointsStr(layer.perspWarpPointsStr)
                }
                if (corners.size == 4) {
                    val strokeW = 2.5f / totalScale.coerceAtLeast(0.3f)
                    val handleRadius = 14f / totalScale.coerceAtLeast(0.3f)
                    val handleInnerRadius = 6f / totalScale.coerceAtLeast(0.3f)
                    
                    val drawCorners = if (warpTarget == "Canvas") {
                        corners.map { canvasToLayerLocal(it, layer) }
                    } else {
                        corners
                    }
                    
                    drawLine(color = EnergeticYellow, start = drawCorners[0], end = drawCorners[1], strokeWidth = strokeW)
                    drawLine(color = EnergeticYellow, start = drawCorners[1], end = drawCorners[2], strokeWidth = strokeW)
                    drawLine(color = EnergeticYellow, start = drawCorners[2], end = drawCorners[3], strokeWidth = strokeW)
                    drawLine(color = EnergeticYellow, start = drawCorners[3], end = drawCorners[0], strokeWidth = strokeW)
                    
                    val handlesList = drawCorners + listOf(
                        (drawCorners[0] + drawCorners[1]) / 2f,
                        (drawCorners[1] + drawCorners[2]) / 2f,
                        (drawCorners[2] + drawCorners[3]) / 2f,
                        (drawCorners[3] + drawCorners[0]) / 2f
                    )
                    for (i in handlesList.indices) {
                        val isSide = i >= 4
                        val r = if (isSide) handleRadius * 0.85f else handleRadius
                        val ir = if (isSide) handleInnerRadius * 0.85f else handleInnerRadius
                        drawCircle(
                            color = EnergeticYellow,
                            radius = r,
                            center = handlesList[i]
                        )
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color.White,
                            radius = ir,
                            center = handlesList[i]
                        )
                    }
                }
            } else if (activeTool == "Mesh") {
                val cols = warpMeshDivisionX
                val rows = warpMeshDivisionY
                val parsedNodes = parseMeshWarpPointsStr(layer.meshWarpPointsStr, cols, rows, layer.width, layer.height, warpTarget, layer)
                
                val strokeW = 1.5f / totalScale.coerceAtLeast(0.3f)
                val handleRadius = 11f / totalScale.coerceAtLeast(0.3f)
                
                // Draw the dense, beautifully curved mesh guidelines
                val subdivisions = 16
                val denseCols = cols * subdivisions
                val denseRows = rows * subdivisions
                val densePoints = Array(denseRows + 1) { Array(denseCols + 1) { Offset.Zero } }
                
                for (dr in 0..denseRows) {
                    val patchR = (dr / subdivisions).coerceAtMost(rows - 1)
                    val v = if (dr == denseRows) 1f else (dr % subdivisions).toFloat() / subdivisions
                    
                    for (dc in 0..denseCols) {
                        val patchC = (dc / subdivisions).coerceAtMost(cols - 1)
                        val u = if (dc == denseCols) 1f else (dc % subdivisions).toFloat() / subdivisions
                        
                        val N00 = parsedNodes[patchR * (cols + 1) + patchC]
                        val N10 = parsedNodes[patchR * (cols + 1) + patchC + 1]
                        val N01 = parsedNodes[(patchR + 1) * (cols + 1) + patchC]
                        val N11 = parsedNodes[(patchR + 1) * (cols + 1) + patchC + 1]
                        
                        val p00 = N00.main
                        val p30 = N10.main
                        val p03 = N01.main
                        val p33 = N11.main
                        
                        val p10 = p00 + N00.hHandle
                        val p20 = p30 - N10.hHandle
                        
                        val p13 = p03 + N01.hHandle
                        val p23 = p33 - N11.hHandle
                        
                        val p01 = p00 + N00.vHandle
                        val p02 = p03 - N01.vHandle
                        
                        val p31 = p30 + N10.vHandle
                        val p32 = p33 - N11.vHandle
                        
                        val p11 = p10 + p01 - p00
                        val p21 = p20 + p31 - p30
                        val p12 = p13 + p02 - p03
                        val p22 = p23 + p32 - p33
                        
                        val interp = evaluateBezierPatch(
                            u, v,
                            p00, p10, p20, p30,
                            p01, p11, p21, p31,
                            p02, p12, p22, p32,
                            p03, p13, p23, p33
                        )
                        
                        val localPt = if (warpTarget == "Canvas") canvasToLayerLocal(interp, layer) else interp
                        densePoints[dr][dc] = localPt
                    }
                }
                
                // Draw horizontal lines
                for (dr in 0..denseRows) {
                    val isMajor = (dr % subdivisions == 0)
                    val lineColor = if (isMajor) EnergeticYellow.copy(alpha = 0.75f) else EnergeticYellow.copy(alpha = 0.22f)
                    val lineStroke = if (isMajor) strokeW else strokeW * 0.7f
                    
                    for (dc in 0 until denseCols) {
                        drawLine(
                            color = lineColor,
                            start = densePoints[dr][dc],
                            end = densePoints[dr][dc + 1],
                            strokeWidth = lineStroke
                        )
                    }
                }
                
                // Draw vertical lines
                for (dc in 0..denseCols) {
                    val isMajor = (dc % subdivisions == 0)
                    val lineColor = if (isMajor) EnergeticYellow.copy(alpha = 0.75f) else EnergeticYellow.copy(alpha = 0.22f)
                    val lineStroke = if (isMajor) strokeW else strokeW * 0.7f
                    
                    for (dr in 0 until denseRows) {
                        drawLine(
                            color = lineColor,
                            start = densePoints[dr][dc],
                            end = densePoints[dr + 1][dc],
                            strokeWidth = lineStroke
                        )
                    }
                }
                
                // Draw selected node's needles (tangent handles)
                if (activeWarpNodeIndex != -1 && activeWarpNodeIndex in parsedNodes.indices) {
                    val selNode = parsedNodes[activeWarpNodeIndex]
                    
                    val mainLocal = if (warpTarget == "Canvas") canvasToLayerLocal(selNode.main, layer) else selNode.main
                    val hRelLocal = if (warpTarget == "Canvas") canvasToLayerLocal(selNode.main + selNode.hHandle, layer) - mainLocal else selNode.hHandle
                    val vRelLocal = if (warpTarget == "Canvas") canvasToLayerLocal(selNode.main + selNode.vHandle, layer) - mainLocal else selNode.vHandle
                    
                    val needleStrokeW = 1.8f / totalScale.coerceAtLeast(0.3f)
                    
                    val rightPt = mainLocal + hRelLocal
                    val leftPt = mainLocal - hRelLocal
                    val bottomPt = mainLocal + vRelLocal
                    val topPt = mainLocal - vRelLocal
                    
                    // Draw horizontal needle line
                    drawLine(color = Color(0xFF64FFDA), start = leftPt, end = rightPt, strokeWidth = needleStrokeW)
                    // Draw vertical needle line
                    drawLine(color = Color(0xFFFF4081), start = topPt, end = bottomPt, strokeWidth = needleStrokeW)
                    
                    // Draw needle handles
                    val needleColors = listOf(Color(0xFF64FFDA), Color(0xFF64FFDA), Color(0xFFFF4081), Color(0xFFFF4081))
                    val needlePoints = listOf(rightPt, leftPt, bottomPt, topPt)
                    
                    for (i in 0 until 4) {
                        drawCircle(
                            color = needleColors[i],
                            radius = handleRadius * 0.85f,
                            center = needlePoints[i]
                        )
                        drawCircle(
                            color = Color.White,
                            radius = handleRadius * 0.4f,
                            center = needlePoints[i]
                        )
                    }
                }
                
                // Draw main control nodes
                for (i in parsedNodes.indices) {
                    val n = parsedNodes[i]
                    val nodeLocal = if (warpTarget == "Canvas") canvasToLayerLocal(n.main, layer) else n.main
                    
                    val isSelected = (i == activeWarpNodeIndex)
                    drawCircle(
                        color = if (isSelected) EnergeticYellow else Color.White,
                        radius = if (isSelected) handleRadius * 1.1f else handleRadius * 0.75f,
                        center = nodeLocal
                    )
                    if (isSelected) {
                        drawCircle(
                            color = Color(0xFF14141A),
                            radius = handleRadius * 0.45f,
                            center = nodeLocal
                        )
                    }
                }
            } else if (activeTool == "Pen" && layer.type == com.example.studio.model.LayerType.VECTOR_BEZIER) {
                val anchors = layer.brushPoints.toAnchorPoints()
                if (anchors.isNotEmpty()) {
                    for (apIdx in anchors.indices) {
                        val ap = anchors[apIdx]
                        if (ap.position.x.isNaN() || ap.position.y.isNaN()) {
                            continue
                        }
                        
                        // If handleIn is active, draw dotted guideline and handle circle
                        if (ap.handleIn != ap.position) {
                            drawLine(
                                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.65f),
                                start = ap.position,
                                end = ap.handleIn,
                                strokeWidth = 3f / totalScale.coerceAtLeast(0.3f)
                            )
                            val isInSelected = activeBezierPointIndex == apIdx * 3 + 1
                            drawCircle(
                                color = if (isInSelected) androidx.compose.ui.graphics.Color(0xFFFFD54F) else IndustrialAmber,
                                radius = (if (isInSelected) 24f else 18f) / totalScale.coerceAtLeast(0.3f),
                                center = ap.handleIn
                            )
                            drawCircle(
                                color = if (isInSelected) androidx.compose.ui.graphics.Color(0xFFFF1744) else androidx.compose.ui.graphics.Color.White,
                                radius = (if (isInSelected) 11f else 8f) / totalScale.coerceAtLeast(0.3f),
                                center = ap.handleIn
                            )
                        }

                        // If handleOut is active, draw dotted guideline and handle circle
                        if (ap.handleOut != ap.position) {
                            drawLine(
                                color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.65f),
                                start = ap.position,
                                end = ap.handleOut,
                                strokeWidth = 3f / totalScale.coerceAtLeast(0.3f)
                            )
                            val isOutSelected = activeBezierPointIndex == apIdx * 3 + 2
                            drawCircle(
                                color = if (isOutSelected) androidx.compose.ui.graphics.Color(0xFFFFD54F) else IndustrialAmber,
                                radius = (if (isOutSelected) 24f else 18f) / totalScale.coerceAtLeast(0.3f),
                                center = ap.handleOut
                            )
                            drawCircle(
                                color = if (isOutSelected) androidx.compose.ui.graphics.Color(0xFFFF1744) else androidx.compose.ui.graphics.Color.White,
                                radius = (if (isOutSelected) 11f else 8f) / totalScale.coerceAtLeast(0.3f),
                                center = ap.handleOut
                            )
                        }

                        // Main anchor center point
                        val isAnchorSelected = activeBezierPointIndex == apIdx * 3
                        drawCircle(
                            color = if (isAnchorSelected) androidx.compose.ui.graphics.Color(0xFFFF1744) else androidx.compose.ui.graphics.Color(0xFF00E5FF),
                            radius = (if (isAnchorSelected) 26f else 20f) / totalScale.coerceAtLeast(0.3f),
                            center = ap.position
                        )
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color.White,
                            radius = (if (isAnchorSelected) 12f else 9f) / totalScale.coerceAtLeast(0.3f),
                            center = ap.position
                        )
                    }
                }
            } else if (activeTool != "Perspective" && activeTool != "Mesh" && (activeTool != "Pen" || layer.type != com.example.studio.model.LayerType.VECTOR_BEZIER)) {
                drawRect(
                    color = IndustrialAmber.copy(0.8f),
                    topLeft = androidx.compose.ui.geometry.Offset(-6f, -6f),
                    size = androidx.compose.ui.geometry.Size(layer.width + 12f, layer.height + 12f),
                    style = androidx.compose.ui.graphics.drawscope.Stroke(
                        width = 1.5f / totalScale.coerceAtLeast(0.5f),
                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f / totalScale.coerceAtLeast(0.5f), 8f / totalScale.coerceAtLeast(0.5f)))
                    )
                )
                
                // Draw 8 resize handles on corners and middles of all sides for clear visual feedback
                val cornerHandles = listOf(
                    androidx.compose.ui.geometry.Offset(0f, 0f),                         // Top-Left (TL)
                    androidx.compose.ui.geometry.Offset(layer.width, 0f),                // Top-Right (TR)
                    androidx.compose.ui.geometry.Offset(0f, layer.height),               // Bottom-Left (BL)
                    androidx.compose.ui.geometry.Offset(layer.width, layer.height)       // Bottom-Right (BR)
                )
                val sideHandles = listOf(
                    androidx.compose.ui.geometry.Offset(layer.width / 2f, 0f),           // Top-Middle (T)
                    androidx.compose.ui.geometry.Offset(layer.width / 2f, layer.height),  // Bottom-Middle (B)
                    androidx.compose.ui.geometry.Offset(0f, layer.height / 2f),          // Left-Middle (L)
                    androidx.compose.ui.geometry.Offset(layer.width, layer.height / 2f)     // Right-Middle (R)
                )
                
                val cornerOuterRadius = 11f / totalScale.coerceAtLeast(0.4f)
                val cornerInnerRadius = 6.5f / totalScale.coerceAtLeast(0.4f)
                val sideRadius = 8f / totalScale.coerceAtLeast(0.4f)
                val sideInnerRadius = 4.5f / totalScale.coerceAtLeast(0.4f)
                
                val hasActiveGradOverlay = showGradientControls && layer.effects.any { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" }
                if (!hasActiveGradOverlay || layer.id != selectedLayerId) {
                    for (pt in sideHandles) {
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color(0xFF1E293B),
                            radius = sideRadius + 2.5f / totalScale.coerceAtLeast(0.4f),
                            center = pt
                        )
                        drawCircle(
                            color = EnergeticYellow,
                            radius = sideRadius,
                            center = pt
                        )
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color.White,
                            radius = sideInnerRadius,
                            center = pt
                        )
                    }
                    for (pt in cornerHandles) {
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color(0xFF0F172A),
                            radius = cornerOuterRadius + 2.5f / totalScale.coerceAtLeast(0.4f),
                            center = pt
                        )
                        drawCircle(
                            color = EnergeticYellow,
                            radius = cornerOuterRadius,
                            center = pt
                        )
                        drawCircle(
                            color = androidx.compose.ui.graphics.Color.White,
                            radius = cornerInnerRadius,
                            center = pt
                        )
                        drawCircle(
                            color = IndustrialAmber,
                            radius = 2.5f / totalScale.coerceAtLeast(0.4f),
                            center = pt
                        )
                    }
                    
                    drawCircle(
                        color = androidx.compose.ui.graphics.Color(0xFFFF5722),
                        radius = 13f / totalScale.coerceAtLeast(0.4f),
                        center = androidx.compose.ui.geometry.Offset(layer.width, layer.height),
                        style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.5f / totalScale.coerceAtLeast(0.4f))
                    )
                }
            }

            // Draw On-Canvas Gradient Overlay Vector Handle Guide Line and Pins dynamically
            val gradOverlay = layer.effects.find { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "GradientOverlay" } as? com.example.studio.model.StudioEffect.PhotoshopEffect
            if (gradOverlay != null && showGradientControls && layer.id == selectedLayerId) {
                val goScale = (gradOverlay.parameters["Scale"]?.value ?: 100f) / 100f
                val goAngle = gradOverlay.parameters["Angle"]?.value ?: 90f
                
                val hasCustomHandles = gradOverlay.parameters["StartX"] != null
                val startX: Float
                val startY: Float
                val endX: Float
                val endY: Float
                if (hasCustomHandles) {
                    startX = (gradOverlay.parameters["StartX"]?.value ?: 0f) * layer.width
                    startY = (gradOverlay.parameters["StartY"]?.value ?: 0f) * layer.height
                    endX = (gradOverlay.parameters["EndX"]?.value ?: 1f) * layer.width
                    endY = (gradOverlay.parameters["EndY"]?.value ?: 1f) * layer.height
                } else {
                    val rads = Math.toRadians(goAngle.toDouble())
                    val cos = Math.cos(rads).toFloat()
                    val sin = Math.sin(rads).toFloat()
                    startX = layer.width / 2f - (layer.width / 2f * cos * goScale)
                    startY = layer.height / 2f - (layer.height / 2f * sin * goScale)
                    endX = layer.width / 2f + (layer.width / 2f * cos * goScale)
                    endY = layer.height / 2f + (layer.height / 2f * sin * goScale)
                }
                
                val startPt = androidx.compose.ui.geometry.Offset(startX, startY)
                val endPt = androidx.compose.ui.geometry.Offset(endX, endY)
                
                val lineThickness = 1.8f / totalScale.coerceAtLeast(0.5f)
                val outlineThickness = 3.8f / totalScale.coerceAtLeast(0.5f)
                
                // 1. Draw Black guideline shadow/outline for extreme contrast against any background
                drawLine(
                    color = androidx.compose.ui.graphics.Color.Black.copy(alpha = 0.65f),
                    start = startPt,
                    end = endPt,
                    strokeWidth = outlineThickness
                )
                
                // 2. Draw white/amber guideline
                drawLine(
                    color = androidx.compose.ui.graphics.Color.White.copy(alpha = 0.95f),
                    start = startPt,
                    end = endPt,
                    strokeWidth = lineThickness
                )
                drawLine(
                    color = IndustrialAmber.copy(0.75f),
                    start = startPt,
                    end = endPt,
                    strokeWidth = lineThickness * 0.5f
                )
                
                // Fetch colors for handles
                val goPresetIdx = (gradOverlay.parameters["Preset"]?.value ?: 0f).toInt().coerceIn(0, 7)
                val stopCount = if (goPresetIdx < 7) {
                    val presetColorList = gradientPresets[goPresetIdx]
                    presetColorList.size
                } else {
                    (gradOverlay.parameters["CustomStopCount"]?.value ?: 2f).toInt().coerceIn(2, 100)
                }
                
                val customColorsList = mutableListOf<androidx.compose.ui.graphics.Color>()
                if (goPresetIdx < 7) {
                    val colors = gradientPresets[goPresetIdx]
                    customColorsList.addAll(colors)
                } else {
                    for (idx in 0 until stopCount) {
                        val rKey = "CustomStop_${idx}_R"
                        val gKey = "CustomStop_${idx}_G"
                        val bKey = "CustomStop_${idx}_B"
                        val aKey = "CustomStop_${idx}_A"
                        val rVal = gradOverlay.parameters[rKey]?.value ?: when(idx) {
                            0 -> gradOverlay.parameters["CustomStart_R"]?.value ?: 1.0f
                            1 -> gradOverlay.parameters["CustomEnd_R"]?.value ?: 0.0f
                            else -> 0.5f
                        }
                        val gVal = gradOverlay.parameters[gKey]?.value ?: when(idx) {
                            0 -> gradOverlay.parameters["CustomStart_G"]?.value ?: 0.0f
                            1 -> gradOverlay.parameters["CustomEnd_G"]?.value ?: 0.0f
                            else -> 0.5f
                        }
                        val bVal = gradOverlay.parameters[bKey]?.value ?: when(idx) {
                            0 -> gradOverlay.parameters["CustomStart_B"]?.value ?: 0.0f
                            1 -> gradOverlay.parameters["CustomEnd_B"]?.value ?: 1.0f
                            else -> 0.5f
                        }
                        val aVal = gradOverlay.parameters[aKey]?.value ?: 1.0f
                        customColorsList.add(androidx.compose.ui.graphics.Color(rVal, gVal, bVal, aVal))
                    }
                }
                
                val startColor = customColorsList.firstOrNull() ?: androidx.compose.ui.graphics.Color.White
                val endColor = customColorsList.lastOrNull() ?: androidx.compose.ui.graphics.Color.Black
                
                // Draw start circular handle with custom color preview & thick white border
                val handleRadius = 11.5f / totalScale.coerceAtLeast(0.5f)
                val blackBorderRadius = handleRadius + 2f / totalScale.coerceAtLeast(0.5f)
                
                // Black base shadow for start handle
                drawCircle(color = androidx.compose.ui.graphics.Color.Black.copy(0.5f), radius = blackBorderRadius, center = startPt)
                drawCircle(color = androidx.compose.ui.graphics.Color.White, radius = handleRadius, center = startPt)
                drawCircle(color = startColor, radius = handleRadius - 2.5f / totalScale.coerceAtLeast(0.5f), center = startPt)
                
                // Draw end circular handle
                drawCircle(color = androidx.compose.ui.graphics.Color.Black.copy(0.5f), radius = blackBorderRadius, center = endPt)
                drawCircle(color = androidx.compose.ui.graphics.Color.White, radius = handleRadius, center = endPt)
                drawCircle(color = endColor, radius = handleRadius - 2.5f / totalScale.coerceAtLeast(0.5f), center = endPt)
                
                // Let's draw interior stop tracking markers along the line
                val activeStopIndex = (gradOverlay.parameters["SelectedStopIndex"]?.value ?: 0f).toInt()
                
                for (idx in 0 until stopCount) {
                    val fraction = if (goPresetIdx < 7) {
                        idx.toFloat() / (stopCount - 1).coerceAtLeast(1)
                    } else {
                        gradOverlay.parameters["CustomStop_${idx}_Pos"]?.value ?: (idx.toFloat() / (stopCount - 1).coerceAtLeast(1))
                    }
                    val stopColor = customColorsList.getOrNull(idx) ?: androidx.compose.ui.graphics.Color.Gray
                    
                    val stopX = startX + (endX - startX) * fraction
                    val stopY = startY + (endY - startY) * fraction
                    
                    val markerRadius = 8.5f / totalScale.coerceAtLeast(0.5f)
                    val outerSquareSize = markerRadius * 2f
                    val ptOffset = androidx.compose.ui.geometry.Offset(stopX - markerRadius, stopY - markerRadius)
                    
                    // Black backing shadow
                    drawRect(
                        color = androidx.compose.ui.graphics.Color.Black.copy(0.55f),
                        topLeft = androidx.compose.ui.geometry.Offset(stopX - markerRadius - 2f / totalScale.coerceAtLeast(0.5f), stopY - markerRadius - 2f / totalScale.coerceAtLeast(0.5f)),
                        size = androidx.compose.ui.geometry.Size(outerSquareSize + 4f / totalScale.coerceAtLeast(0.5f), outerSquareSize + 4f / totalScale.coerceAtLeast(0.5f))
                    )
                    
                    // White/Yellow border
                    drawRect(
                        color = if (idx == activeStopIndex) EnergeticYellow else androidx.compose.ui.graphics.Color.White,
                        topLeft = ptOffset,
                        size = androidx.compose.ui.geometry.Size(outerSquareSize, outerSquareSize)
                    )
                    
                    // Internals colored square representing stop color
                    val innerSize = (markerRadius - 2.5f / totalScale.coerceAtLeast(0.5f)) * 2f
                    val innerOffset = markerRadius - 2.5f / totalScale.coerceAtLeast(0.5f)
                    drawRect(
                        color = stopColor,
                        topLeft = androidx.compose.ui.geometry.Offset(stopX - innerOffset, stopY - innerOffset),
                        size = androidx.compose.ui.geometry.Size(innerSize, innerSize)
                    )
                }
            }
        }
    }
    drawContext.canvas.restore()
} catch (e: Throwable) {
    e.printStackTrace()
    try {
        drawAllEffectsAndLayersLocal(
            layer = layer,
            layerOpacity = layerOpacity,
            selectedLayerId = selectedLayerId,
            pathCache = pathCache,
            pathPointsCountCache = pathPointsCountCache,
            totalScale = totalScale,
            dashEffect = dashEffect,
            imageBitmapCache = imageBitmapCache,
            composeBlendMode = androidx.compose.ui.graphics.BlendMode.SrcOver,
            backdropBitmap = backdropBitmap,
            globalX = globalX,
            globalY = globalY,
            activeTool = activeTool,
            viewportWidth = viewportWidth,
            viewportHeight = viewportHeight,
            panX = panX,
            panY = panY,
            canvasWidth = canvasWidth,
            canvasHeight = canvasHeight,
            pulseAlpha = pulseAlpha,
            spinAngle = spinAngle
        )
    } catch (ex: Throwable) {
        ex.printStackTrace()
    }
}
}

private fun getOrCreateBackdropBitmap(width: Int, height: Int, existing: android.graphics.Bitmap?): android.graphics.Bitmap {
    if (existing != null && existing.width == width && existing.height == height) {
        existing.eraseColor(android.graphics.Color.TRANSPARENT)
        return existing
    }
    existing?.recycle()
    return android.graphics.Bitmap.createBitmap(width, height, android.graphics.Bitmap.Config.ARGB_8888)
}

private fun isLayerShieldedByAdjustment(
    layers: List<com.example.studio.model.StudioLayer>,
    currentIndex: Int,
    limitIndex: Int
): Boolean {
    for (i in limitIndex until currentIndex) {
        if (i >= 0 && i < layers.size) {
            val lyr = layers[i]
            if (lyr.isVisible && lyr.type == com.example.studio.model.LayerType.ADJUSTMENT_LAYER) {
                return true
            }
        }
    }
    return false
}

private var lastSuccessfulMatrix = floatArrayOf(
    1f, 0f, 0f, 0f, 0f,
    0f, 1f, 0f, 0f, 0f,
    0f, 0f, 1f, 0f, 0f,
    0f, 0f, 0f, 1f, 0f
)

fun computeLayerColorMatrix(layer: com.example.studio.model.StudioLayer): android.graphics.ColorMatrix {
    val matrix = android.graphics.ColorMatrix()
    try {
        val brightness = SlidersHighFreqState.get("${layer.id}_adj_brightness", layer.adjBrightness)
        val contrast = SlidersHighFreqState.get("${layer.id}_adj_contrast", layer.adjContrast)
        val saturation = SlidersHighFreqState.get("${layer.id}_adj_saturation", layer.adjSaturation)
        val tintIntensity = SlidersHighFreqState.get("${layer.id}_adj_tintIntensity", layer.adjTintColorIntensity)
        val tintColor = layer.adjColorTint ?: androidx.compose.ui.graphics.Color.Transparent

        val baseMatrix = createAdjustmentColorMatrix(
            brightness = brightness,
            contrast = contrast,
            saturation = saturation,
            tintColor = tintColor,
            tintIntensity = tintIntensity
        )
        matrix.set(baseMatrix)

        val colorGrading = layer.effects.find { it.isEnabled && it is com.example.studio.model.StudioEffect.PhotoshopEffect && (it.effectType == "CameraRaw" || it.effectType == "ColorGrading") } as? com.example.studio.model.StudioEffect.PhotoshopEffect
        if (colorGrading != null) {
            val rawExposure = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Exposure", colorGrading.parameters["Exposure"]?.value ?: 0f)
            val rawContrast = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Contrast", colorGrading.parameters["Contrast"]?.value ?: 0f)
            val rawHighlights = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Highlights", colorGrading.parameters["Highlights"]?.value ?: 0f)
            val rawShadows = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Shadows", colorGrading.parameters["Shadows"]?.value ?: 0f)
            val rawWhites = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Whites", colorGrading.parameters["Whites"]?.value ?: 0f)
            val rawBlacks = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Blacks", colorGrading.parameters["Blacks"]?.value ?: 0f)
            val rawTemp = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Temp", SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Temperature", colorGrading.parameters["Temp"]?.value ?: colorGrading.parameters["Temperature"]?.value ?: 0f))
            val rawTint = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Tint", colorGrading.parameters["Tint"]?.value ?: 0f)
            val rawVibrance = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Vibrance", colorGrading.parameters["Vibrance"]?.value ?: 0f)
            val rawSaturation = SlidersHighFreqState.get("${layer.id}_effect_${colorGrading.id}_Saturation", colorGrading.parameters["Saturation"]?.value ?: 0f)

            // Incorporate Exposure & Contrast
            val expScale = if (rawExposure >= 0f) 1f + rawExposure * 0.2f else 1f / (1f - rawExposure * 0.2f)
            val expMatrix = android.graphics.ColorMatrix(floatArrayOf(
                expScale, 0f, 0f, 0f, 0f,
                0f, expScale, 0f, 0f, 0f,
                0f, 0f, expScale, 0f, 0f,
                0f, 0f, 0f, 1f, 0f
            ))
            matrix.postConcat(expMatrix)

            if (rawContrast != 0f) {
                val conScale = if (rawContrast >= 0f) 1f + rawContrast * 0.05f else 1f / (1f - rawContrast * 0.05f)
                val conTranslate = (-0.5f * conScale + 0.5f) * 255f
                val conMatrix = android.graphics.ColorMatrix(floatArrayOf(
                    conScale, 0f, 0f, 0f, conTranslate,
                    0f, conScale, 0f, 0f, conTranslate,
                    0f, 0f, conScale, 0f, conTranslate,
                    0f, 0f, 0f, 1f, 0f
                ))
                matrix.postConcat(conMatrix)
            }

            // Incorporate Temp & Tint
            if (rawTemp != 0f || rawTint != 0f) {
                val tempShiftR = rawTemp * 0.2f
                val tempShiftG = rawTemp * 0.05f
                val tempShiftB = -rawTemp * 0.2f

                val tintShiftR = rawTint * 0.1f
                val tintShiftG = -rawTint * 0.2f
                val tintShiftB = rawTint * 0.1f

                val tMatrix = android.graphics.ColorMatrix(floatArrayOf(
                    1f, 0f, 0f, 0f, tempShiftR + tintShiftR,
                    0f, 1f, 0f, 0f, tempShiftG + tintShiftG,
                    0f, 0f, 1f, 0f, tempShiftB + tintShiftB,
                    0f, 0f, 0f, 1f, 0f
                ))
                matrix.postConcat(tMatrix)
            }

            // Incorporate Saturation
            if (rawSaturation != 0f) {
                val satFactor = if (rawSaturation >= 0f) 1f + rawSaturation * 0.05f else 1f / (1f - rawSaturation * 0.05f)
                val satM = android.graphics.ColorMatrix()
                satM.setSaturation(satFactor)
                matrix.postConcat(satM)
            }
        }
    } catch (e: Exception) {
        e.printStackTrace()
    }
    return matrix
}

private fun createAdjustmentColorMatrix(
    brightness: Float,
    contrast: Float,
    saturation: Float,
    tintColor: androidx.compose.ui.graphics.Color?,
    tintIntensity: Float
): android.graphics.ColorMatrix {
    val matrix = android.graphics.ColorMatrix()
    try {
        val bSafe = (brightness * 255f).coerceIn(-255f, 255f)
        if (bSafe.isNaN() || bSafe.isInfinite()) throw ArithmeticException("NaN/Infinity in brightness")

        val brightnessMatrix = android.graphics.ColorMatrix(floatArrayOf(
            1f, 0f, 0f, 0f, bSafe,
            0f, 1f, 0f, 0f, bSafe,
            0f, 0f, 1f, 0f, bSafe,
            0f, 0f, 0f, 1f, 0f
        ))
        
        val scale = contrast.coerceIn(0f, 10f)
        if (scale.isNaN() || scale.isInfinite()) throw ArithmeticException("NaN/Infinity in contrast scale")
        val translate = ((-0.5f * scale + 0.5f) * 255f).coerceIn(-255f, 255f)
        if (translate.isNaN() || translate.isInfinite()) throw ArithmeticException("NaN/Infinity in contrast translate")

        val contrastMatrix = android.graphics.ColorMatrix(floatArrayOf(
            scale, 0f, 0f, 0f, translate,
            0f, scale, 0f, 0f, translate,
            0f, 0f, scale, 0f, translate,
            0f, 0f, 0f, 1f, 0f
        ))
        
        val satSafe = saturation.coerceIn(0f, 10f)
        if (satSafe.isNaN() || satSafe.isInfinite()) throw ArithmeticException("NaN/Infinity in saturation")
        val satMatrix = android.graphics.ColorMatrix()
        satMatrix.setSaturation(satSafe)
        
        val tintMatrix = android.graphics.ColorMatrix()
        val tintSafeIntensity = tintIntensity.coerceIn(0f, 1f)
        if (tintColor != null && tintColor != androidx.compose.ui.graphics.Color.Transparent && tintSafeIntensity > 0f) {
            val tr = tintColor.red.coerceIn(0f, 1f)
            val tg = tintColor.green.coerceIn(0f, 1f)
            val tb = tintColor.blue.coerceIn(0f, 1f)
            val invT = (1f - tintSafeIntensity).coerceIn(0f, 1f)
            
            val rVal = invT + tintSafeIntensity * tr
            val gVal = invT + tintSafeIntensity * tg
            val bVal = invT + tintSafeIntensity * tb
            
            if (rVal.isNaN() || gVal.isNaN() || bVal.isNaN()) throw ArithmeticException("NaN/Infinity in tint color elements")

            val tintArray = floatArrayOf(
                rVal, 0f, 0f, 0f, 0f,
                0f, gVal, 0f, 0f, 0f,
                0f, 0f, bVal, 0f, 0f,
                0f, 0f, 0f, 1f, 0f
            )
            tintMatrix.set(tintArray)
        }
        
        matrix.postConcat(brightnessMatrix)
        matrix.postConcat(contrastMatrix)
        matrix.postConcat(satMatrix)
        matrix.postConcat(tintMatrix)

        val arr = matrix.array
        for (f in arr) {
            if (f.isNaN() || f.isInfinite()) {
                throw ArithmeticException("ColorMatrix contains non-finite element")
            }
        }
        
        System.arraycopy(arr, 0, lastSuccessfulMatrix, 0, 20)
        
    } catch (e: Exception) {
        android.util.Log.e("StudioColorMatrix", "Arithmetic / float issue detected inside rapid ColorMatrix calculation. Returning last successful clean configuration.", e)
        matrix.set(lastSuccessfulMatrix)
    }
    return matrix
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.generateBackdropForLayer(
    layers: List<com.example.studio.model.StudioLayer>,
    currentIndex: Int,
    canvasWidth: Float,
    canvasHeight: Float,
    imageBitmapCache: Map<String, androidx.compose.ui.graphics.ImageBitmap>,
    pathCache: android.util.SparseArray<androidx.compose.ui.graphics.Path>,
    pathPointsCountCache: android.util.SparseIntArray,
    existingBitmap: android.graphics.Bitmap?,
    warpMeshDivisionX: Int = 3,
    warpMeshDivisionY: Int = 3,
    warpRepeatMode: String = "Off",
    warpRepeatX: Float = 1.0f,
    warpRepeatY: Float = 1.0f,
    warpPhaseX: Float = 0.0f,
    warpPhaseY: Float = 0.0f,
    warpInterpolation: Boolean = true,
    warpTarget: String = "Layer",
    isExporting: Boolean = false
): android.graphics.Bitmap? {
    val w = canvasWidth.toInt().coerceIn(100, 4000)
    val h = canvasHeight.toInt().coerceIn(100, 4000)
    
    return try {
        val bitmap = getOrCreateBackdropBitmap(w, h, existingBitmap)
        val canvas = android.graphics.Canvas(bitmap)
        val composeCanvas = androidx.compose.ui.graphics.Canvas(canvas)
        val drawScope = androidx.compose.ui.graphics.drawscope.CanvasDrawScope()
        
        drawScope.draw(
            density = androidx.compose.ui.unit.Density(1.0f),
            layoutDirection = androidx.compose.ui.unit.LayoutDirection.Ltr,
            canvas = composeCanvas,
            size = androidx.compose.ui.geometry.Size(w.toFloat(), h.toFloat())
        ) {
            // Draw previous layers from back to front (largest index down to currentIndex + 1)
            for (idx in layers.size - 1 downTo currentIndex + 1) {
                val lyr = layers[idx]
                if (!lyr.isVisible) continue
                if (isLayerShieldedByAdjustment(layers, idx, currentIndex + 1)) continue
                val lOpacity = lyr.opacity
                val cBlend = lyr.blendMode.toComposeBlendMode()
                
                drawSingleConnectedLayer(
                    layer = lyr,
                    layerOpacity = lOpacity,
                    selectedLayerId = null,
                    pathCache = pathCache,
                    pathPointsCountCache = pathPointsCountCache,
                    totalScale = 1.0f,
                    dashEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(12f, 8f)),
                    composeBlendMode = cBlend,
                    imageBitmapCache = imageBitmapCache,
                    sharedTransformMatrix = androidx.compose.ui.graphics.Matrix(),
                    viewportWidth = canvasWidth,
                    viewportHeight = canvasHeight,
                    canvasWidth = canvasWidth,
                    canvasHeight = canvasHeight,
                    allLayers = layers,
                    warpMeshDivisionX = warpMeshDivisionX,
                    warpMeshDivisionY = warpMeshDivisionY,
                    warpRepeatMode = warpRepeatMode,
                    warpRepeatX = warpRepeatX,
                    warpRepeatY = warpRepeatY,
                    warpPhaseX = warpPhaseX,
                    warpPhaseY = warpPhaseY,
                    warpInterpolation = warpInterpolation,
                    warpTarget = warpTarget,
                    isExporting = isExporting,
                )
            }
        }
        bitmap
    } catch (e: Exception) {
        e.printStackTrace()
        null
    }
}

@Composable
fun BordersAndShadowsTabPanel(
    selectedLayer: com.example.studio.model.StudioLayer,
    onAddEffect: (com.example.studio.model.StudioEffect) -> Unit,
    onUpdateEffectParam: (String, String, Float) -> Unit,
    isSingleColumn: Boolean = false,
    onRemoveEffect: ((String) -> Unit)? = null,
    onToggleEffectEnabled: ((String) -> Unit)? = null
) {
    val bordersShadowsEffs = selectedLayer.effects.filter { it is com.example.studio.model.StudioEffect.PhotoshopEffect && it.effectType == "BordersAndShadows" }.map { it as com.example.studio.model.StudioEffect.PhotoshopEffect }

    if (bordersShadowsEffs.isEmpty()) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(SlatePanel, RoundedCornerShape(8.dp))
                .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                .padding(24.dp),
            contentAlignment = Alignment.Center
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Text(
                    text = "Advanced Borders & Shadows Layer Styles",
                    style = Typography.bodyMedium,
                    color = EnergeticYellow,
                    fontWeight = FontWeight.Bold
                )
                Text(
                    text = "Apply real-time high-fidelity drop shadows, inner shadows, nested inner/outer borders, and precise center/inner/outer stroke effects to your layout non-destructively.",
                    style = Typography.labelSmall,
                    color = TextSecondary,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.width(420.dp)
                )
                Button(
                    onClick = {
                        val newEff = com.example.studio.model.PhotoshopEffectTemplates.create(
                            id = java.util.UUID.randomUUID().toString(),
                            effectType = "BordersAndShadows"
                        )
                        onAddEffect(newEff)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber),
                    shape = RoundedCornerShape(6.dp)
                ) {
                    Icon(Icons.Default.Add, "Add FX", tint = DarkOnyx, modifier = Modifier.size(16.dp))
                    Spacer(Modifier.width(6.dp))
                    Text("Activate Styling Engine", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
                }
            }
        }
    } else {
        var borderStrokeTypeToEditMap = remember { mutableStateMapOf<String, String>() }
        val effectExpandedMap = remember { mutableStateMapOf<String, Boolean>() }
        val sectionExpandedMap = remember { mutableStateMapOf<String, Boolean>() }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(androidx.compose.foundation.rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            bordersShadowsEffs.forEachIndexed { index, eff ->
                val isEffectExpanded = effectExpandedMap[eff.id] ?: true
                
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(SlatePanel, RoundedCornerShape(12.dp))
                        .border(BorderStroke(1.dp, HighslateOutline), RoundedCornerShape(12.dp))
                        .padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // FX Card Header
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { effectExpandedMap[eff.id] = !isEffectExpanded },
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = if (isEffectExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                contentDescription = "Toggle Collapse FX",
                                tint = EnergeticYellow,
                                modifier = Modifier.size(20.dp)
                            )
                            Spacer(Modifier.width(6.dp))
                            Text(
                                text = "Borders & Shadows FX #${index + 1}",
                                style = Typography.bodyMedium,
                                color = EnergeticYellow,
                                fontWeight = FontWeight.Bold
                            )
                            if (!eff.isEnabled) {
                                Spacer(Modifier.width(8.dp))
                                Text(
                                    text = "(Disabled)",
                                    style = Typography.labelSmall,
                                    color = Color.Red.copy(alpha = 0.8f)
                                )
                            }
                        }

                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            // Enable/Disable switch
                            Switch(
                                checked = eff.isEnabled,
                                onCheckedChange = {
                                    if (onToggleEffectEnabled != null) {
                                        onToggleEffectEnabled(eff.id)
                                    }
                                },
                                colors = SwitchDefaults.colors(
                                    checkedThumbColor = IndustrialAmber,
                                    checkedTrackColor = IndustrialAmber.copy(alpha = 0.5f)
                                ),
                                modifier = Modifier.scale(0.8f)
                            )

                            // Duplicate Button
                            IconButton(
                                onClick = {
                                    val duplicated = eff.duplicate()
                                    onAddEffect(duplicated)
                                },
                                modifier = Modifier.size(32.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.ContentCopy,
                                    contentDescription = "Duplicate FX",
                                    tint = MatteBlue,
                                    modifier = Modifier.size(16.dp)
                                )
                            }

                            // Delete Button
                            IconButton(
                                onClick = {
                                    if (onRemoveEffect != null) {
                                        onRemoveEffect(eff.id)
                                    }
                                },
                                enabled = onRemoveEffect != null,
                                modifier = Modifier.size(32.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Default.Delete,
                                    contentDescription = "Delete FX",
                                    tint = if (onRemoveEffect != null) Color.Red.copy(alpha = 0.8f) else Color.Gray,
                                    modifier = Modifier.size(16.dp)
                                )
                            }
                        }
                    }

                    if (isEffectExpanded) {
                        var borderStrokeTypeToEdit = borderStrokeTypeToEditMap[eff.id] ?: "InnerBorder"

                        if (isSingleColumn) {
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                // Subsection 1: DROP SHADOW
                                val dsExpanded = sectionExpandedMap["${eff.id}_drop_shadow"] ?: true
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(MidSlate, RoundedCornerShape(8.dp))
                                        .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                                        .padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    DropShadowCardContent(
                                        bordersShadowsEff = eff,
                                        onUpdateEffectParam = onUpdateEffectParam,
                                        isExpanded = dsExpanded,
                                        onToggleExpand = { sectionExpandedMap["${eff.id}_drop_shadow"] = !dsExpanded }
                                    )
                                }

                                // Subsection 2: INNER SHADOW
                                val isExpandedSec = sectionExpandedMap["${eff.id}_inner_shadow"] ?: true
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(MidSlate, RoundedCornerShape(8.dp))
                                        .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                                        .padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    InnerShadowCardContent(
                                        bordersShadowsEff = eff,
                                        onUpdateEffectParam = onUpdateEffectParam,
                                        isExpanded = isExpandedSec,
                                        onToggleExpand = { sectionExpandedMap["${eff.id}_inner_shadow"] = !isExpandedSec }
                                    )
                                }

                                // Subsection 3: BORDERS & STROKES
                                val bExpanded = sectionExpandedMap["${eff.id}_borders"] ?: true
                                Column(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .background(MidSlate, RoundedCornerShape(8.dp))
                                        .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                                        .padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    BordersCardContent(
                                        bordersShadowsEff = eff,
                                        borderStrokeTypeToEdit = borderStrokeTypeToEdit,
                                        onStrokeTypeChange = { borderStrokeTypeToEditMap[eff.id] = it },
                                        onUpdateEffectParam = onUpdateEffectParam,
                                        isExpanded = bExpanded,
                                        onToggleExpand = { sectionExpandedMap["${eff.id}_borders"] = !bExpanded }
                                    )
                                }
                            }
                        } else {
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .horizontalScroll(androidx.compose.foundation.rememberScrollState()),
                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                // Subsection 1: DROP SHADOW
                                val dsExpanded = sectionExpandedMap["${eff.id}_drop_shadow"] ?: true
                                Column(
                                    modifier = Modifier
                                        .width(310.dp)
                                        .background(MidSlate, RoundedCornerShape(8.dp))
                                        .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                                        .padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    DropShadowCardContent(
                                        bordersShadowsEff = eff,
                                        onUpdateEffectParam = onUpdateEffectParam,
                                        isExpanded = dsExpanded,
                                        onToggleExpand = { sectionExpandedMap["${eff.id}_drop_shadow"] = !dsExpanded }
                                    )
                                }

                                // Subsection 2: INNER SHADOW
                                val isExpandedSec = sectionExpandedMap["${eff.id}_inner_shadow"] ?: true
                                Column(
                                    modifier = Modifier
                                        .width(310.dp)
                                        .background(MidSlate, RoundedCornerShape(8.dp))
                                        .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                                        .padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    InnerShadowCardContent(
                                        bordersShadowsEff = eff,
                                        onUpdateEffectParam = onUpdateEffectParam,
                                        isExpanded = isExpandedSec,
                                        onToggleExpand = { sectionExpandedMap["${eff.id}_inner_shadow"] = !isExpandedSec }
                                    )
                                }

                                // Subsection 3: BORDERS & STROKES
                                val bExpanded = sectionExpandedMap["${eff.id}_borders"] ?: true
                                Column(
                                    modifier = Modifier
                                        .width(320.dp)
                                        .background(MidSlate, RoundedCornerShape(8.dp))
                                        .border(BorderStroke(0.5.dp, HighslateOutline), RoundedCornerShape(8.dp))
                                        .padding(10.dp),
                                    verticalArrangement = Arrangement.spacedBy(10.dp)
                                ) {
                                    BordersCardContent(
                                        bordersShadowsEff = eff,
                                        borderStrokeTypeToEdit = borderStrokeTypeToEdit,
                                        onStrokeTypeChange = { borderStrokeTypeToEditMap[eff.id] = it },
                                        onUpdateEffectParam = onUpdateEffectParam,
                                        isExpanded = bExpanded,
                                        onToggleExpand = { sectionExpandedMap["${eff.id}_borders"] = !bExpanded }
                                    )
                                }
                            }
                        }
                    }
                }
            }

            // Button to Add another instance
            Button(
                onClick = {
                    val newEff = com.example.studio.model.PhotoshopEffectTemplates.create(
                        id = java.util.UUID.randomUUID().toString(),
                        effectType = "BordersAndShadows"
                    )
                    onAddEffect(newEff)
                },
                colors = ButtonDefaults.buttonColors(containerColor = IndustrialAmber),
                shape = RoundedCornerShape(6.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp)
            ) {
                Icon(Icons.Default.Add, "Add FX", tint = DarkOnyx, modifier = Modifier.size(16.dp))
                Spacer(Modifier.width(6.dp))
                Text("Add New Border & Shadow FX", style = Typography.labelSmall, color = DarkOnyx, fontWeight = FontWeight.Bold)
            }
        }
    }
}

@Composable
private fun UnifiedEffectColorGradientPicker(
    prefix: String,
    bordersShadowsEff: com.example.studio.model.StudioEffect.PhotoshopEffect,
    onUpdateEffectParam: (String, String, Float) -> Unit,
    opacity: Float,
    opacityParamName: String
) {
    val gradEnabled = (bordersShadowsEff.parameters["${prefix}_Grad_Enabled"]?.value ?: 0f) > 0.5f
    var editStopIndex by remember { mutableStateOf(0) }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 4.dp, bottom = 4.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        // Mode Selector: Solid vs Gradient
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(30.dp)
                .background(Color(0xFF0F0F14), RoundedCornerShape(6.dp))
                .padding(2.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            val modes = listOf("Solid", "Gradient")
            modes.forEach { mode ->
                val isSelected = (mode == "Gradient") == gradEnabled
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight()
                        .clip(RoundedCornerShape(4.dp))
                        .background(if (isSelected) MidSlate else Color.Transparent)
                        .clickable {
                            onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Grad_Enabled", if (mode == "Gradient") 1f else 0f)
                        },
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = mode,
                        style = Typography.labelSmall.copy(
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp,
                            color = if (isSelected) IndustrialAmber else Color(0x99FFFFFF)
                        )
                    )
                }
            }
        }

        if (!gradEnabled) {
            val colR = bordersShadowsEff.parameters["${prefix}_Color_R"]?.value ?: 1f
            val colG = bordersShadowsEff.parameters["${prefix}_Color_G"]?.value ?: 1f
            val colB = bordersShadowsEff.parameters["${prefix}_Color_B"]?.value ?: 1f

            Text("Solid Color Tint", style = Typography.labelSmall, fontSize = 8.sp, color = MatteBlue, fontWeight = FontWeight.Bold)

            EffectColorPicker(
                red = colR,
                green = colG,
                blue = colB,
                opacity = opacity,
                onColorChanged = { newCol ->
                    onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Color_R", newCol.red)
                    onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Color_G", newCol.green)
                    onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Color_B", newCol.blue)
                }
            )
        } else {
            val r1 = bordersShadowsEff.parameters["${prefix}_Grad_R1"]?.value ?: 1f
            val g1 = bordersShadowsEff.parameters["${prefix}_Grad_G1"]?.value ?: 1f
            val b1 = bordersShadowsEff.parameters["${prefix}_Grad_B1"]?.value ?: 1f
            val a1 = bordersShadowsEff.parameters["${prefix}_Grad_A1"]?.value ?: 1f

            val r2 = bordersShadowsEff.parameters["${prefix}_Grad_R2"]?.value ?: 0f
            val g2 = bordersShadowsEff.parameters["${prefix}_Grad_G2"]?.value ?: 0f
            val b2 = bordersShadowsEff.parameters["${prefix}_Grad_B2"]?.value ?: 0f
            val a2 = bordersShadowsEff.parameters["${prefix}_Grad_A2"]?.value ?: 1f

            val angle = bordersShadowsEff.parameters["${prefix}_Grad_Angle"]?.value ?: 90f

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFF0F0F14), RoundedCornerShape(4.dp))
                    .padding(2.dp),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                listOf("Start Color" to 0, "End Color" to 1).forEach { (label, index) ->
                    val isSel = editStopIndex == index
                    val stopCol = if (index == 0) Color(r1, g1, b1, a1) else Color(r2, g2, b2, a2)
                    Row(
                        modifier = Modifier
                            .weight(1f)
                            .height(28.dp)
                            .clip(RoundedCornerShape(3.dp))
                            .background(if (isSel) MidSlate else Color.Transparent)
                            .border(BorderStroke(0.5.dp, if (isSel) IndustrialAmber else Color.Transparent), RoundedCornerShape(3.dp))
                            .clickable { editStopIndex = index }
                            .padding(horizontal = 6.dp, vertical = 2.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(14.dp)
                                .clip(RoundedCornerShape(2.dp))
                                .background(stopCol)
                                .border(BorderStroke(0.5.dp, Color.White), RoundedCornerShape(2.dp))
                        )
                        Text(
                            text = label,
                            style = Typography.labelSmall.copy(
                                fontWeight = FontWeight.Bold,
                                fontSize = 10.sp,
                                color = if (isSel) IndustrialAmber else Color(0x99FFFFFF)
                            )
                        )
                    }
                }
            }

            val currentR = if (editStopIndex == 0) r1 else r2
            val currentG = if (editStopIndex == 0) g1 else g2
            val currentB = if (editStopIndex == 0) b1 else b2
            val currentA = if (editStopIndex == 0) a1 else a2

            Text(
                text = if (editStopIndex == 0) "Editing: Start Color" else "Editing: End Color",
                style = Typography.labelSmall,
                fontSize = 8.sp,
                color = MatteBlue,
                fontWeight = FontWeight.Bold
            )

            EffectColorPicker(
                red = currentR,
                green = currentG,
                blue = currentB,
                opacity = currentA,
                onColorChanged = { col ->
                    val suff = if (editStopIndex == 0) "1" else "2"
                    onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Grad_R$suff", col.red)
                    onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Grad_G$suff", col.green)
                    onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Grad_B$suff", col.blue)
                }
            )

            Column {
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                    Text(
                        text = if (editStopIndex == 0) "Start Color Opacity" else "End Color Opacity",
                        style = Typography.labelSmall,
                        fontSize = 8.sp,
                        color = TextSecondary
                    )
                    Text("${(currentA * 100).toInt()}%", style = Typography.labelSmall, fontSize = 8.sp, color = IndustrialAmber)
                }
                Slider(
                    value = currentA,
                    onValueChange = {
                        val suff = if (editStopIndex == 0) "1" else "2"
                        onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Grad_A$suff", it)
                    },
                    valueRange = 0f..1f,
                    colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                    modifier = Modifier.height(20.dp)
                )
            }

            Spacer(Modifier.height(4.dp))

            Column {
                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                    Text("Gradient Angle", style = Typography.labelSmall, fontSize = 8.sp, color = TextSecondary)
                    Text("${angle.toInt()}°", style = Typography.labelSmall, fontSize = 8.sp, color = IndustrialAmber)
                }
                Slider(
                    value = angle,
                    onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "${prefix}_Grad_Angle", it) },
                    valueRange = 0f..360f,
                    colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                    modifier = Modifier.height(20.dp)
                )
            }
        }
    }
}

@Composable
private fun BordersCardContent(
    bordersShadowsEff: com.example.studio.model.StudioEffect.PhotoshopEffect,
    borderStrokeTypeToEdit: String,
    onStrokeTypeChange: (String) -> Unit,
    onUpdateEffectParam: (String, String, Float) -> Unit,
    isExpanded: Boolean = true,
    onToggleExpand: (() -> Unit)? = null
) {
    val bEnabled = (bordersShadowsEff.parameters["${borderStrokeTypeToEdit}_Enabled"]?.value ?: 1f) > 0.5f
    var typeDropdownExpanded by androidx.compose.runtime.remember { androidx.compose.runtime.mutableStateOf(false) }

    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth().then(if (onToggleExpand != null) Modifier.clickable { onToggleExpand() } else Modifier),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                if (onToggleExpand != null) {
                    Icon(
                        imageVector = if (isExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                        contentDescription = "Toggle Collapse",
                        tint = EnergeticYellow,
                        modifier = Modifier.size(16.dp)
                    )
                    Spacer(Modifier.width(4.dp))
                }
                Text("Borders & Strokes", style = Typography.labelSmall, color = EnergeticYellow, fontWeight = FontWeight.Bold)
            }
            Switch(
                checked = bEnabled,
                onCheckedChange = { 
                    onUpdateEffectParam(bordersShadowsEff.id, "${borderStrokeTypeToEdit}_Enabled", if (it) 1f else 0f) 
                },
                colors = SwitchDefaults.colors(
                    checkedThumbColor = IndustrialAmber,
                    checkedTrackColor = IndustrialAmber.copy(alpha = 0.5f)
                ),
                modifier = Modifier.scale(0.8f)
            )
        }
        
        if (isExpanded) {
            // Type Selector Dropdown
            Box {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFF222228), RoundedCornerShape(6.dp))
                        .border(1.dp, HighslateOutline, RoundedCornerShape(6.dp))
                        .clickable { typeDropdownExpanded = true }
                        .padding(horizontal = 12.dp, vertical = 8.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    val displayName = when (borderStrokeTypeToEdit) {
                        "InnerBorder" -> "Inner Border"
                        "OuterBorder" -> "Outer Border"
                        "InnerStroke" -> "Inner Stroke"
                        "OuterStroke" -> "Outer Stroke"
                        else -> borderStrokeTypeToEdit
                    }
                    Text(displayName, style = Typography.bodyMedium, color = TextPrimary)
                    Icon(Icons.Default.ArrowDropDown, contentDescription = "Select Type", tint = TextSecondary)
                }
                
                DropdownMenu(
                    expanded = typeDropdownExpanded,
                    onDismissRequest = { typeDropdownExpanded = false },
                    modifier = Modifier.background(MidSlate)
                ) {
                    listOf("InnerBorder", "OuterBorder", "InnerStroke", "OuterStroke").forEach { type ->
                        val displayName = when (type) {
                            "InnerBorder" -> "Inner Border"
                            "OuterBorder" -> "Outer Border"
                            "InnerStroke" -> "Inner Stroke"
                            "OuterStroke" -> "Outer Stroke"
                            else -> type
                        }
                        DropdownMenuItem(
                            text = { Text(displayName, color = TextPrimary, style = Typography.bodyMedium) },
                            onClick = {
                                onStrokeTypeChange(type)
                                typeDropdownExpanded = false
                            }
                        )
                    }
                }
            }

            if (bEnabled) {
                Spacer(Modifier.height(4.dp))
                val thickness = bordersShadowsEff.parameters["${borderStrokeTypeToEdit}_Size"]?.value ?: 2f
                Column {
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Stroke Width", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                        Text("${thickness.toInt()} px", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
                    }
                    Slider(
                        value = thickness,
                        onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "${borderStrokeTypeToEdit}_Size", it) },
                        valueRange = 0f..100f,
                        colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                        modifier = Modifier.height(24.dp)
                    )
                }

                // Corner Radius
                val cRadius = bordersShadowsEff.parameters["${borderStrokeTypeToEdit}_CornerRadius"]?.value ?: 0f
                Column {
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Corner Radius", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                        Text("${cRadius.toInt()} px", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
                    }
                    Slider(
                        value = cRadius,
                        onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "${borderStrokeTypeToEdit}_CornerRadius", it) },
                        valueRange = 0f..100f,
                        colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                        modifier = Modifier.height(24.dp)
                    )
                }

                // Opacity / Alpha
                val bOpacity = bordersShadowsEff.parameters["${borderStrokeTypeToEdit}_Opacity"]?.value ?: 1f
                Column {
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Opacity", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                        Text("${(bOpacity * 100).toInt()}%", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
                    }
                    Slider(
                        value = bOpacity,
                        onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "${borderStrokeTypeToEdit}_Opacity", it) },
                        valueRange = 0f..1f,
                        colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                        modifier = Modifier.height(24.dp)
                    )
                }

                UnifiedEffectColorGradientPicker(
                    prefix = borderStrokeTypeToEdit,
                    bordersShadowsEff = bordersShadowsEff,
                    onUpdateEffectParam = onUpdateEffectParam,
                    opacity = bOpacity,
                    opacityParamName = "${borderStrokeTypeToEdit}_Opacity"
                )
            }
        }
    }
}

@Composable
private fun DropShadowCardContent(
    bordersShadowsEff: com.example.studio.model.StudioEffect.PhotoshopEffect,
    onUpdateEffectParam: (String, String, Float) -> Unit,
    isExpanded: Boolean = true,
    onToggleExpand: (() -> Unit)? = null
) {
    val dsEnabled = (bordersShadowsEff.parameters["DropShadow_Enabled"]?.value ?: 0f) > 0.5f

    Row(
        modifier = Modifier.fillMaxWidth().then(if (onToggleExpand != null) Modifier.clickable { onToggleExpand() } else Modifier),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            if (onToggleExpand != null) {
                Icon(
                    imageVector = if (isExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                    contentDescription = "Toggle Collapse",
                    tint = EnergeticYellow,
                    modifier = Modifier.size(16.dp)
                )
                Spacer(Modifier.width(4.dp))
            }
            Text("Drop Shadow", style = Typography.labelSmall, color = EnergeticYellow, fontWeight = FontWeight.Bold)
        }
        Switch(
            checked = dsEnabled,
            onCheckedChange = {
                onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Enabled", if (it) 1f else 0f)
            },
            colors = SwitchDefaults.colors(
                checkedThumbColor = IndustrialAmber,
                checkedTrackColor = IndustrialAmber.copy(alpha = 0.5f)
            ),
            modifier = Modifier.scale(0.8f)
        )
    }

    if (dsEnabled && isExpanded) {
        // Distance
        val dsDist = bordersShadowsEff.parameters["DropShadow_Distance"]?.value ?: 10f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Distance", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${dsDist.toInt()} px", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsDist,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Distance", it) },
                valueRange = 0f..500f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        // Size / Blur
        val dsSize = bordersShadowsEff.parameters["DropShadow_Size"]?.value ?: 15f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Blur / Size", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${dsSize.toInt()} px", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsSize,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Size", it) },
                valueRange = 0f..120f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        // Angle
        val dsAngle = bordersShadowsEff.parameters["DropShadow_Angle"]?.value ?: 120f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Angle", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${dsAngle.toInt()}°", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsAngle,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Angle", it) },
                valueRange = 0f..360f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        // Hardness
        val dsHardness = bordersShadowsEff.parameters["DropShadow_Hardness"]?.value ?: 0f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Edge Hardness", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${(dsHardness * 100).toInt()}%", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsHardness,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Hardness", it) },
                valueRange = 0f..1f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        // Glow / Flow / Spread
        val dsGlow = bordersShadowsEff.parameters["DropShadow_Glow"]?.value ?: 0f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Outer Glow / Spread", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${dsGlow.toInt()}%", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsGlow,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Glow", it) },
                valueRange = 0f..100f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        // Zoom / Scale
        val dsZoom = bordersShadowsEff.parameters["DropShadow_Zoom"]?.value ?: 1.0f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Shadow Scale / Zoom", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${"%.2f".format(dsZoom)}x", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsZoom,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Zoom", it) },
                valueRange = 0.5f..2.0f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        // Opacity / Alpha
        val dsOpacity = bordersShadowsEff.parameters["DropShadow_Opacity"]?.value ?: 0.5f
        Column {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("Shadow Opacity", style = Typography.labelSmall, fontSize = 9.sp, color = TextSecondary)
                Text("${(dsOpacity * 100).toInt()}%", style = Typography.labelSmall, fontSize = 9.sp, color = IndustrialAmber)
            }
            Slider(
                value = dsOpacity,
                onValueChange = { onUpdateEffectParam(bordersShadowsEff.id, "DropShadow_Opacity", it) },
                valueRange = 0f..1f,
                colors = SliderDefaults.colors(activeTrackColor = IndustrialAmber, thumbColor = IndustrialAmber),
                modifier = Modifier.height(24.dp)
            )
        }

        UnifiedEffectColorGradientPicker(
            prefix = "DropShadow",
            bordersShadowsEff = bordersShadowsEff,
            onUpdateEffectParam = onUpdateEffectParam,
            opacity = dsOpacity,
            opacityParamName = "DropShadow_Opacity"
        )
    }
}

